  ui_story_5036_50360101_118_dialog_content = "Saya sarankan Anda mencoba keberuntungan Anda di tempat lain.",
  ui_story_5036_50360101_119_dialog_content = "Tapi semua teater lain di Umbraton sudah menolakku...",
