  ui_story_5036_50360101_124_dialog_content = "Woah!",
  ui_story_5036_50360101_125_dialog_content = "Kami benar-benar lepas landas!",
  ui_story_5036_50360101_126_dialog_content = "Editor yang melecehkan saya hari demi hari bahkan tidak akan pernah membayangkan ini dalam sejuta tahun!",
  ui_story_5036_50360101_127_dialog_content = "Bahwa dari semua jurnalis yang berebut kesempatan untuk mengikuti salah satu cerita Caelestite di Umbraton, saya satu-satunya yang benar-benar terbang di dalam Colossus!",
  ui_story_5036_50360101_128_dialog_content = "Akan kutunjukkan siapa reporter paling keren di kota ini!",
