  ui_story_5036_50360101_131_dialog_content = "Ahem. Harap yakinlah, semuanya. Saya seorang profesional dan akan melanjutkan pekerjaan saya dengan sangat objektif.",
  ui_story_5036_50360101_132_dialog_content = "Itu bukanlah apa yang saya maksud.",
