  ui_story_5036_50360101_146_dialog_content = "Aku ingin tahu apa yang dia lakukan akhir-akhir ini?",
  ui_story_5036_50360101_147_dialog_content = "Aku merasa dia menjadi populer di Umbraton akhir-akhir ini. Saya melihat posternya ke mana pun saya pergi.",
