  ui_story_5036_50360101_154_dialog_content = "Saya baru saja mewawancarai Goldie setelah \"Into the Haunted House\" tayang perdana.",
  ui_story_5036_50360101_155_dialog_content = "Saya menemukan dia sangat optimis dan baik hati, seperti angin hangat yang menyebarkan semua masalah saya.",
  ui_story_5036_50360101_156_dialog_content = "Kalau tidak, saya mungkin tidak akan bertahan selama saya magang di The Daily Scoop.",
  ui_story_5036_50360101_157_dialog_content = "Jadi setelah itu saya hanya mengikuti pekerjaannya dari waktu ke waktu, itu saja.",
  ui_story_5036_50360101_158_dialog_content = "Bukankah itu pada dasarnya membuat Anda menjadi penggemar?",
  ui_story_5036_50360101_159_dialog_content = "D-Apakah itu? Tapi saya mendengar selentingan bahwa kecenderungan kekerasan Goldie.",
  ui_story_5036_50360101_160_dialog_content = "Memang benar bahwa banyak figur publik memiliki sisi yang tidak diketahui oleh siapa pun.",
  ui_story_5036_50360101_161_dialog_content = "Tapi saya tidak ingin mengidolakan seseorang yang kejam.",
  ui_story_5036_50360101_162_dialog_content = "Goldie, kekerasan? Tidak mungkin!",
  ui_story_5036_50360101_163_dialog_content = "Ada banyak rumor absurd yang beredar akhir-akhir ini, dan itu mungkin salah satunya.",
