  ui_story_5036_50360101_165_dialog_content = "BENAR! Saya membencinya.",
  ui_story_5036_50360101_166_dialog_content = "Anda sebaiknya tidak menyeret saya melalui lumpur seperti mereka, Brandy!",
  ui_story_5036_50360101_167_dialog_content = "Santai!",
  ui_story_5036_50360101_168_dialog_content = "Saya hanya melaporkan kebenaran seperti yang saya lihat dengan mata kepala sendiri.",
  ui_story_5036_50360101_169_dialog_content = "Saya berharap ada lebih banyak jurnalis seperti Anda di Umbraton.",
  ui_story_5036_50360101_170_dialog_content = "A-Aku? Ya ampun, hehehe...",
  ui_story_5036_50360101_171_dialog_content = "<color=#e8d9bb>Peringatan: Benda terbang tak dikenal terdeteksi di depan.</color>",
  ui_story_5036_50360101_172_dialog_content = "<color=#e8d9bb>Tolong beri perintah untuk tindakan mengelak!</color>",
  ui_story_5036_50360101_173_dialog_content = "Objek terbang yang tidak dikenal?",
  ui_story_5036_50360101_174_dialog_content = "Build-nya sangat berbeda dengan Soroz...",
