  ui_story_5036_50360101_189_dialog_content = "Apa? Saya tidak mendengar apa-apa.",
  ui_story_5036_50360101_190_dialog_content = "♪ La la la la... ♪",
  ui_story_5036_50360101_191_dialog_content = "(Apakah Anda Navigator Eulogoz?)",
  ui_story_5036_50360101_192_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360101_193_dialog_content = "(Mengapa Anda meninggalkan Colossus Anda?)",
  ui_story_5036_50360101_194_dialog_content = "♪ La... La la... ♪",
  ui_story_5036_50360101_195_dialog_content = "(Mengapa...?)",
  ui_story_5036_50360101_196_dialog_content = "<color=#e8d9bb>Peringatan: Benda terbang tak dikenal terdeteksi di depan.</color>",
  ui_story_5036_50360101_197_dialog_content = "<color=#e8d9bb>Untuk menghindari tabrakan, Colossus akan mengubah jalur penerbangan secara otomatis dalam tiga detik.</color>",
  ui_story_5036_50360101_198_dialog_content = "<color=#e8d9bb>Tiga...</color>",
  ui_story_5036_50360101_199_dialog_content = "<color=#e8d9bb>Dua...</color>",
  ui_story_5036_50360101_200_dialog_content = "Hentikan pengalihan jalur penerbangan.",
  ui_story_5036_50360101_201_dialog_content = "Cocokkan kecepatan dan arah benda terbang tak dikenal.",
  ui_story_5036_50360101_202_dialog_content = "Sesuaikan penerbangan sesuai kebutuhan.",
  ui_story_5036_50360201_1_dialog_content = "<color=#e8d9bb>Perhatian, mendekati benda terbang tak dikenal.</color>",
  ui_story_5036_50360201_2_dialog_content = "Colossus sangat bergetar! Apakah kita bertabrakan dengan Wandering Colossus?",
  ui_story_5036_50360201_3_dialog_content = "Jangan khawatir. Itu hanya Soroz yang mengurangi kecepatan.",
  ui_story_5036_50360201_4_dialog_content = "Itu terlalu buruk. Saya pikir saya bisa menangkap bidikan dua Colossi yang saling bertabrakan.",
  ui_story_5036_50360201_5_dialog_content = "Foto yang luar biasa seperti itu akan menjadi halaman depan setiap surat kabar!",
  ui_story_5036_50360201_6_dialog_content = "Jika itu terjadi, saya ragu Anda punya waktu untuk mengambil foto.",
  ui_story_5036_50360201_7_dialog_content = "Aku hanya mengatakan!",
  ui_story_5036_50360201_8_dialog_content = "Yang mengatakan, kamera Anda memang terlihat cukup unik.",
  ui_story_5036_50360201_9_dialog_content = "Matamu bagus, Vice!",
  ui_story_5036_50360201_10_dialog_content = "Tidak semua orang memiliki hak istimewa untuk memiliki perangkat canggih seperti kamera.",
  ui_story_5036_50360201_11_dialog_content = "Belum lagi saya selalu memperbarui bagian-bagiannya sehingga saya bisa mendapatkan bidikan yang lebih baik.",
  ui_story_5036_50360201_12_dialog_content = "Saya dipekerjakan sebagai magang berkat kamera ini.",
  ui_story_5036_50360201_13_dialog_content = "Wow! Jadi bisakah kamera Anda membuat orang terlihat lebih cantik dalam gambar?",
  ui_story_5036_50360201_14_dialog_content = "Itu tidak bisa saya janjikan, tapi saya jamin itu akan menangkap gambar yang paling otentik dan nyata!",
  ui_story_5036_50360201_15_dialog_content = "<color=#e8d9bb>Penyesuaian dilakukan untuk menjaga kecepatan dan arah yang konsisten dengan objek yang tidak dikenal.</color>",
  ui_story_5036_50360201_16_dialog_content = "Ayo.",
  ui_story_5036_50360201_17_dialog_content = "Tunggu, kita masih jauh dari Wandering Colossus.",
  ui_story_5036_50360201_18_dialog_content = "Bagaimana kita bisa mendekatinya?",
  ui_story_5036_50360201_19_dialog_content = "Dengan terbang tentunya.",
  ui_story_5036_50360201_20_dialog_content = "<anim type=Shake>Ahhhh!!!</anim>",
  ui_story_5036_50360201_21_dialog_content = "K-Kami benar-benar terbang!",
  ui_story_5036_50360201_22_dialog_content = "Itu adalah pertama kalinya saya naik pesawat, itu brilian!",
  ui_story_5036_50360201_23_dialog_content = "Belum lagi, aku tidak percaya Colossus Pengembara benar-benar ada di bawah kakiku sekarang!",
  ui_story_5036_50360201_24_dialog_content = "Ya ampun, begitu banyak reporter yang rela mati demi kesempatan seperti ini!",
  ui_story_5036_50360201_25_dialog_content = "Tapi ups, betapapun bersemangatnya saya, seorang reporter profesional tidak boleh mengabaikan subjek tulisan mereka.",
  ui_story_5036_50360201_26_dialog_content = "Izinkan saya bertanya bagaimana caranya PlayerName terasa saat ini!",
  ui_story_5036_50360201_27_dialog_content = "Permisi, PlayerName...?",
  ui_story_5036_50360201_28_dialog_content = "...",
  ui_story_5036_50360201_29_dialog_content = "Hei, kamu terlihat pucat... Apakah ini semacam protes tanpa kata terhadap tindakan Illumina dan Lumopolis?",
  ui_story_5036_50360201_30_dialog_content = "Ini Arus Gelap! Tiba-tiba begitu banyak Darkflow!",
  ui_story_5036_50360201_31_dialog_content = "Apa? Apakah kita di tempat yang salah?",
  ui_story_5036_50360201_32_dialog_content = "Mustahil, Ketua Hakim Irridon memberiku koordinatnya sendiri. Mereka tidak mungkin salah.",
  ui_story_5036_50360201_33_dialog_content = "Teman-teman, tidak ada waktu untuk itu sekarang, kita punya masalah yang lebih besar!",
  ui_story_5036_50360201_34_dialog_content = "<size=45>Grah!!!</size>",
  ui_story_5036_50360202_1_dialog_content = "♪ La... La la la... ♪",
  ui_story_5036_50360202_2_dialog_content = "(Ini bernyanyi lagi ...)",
  ui_story_5036_50360202_3_dialog_content = "(Kenapa kedengarannya sangat familiar padahal aku belum pernah mendengarnya sebelumnya?)",
  ui_story_5036_50360202_4_dialog_content = "(Ini seperti ritme yang selalu berdenyut di pembuluh darahku, hanya meluap ke permukaan ingatanku saat ini.)",
  ui_story_5036_50360202_5_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360202_6_dialog_content = "♪ La la la la... ♪",
  ui_story_5036_50360202_7_dialog_content = "K-Kau...",
  ui_story_5036_50360202_8_dialog_content = "Beraninya seorang Caelestite belaka melupakan nama Hakim Matthieu!",
  ui_story_5036_50360202_9_dialog_content = "Bahkan tidak seorang pun di Lumopolis berani mengabaikanku! Saya menolak untuk menderita penghinaan seperti itu!",
  ui_story_5036_50360202_10_dialog_content = "Tidakkah kamu setuju, Loewe? ... Apa yang kamu lakukan, Loewe?",
  ui_story_5036_50360202_11_dialog_content = "Apakah Anda baik-baik saja, Yang Mulia?",
  ui_story_5036_50360202_12_dialog_content = "Saya baik-baik saja. Itu hanya beberapa Eclipsites.",
  ui_story_5036_50360202_13_dialog_content = "Namun berkat kedatangan Anda tepat waktu, kami menyingkirkannya dengan cukup cepat.",
  ui_story_5036_50360202_14_dialog_content = "Hmph, saya tidak akan pernah menduga ...",
  ui_story_5036_50360202_15_dialog_content = "bahwa suatu hari Anda akan belajar untuk mengambil pujian dan mencuri guntur untuk diri Anda sendiri, Loewe!",
  ui_story_5036_50360202_16_dialog_content = "Investigasi belum berakhir.",
  ui_story_5036_50360202_17_dialog_content = "Tetapi seseorang ingin pulang.",
  ui_story_5036_50360202_18_dialog_content = "Sekali lagi dengan itu!",
  ui_story_5036_50360202_19_dialog_content = "Saya tidak tahu dari mana Loewe belajar menjadi penjilat dan menusuk dari belakang rekan-rekannya.",
  ui_story_5036_50360202_20_dialog_content = "Jangan biarkan omong kosongnya memengaruhi Anda, Lady Carleen.",
  ui_story_5036_50360202_21_dialog_content = "Selama beberapa hari terakhir, saya telah memimpin pekerjaan unit investigasi Lumopolis di Wandering Colossus dengan cara yang paling tepat dan teratur.",
  ui_story_5036_50360202_22_dialog_content = "Anda akan dapat membaca laporan terperinci saya dari atas bantal beludru empuk Anda di Lumopolis pada waktunya.",
  ui_story_5036_50360202_23_dialog_content = "Ah, benarkah? Jadi kamu tidak berkeliaran di sekitar Siobhan dalam upaya untuk menjiplak karyanya, ya?",
  ui_story_5036_50360202_24_dialog_content = "Yakinlah, Petugas Gronru.",
  ui_story_5036_50360202_25_dialog_content = "Saya akan melindungi file kami dengan semua yang saya miliki.",
  ui_story_5036_50360202_26_dialog_content = "Sepertinya Anda tertangkap basah.",
  ui_story_5036_50360202_27_dialog_content = "Oh, diamlah! Saya baru saja mengkonfirmasi temuan kami sendiri!",
  ui_story_5036_50360202_28_dialog_content = "Petugas Gronru, Nona Siobhan!",
  ui_story_5036_50360202_29_dialog_content = "Jadi kau di sini untuk penugasan di Wandering Colossus?",
  ui_story_5036_50360202_30_dialog_content = "Mari kita lihat dirimu... Wakil, sayang, apakah berat badanmu turun lagi?",
  ui_story_5036_50360202_31_dialog_content = "Eh, benarkah?",
  ui_story_5036_50360202_32_dialog_content = "Jika kau terus memperlakukan Vice seperti ini, PlayerName, Aku akan mencurinya darimu!",
  ui_story_5036_50360202_33_dialog_content = "Aku belum melakukan apa-apa...",
  ui_story_5036_50360202_34_dialog_content = "Apakah begitu? hehehe...",
  ui_story_5036_50360202_35_dialog_content = "Bagaimanapun, Anda tiba di sini lebih lambat dari yang saya harapkan.",
  ui_story_5036_50360202_36_dialog_content = "Saya hampir berpikir PlayerName telah melepaskan gagasan untuk memeriksa Colossus ini.",
  ui_story_5036_50360202_37_dialog_content = "Tapi sejauh yang saya tahu...",
  ui_story_5036_50360202_38_dialog_content = "Baik Lumopolis maupun Federasi Illumina tidak pernah diberitahu secara resmi PlayerName tentang Raksasa Pengembara.",
  ui_story_5036_50360202_39_dialog_content = "Hmm? Aku tidak percaya kita pernah bertemu.",
  ui_story_5036_50360202_40_dialog_content = "Halo, saya Brandy, reporter magang untuk The Daily Scoop.",
  ui_story_5036_50360202_41_dialog_content = "Aku sedang melakukan fitur pada PlayerName. Tolong jawab pertanyaan saya.",
  ui_story_5036_50360202_42_dialog_content = "Kenapa tidak ada di antara kalian yang memberi tahu PlayerName tentang Wandering Colossus?",
  ui_story_5036_50360202_43_dialog_content = "Benarkah Illumina dan Lumopolis berencana untuk membelah Colossus di belakang punggung Caelestite?",
  ui_story_5036_50360202_44_dialog_content = "Reporter muda, Illumina wajib memberi tahu PlayerName?",
  ui_story_5036_50360202_45_dialog_content = "Petugas Gronru!",
  ui_story_5036_50360202_46_dialog_content = "Oh! Apakah saya menakuti Anda semua?",
  ui_story_5036_50360202_47_dialog_content = "Ehehe baiklah, aku akan menjawab dengan baik.",
  ui_story_5036_50360202_48_dialog_content = "Kami mengirim tim besar untuk menyelidiki segera setelah kami menerima berita tentang Wandering Colossus.",
  ui_story_5036_50360202_49_dialog_content = "Kami mendapat banyak dukungan siaga baik di darat maupun di udara terdekat.",
  ui_story_5036_50360202_50_dialog_content = "Bertentangan dengan asumsi Anda, tujuan utama kami bukanlah mengambil Colossus untuk diri kami sendiri.",
  ui_story_5036_50360202_51_dialog_content = "Kami di sini untuk mengevaluasi tingkat ancaman apa yang dapat ditimbulkan oleh Colossus yang keluar dari Zona Gelap ke Illumina.",
  ui_story_5036_50360202_52_dialog_content = "Lagi pula, itu berasal dari Zona Gelap, dan tidak ada yang tahu jenis apa <color=#FFB400>penumpang</color> ada di kapal.",
  ui_story_5036_50360202_53_dialog_content = "Lumopolis membagikan pandangan ini.",
  ui_story_5036_50360202_54_dialog_content = "Aku hanya tidak mengerti kenapa aku selalu terpilih untuk pekerjaan yang melelahkan dan kotor seperti ini.",
  ui_story_5036_50360202_55_dialog_content = "Berita tentang Raksasa Pengembara tidak pernah disensor.",
  ui_story_5036_50360202_56_dialog_content = "Aku sendiri penasaran kenapa PlayerName tidak menyadarinya.",
  ui_story_5036_50360202_57_dialog_content = "Y-Yah, ada alasannya...",
  ui_story_5036_50360202_58_dialog_content = "Oh?",
  ui_story_5036_50360202_59_dialog_content = "Sudahlah. Saya tidak berpikir kita sampai di sini terlambat.",
  ui_story_5036_50360202_60_dialog_content = "Tapi saya bingung melihat Eclipsites berkeliaran di aula Wandering Colossus.",
  ui_story_5036_50360202_61_dialog_content = "Saya sangat menyesal Anda harus mengalami ketakutan seperti itu pada saat kedatangan, Lady Carleen.",
  ui_story_5036_50360202_62_dialog_content = "Jika saya boleh, saya sarankan Anda segera meninggalkan Colossus ini.",
  ui_story_5036_50360202_63_dialog_content = "Tidak hanya dipenuhi sarang laba-laba, tampaknya juga menampung Eclipsites kotor yang tak terhitung jumlahnya.",
  ui_story_5036_50360202_64_dialog_content = "Namun, Anda tidak perlu mengkhawatirkan keselamatan kami.",
  ui_story_5036_50360202_65_dialog_content = "Setelah berhari-hari berusaha, kami telah memuat sebagian besar Eclipsites dalam a <color=#FFB400>daerah yang diblokade</color> di bagian belakang.",
  ui_story_5036_50360202_66_dialog_content = "Jadi yakinlah!",
  ui_story_5036_50360202_67_dialog_content = "Saya sudah mengirim orang untuk meningkatkan penghapusan Eclipsites, saya janji!",
  ui_story_5036_50360202_68_dialog_content = "Sampah kotor itu tidak akan pernah mengganggumu lagi.",
  ui_story_5036_50360202_69_dialog_content = "Kerja bagus, Hakim Matthieu.",
  ui_story_5036_50360202_70_dialog_content = "Kehormatan adalah milikku.",
  ui_story_5036_50360202_71_dialog_content = "Jadi relatif aman di Colossus ini untuk saat ini?",
  ui_story_5036_50360202_72_dialog_content = "Selama Anda tidak menginjakkan kaki di <color=#FFB400>daerah yang diblokade</color> di mana kesulitan dipanggil, Anda harus baik-baik saja!",
  ui_story_5036_50360202_73_dialog_content = "Gronru, aku ingin tahu lebih banyak tentang Colossus ini...",
  ui_story_5036_50360202_74_option_content = "Sistem pengaturan",
  ui_story_5036_50360202_75_dialog_content = "Mungkin aku bisa mencoba mendaratkannya.",
  ui_story_5036_50360202_76_dialog_content = "Aku juga memikirkan itu, jadi kami memeriksa jembatannya secara menyeluruh.",
  ui_story_5036_50360202_77_dialog_content = "Tapi kami menemukan sistem kontrol dan navigasi, bahkan Echo Template, semuanya rusak.",
  ui_story_5036_50360202_78_dialog_content = "Bahkan Anda mungkin tidak bisa mengendalikannya sekarang.",
  ui_story_5036_50360202_79_dialog_content = "Bagaimana ini bisa terjadi? Lalu bagaimana dengan—",
  ui_story_5036_50360202_80_option_content = "Inti kekuatan",
  ui_story_5036_50360202_81_dialog_content = "Colossus masih bergerak, jadi inti kekuatannya harus utuh, kan?",
  ui_story_5036_50360202_82_dialog_content = "Bisa dikatakan begitu.",
  ui_story_5036_50360202_83_dialog_content = "Karena masih menyuplai tenaga untuk Colossus agar tetap terbang.",
  ui_story_5036_50360202_84_dialog_content = "Tetapi pada saat yang sama, itu juga tidak dalam kondisi terbaik ...",
  ui_story_5036_50360202_85_dialog_content = "karena mengalami serangan Eclipsite di beberapa titik di masa lalu.",
  ui_story_5036_50360202_86_dialog_content = "Ini tidak cukup buruk untuk kehilangan daya secara tiba-tiba, tetapi itu pasti berdampak pada keluaran energi.",
  ui_story_5036_50360202_87_dialog_content = "Itu bisa diperbaiki, bukan?",
  ui_story_5036_50360202_88_dialog_content = "Memulihkan inti daya bukanlah tugas yang mudah.",
  ui_story_5036_50360202_89_dialog_content = "Paling tidak, Anda harus mematikan Colossus dan mematikan inti daya terlebih dahulu.",
  ui_story_5036_50360202_90_dialog_content = "Kalau tidak, kami tidak punya cukup waktu untuk mendiagnosis dan memperbaikinya.",
  ui_story_5036_50360202_91_dialog_content = "Kecuali saat ini kita bahkan tidak tahu cara menghentikannya terbang.",
  ui_story_5036_50360202_92_dialog_content = "Bagaimana ini bisa terjadi? Lalu bagaimana dengan—",
  ui_story_5036_50360202_93_option_content = "Layar dan sistem pengeras suara",
  ui_story_5036_50360202_94_dialog_content = "Saya perhatikan itu dilengkapi dengan apa yang tampak seperti layar dan speaker di luar.",
  ui_story_5036_50360202_95_dialog_content = "Ya, itu asli!",
  ui_story_5036_50360202_96_dialog_content = "Teknologi ini jauh melampaui luasnya pengetahuan kita saat ini.",
  ui_story_5036_50360202_97_dialog_content = "Secara mengejutkan, mereka terpelihara dengan baik terlepas dari usia mereka.",
  ui_story_5036_50360202_98_dialog_content = "Berkat bantuan dari Siobhan, kami menemukan cara mengaktifkannya!",
  ui_story_5036_50360202_99_dialog_content = "Akan sangat spektakuler untuk memutar film di layar sebesar itu!",
  ui_story_5036_50360202_100_dialog_content = "Dan…",
  ui_story_5036_50360202_100X1_dialog_content = "Ada lagi?",
  ui_story_5036_50360202_100X2_option_content = "Ya.",
  ui_story_5036_50360202_100X3_option_content = "Itu saja",
  ui_story_5036_50360202_101_dialog_content = "Oh, dan satu hal lagi...",
  ui_story_5036_50360202_102_dialog_content = "Apakah Anda menemukan Caelestites atau item terkait?",
  ui_story_5036_50360202_103_dialog_content = "Mm, belum.",
  ui_story_5036_50360202_104_dialog_content = "Tapi berbicara tentang itu...",
  ui_story_5036_50360202_105_dialog_content = "Asisten saya Siobhan membantu kami menggali catatan sejarah tentang Colossus pengembara ini.",
  ui_story_5036_50360202_106_dialog_content = "Dari penampilan dan ukurannya, sangat jelas bahwa Colossus ini adalah yang dilaporkan hilang oleh Caelestites lebih dari seratus tahun yang lalu, disebut—",
  ui_story_5036_50360202_107_dialog_content = "<color=#FFB400>Eulogoz?</color>",
  ui_story_5036_50360202_108_dialog_content = "Apa, kamu sudah tahu?",
  ui_story_5036_50360202_109_dialog_content = "Sayangnya, mengetahui namanya tidak masalah.",
  ui_story_5036_50360202_110_dialog_content = "Colossus ini dipenuhi dengan teknologi jahat dan mau tidak mau harus dihancurkan.",
  ui_story_5036_50360202_111_dialog_content = "Maaf apa? Siapa yang menghancurkan Eulogoz?",
  ui_story_5036_50360202_112_dialog_content = "Jangan salah paham. Itu bukan satu-satunya keputusan saya.",
  ui_story_5036_50360202_113_dialog_content = "Itu adalah solusi yang disetujui sebagian besar dari kita.",
  ui_story_5036_50360202_114_dialog_content = "Wow, bisakah kamu bertindak lebih jahat lagi?",
  ui_story_5036_50360202_115_dialog_content = "Terlalu dini untuk mengatakan itu. Saya belum menandatanganinya.",
  ui_story_5036_50360202_116_dialog_content = "Yah, mungkin itu sama sekali bukan pilihan Anda pada akhirnya.",
  ui_story_5036_50360202_117_dialog_content = "Apa yang terjadi, Hakim Matthieu? Silakan uraikan.",
  ui_story_5036_50360202_118_dialog_content = "Anda mendengar saya, Lady Carleen.",
  ui_story_5036_50360202_119_dialog_content = "Colossus ini tidak berharga dan penuh dengan Eclipsites yang tidak terkendali.",
  ui_story_5036_50360202_120_dialog_content = "Membiarkannya hanyut akan menimbulkan ancaman besar bagi kelangsungan hidup setiap orang di Astra.",
  ui_story_5036_50360202_121_dialog_content = "Lalu…",
  ui_story_5036_50360202_122_dialog_content = "Apa yang terjadi jika crash mendarat di Lumopolis?",
  ui_story_5036_50360202_123_dialog_content = "Menghancurkan mesin terlantar ini membuat kampung halaman kita aman.",
  ui_story_5036_50360202_124_dialog_content = "Saya yakin Anda sama sadarnya dengan saya bahwa Tuan Kota akan melakukan panggilan yang sama jika dia hadir.",
  ui_story_5036_50360202_125_dialog_content = "Tim ekspedisi kami terus mencari sisa-sisa Colossi di hutan belantara.",
  ui_story_5036_50360202_126_dialog_content = "Sekarang kita akhirnya menemukan satu yang benar-benar berfungsi, kita akan menghancurkannya?",
  ui_story_5036_50360202_127_dialog_content = "Jangan dengarkan omong kosong jahatnya, Vice.",
  ui_story_5036_50360202_128_dialog_content = "Kami sudah menentukan bahwa jalur penerbangannya tidak akan menyeberang ke Lumopolis.",
  ui_story_5036_50360202_129_dialog_content = "Dan jika kita terus melakukan apa yang kita lakukan di sini, kita akan menyingkirkan semua Eclipsites.",
  ui_story_5036_50360202_130_dialog_content = "Selain itu, Eulogoz tidak \"sepenuhnya tidak berharga\" seperti yang diklaim oleh badut itu.",
  ui_story_5036_50360202_131_dialog_content = "Setiap bagiannya berharga untuk diteliti.",
  ui_story_5036_50360202_132_dialog_content = "Meski banyak yang rusak dan sangat sulit untuk diperbaiki...",
  ui_story_5036_50360202_133_dialog_content = "Saya masih berpikir itu sepadan dengan harga untuk memperbaikinya.",
  ui_story_5036_50360202_134_dialog_content = "Tapi kamu juga harus sadar...",
  ui_story_5036_50360202_135_dialog_content = "bahwa jauh lebih efisien secara finansial bagi Anda untuk hanya menyelamatkan bagian yang ingin Anda pelajari dan meledakkan sisanya.",
  ui_story_5036_50360202_136_dialog_content = "Mengapa membiarkan benda tak terkendali ini terbang ke mana-mana?",
  ui_story_5036_50360202_137_dialog_content = "Jauh lebih berharga untuk mempelajari seluruh sampel!",
  ui_story_5036_50360202_138_dialog_content = "Apakah Anda dapat memberikan bukti potensi Colossus untuk diperbaiki?",
  ui_story_5036_50360202_139_dialog_content = "Aku... Aku butuh lebih banyak waktu!",
  ui_story_5036_50360202_140_dialog_content = "Waktu tidak menunggu siapapun.",
  ui_story_5036_50360202_141_dialog_content = "Semakin lama Anda menunggu, semakin mahal usaha ini.",
  ui_story_5036_50360202_142_dialog_content = "Kami menembak jatuh Colossus, menyelesaikan misi, dan berpisah. Bukankah itu lebih baik?",
  ui_story_5036_50360202_143_dialog_content = "Jadi kau hanya ingin pulang?",
  ui_story_5036_50360202_144_dialog_content = "Jangan salah paham, saya hanya menggunakan taktik negosiasi, Lady Carleen.",
  ui_story_5036_50360202_145_dialog_content = "Eulogoz milik Caelestites. Aku tidak akan membiarkan siapa pun menembaknya!",
  ui_story_5036_50360202_146_dialog_content = "Saya dapat membantu membersihkan Eclipsites!",
  ui_story_5036_50360202_147_dialog_content = "Saya juga akan membuktikan kepada Anda nilai sebenarnya!",
  ui_story_5036_50360202_148_dialog_content = "Memang. Saya akan membantu juga.",
  ui_story_5036_50360202_149_dialog_content = "Apa yang kamu lakukan, Nona Carleen?",
  ui_story_5036_50360202_150_dialog_content = "Aha, sepertinya Putri Lumopolis juga enggan melihat Eulogoz ditembak jatuh!",
  ui_story_5036_50360202_151_dialog_content = "Sayang, tidak ada waktu untuk keengganan di dunia ini.",
  ui_story_5036_50360202_152_dialog_content = "Jika ada, itu berarti uang yang ditawarkan tidak cukup.",
  ui_story_5036_50360202_153_dialog_content = "Hah?",
  ui_story_5036_50360202_154_dialog_content = "Meskipun aku tidak keberatan gadis-gadis menjilatku, ini masih membuatku merinding.",
  ui_story_5036_50360202_155_dialog_content = "Lady Sheol?",
  ui_story_5036_50360202_156_dialog_content = "Ah, PlayerName, VIP saya!",
  ui_story_5036_50360202_157_dialog_content = "Anda belum pernah ke Cloudrover Guild untuk melihat saya untuk waktu yang lama.",
  ui_story_5036_50360202_158_dialog_content = "Tapi itu bukan alasan bagimu untuk datang sejauh ini untuk menjual barang-barangku...",
  ui_story_5036_50360202_159_dialog_content = "Hahaha, kami menggemaskan PlayerName telah mengembangkan rasa humor.",
  ui_story_5036_50360202_160_dialog_content = "Tapi dalam arti tertentu, Anda benar.",
  ui_story_5036_50360202_161_dialog_content = "Namun kali ini, saya punya sedikit proposal yang berbeda.",
  ui_story_5036_50360202_162_dialog_content = "Kemarilah, sayang!",
  ui_story_5036_50360202_163_dialog_content = "Anda berbicara dengan saya?",
  ui_story_5036_50360202_164_dialog_content = "Jangan takut bahaya atau kegagalan.",
  ui_story_5036_50360202_165_dialog_content = "Kegigihan akan dibalas dengan keberuntungan.",
  ui_story_5036_50360202_166_dialog_content = "Jangan berkecil hati atau sedih.",
  ui_story_5036_50360202_167_dialog_content = "Lihat saja cara Goldie!",
  ui_story_5036_50360202_168_dialog_content = "Pengunjung Colossus, senang bertemu dengan kalian semua!",
  ui_story_5036_50360202_169_dialog_content = "G-Goldie?",
  ui_story_5036_50360202_170_dialog_content = "Halo, PlayerName! Bagaimana kabarmu?",
  ui_story_5036_50360202_171_dialog_content = "Apa?",
  ui_story_5036_50360202_172_dialog_content = "Apa yang dilakukan Goldie di sini?",
  ui_story_5036_50360202_173_dialog_content = "Karena tampaknya semua orang mengenal satu sama lain, saya dapat memulai pembicaraan bisnis.",
  ui_story_5036_50360202_174_dialog_content = "Saya pikir Anda melebih-lebihkan saya, Lady Sheol.",
  ui_story_5036_50360202_175_dialog_content = "Saya tidak pernah mampu menyewa seorang selebriti untuk mengadakan pertunjukan untuk saya.",
  ui_story_5036_50360202_176_dialog_content = "Sayang, alasan aku naik pesawat sewaan mahal dan datang sejauh ini dengan bintang terpanas di belakangnya...",
  ui_story_5036_50360202_177_dialog_content = "tentu bukan hanya untuk menawarkan usaha bisnis kepada Anda sendiri.",
  ui_story_5036_50360202_178_dialog_content = "Ini mungkin agak terlalu mendadak dan mungkin terdengar mengagetkan, hehe.",
  ui_story_5036_50360202_179_dialog_content = "Tapi Anda tahu, kami ingin mengadakan konser khusus yang unik di Colossus ini yang mengirimkan gelombang kejutan ke seluruh Astra!",
  ui_story_5036_50360202_180_dialog_content = "Saat tiba di Umbraton...",
  ui_story_5036_50360202_181_dialog_content = "Saya akan berdiri di atasnya dan menyanyikan berkat saya untuk didengar semua orang!",
  ui_story_5036_50360202_182_dialog_content = "Semua Umbraton dan Lumopolis akan dapat melihat pertunjukan di layar raksasa!",
  ui_story_5036_50360202_183_dialog_content = "Hmph, rakyat jelata tidak pernah berubah... Selalu bermimpi terlalu besar untuk celanamu.",
  ui_story_5036_50360202_184_dialog_content = "Anda tidak benar-benar berpikir Anda bisa bernyanyi hanya karena Anda punya mulut, bukan? Dan ngomong-ngomong, kamu terlihat seperti memakai dekorasi kue.",
  ui_story_5036_50360202_185_dialog_content = "Istilah vulgar seperti apa \"idola\" itu?",
  ui_story_5036_50360202_186_dialog_content = "Wow, inilah mengapa orang tidak boleh mengasingkan diri di pulau terapung kecil seperti yang banyak Anda lakukan di Lumopolis.",
  ui_story_5036_50360202_187_dialog_content = "Anda tidak boleh berbicara ketika Anda bahkan tidak tahu apa itu idola.",
  ui_story_5036_50360202_188_dialog_content = "Apakah Anda memanggil saya bodoh?",
  ui_story_5036_50360202_189_dialog_content = "Kebenaran selalu menyakitkan.",
  ui_story_5036_50360202_190_dialog_content = "Siobhan, mari mendidik hakim kita di sini tentang konsep idola, oke?",
  ui_story_5036_50360202_191_dialog_content = "Ya, Petugas Gronru.",
  ui_story_5036_50360202_192_dialog_content = "Berhala adalah pekerjaan yang baru muncul di Umbraton dan Gurun Rediesel.",
  ui_story_5036_50360202_193_dialog_content = "Mereka terutama terlibat dalam kegiatan yang berhubungan dengan hiburan, seperti menyanyi, menari, dan membawakan acara.",
  ui_story_5036_50360202_194_dialog_content = "Dibandingkan dengan penyanyi, penari, dan aktor tradisional, mereka jauh lebih ingin lebih dekat dengan penggemarnya.",
  ui_story_5036_50360202_195_dialog_content = "Mereka mendapatkan dukungan dengan pesona masing-masing dan, sebagai gantinya, menyebarkan hal positif kepada penggemar mereka.",
  ui_story_5036_50360202_196_dialog_content = "Ya, itulah intinya.",
  ui_story_5036_50360202_197_dialog_content = "Goldie saya multitalenta, meskipun fokus kami saat ini adalah pada karier menyanyinya.",
  ui_story_5036_50360202_198_dialog_content = "Oh, begitu…",
  ui_story_5036_50360202_199_dialog_content = "Uh, maksudku, aku tidak tertarik pada hal-hal biasa!",
  ui_story_5036_50360202_200_dialog_content = "Saya sampai di tempat saya hari ini semua berkat penggemar saya, Goldilocks.",
  ui_story_5036_50360202_201_dialog_content = "Saya ingin mereka melihat saya tampil untuk mereka di panggung sebesar mungkin!",
  ui_story_5036_50360202_202_dialog_content = "Heh, saya tidak keberatan konser ...",
  ui_story_5036_50360202_203_dialog_content = "Tapi bukankah terlalu berlebihan untuk menjadi tuan rumah di Wandering Colossus?",
  ui_story_5036_50360202_204_dialog_content = "Sayang, bukankah Anda sendiri mengatakan bahwa layar dan sistem stereo berfungsi dengan baik?",
  ui_story_5036_50360202_205_dialog_content = "Tentunya seseorang yang sangat menyukai Colossi seperti Anda akan senang menyaksikan sistem ini berjalan secara langsung, bukan?",
  ui_story_5036_50360202_206_dialog_content = "Hmm…",
  ui_story_5036_50360202_207_dialog_content = "Bayangkan, kerumunan besar berkumpul di tepi Sungai Emas. Mereka hanya perlu melihat ke atas...",
  ui_story_5036_50360202_208_dialog_content = "untuk melihat konser di layar besar.",
  ui_story_5036_50360202_209_dialog_content = "Orang-orang yang mengendarai pesawat bahkan dapat menonton pertunjukan di atas panggung konser.",
  ui_story_5036_50360202_210_dialog_content = "Kedengarannya seperti itu akan menjadi pesta besar untuk seluruh benua...",
  ui_story_5036_50360202_211_dialog_content = "Ya, festival akbar untuk Astra! Saya suka bagaimana Anda mengatakannya, PlayerName!",
  ui_story_5036_50360202_212_dialog_content = "Saya terkejut mendengar Anda menyebut Colossus Eulogoz ini.",
  ui_story_5036_50360202_213_dialog_content = "Mungkin itu dibangun untuk menyiarkan lagu.",
  ui_story_5036_50360202_214_dialog_content = "Jika memang harus dihancurkan...",
  ui_story_5036_50360202_215_dialog_content = "Saya ingin sekali membawakan satu lagu terakhir sebelum itu!",
  ui_story_5036_50360202_216_dialog_content = "!!!",
  ui_story_5036_50360202_217_dialog_content = "Sayang sekali.",
  ui_story_5036_50360202_218_dialog_content = "Colossus terbang melalui wilayah tak berpenghuni besok, yang merupakan lokasi terbaik untuk menembak jatuh.",
  ui_story_5036_50360202_219_dialog_content = "Itu tidak akan meninggalkan Anda dengan waktu untuk konser.",
  ui_story_5036_50360202_220_dialog_content = "Jangan terburu-buru, semuanya.",
  ui_story_5036_50360202_221_dialog_content = "Setelah terbang di atas Umbraton, jika terus menyusuri Sungai Emas...",
  ui_story_5036_50360202_222_dialog_content = "itu akan mencapai wilayah tak berpenghuni yang lebih besar.",
  ui_story_5036_50360202_223_dialog_content = "Maksudmu... laut?",
  ui_story_5036_50360202_224_dialog_content = "Menembak Colossus di atas laut?",
  ui_story_5036_50360202_225_dialog_content = "Saya pikir itu ide yang bagus, Petugas Gronru.",
  ui_story_5036_50360202_226_dialog_content = "Konser yang sukses akan menunjukkan nilainya dan menyelamatkannya dari kehancuran.",
  ui_story_5036_50360202_227_dialog_content = "Itu juga akan memberi kita lebih banyak waktu untuk mencoba dan memperbaiki Colossus.",
  ui_story_5036_50360202_228_dialog_content = "Jika konsernya terbukti gagal, kita masih bisa menembaknya begitu konser itu berada di atas lautan.",
  ui_story_5036_50360202_229_dialog_content = "Ini cara teraman untuk melakukannya, karena tidak akan membahayakan siapa pun di darat.",
  ui_story_5036_50360202_230_dialog_content = "Oh, aku mohon padamu!",
  ui_story_5036_50360202_231_dialog_content = "Tolong tunda penghancuran Colossus ini...",
  ui_story_5036_50360202_232_dialog_content = "Izinkan kami membangun panggung dan menyelenggarakan konser yang belum pernah ada sebelumnya!",
  ui_story_5036_50360301_1_dialog_content = "<color=#e8d9bb>Enam hari menjelang konser</color>",
  ui_story_5036_50360301_2_dialog_content = "Sisi kiri tidak aktif. Pindahkan sedikit.",
  ui_story_5036_50360301_3_dialog_content = "Begini?",
  ui_story_5036_50360301_4_dialog_content = "Sekarang sisi kanan mati.",
  ui_story_5036_50360301_5_dialog_content = "Mm, menurut saya posternya terlihat bengkok.",
  ui_story_5036_50360301_6_dialog_content = "Bagaimana menurutmu, PlayerName?",
  ui_story_5036_50360301_7_dialog_content = "Aku bukan ahlinya, jadi kenapa kita tidak bertanya pada Goldie?",
  ui_story_5036_50360301_8_dialog_content = "Guk!",
  ui_story_5036_50360301_9_dialog_content = "Ahh! Manis sekali! Saya ingin mengelus Marshmallow setiap kali saya melihatnya!",
  ui_story_5036_50360301_10_dialog_content = "Marshmallow juga suka menjadi hewan peliharaan!",
  ui_story_5036_50360301_11_dialog_content = "Guk, guk!",
  ui_story_5036_50360301_12_dialog_content = "Baiklah, Marshmallow, aku akan bermain denganmu nanti.",
  ui_story_5036_50360301_13_dialog_content = "Jadi beri kami waktu untuk berbicara, oke?",
  ui_story_5036_50360301_14_dialog_content = "Guk!",
  ui_story_5036_50360301_15_dialog_content = "Apa yang ingin kalian tanyakan begitu mendesak?",
  ui_story_5036_50360301_16_dialog_content = "Kami sibuk memasang poster, tapi kami tidak yakin apa cara terbaik untuk melakukannya...",
  ui_story_5036_50360301_17_dialog_content = "Apa? Kalian tidak harus melakukan semua ini.",
  ui_story_5036_50360301_18_dialog_content = "Ya, kami tahu.",
  ui_story_5036_50360301_19_dialog_content = "Jika bukan karena ide konser Anda, Eulogoz mungkin sudah hancur sekarang.",
  ui_story_5036_50360301_20_dialog_content = "Kami tidak dapat menangani peralatan apa pun, jadi hanya poster yang dapat kami lakukan.",
  ui_story_5036_50360301_21_dialog_content = "Oh, kalian sudah membantuku lebih dari yang kalian tahu.",
  ui_story_5036_50360301_22_dialog_content = "Tanpa Anda, saya rasa Illumina dan Lumopolis tidak akan pernah menyetujui hal ini.",
  ui_story_5036_50360301_23_dialog_content = "Grand Marshal memberi saya wewenang untuk membuat keputusan terkait Wandering Colossus...",
  ui_story_5036_50360301_24_dialog_content = "tapi saya masih perlu beberapa hari lagi untuk menyelidiki sebelum saya bisa memberikan jawaban.",
  ui_story_5036_50360301_25_dialog_content = "Apa lagi yang harus diselidiki? Ini lelucon!",
  ui_story_5036_50360301_26_dialog_content = "Mengapa bangsawan Lumopolis bahkan peduli dengan idola rakyat jelata?",
  ui_story_5036_50360301_27_dialog_content = "Saya tahu bahwa hanya saya saja tidak cukup, jadi ini tidak akan menjadi konser solo saya sendiri.",
  ui_story_5036_50360301_28_dialog_content = "Saya berencana mengundang bintang dari mana saja untuk bergabung dengan saya di konser di langit ini!",
  ui_story_5036_50360301_29_dialog_content = "Mungkin di Lumopolis dan Illumina, kalian punya ide yang berbeda tentang apa itu idol,",
  ui_story_5036_50360301_30_dialog_content = "tapi tidak apa-apa. Anda juga dapat mengirim idola Anda untuk berpartisipasi, siapa pun mereka!",
  ui_story_5036_50360301_31_dialog_content = "Saya mendukung ini!",
  ui_story_5036_50360301_32_dialog_content = "Hah?",
  ui_story_5036_50360301_33_dialog_content = "Saya mendukung Goldie mengadakan konser di Colossus!",
  ui_story_5036_50360301_34_dialog_content = "Dia benar. Tujuan Eulogoz mungkin untuk menyiarkan musik.",
  ui_story_5036_50360301_35_dialog_content = "Sebagai Caelestite, saya ingin melihatnya memenuhi tujuannya.",
  ui_story_5036_50360301_36_dialog_content = "Dan saya ingin melihat orang-orang dari berbagai tempat mengesampingkan bias mereka dan menikmati musik bersama!",
  ui_story_5036_50360301_37_dialog_content = "Mungkin Eulogoz kembali untuk membantu kami memahami",
  ui_story_5036_50360301_38_dialog_content = "bahwa kita mampu mencapai sesuatu bersama, terlepas dari mana kita berasal atau siapa kita!",
  ui_story_5036_50360301_39_dialog_content = "Tolong beri Goldie dan Eugoloz waktu yang mereka butuhkan.",
  ui_story_5036_50360301_40_dialog_content = "Dan saya juga. Mungkin...",
  ui_story_5036_50360301_41_dialog_content = "Mungkin saya bisa menemukan cara untuk menyelamatkan Eulogoz!",
  ui_story_5036_50360301_42_dialog_content = "Memikirkan kembali sekarang, pidato Anda sangat epik, PlayerName!",
  ui_story_5036_50360301_43_dialog_content = "Itu membuat saya sangat emosional sehingga saya hampir menangis.",
  ui_story_5036_50360301_44_dialog_content = "Tidak heran Sheol selalu mengatakan bahwa Lovegator melebihi jumlah Goldilocks.",
  ui_story_5036_50360301_45_dialog_content = "Nah, saya tidak terlalu... Saya rasa saya mudah bergairah dan memiliki kecenderungan untuk mulai mengoceh tanpa berpikir.",
  ui_story_5036_50360301_46_dialog_content = "Secara pribadi, saya pikir Lady Sheol adalah yang paling keren.",
  ui_story_5036_50360301_47_dialog_content = "Dia praktis bersinar ketika dia tersenyum dan berkata dia akan membayar tagihan untuk semua orang yang mengerjakan proyek!",
  ui_story_5036_50360301_48_dialog_content = "Pebisnis tidak membuat kesepakatan yang merugi.",
  ui_story_5036_50360301_49_dialog_content = "Dia yakin konser itu akan menguntungkan ketika dia memutuskan untuk berinvestasi di dalamnya.",
  ui_story_5036_50360301_50_dialog_content = "Tapi bagaimana dia akan menghasilkan uang ketika semua orang harus berdiri di tepi Sungai Emas dan mendengarkannya secara gratis?",
  ui_story_5036_50360301_51_dialog_content = "Sayang sekali dia sudah kembali Umbraton untuk mempromosikan konser.",
  ui_story_5036_50360301_52_dialog_content = "Aku harus bertanya padanya bagaimana dia mendapat untung!",
  ui_story_5036_50360301_53_dialog_content = "Vice, terkadang saya pikir Anda seharusnya lahir di Umbraton.",
  ui_story_5036_50360301_54_dialog_content = "Anda jauh lebih serius mendiskusikan Nightium daripada sebelumnya selama tahun-tahun Anda sebagai siswa pertukaran di Lumopolis.",
  ui_story_5036_50360301_55_dialog_content = "Saya? Nah, salahkan seseorang tertentu untuk itu.",
  ui_story_5036_50360301_56_dialog_content = "Hei, kenapa kalian semua menatapku?",
  ui_story_5036_50360301_57_dialog_content = "Heh, kita tidak bisa berharap memahami manuver bisnis Sheol.",
  ui_story_5036_50360301_58_dialog_content = "Yang harus kita lakukan adalah melakukan pekerjaan kita sendiri!",
  ui_story_5036_50360301_59_dialog_content = "Dan sekarang, tugasku adalah mempersiapkan konser!",
  ui_story_5036_50360301_60_dialog_content = "...",
  ui_story_5036_50360301_61_dialog_content = "Sesuatu di pikiran Anda, PlayerName?",
  ui_story_5036_50360301_62_dialog_content = "Oh, saya hanya berpikir, padahal layar dan speaker di Eulogoz baik-baik saja...",
  ui_story_5036_50360301_63_dialog_content = "Apakah itu benar-benar cukup bagi semua orang di lapangan untuk mendengarkan musik?",
  ui_story_5036_50360301_64_dialog_content = "Apakah Anda memiliki sedikit kepercayaan pada teknologi Caelestite?",
  ui_story_5036_50360301_65_dialog_content = "Saya memiliki keyakinan di dalamnya, tentu saja! Hanya saja...",
  ui_story_5036_50360301_66_dialog_content = "Dengar, aku tahu apa yang dikhawatirkan semua orang. Percayalah, saya ingin konser berjalan lancar lebih dari siapa pun.",
  ui_story_5036_50360301_67_dialog_content = "Saya bertanya kepada Siobhan tentang masalah peralatan dan mempelajari cara mengontrol volume.",
  ui_story_5036_50360301_68_dialog_content = "Mereka pasti bisa mendengar suaraku di tanah melalui peralatan!",
  ui_story_5036_50360301_69_dialog_content = "Jadi kau sudah mengurusnya? Saya seharusnya tidak mengharapkan idola profesional.",
  ui_story_5036_50360301_70_dialog_content = "Omong-omong, bukankah Anda sedang mencari cara untuk menyelamatkan Eulogoz?",
  ui_story_5036_50360301_71_dialog_content = "Ada berita di bagian depan itu?",
  ui_story_5036_50360301_72_dialog_content = "Sama sekali tidak ada.",
  ui_story_5036_50360301_73_dialog_content = "Saya benar-benar tidak tahu apa yang saya hadapi.",
  ui_story_5036_50360301_74_dialog_content = "Mengapa saya pikir saya bisa menemukan sesuatu ketika Petugas Teknologi Illumina pun tidak bisa?",
  ui_story_5036_50360301_75_dialog_content = "Jangan terlalu negatif, PlayerName!",
  ui_story_5036_50360301_76_dialog_content = "Anda ingin saya berkonsultasi dengan saya <color=#FFB400>peluru keberuntungan</color> untukmu?",
  ui_story_5036_50360301_77_dialog_content = "Anda apa?",
  ui_story_5036_50360301_78_dialog_content = "Peluru keberuntungan, will PlayerName menemukan cara untuk menyelamatkan Eulogoz?",
  ui_story_5036_50360301_79_dialog_content = "Jika demikian, mendaratlah dulu!",
  ui_story_5036_50360301_80_dialog_content = "PlayerName, ayo lemparkan peluru ke udara!",
  ui_story_5036_50360301_81_dialog_content = "Lempar itu? Seperti ini?",
  ui_story_5036_50360301_82_dialog_content = "<color=#e8d9bb>Wuush…</color>",
  ui_story_5036_50360301_83_dialog_content = "Itu dia...",
  ui_story_5036_50360301_84_dialog_content = "<color=#e8d9bb>Denting!</color>",
  ui_story_5036_50360301_85_dialog_content = "Sempurna! Lihat, itu mendarat lebih dulu!",
  ui_story_5036_50360301_86_dialog_content = "Peluru keberuntungan saya yakin Anda akan menemukan jalan!",
  ui_story_5036_50360301_87_dialog_content = "Sungguh?",
  ui_story_5036_50360301_88_dialog_content = "Ketika saya mengalami masalah, peluru selalu memiliki jawaban untuk saya.",
  ui_story_5036_50360301_89_dialog_content = "Saya pikir itu akan memberi Anda keberuntungan juga!",
  ui_story_5036_50360301_90_dialog_content = "... Baiklah. Saya tidak akan menyerah!",
  ui_story_5036_50360301_91_dialog_content = "Anda selalu memberi saya motivasi, Goldie.",
  ui_story_5036_50360301_92_dialog_content = "Saya pikir saya akan menjadi Goldilock sendiri!",
  ui_story_5036_50360301_93_dialog_content = "Hah, kamu harus!",
  ui_story_5036_50360301_94_dialog_content = "Saya sudah lama menjadi Lovegator diehard, asal tahu saja.",
  ui_story_5036_50360301_95_dialog_content = "Apa?",
  ui_story_5036_50360301_96_dialog_content = "<color=#e8d9bb>Klik!</color>",
  ui_story_5036_50360301_97_dialog_content = "Hah?",
  ui_story_5036_50360301_98_dialog_content = "M-Maafkan aku!",
  ui_story_5036_50360301_99_dialog_content = "Saya tersentuh oleh persahabatan baru Anda dan mau tidak mau mengambil foto grup demi kenang-kenangan...",
  ui_story_5036_50360301_100_dialog_content = "Wow, terima kasih Brandy!",
  ui_story_5036_50360301_101_dialog_content = "(Goldie... menyebut namaku...?)",
  ui_story_5036_50360301_102_dialog_content = "Pers di Umbraton pasti tahu apa yang mereka lakukan jika mereka bisa mengirimmu untuk meliput konser begitu cepat.",
  ui_story_5036_50360301_103_dialog_content = "Sebenarnya, saya datang dengan PlayerName.",
  ui_story_5036_50360301_104_dialog_content = "Ya, Brandy melakukan fitur pada saya.",
  ui_story_5036_50360301_105_dialog_content = "Ah, jadi kamu di sini untuknya?",
  ui_story_5036_50360301_106_dialog_content = "Saya pikir saya sedikit cemburu.",
  ui_story_5036_50360301_107_dialog_content = "eh, um...",
  ui_story_5036_50360301_108_dialog_content = "Hanya bercanda!",
  ui_story_5036_50360301_109_dialog_content = "Saya tidak berpikir Anda akan mengingat saya.",
  ui_story_5036_50360301_110_dialog_content = "Tentu saja. Saya menyimpan kliping artikel yang Anda lakukan pada saya!",
  ui_story_5036_50360301_111_dialog_content = "Tapi itu ditulis dengan sangat buruk, editor bahkan memarahi saya karenanya.",
  ui_story_5036_50360301_112_dialog_content = "Saya tidak ingin mendengar Anda mengatakan bahwa tentang diri Anda, Brandy.",
  ui_story_5036_50360301_113_dialog_content = "Anda lebih rajin daripada siapa pun dalam hal wawancara!",
  ui_story_5036_50360301_114_dialog_content = "Anda harus percaya pada diri sendiri dan penilaian Anda, tidak peduli apa yang orang lain katakan.",
  ui_story_5036_50360301_115_dialog_content = "Percayalah pada diriku sendiri...",
  ui_story_5036_50360301_116_dialog_content = "Anda selalu menyebarkan begitu banyak hal positif sehingga saya mendapatkan energi untuk terus bekerja.",
  ui_story_5036_50360301_117_dialog_content = "Tapi saya mendengar wartawan senior mengatakan Anda telah merencanakan pertunjukan Anda di Star Theater untuk waktu yang lama.",
  ui_story_5036_50360301_118_dialog_content = "Bukankah itu akan dibatalkan jika Anda melakukan konser di Wandering Colossus?",
  ui_story_5036_50360301_119_dialog_content = "Tentang itu...",
  ui_story_5036_50360301_120_dialog_content = "Saya tidak bisa melewatkan tempat semegah Eulogoz.",
  ui_story_5036_50360301_121_dialog_content = "Akan ada lebih banyak kesempatan bagi saya di panggung Umbraton di masa depan.",
  ui_story_5036_50360301_122_dialog_content = "Aku tahu.",
  ui_story_5036_50360301_123_dialog_content = "Ha ha! Semuanya bekerja dengan sempurna!",
  ui_story_5036_50360301_124_dialog_content = "Peluru keberuntungan benar tentang saya mendapatkan reporter yang hebat!",
  ui_story_5036_50360301_125_dialog_content = "Apa?",
  ui_story_5036_50360301_126_dialog_content = "Sheol meminta saya untuk mendapatkan reporter untuk meliput konser, tetapi saya tidak tahu di mana menemukannya.",
  ui_story_5036_50360301_127_dialog_content = "Jika memungkinkan, saya ingin Anda meliput proyek ini sampai akhir, Brandy!",
  ui_story_5036_50360301_128_dialog_content = "Artinya, jika tidak terlalu banyak bertanya ...",
  ui_story_5036_50360301_129_dialog_content = "Anda bisa memikirkannya sebelum memberi saya jawaban.",
  ui_story_5036_50360301_130_dialog_content = "(Itu jenisnya, Goldie perhatian yang saya tahu!)",
  ui_story_5036_50360301_131_dialog_content = "(Berita bahwa dia memiliki pukulan yang kejam mungkin dibuat-buat.)",
  ui_story_5036_50360301_132_dialog_content = "Mari kita tidak berdiri di sekitar.",
  ui_story_5036_50360301_133_dialog_content = "Kami masih memiliki poster untuk dipasang!",
  ui_story_5036_50360301_134_dialog_content = "Mereka pasti bergerak cepat.",
  ui_story_5036_50360301_135_dialog_content = "Koridor di sini juga ditempeli poster warna-warni.",
  ui_story_5036_50360301_136_dialog_content = "Aku hanya tidak mendapatkan kesepakatan dengan idola.",
  ui_story_5036_50360301_137_dialog_content = "Mereka naik ke atas panggung, tersenyum, bertingkah imut, dan mendapat sorakan dan tepuk tangan.",
  ui_story_5036_50360301_138_dialog_content = "Sementara itu, kami bekerja keras di sini dan tidak mendapat pujian sama sekali.",
  ui_story_5036_50360301_139_dialog_content = "Benar? Aku belum pernah mendengar idola dengan kostum yang begitu mencolok dan aneh sebelumnya.",
  ui_story_5036_50360301_140_dialog_content = "Menyanyi dan menari hanya bisa menghibur, bukan menyelamatkan orang!",
  ui_story_5036_50360301_141_dialog_content = "Saya tidak pernah berpikir akan ada hari dimana saya bertemu langsung dengan seseorang dari Lumopolis.",
  ui_story_5036_50360301_142_dialog_content = "Nah, kita yang kurang beruntung.",
  ui_story_5036_50360301_143_dialog_content = "Mereka bisa mengadakan konser dan meninggalkan kami untuk mengamankan perimeter dan membersihkan Eclipsites!",
  ui_story_5036_50360301_144_dialog_content = "Saya tidak tahu mengapa, tetapi beberapa hari terakhir ini saya merasa semakin lelah.",
  ui_story_5036_50360301_145_dialog_content = "Coba ceritakan.",
  ui_story_5036_50360301_146_dialog_content = "Ehem...",
  ui_story_5036_50360301_147_dialog_content = "!!!",
  ui_story_5036_50360301_148_dialog_content = "Salam, Wakil Letnan!",
  ui_story_5036_50360301_149_dialog_content = "Selamat siang, Nona Carleen!",
  ui_story_5036_50360301_150_dialog_content = "Nyaman. Anda melakukan pekerjaan dengan baik.",
  ui_story_5036_50360301_151_dialog_content = "Uh, kami mungkin mengatakan banyak hal bodoh, jadi tolong maafkan kami!",
  ui_story_5036_50360301_152_dialog_content = "Maafkan kami, Wakil Letnan!",
  ui_story_5036_50360301_153_dialog_content = "Mengejek warga sipil bukanlah hal yang kami lakukan sebagai ksatria.",
  ui_story_5036_50360301_154_dialog_content = "Anda harus tahu apa yang harus Anda lakukan sekarang.",
  ui_story_5036_50360301_155_dialog_content = "Maafkan saya, Nona Goldie!",
  ui_story_5036_50360301_156_dialog_content = "Dan Anda juga.",
  ui_story_5036_50360301_157_dialog_content = "M-Maaf, Nona Goldie!",
  ui_story_5036_50360301_158_dialog_content = "Saya tidak sopan dalam pidato saya. Tolong hukum aku dengan pedang ini!",
  ui_story_5036_50360301_159_dialog_content = "Baiklah. Aku akan menghukum kalian berdua...",
  ui_story_5036_50360301_160_dialog_content = "dengan menyuruhmu tidur lebih awal. Semoga mimpi indah!",
  ui_story_5036_50360301_161_dialog_content = "Hah?",
  ui_story_5036_50360301_162_dialog_content = "Ayolah, siapa yang tidak mengeluh ketika sedang bekerja?",
  ui_story_5036_50360301_163_dialog_content = "Dan sungguh, saya adalah alasan meningkatnya beban kerja semua orang.",
  ui_story_5036_50360301_164_dialog_content = "Seharusnya aku yang meminta maaf!",
  ui_story_5036_50360301_165_dialog_content = "Saya telah meminta Sheol untuk menyewa tentara bayaran dari Umbraton untuk membantu memikul beban.",
  ui_story_5036_50360301_166_dialog_content = "Anda akan memiliki lebih banyak downtime untuk diri sendiri!",
  ui_story_5036_50360301_167_dialog_content = "Ini...",
  ui_story_5036_50360301_168_dialog_content = "Ada minuman berenergi di ujung lorong. Saya pikir kalian berdua belum punya kesempatan untuk mengambil beberapa?",
  ui_story_5036_50360301_169_dialog_content = "Cobalah!",
  ui_story_5036_50360301_170_dialog_content = "Saya jamin Anda akan merasa segar kembali setelah meminumnya!",
  ui_story_5036_50360301_171_dialog_content = "...",
  ui_story_5036_50360301_172_dialog_content = "Kenapa kamu masih disini? Anda mendengarnya.",
  ui_story_5036_50360301_173_dialog_content = "Yang mulia...?",
  ui_story_5036_50360301_174_dialog_content = "Nona Goldie telah memberikan hukumannya, jadi Anda boleh pergi.",
  ui_story_5036_50360301_175_dialog_content = "Terima kasih, Yang Mulia! Terima kasih, Nona Goldie!",
  ui_story_5036_50360301_176_dialog_content = "Terima kasih, Wakil Letnan! Terima kasih, Nona Goldie!",
  ui_story_5036_50360301_177_dialog_content = "Ada banyak hal yang harus dipertimbangkan saat mengadakan konser.",
  ui_story_5036_50360301_178_dialog_content = "Tidak percaya saya lupa mempertimbangkan tentara ...",
  ui_story_5036_50360301_179_dialog_content = "Jika Anda merasa perlu, Goldie, saya dapat meminta lebih banyak Ksatria Lumo.",
  ui_story_5036_50360301_180_dialog_content = "Tidak apa-apa, saya seharusnya tidak merepotkan Anda lebih dari yang saya miliki!",
  ui_story_5036_50360301_181_dialog_content = "Saya sudah meminta Tentara Bayaran Api Putih untuk membantu saya mengirimkan persediaan dan membangun panggung.",
  ui_story_5036_50360301_182_dialog_content = "Saya hanya akan menambahkan agenda mereka ketika mereka tiba di sini!",
  ui_story_5036_50360301_183_dialog_content = "Tidak murah untuk menyewa White Flames untuk hal-hal seperti ini.",
  ui_story_5036_50360301_184_dialog_content = "Apakah Sheol akan bertanggung jawab atas biayanya?",
  ui_story_5036_50360301_185_dialog_content = "...",
  ui_story_5036_50360301_186_dialog_content = "Goldie?",
  ui_story_5036_50360301_187_dialog_content = "Hah?",
  ui_story_5036_50360301_188_dialog_content = "Oh, uh... ya, Sheol sangat banyak akal. Seharusnya tidak menjadi masalah.",
  ui_story_5036_50360301_189_dialog_content = "Apakah Anda khawatir tentang sesuatu, Goldie?",
  ui_story_5036_50360301_190_dialog_content = "Tidak juga...",
  ui_story_5036_50360301_191_dialog_content = "Hanya saja Api Putih seharusnya sudah ada di sini sekarang, tapi mereka tidak…",
  ui_story_5036_50360301_192_dialog_content = "<color=#e8d9bb>* Langkah kaki kacau *</color>",
  ui_story_5036_50360301_193_dialog_content = "Saya mendengar langkah kaki... Kedengarannya seperti sekelompok orang datang ke sini.",
  ui_story_5036_50360301_194_dialog_content = "Berbicara tentang iblis... Itu pasti mereka.",
  ui_story_5036_50360301_195_dialog_content = "Kebetulan sekali!",
  ui_story_5036_50360301_196_dialog_content = "Graaaaaagh!",
  ui_story_5036_50360301_197_dialog_content = "Apa? Oh tidak!",
  ui_story_5036_50360301_198_dialog_content = "Ini bukan tentara bayaran!",
  ui_story_5036_50360301_199_dialog_content = "Saya tidak menyewa Eclipsites!",
  ui_story_5036_50360302_1_dialog_content = "Awas di belakangmu, Goldie!",
  ui_story_5036_50360302_2_dialog_content = "Apa...?",
  ui_story_5036_50360302_3_dialog_content = "Astaga!",
  ui_story_5036_50360302_4_dialog_content = "Pergi!",
  ui_story_5036_50360302_5_dialog_content = "Tentara Bayaran Api Putih ada di sini!",
  ui_story_5036_50360302_6_dialog_content = "Apakah Anda baik-baik saja, Nona Goldie?",
  ui_story_5036_50360302_7_dialog_content = "Aku baik-baik saja, terima kasih atas waktumu yang tepat.",
  ui_story_5036_50360302_8_dialog_content = "Saya tidak akan menyebutnya sempurna...",
  ui_story_5036_50360302_9_dialog_content = "Mendapatkan persediaan untuk panggung memakan waktu lebih lama dari yang diperkirakan, jadi maaf kami baru saja tiba di sini sekarang.",
  ui_story_5036_50360302_10_dialog_content = "Meskipun saya tidak pernah berpikir akan ada Eclipsites di Wandering Colossus juga.",
  ui_story_5036_50360302_11_dialog_content = "Yah, saya mengetahuinya setelah saya mendapatkan diri saya sendiri.",
  ui_story_5036_50360302_12_dialog_content = "Tapi tentara Illumina dan Lumopolis membatasi sebagian besar Eclipsites ke area aman di bagian belakang.",
  ui_story_5036_50360302_13_dialog_content = "Masih ada beberapa orang yang tersesat berkeliaran, tetapi seperti yang Anda lihat ...",
  ui_story_5036_50360302_14_dialog_content = "Mereka tidak tangguh.",
  ui_story_5036_50360302_15_dialog_content = "Para prajurit telah meningkatkan upaya pembersihan mereka.",
  ui_story_5036_50360302_16_dialog_content = "Sekarang dengan bantuanmu...",
  ui_story_5036_50360302_17_dialog_content = "Saya yakin orang-orang yang tersesat ini dan mereka yang berada di belakang akan ditangani juga.",
  ui_story_5036_50360302_18_dialog_content = "Kami akan melakukan yang terbaik untuk menyelesaikan tugas Lady Sheol.",
  ui_story_5036_50360302_19_dialog_content = "Anda dapat mengandalkan kami!",
  ui_story_5036_50360302_20_dialog_content = "Terimakasih semuanya!",
  ui_story_5036_50360302_21_dialog_content = "Tanpa keringat. Oh, kami mendengarnya di Umbraton",
  ui_story_5036_50360302_22_dialog_content = "satu ton orang telah mendaftar untuk konser!",
  ui_story_5036_50360302_23_dialog_content = "Berita pasti menyebar dengan cepat!",
  ui_story_5036_50360302_24_dialog_content = "Wow, orang-orang jauh lebih bersemangat daripada yang saya bayangkan.",
  ui_story_5036_50360302_25_dialog_content = "Sebelum pertunjukan resmi dimulai, kami juga menjalankan <color=#FFB400>audisi idola</color>.",
  ui_story_5036_50360302_26_dialog_content = "Kami akan memilih idola dengan penampilan panggung yang kuat.",
  ui_story_5036_50360302_27_dialog_content = "Audisi idola? Kedengarannya seperti acara yang menarik!",
  ui_story_5036_50360302_28_dialog_content = "Babak pertama adalah besok, jadi kami membutuhkan beberapa dari kalian untuk pengendalian massa.",
  ui_story_5036_50360302_29_dialog_content = "Bukan masalah!",
  ui_story_5036_50360302_30_dialog_content = "Ayo sibuk, teman-teman!",
  ui_story_5036_50360302_31_dialog_content = "Siap!",
  ui_story_5036_50360302_32_dialog_content = "Anda seorang motivator yang hebat.",
  ui_story_5036_50360302_33_dialog_content = "Namun, audisi idola terdengar seperti banyak pekerjaan.",
  ui_story_5036_50360302_34_dialog_content = "Itu adalah sesuatu yang selalu ingin saya lakukan. Tidak setiap hari saya mendapat kesempatan untuk memenuhi salah satu impian saya.",
  ui_story_5036_50360302_35_dialog_content = "Sama sekali tidak terasa seperti bekerja bagi saya!",
  ui_story_5036_50360302_36_dialog_content = "Apakah Anda selalu ingin mengadakan audisi?",
  ui_story_5036_50360302_37_dialog_content = "Betul sekali. Saya suka panggung dan penonton di bawahnya.",
  ui_story_5036_50360302_38_dialog_content = "Saya ingin menyebarkan semangat saya kepada orang lain!",
  ui_story_5036_50360302_39_dialog_content = "Saya ingin ada lebih banyak idola untuk bergerak dan menginspirasi penonton.",
  ui_story_5036_50360302_40_dialog_content = "Saya harus mendukung semua orang yang bercita-cita menjadi idola selama saya memiliki kemampuan untuk itu.",
  ui_story_5036_50360302_41_dialog_content = "Anda sangat mencintai karir Anda.",
  ui_story_5036_50360302_42_dialog_content = "Ngomong-ngomong soal...",
  ui_story_5036_50360302_43_dialog_content = "Apakah Anda tertarik <color=#FFB400>bergabung dengan panitia seleksi</color>?",
  ui_story_5036_50360302_44_dialog_content = "Siapa, saya?",
  ui_story_5036_50360302_45_dialog_content = "Ya! Menjadi panitia sebenarnya cukup mudah.",
  ui_story_5036_50360302_46_dialog_content = "Anda hanya perlu menonton penampilan para kontestan dan memutuskan siapa yang akan tampil di atas panggung berdasarkan preferensi Anda.",
  ui_story_5036_50360302_47_dialog_content = "Saya menyimpan posisi untuk Sheol, tetapi dia tampaknya sangat sibuk melakukan semua hal promosi.",
  ui_story_5036_50360302_48_dialog_content = "Setelah merenungkannya, saya memutuskan bahwa Anda paling cocok untuk tugas itu.",
  ui_story_5036_50360302_49_dialog_content = "Tapi aku tidak yakin aku bisa mengatasinya.",
  ui_story_5036_50360302_50_dialog_content = "Hai! Carleen, Vice... Bukankah kalian berdua juga suka menyanyi?",
  ui_story_5036_50360302_51_dialog_content = "Tertarik untuk bergabung menjadi panitia?",
  ui_story_5036_50360302_52_dialog_content = "Anu…",
  ui_story_5036_50360302_53_dialog_content = "Hmm…",
  ui_story_5036_50360302_54_dialog_content = "Oh, kamu tidak tahu?",
  ui_story_5036_50360302_55_dialog_content = "Vice dan Carleen sama-sama mendaftar untuk audisi!",
  ui_story_5036_50360302_56_dialog_content = "Mereka apa?!",
  ui_story_5036_50360302_57_dialog_content = "Mengapa saya tidak menyadari hal ini?",
  ui_story_5036_50360302_58_dialog_content = "Anda tidak bisa menyalahkan kami untuk itu. Kami memang memberitahumu.",
  ui_story_5036_50360302_59_dialog_content = "Tetapi Anda sedang mendengarkan sesuatu pada saat itu dan tidak memperhatikan kami.",
  ui_story_5036_50360302_60_dialog_content = "Vice dan saya mendiskusikannya. Jika konsernya sukses, itu sudah cukup untuk membuktikan nilai Eulogoz.",
  ui_story_5036_50360302_61_dialog_content = "Lalu, kita bisa membujuk para petinggi Illumina dan ayahku untuk tidak menghancurkannya.",
  ui_story_5036_50360302_62_dialog_content = "Bahkan jika kita tidak dapat menemukan cara untuk mengendalikan Colossus...",
  ui_story_5036_50360302_63_dialog_content = "Setidaknya Eulogoz masih bisa dibiarkan terus mengembara seperti sekarang.",
  ui_story_5036_50360302_64_dialog_content = "Mungkin dalam seratus tahun, itu akan melayang kembali ke langit Astra!",
  ui_story_5036_50360302_65_dialog_content = "Kalian berdua benar-benar berpikir jauh ke depan.",
  ui_story_5036_50360302_66_dialog_content = "Sebenarnya, kami hampir mendaftarkanmu juga, tapi kemudian kami pikir...",
  ui_story_5036_50360302_67_dialog_content = "Nah, kita tidak seharusnya.",
  ui_story_5036_50360302_68_dialog_content = "Saya benar-benar tidak percaya diri dengan keterampilan penampilan saya, tetapi Anda tidak harus terlalu blak-blakan tentang itu!",
  ui_story_5036_50360302_69_dialog_content = "Anda tidak harus pandai seni pertunjukan untuk menjadi panitia seleksi.",
  ui_story_5036_50360302_70_dialog_content = "Yang Anda butuhkan hanyalah bakat untuk memenuhi syarat!",
  ui_story_5036_50360302_71_dialog_content = "Hmm…",
  ui_story_5036_50360302_72_dialog_content = "Sigh, tebak ini adalah satu-satunya pilihan.",
  ui_story_5036_50360302_73_dialog_content = "Sulit dipercaya...",
  ui_story_5036_50360302_74_dialog_content = "bahwa saya akan melakukan sesuatu seperti ini pada usia saya.",
  ui_story_5036_50360302_75_dialog_content = "Groar!",
  ui_story_5036_50360302_76_dialog_content = "Hush!",
  ui_story_5036_50360302_77_dialog_content = "<size=35>Mengaum?</size>",
  ui_story_5036_50360302_78_dialog_content = "Sudah larut, Drako kecil.",
  ui_story_5036_50360302_79_dialog_content = "Anda akan menakut-nakuti orang dengan menjadi begitu keras.",
  ui_story_5036_50360302_80_dialog_content = "Saya tidak ingin menonjol seperti ibu jari yang sakit segera.",
  ui_story_5036_50360302_81_dialog_content = "*Tersedu*",
  ui_story_5036_50360302_82_dialog_content = "Oke, kamu cepat kembali ke Fia sekarang.",
  ui_story_5036_50360302_83_dialog_content = "Tapi ingat...",
  ui_story_5036_50360302_84_dialog_content = "Jangan ungkapkan keberadaanku padanya.",
  ui_story_5036_50360401_1_dialog_content = "Ini aku, pemimpin redaksi!",
  ui_story_5036_50360401_2_dialog_content = "Bagaimana saya tahu siapa Anda jika Anda tidak memberi tahu saya nama Anda?",
  ui_story_5036_50360401_3_dialog_content = "... Ini Brandy.",
  ui_story_5036_50360401_4_dialog_content = "Oh, aku ingat sekarang.",
  ui_story_5036_50360401_5_dialog_content = "Magang yang hanya menulis artikel membosankan.",
  ui_story_5036_50360401_6_dialog_content = "Saya pikir Anda sudah berhenti.",
  ui_story_5036_50360401_7_dialog_content = "Kau bilang kau akan memberiku satu kesempatan terakhir.",
  ui_story_5036_50360401_8_dialog_content = "Ah, sepertinya aku mengingat sesuatu seperti itu... Jadi, apakah kamu punya kabar baik untukku?",
  ui_story_5036_50360401_9_dialog_content = "Ya! Tebak apa?",
  ui_story_5036_50360401_10_dialog_content = "Saya di Eulogoz sekarang, Colossus Pengembara yang dibicarakan semua orang!",
  ui_story_5036_50360401_11_dialog_content = "Lalu?",
  ui_story_5036_50360401_12_dialog_content = "Saat terbang di atas Umbraton, akan ada konser besar di dalamnya!",
  ui_story_5036_50360401_13_dialog_content = "Saya memiliki jadwal yang padat, jadi beri tahu saya sesuatu yang tidak saya ketahui.",
  ui_story_5036_50360401_14_dialog_content = "Oh, dan...",
  ui_story_5036_50360401_15_dialog_content = "Saya terpilih menjadi reporter resmi untuk konser tersebut dan saya juga akan menjadi pembawa acara audisi idola!",
  ui_story_5036_50360401_16_dialog_content = "Anda bangga melaporkan siaran pers resmi?",
  ui_story_5036_50360401_17_dialog_content = "Sepertinya kamu masih belum mengerti.",
  ui_story_5036_50360401_18_dialog_content = "Yang saya inginkan adalah bagian dalam sendok yang cukup panas untuk menarik perhatian!",
  ui_story_5036_50360401_19_dialog_content = "Apa?",
  ui_story_5036_50360401_20_dialog_content = "... Di dalam sendok?",
  ui_story_5036_50360401_21_dialog_content = "<color=#e8d9bb>Lima hari menuju konser</color>",
  ui_story_5036_50360401_22_dialog_content = "Maaf membuat Anda menunggu, kontestan sayang!",
  ui_story_5036_50360401_23_dialog_content = "Selamat datang di audisi untuk <color=#FFB400>Konser Langit 'The Moment the Stars Shine Brightest'</color>.",
  ui_story_5036_50360401_24_dialog_content = "Bagaimana perasaan Anda menaiki Colossus dengan kapal udara eksklusif?",
  ui_story_5036_50360401_25_dialog_content = "Bergairah? Gembira? Grogi? Sangat senang?",
  ui_story_5036_50360401_26_dialog_content = "Tapi ada lebih banyak kegembiraan dan sensasi yang akan datang.",
  ui_story_5036_50360401_27_dialog_content = "Saya dengan ini mengumumkan dimulainya putaran pertama audisi!",
  ui_story_5036_50360401_28_dialog_content = "Ohhh! Ini dia!",
  ui_story_5036_50360401_29_dialog_content = "Harap diam sejenak sementara saya menjelaskan aturannya.",
  ui_story_5036_50360401_30_dialog_content = "Seperti yang Anda lihat, kami memiliki panel yang terdiri dari enam juri.",
  ui_story_5036_50360401_31_dialog_content = "Anda dipersilakan untuk berbicara dengan saya tentang game sim favorit Anda!",
  ui_story_5036_50360401_32_dialog_content = "Saya akan menilai nyanyian, tarian, visual, figur, EQ, dan IQ Anda.",
  ui_story_5036_50360401_33_dialog_content = "Anda harus unggul hanya dalam satu dari enam untuk mendapatkan suara saya.",
  ui_story_5036_50360401_34_dialog_content = "Saya mencari penampilan yang sangat altruistik, sehat, murni, dan pantas yang layak untuk para bangsawan...",
  ui_story_5036_50360401_35_dialog_content = "Apakah Anda mampu?",
  ui_story_5036_50360401_36_dialog_content = "Pergi, semuanya.",
  ui_story_5036_50360401_37_dialog_content = "Saya berharap untuk menerangi langit dengan Anda!",
  ui_story_5036_50360401_38_dialog_content = "Halo semua. Saya akan memperhatikan penampilan Anda!",
  ui_story_5036_50360401_39_dialog_content = "Aturannya sederhana, yang Anda butuhkan hanyalah empat suara dari juri...",
  ui_story_5036_50360401_40_dialog_content = "dan Anda akan maju ke babak berikutnya untuk mendapat kesempatan tampil di panggung konser.",
  ui_story_5036_50360401_41_dialog_content = "Mereka yang menerima suara bulat secara otomatis dapat tampil di konser!",
  ui_story_5036_50360401_42_dialog_content = "Jika Anda tidak maju, jangan khawatir, karena setiap orang mendapat tiga kesempatan.",
  ui_story_5036_50360401_43_dialog_content = "Jangan ragu untuk menggunakan ruangan di Eulogoz untuk berlatih.",
  ui_story_5036_50360401_44_dialog_content = "Sekarang, mari kita mulai acaranya!",
  ui_story_5036_50360401_45_dialog_content = "Silakan datang dan tampil ketika nomor Anda dipanggil!",
  ui_story_5036_50360401_46_dialog_content = "Nomor 1, Paduan Suara Illumina!",
  ui_story_5036_50360401_47_dialog_content = "Audisi sudah dimulai. Anda tidak ingin memeriksanya?",
  ui_story_5036_50360401_48_dialog_content = "Tidak, tidak sekarang.",
  ui_story_5036_50360401_49_dialog_content = "Aku masih belum memutuskan apa yang akan kulakukan.",
  ui_story_5036_50360401_50_dialog_content = "Jika saya menonton sekarang, itu hanya akan membuat saya semakin gugup.",
  ui_story_5036_50360401_51_dialog_content = "Aku juga belum memutuskan apa yang harus dilakukan.",
  ui_story_5036_50360401_52_dialog_content = "Kami mendaftar sebagian besar karena kami khawatir tidak akan ada cukup peserta.",
  ui_story_5036_50360401_53_dialog_content = "Tapi melihat berapa banyak orang di sini, aku benar-benar berpikir...",
  ui_story_5036_50360401_54_dialog_content = "Mungkin aku tidak dibutuhkan.",
  ui_story_5036_50360401_55_dialog_content = "Apa? Saya mendengar Illumina dan Lumopolis mendapat slot yang dipesan.",
  ui_story_5036_50360401_56_dialog_content = "Illumina memilih Paduan Suara, dan saya pikir Anda akan mendapatkan slot Lumopolis.",
  ui_story_5036_50360401_57_dialog_content = "Itu penampilan kami. Terima kasih!",
  ui_story_5036_50360401_58_dialog_content = "Gerakan Anda tersinkronisasi dengan baik dan energik, dan Anda menyanyikan lagu-lagu inspirasional yang benar-benar menjadi contoh prajurit Illumina!",
  ui_story_5036_50360401_59_dialog_content = "Saya tahu grup Anda selalu melakukan tur di seluruh Illumina, dan keakraban Anda dengan panggung terlihat jelas.",
  ui_story_5036_50360401_60_dialog_content = "Aku suka nyanyianmu! Semoga berhasil!",
  ui_story_5036_50360401_61_dialog_content = "Terima kasih.",
  ui_story_5036_50360401_62_dialog_content = "Sekarang, Paduan Suara Illumina mendapat...",
  ui_story_5036_50360401_63_dialog_content = "Semua 6 suara!",
  ui_story_5036_50360401_64_dialog_content = "Mereka melewati tekanan audisi terlebih dahulu dan mendapat kesempatan untuk tampil di konser! Selamat!",
  ui_story_5036_50360401_65_dialog_content = "Terima kasih! Kami tidak akan mengecewakan penonton!",
  ui_story_5036_50360401_66_dialog_content = "Oke selanjutnya ada Lumopolis Choir, Keating!",
  ui_story_5036_50360401_67_dialog_content = "Jadi begitulah cara kerjanya.",
  ui_story_5036_50360401_68_dialog_content = "Sayang sekali melewatkan kesempatan langka seperti itu.",
  ui_story_5036_50360401_69_dialog_content = "Itulah mengapa itu harus disediakan untuk mereka yang pantas mendapatkannya.",
  ui_story_5036_50360401_70_dialog_content = "Apa apaan?",
  ui_story_5036_50360401_71_dialog_content = "Hmm?",
  ui_story_5036_50360401_72_dialog_content = "Jadi aku satu-satunya yang mengikuti audisi sekarang?",
  ui_story_5036_50360401_73_dialog_content = "Oh tunggu, aku tahu!",
  ui_story_5036_50360401_74_dialog_content = "Mereka juga akan melihat konser di Lumopolis...",
  ui_story_5036_50360401_75_dialog_content = "Apakah Anda terlalu malu untuk tampil untuk penonton tuan rumah Anda, Carleen?",
  ui_story_5036_50360401_76_dialog_content = "Sama sekali tidak!",
  ui_story_5036_50360401_77_dialog_content = "Lalu buktikan.",
  ui_story_5036_50360401_78_dialog_content = "Tunjukkan kepada semua orang apa yang Anda mampu.",
  ui_story_5036_50360401_79_dialog_content = "Ini adalah ♪",
  ui_story_5036_50360401_80_dialog_content = "Penampilan kami ♪",
  ui_story_5036_50360401_81_dialog_content = "Sekarang silakan mulai ♪",
  ui_story_5036_50360401_82_dialog_content = "Penampilanmu ♪",
  ui_story_5036_50360401_83_dialog_content = "Rahmat yang luar biasa!",
  ui_story_5036_50360401_84_dialog_content = "Tidak heran Anda dipilih oleh Lord Schwartz sendiri!",
  ui_story_5036_50360401_85_dialog_content = "Suara mereka benar-benar ilahi dan telah membersihkan saya luar dalam.",
  ui_story_5036_50360401_86_dialog_content = "Rakyat jelata harus menghargai ini.",
  ui_story_5036_50360401_87_dialog_content = "Anda diberkati oleh Dewa Cahaya untuk dapat mendengar himne yang begitu sakral.",
  ui_story_5036_50360401_88_dialog_content = "Tindakanmu ♪",
  ui_story_5036_50360401_89_dialog_content = "Konyol ♪",
  ui_story_5036_50360401_90_dialog_content = "Kata-katamu ♪",
  ui_story_5036_50360401_91_dialog_content = "Apakah sanjungan kosong ♪",
  ui_story_5036_50360401_92_dialog_content = "Dengar itu? Mereka merdu bahkan ketika mereka berbicara!",
  ui_story_5036_50360401_93_dialog_content = "Anda tidak bisa membedakan sanjungan dari ejekan.",
  ui_story_5036_50360401_94_dialog_content = "Apa ini...?",
  ui_story_5036_50360401_95_dialog_content = "Keating juga mendapat 6 suara dan langsung menuju ke konser! Selamat!",
  ui_story_5036_50360401_96_dialog_content = "Kedua kontestan? Ini tidak dicurangi, bukan?",
  ui_story_5036_50360401_97_dialog_content = "Apakah Anda kontestan no. 3, Barbara?",
  ui_story_5036_50360401_98_dialog_content = "Itu aku, Barbara!",
  ui_story_5036_50360401_99_dialog_content = "Abaikan wanita berisik itu. Aku, Barbara, benar-benar terlahir untuk menjadi idola!",
  ui_story_5036_50360401_100_dialog_content = "Ha, mungkin Anda harus memastikan bahwa Anda dapat mencapai catatan Anda sebelum naik ke atas panggung!",
  ui_story_5036_50360401_101_dialog_content = "Mengapa Anda tidak menghabiskan lebih sedikit waktu untuk mengkritik saya dan lebih banyak waktu belajar untuk benar-benar bernyanyi?",
  ui_story_5036_50360401_102_dialog_content = "Saatnya kalian berdua tampil.",
  ui_story_5036_50360401_103_dialog_content = "Saya tidak percaya ini.",
  ui_story_5036_50360401_104_dialog_content = "Bagaimana Rediesel Wrench bisa berakhir dengan seseorang yang memiliki selera musik yang sama buruknya dengan Anda?",
  ui_story_5036_50360401_105_dialog_content = "Oh wow, lihat siapa yang berbicara ...",
  ui_story_5036_50360401_106_dialog_content = "Anda benar-benar berpikir siapa pun di Rediesel Wrench menyukai suara jelek Anda?",
  ui_story_5036_50360401_107_dialog_content = "Apa? Katakan itu lagi!",
  ui_story_5036_50360401_108_dialog_content = "aku menantangmu!",
  ui_story_5036_50360401_109_dialog_content = "Hei, kenapa ada orang lain di atas panggung?",
  ui_story_5036_50360401_110_dialog_content = "Saya nomor 3!",
  ui_story_5036_50360401_111_dialog_content = "Maaf Barbara, dan entri no. 4, Reina...",
  ui_story_5036_50360401_112_dialog_content = "Para hakim mendiskualifikasi Anda karena perilaku tidak tertib.",
  ui_story_5036_50360401_113_dialog_content = "Silakan mendaftar lagi untuk putaran berikutnya.",
  ui_story_5036_50360401_114_dialog_content = "Apa?!",
  ui_story_5036_50360401_115_dialog_content = "Oh, begitu.",
  ui_story_5036_50360401_116_dialog_content = "A-Apa yang kamu lihat?",
  ui_story_5036_50360401_117_dialog_content = "Apakah Anda merasa kesepian karena akan tampil sendiri?",
  ui_story_5036_50360401_118_dialog_content = "Tidak begitu keras...",
  ui_story_5036_50360401_119_dialog_content = "Baik, saya mengakuinya.",
  ui_story_5036_50360401_120_dialog_content = "Bagaimanapun juga, kami selalu melakukan semuanya bersama-sama sebagai sebuah kelompok.",
  ui_story_5036_50360401_121_dialog_content = "Rasanya agak aneh tiba-tiba pergi sendirian.",
  ui_story_5036_50360401_122_dialog_content = "Baiklah kalau begitu.",
  ui_story_5036_50360401_123_dialog_content = "Kurasa aku bisa membantu seekor merpati yang kesepian.",
  ui_story_5036_50360401_124_dialog_content = "Aku bukan merpati kesepian!",
  ui_story_5036_50360401_125_dialog_content = "Hahahah...",
  ui_story_5036_50360401_126_dialog_content = "Namun, dibandingkan dengan berdiri di sana sendirian ...",
  ui_story_5036_50360401_127_dialog_content = "Aku rindu bagaimana rasanya berada di atas panggung bersamamu.",
  ui_story_5036_50360401_128_dialog_content = "Hah?",
  ui_story_5036_50360401_129_dialog_content = "Ada apa dengan nostalgia yang tiba-tiba?",
  ui_story_5036_50360401_130_dialog_content = "Yah, pokoknya, saya hanya berpikir orang saya dulu akan jauh lebih bersemangat untuk tampil.",
  ui_story_5036_50360401_131_dialog_content = "Sebenarnya aku juga...",
  ui_story_5036_50360401_132_dialog_content = "Sayang sekali.",
  ui_story_5036_50360401_133_dialog_content = "Sejauh ini tidak ada kontestan yang berhasil masuk ke konser selain dua kontestan pertama kami.",
  ui_story_5036_50360401_134_dialog_content = "Sekarang, mari sambut peserta terakhir untuk hari ini.",
  ui_story_5036_50360401_135_dialog_content = "Performa apa yang dia miliki untuk kita?",
  ui_story_5036_50360401_136_dialog_content = "Halo semuanya.",
  ui_story_5036_50360401_137_dialog_content = "saya Vic. Saya seorang pelatih binatang yang menakjubkan.",
  ui_story_5036_50360401_138_dialog_content = "Vik?!",
  ui_story_5036_50360401_139_dialog_content = "PlayerName?",
  ui_story_5036_50360401_140_dialog_content = "Saya tidak menyangka akan melihat wajah yang familiar di panitia seleksi.",
  ui_story_5036_50360401_141_dialog_content = "Saya harus mengklarifikasi bahwa saya benar-benar tidak tahu PlayerName akan menjadi hakim.",
  ui_story_5036_50360401_142_dialog_content = "Ini benar-benar kamu!",
  ui_story_5036_50360401_143_dialog_content = "Saya pikir saya salah... Mengapa Anda mendaftar untuk ini?",
  ui_story_5036_50360401_144_dialog_content = "Karena saya ingin menjadi idola dan tampil di panggung yang unik ini.",
  ui_story_5036_50360401_145_dialog_content = "Aku tidak pernah tahu kau ingin menjadi idola.",
  ui_story_5036_50360401_146_dialog_content = "Dari apa yang saya tahu, Anda sudah membuat nama untuk diri Anda sendiri di dunia pelatihan binatang yang menakjubkan.",
  ui_story_5036_50360401_147_dialog_content = "Siapa bilang ahli ekstrozoologi tidak bisa menjadi idola?",
  ui_story_5036_50360401_148_dialog_content = "Hanya aku yang bisa memutuskan itu!",
  ui_story_5036_50360401_149_dialog_content = "Di zaman sekarang ini, siapapun bisa menjadi idola...",
  ui_story_5036_50360401_150_dialog_content = "dan nikmati ketenaran mereka selama 15 menit dalam sorotan.",
  ui_story_5036_50360401_151_dialog_content = "\"Di zaman sekarang ini, siapa pun bisa menjadi idola,\" katamu?",
  ui_story_5036_50360401_152_dialog_content = "Ditempatkan dengan sangat baik!",
  ui_story_5036_50360401_153_dialog_content = "Saya menghargai sikap dan pengertian Anda tentang bisnis ini. Saya menantikan tindakan Anda!",
  ui_story_5036_50360401_154_dialog_content = "Wow, ini adalah kontestan pertama sejauh ini yang menarik perhatian Miss Goldie sendiri!",
  ui_story_5036_50360401_155_dialog_content = "Jadi penampilan menarik apa yang akan dia bawakan untuk kita?",
  ui_story_5036_50360401_156_dialog_content = "Silakan mulai, Vic!",
  ui_story_5036_50360401_157_dialog_content = "Saya akan membacakan sesuatu untuk Anda semua. Ahem...",
  ui_story_5036_50360401_158_dialog_content = "Ah! Musim semi telah tiba, dan bumi kembali hidup!",
  ui_story_5036_50360401_159_dialog_content = "Sekali lagi ini adalah musim di mana binatang-binatang yang menakjubkan menunjukkan kekuatan mereka.",
  ui_story_5036_50360401_160_dialog_content = "(Saya bahkan tidak yakin ini memenuhi syarat sebagai kinerja ...)",
  ui_story_5036_50360401_161_dialog_content = "(Tapi sepertinya Vic sedang membacakan Ensiklopedia Exotica miliknya?!)",
  ui_story_5036_50360401_162_dialog_content = "Sayang! Kemuliaan hidup memenuhi setiap jengkal tanah, baik itu hutan atau dataran!",
  ui_story_5036_50360401_163_dialog_content = "Namun di tengah hiruk pikuk ini, ada satu makhluk yang menjadi pengecualian.",
  ui_story_5036_50360401_164_dialog_content = "Itu <color=#FFB400>Ouroboros</color> adalah salah satu <color=#FFB400> hidup paling lama </color> binatang yang menakjubkan di Astra.",
  ui_story_5036_50360401_165_dialog_content = "Ketika mereka mencapai kedewasaan—",
  ui_story_5036_50360401_166_dialog_content = "Maaf, izinkan saya mengganggu Anda sebentar!",
  ui_story_5036_50360401_167_dialog_content = "Para juri bertanya-tanya apakah Anda memiliki hal lain untuk ditunjukkan kepada kami?",
  ui_story_5036_50360401_168_dialog_content = "Yah, tidak... Aku hanya menyiapkan narasi dramatis ini untuk hari ini.",
  ui_story_5036_50360401_169_dialog_content = "Begitu... Sayang sekali.",
  ui_story_5036_50360401_170_dialog_content = "Anda melakukannya dengan baik dalam bacaan Anda, tetapi itu tidak sesuai dengan yang kami cari.",
  ui_story_5036_50360401_171_dialog_content = "Tapi jangan merendahkan diri sendiri!",
  ui_story_5036_50360401_172_dialog_content = "Anda memang memiliki suara yang sangat bagus, dan juga visual yang sangat bagus.",
  ui_story_5036_50360401_173_dialog_content = "Saya yakin Anda akan melakukannya dengan baik beralih ke bernyanyi atau menari.",
  ui_story_5036_50360401_174_dialog_content = "Tidak akan mengejutkan saya jika suatu hari Anda bahkan melampaui beberapa penghibur berpengalaman.",
  ui_story_5036_50360401_175_dialog_content = "Saya berharap untuk melihat yang berbeda dari Anda di babak selanjutnya.",
  ui_story_5036_50360401_176_dialog_content = "Saya pikir Anda memiliki potensi besar, jadi teruslah berjuang!",
  ui_story_5036_50360401_177_dialog_content = "Ah, saya kira saya akan mencoba lagi.",
  ui_story_5036_50360401_178_dialog_content = "(Goldie menatap Vic seolah dia baru saja menemukan permata tersembunyi...)",
  ui_story_5036_50360401_179_dialog_content = "(Apakah Vic benar-benar memiliki apa yang diperlukan untuk menjadi seorang idola?)",
  ui_story_5036_50360401_180_dialog_content = "Terima kasih untuk semua kandidat dan juri! Audisi hari ini telah berakhir.",
  ui_story_5036_50360401_181_dialog_content = "Pastikan Anda mendengarkan putaran audisi mendatang!",
  ui_story_5036_50360401_182_dialog_content = "Baik, sampai jumpa besok!",
  ui_story_5036_50360401_183_dialog_content = "PlayerName, Goldie, sudah selesai?",
  ui_story_5036_50360401_184_dialog_content = "Ya. Saya pikir akan santai untuk menonton pertunjukan, tetapi sebenarnya saya sangat membutuhkannya.",
  ui_story_5036_50360401_185_dialog_content = "Ngomong-ngomong, kenapa kalian tidak muncul?",
  ui_story_5036_50360401_186_dialog_content = "Kami ingin berlatih lagi sebelum bergabung.",
  ui_story_5036_50360401_187_dialog_content = "Kalian berlatih bersama?",
  ui_story_5036_50360401_188_dialog_content = "Ya. Kami pikir akan lebih menyenangkan untuk masuk sebagai duo.",
  ui_story_5036_50360401_189_dialog_content = "Jangan terlihat begitu terkejut. Anda mendengarnya dengan benar.",
  ui_story_5036_50360401_190_dialog_content = "Vice dan aku akan tampil sebagai duo.",
  ui_story_5036_50360401_191_dialog_content = "Itu ide yang bagus!",
  ui_story_5036_50360401_192_dialog_content = "Apakah Anda sudah tahu apa yang akan Anda lakukan?",
  ui_story_5036_50360401_193_dialog_content = "Kami akan bernyanyi. Kami sudah memilih beberapa lagu.",
  ui_story_5036_50360401_194_dialog_content = "Tapi kita harus berlatih sebelum memutuskan mana yang akan dipilih.",
  ui_story_5036_50360401_195_dialog_content = "Sejujurnya, aku tidak tahu apakah kita bisa membuatnya...",
  ui_story_5036_50360401_196_dialog_content = "Jangan khawatir. Izinkan saya memberi tahu Anda sebuah rahasia.",
  ui_story_5036_50360401_197_dialog_content = "Sebenarnya aku juga belum memutuskan lagu apa yang akan dinyanyikan.",
  ui_story_5036_50360401_198_dialog_content = "Anda pasti memiliki banyak pilihan lagu sendiri untuk dipilih, bukan?",
  ui_story_5036_50360401_199_dialog_content = "Ya, tapi saya rasa tidak ada yang cocok untuk panggung di Eulogoz.",
  ui_story_5036_50360401_200_dialog_content = "Tapi tidak apa-apa. Mungkin saya akan mengetahuinya dalam beberapa hari ke depan.",
  ui_story_5036_50360401_201_dialog_content = "Maksud Anda, Anda sedang menulis lagu baru hanya untuk Eulogoz?",
  ui_story_5036_50360401_202_dialog_content = "Ssst, jangan terlalu keras! Tapi ya, itulah idenya.",
  ui_story_5036_50360401_203_dialog_content = "Saya tidak yakin apakah saya bisa melakukannya, jadi tolong rahasiakan.",
  ui_story_5036_50360401_204_dialog_content = "Apakah Anda menulis semua lagu Anda?",
  ui_story_5036_50360401_205_dialog_content = "Mengesankan sekali!",
  ui_story_5036_50360401_206_dialog_content = "Tidak semuanya, tidak.",
  ui_story_5036_50360401_207_dialog_content = "Hanya saja melodi atau ketukan kadang-kadang muncul di benak saya.",
  ui_story_5036_50360401_208_dialog_content = "Kemudian saya mencoba menuliskannya dan membuatnya menjadi sebuah lagu.",
  ui_story_5036_50360401_209_dialog_content = "Tapi tidak setiap saat saya mendapatkan melodi yang saya inginkan.",
  ui_story_5036_50360401_210_dialog_content = "Melodi yang muncul di benak Anda...?",
  ui_story_5036_50360401_211_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360401_212_dialog_content = "♪ La la la la... ♪",
  ui_story_5036_50360401_213_dialog_content = "Jadi eh, sejak saya berada dalam jarak dekat dengan Eulogoz, saya mendengar lagu-lagu di kepala saya.",
  ui_story_5036_50360401_214_dialog_content = "Saya bahkan akan mengatakan itu bukan melodi seperti seseorang yang benar-benar bersenandung.",
  ui_story_5036_50360401_215_dialog_content = "Sungguh?",
  ui_story_5036_50360401_216_dialog_content = "Saya mendengar bahwa Caelestites adalah ras yang menyukai musik.",
  ui_story_5036_50360401_217_dialog_content = "Mungkin Anda memiliki ketertarikan alami untuk membuat musik!",
  ui_story_5036_50360401_218_dialog_content = "K-Menurutmu?",
  ui_story_5036_50360401_219_dialog_content = "Mungkinkah Eugoloz mengirimi saya inspirasi?",
  ui_story_5036_50360401_220_dialog_content = "Itu mungkin!",
  ui_story_5036_50360401_221_dialog_content = "Masuk akal.",
  ui_story_5036_50360401_222_dialog_content = "Eulogoz milik Caelestites.",
  ui_story_5036_50360401_223_dialog_content = "Jika saya bisa menyanyikan lagu yang dibuat oleh Caelestite di Eulogoz, itu akan sangat berarti!",
  ui_story_5036_50360401_224_dialog_content = "PlayerName!",
  ui_story_5036_50360401_225_dialog_content = "Jika Anda tidak keberatan, bisakah Anda berbagi melodi yang muncul di kepala Anda?",
  ui_story_5036_50360401_226_dialog_content = "Tentu saja saya tidak keberatan.",
  ui_story_5036_50360401_227_dialog_content = "Berhenti-!",
  ui_story_5036_50360401_228_dialog_content = "Ada apa?",
  ui_story_5036_50360401_229_dialog_content = "Astaga!",
  ui_story_5036_50360401_230_dialog_content = "Sepertinya kita harus menunggu itu, PlayerName!",
  ui_story_5036_50360402_1_dialog_content = "Maaf mengganggu Anda!",
  ui_story_5036_50360402_2_dialog_content = "Seorang penjaga pingsan di area kuncian saat membersihkan Eclipsites, yang membuat mereka keluar.",
  ui_story_5036_50360402_3_dialog_content = "Syukurlah, para prajurit dari Illumina dan Lumopolis membantu kami.",
  ui_story_5036_50360402_4_dialog_content = "Bagaimana dengan penjaganya? Apakah dia terluka?",
  ui_story_5036_50360402_5_dialog_content = "Dia sadar dan seharusnya baik-baik saja.",
  ui_story_5036_50360402_6_dialog_content = "Apakah karena berurusan dengan Eclipsites di area lockdown terlalu melelahkan?",
  ui_story_5036_50360402_7_dialog_content = "Kami mengikuti saran Anda dan memberi semua orang banyak istirahat, jadi semuanya tidak terlalu buruk.",
  ui_story_5036_50360402_8_dialog_content = "Dia bilang dia pingsan karena dia tidak punya apa-apa untuk dimakan.",
  ui_story_5036_50360402_9_dialog_content = "Bukankah kita menyediakan makanan yang cukup?",
  ui_story_5036_50360402_10_dialog_content = "Nah, seseorang mencuri bagiannya, dan dia tidak punya waktu untuk mendapatkan penggantinya.",
  ui_story_5036_50360402_11_dialog_content = "Seseorang mencuri makanannya?",
  ui_story_5036_50360402_12_dialog_content = "Tidak mungkin, jangan bilang mereka menangkapku juga!",
  ui_story_5036_50360402_13_dialog_content = "Apakah Anda terluka, prajurit?",
  ui_story_5036_50360402_14_dialog_content = "Aku baik-baik saja, Wakil Letnan!",
  ui_story_5036_50360402_15_dialog_content = "Hanya saja jatah yang saya miliki tampaknya hilang.",
  ui_story_5036_50360402_16_dialog_content = "Kamu juga?",
  ui_story_5036_50360402_17_dialog_content = "Ya. Orang-orang di sekitar saya semua mengalami hal yang sama terjadi pada mereka.",
  ui_story_5036_50360402_18_dialog_content = "Jatah kami terus menghilang secara misterius.",
  ui_story_5036_50360402_19_dialog_content = "Saya pikir membawa ransum saya pada saya akan aman, namun ...",
  ui_story_5036_50360402_20_dialog_content = "Mungkin kalian kehilangan mereka saat melawan Eclipsites?",
  ui_story_5036_50360402_21_dialog_content = "Itu juga yang kami pikirkan, jadi kami tidak melaporkannya.",
  ui_story_5036_50360402_22_dialog_content = "Itu <color=#FFB400>pencuri hantu</color>... Itu pasti si pencuri hantu!",
  ui_story_5036_50360402_23_dialog_content = "Pencuri hantu?",
  ui_story_5036_50360402_24_dialog_content = "Ada pencuri hantu di Colossus, Lady Carleen!",
  ui_story_5036_50360402_25_dialog_content = "Pencuri menjatuhkan Anda saat Anda tidak menduganya.",
  ui_story_5036_50360402_26_dialog_content = "Maka itu mengambil semua barang berharga Anda tanpa terlihat!",
  ui_story_5036_50360402_27_dialog_content = "Begitulah cara saya kehilangan arloji saku batu permata saya.",
  ui_story_5036_50360402_28_dialog_content = "Mencuri makanan dan perhiasan?",
  ui_story_5036_50360402_29_dialog_content = "Itu tidak terdengar seperti sesuatu yang akan dilakukan Eclipsites.",
  ui_story_5036_50360402_30_dialog_content = "Jadi kita punya pencuri di tangan kita...",
  ui_story_5036_50360402_31_dialog_content = "Anda tahu, entah bagaimana, ini terdengar familiar.",
  ui_story_5036_50360402_32_dialog_content = "Di mana saya pernah melihat situasi yang sama sebelumnya ...",
  ui_story_5036_50360402_33_dialog_content = "Mungkinkah pencopet profesional naik ke Wandering Colossus?",
  ui_story_5036_50360402_34_dialog_content = "Tentara bayaran juga menyadari masalah ini, Nona Goldie.",
  ui_story_5036_50360402_35_dialog_content = "Bukan hanya kami, tetapi bahkan mereka yang mendaftar untuk audisi mengeluh tentang kehilangan permen dan minuman.",
  ui_story_5036_50360402_36_dialog_content = "Kutukan, mengapa penjahat harus muncul jauh-jauh di langit?!",
  ui_story_5036_50360402_37_dialog_content = "Saya khawatir pencuri itu akan mengecewakan calon audisi, Goldie.",
  ui_story_5036_50360402_38_dialog_content = "Carleen benar. Masalah yang paling mendesak adalah memastikan pencuri tidak menyebabkan mereka kehilangan kepercayaan pada tuan rumah konser.",
  ui_story_5036_50360402_39_dialog_content = "Maukah Anda mengirim seseorang untuk membeli kiriman makanan dan minuman lagi dari Umbraton?",
  ui_story_5036_50360402_40_dialog_content = "Kami harus memastikan semua kontestan dan prajurit di Eulogoz diberi makan.",
  ui_story_5036_50360402_41_dialog_content = "Mempertimbangkan volume yang terlibat, saya harus mengirim lebih banyak orang.",
  ui_story_5036_50360402_42_dialog_content = "Silakan lakukan, dan sertakan biaya dalam tagihan.",
  ui_story_5036_50360402_43_dialog_content = "Siap!",
  ui_story_5036_50360402_44_dialog_content = "...",
  ui_story_5036_50360402_45_dialog_content = "Apakah kamu baik-baik saja, Goldie?",
  ui_story_5036_50360402_46_dialog_content = "...",
  ui_story_5036_50360402_47_dialog_content = "Goldie?",
  ui_story_5036_50360402_48_dialog_content = "Hm? Hah... Ya, aku baik-baik saja, jangan khawatirkan aku!",
  ui_story_5036_50360402_49_dialog_content = "Fokus pada latihanmu dan jangan khawatir tentang ini, Carleen, Vice.",
  ui_story_5036_50360402_50_dialog_content = "Saya benar-benar akan...",
  ui_story_5036_50360402_51_dialog_content = "Saya benar-benar tidak akan membiarkan siapa pun menghentikan konser itu terjadi!",
  ui_story_5036_50360501_1_dialog_content = "tentara bayaran...",
  ui_story_5036_50360501_2_dialog_content = "Apa yang kamu lakukan?!",
  ui_story_5036_50360501_3_dialog_content = "Panggung luar biasa yang telah Anda bangun!",
  ui_story_5036_50360501_4_dialog_content = "Anda benar-benar membersihkan layar Eugoloz, dan melengkapinya dengan pencahayaan warna-warni!",
  ui_story_5036_50360501_5_dialog_content = "Percayalah saat aku mengatakan ini...",
  ui_story_5036_50360501_6_dialog_content = "Tahap ini lebih menakjubkan daripada yang pernah saya lihat di Umbraton!",
  ui_story_5036_50360501_7_dialog_content = "Terima kasih atas pujiannya, Nona Goldie.",
  ui_story_5036_50360501_8_dialog_content = "Kami hanya mengikuti instruksi Ms. Sheol.",
  ui_story_5036_50360501_9_dialog_content = "Tidak, kalian berbeda.",
  ui_story_5036_50360501_10_dialog_content = "Lady Sheol mengatakan sebagian besar tentara bayaran melakukan pekerjaan yang buruk dan ceroboh.",
  ui_story_5036_50360501_11_dialog_content = "Hanya White Flames yang bisa diandalkan untuk selalu teliti dan bisa diandalkan.",
  ui_story_5036_50360501_12_dialog_content = "Sayang sekali, meskipun ...",
  ui_story_5036_50360501_13_dialog_content = "bahwa tempat yang menakjubkan seperti itu hanya akan dilakukan sekaligus.",
  ui_story_5036_50360501_14_dialog_content = "Jika Anda mau, Nona Goldie...",
  ui_story_5036_50360501_15_dialog_content = "Kami dapat membangun panggung yang sama untuk Anda nanti di Umbraton.",
  ui_story_5036_50360501_16_dialog_content = "Lagi?",
  ui_story_5036_50360501_17_dialog_content = "Dengan asumsi aku masih menjadi idola saat itu...",
  ui_story_5036_50360501_18_dialog_content = "Hah?",
  ui_story_5036_50360501_19_dialog_content = "Sudahlah. Ada berita tentang pencuri itu?",
  ui_story_5036_50360501_20_dialog_content = "Tidak ada sejauh ini.",
  ui_story_5036_50360501_21_dialog_content = "Pelakunya cukup licik. Kami belum memiliki petunjuk yang kuat.",
  ui_story_5036_50360501_22_dialog_content = "Yang kami tahu adalah bahwa kebanyakan barang dicuri pada malam hari.",
  ui_story_5036_50360501_23_dialog_content = "Itu awal.",
  ui_story_5036_50360501_24_dialog_content = "Aku akan berpatroli denganmu di malam hari.",
  ui_story_5036_50360501_25_dialog_content = "Anda akan berpatroli dengan kami?",
  ui_story_5036_50360501_26_dialog_content = "Haha, kamu adalah orang pertama yang menolak ditemani idola terkenal.",
  ui_story_5036_50360501_27_dialog_content = "Saya tidak akan berani! Saya hanya khawatir itu akan memakan waktu lama dari penulisan lagu Anda.",
  ui_story_5036_50360501_28_dialog_content = "Oh, jangan pernah meremehkan apa yang bisa dilakukan oleh seorang idola!",
  ui_story_5036_50360501_29_dialog_content = "Saya punya banyak lagu yang bisa saya nyanyikan di atas panggung.",
  ui_story_5036_50360501_30_dialog_content = "Saya ingin sekali menulis lagu baru untuk melodi Caelestite...",
  ui_story_5036_50360501_31_dialog_content = "tetapi PlayerName hanya memberi saya beberapa catatan. Saya tidak tahu di mana saya bisa mengambilnya.",
  ui_story_5036_50360501_32_dialog_content = "Hanya beberapa catatan?",
  ui_story_5036_50360501_33_dialog_content = "Apakah kamu penasaran?",
  ui_story_5036_50360501_34_dialog_content = "U-Uh, aku tidak akan berani mengganggu...",
  ui_story_5036_50360501_35_dialog_content = "Tidak? Tapi saya memiliki keinginan untuk menyanyikannya di panggung baru ini.",
  ui_story_5036_50360501_36_dialog_content = "♪ La... ♪",
  ui_story_5036_50360501_37_dialog_content = "♪ La... La la la... ♪",
  ui_story_5036_50360501_38_dialog_content = "Grahhhhhhhh!",
  ui_story_5036_50360501_39_dialog_content = "Eclipsites yang kabur... Mereka bersembunyi di bawah panggung!",
  ui_story_5036_50360501_40_dialog_content = "Mereka keluar begitu Nona Goldie mulai bernyanyi...",
  ui_story_5036_50360501_41_dialog_content = "Jangan bilang mereka juga Goldilocks?!",
  ui_story_5036_50360502_1_dialog_content = "Saya mendengar panggung akan selesai malam ini.",
  ui_story_5036_50360502_2_dialog_content = "Saya harus mengalahkan semua orang di sana untuk mendapatkan tembakan dari semua sudut!",
  ui_story_5036_50360502_3_dialog_content = "Yang saya inginkan adalah bagian dalam sendok yang cukup panas untuk menarik perhatian!",
  ui_story_5036_50360502_4_dialog_content = "Serius, bisakah editor membuat permintaan yang lebih sulit?",
  ui_story_5036_50360502_5_dialog_content = "Di mana saya harus masuk ke dalam sendok?",
  ui_story_5036_50360502_6_dialog_content = "Satu-satunya hal yang dapat saya lakukan adalah menjadi yang pertama melaporkan berita apa pun di Eulogoz.",
  ui_story_5036_50360502_7_dialog_content = "Hei, ada seseorang di atas panggung...",
  ui_story_5036_50360502_8_dialog_content = "Andai saja Eclipsites bisa menjadi Goldilocks...",
  ui_story_5036_50360502_9_dialog_content = "Anda menyukai Eclipsites?",
  ui_story_5036_50360502_10_dialog_content = "Apakah kamu bercanda?!",
  ui_story_5036_50360502_11_dialog_content = "M-maaf!",
  ui_story_5036_50360502_12_dialog_content = "Yah, itu salahku karena tidak mengklarifikasi.",
  ui_story_5036_50360502_13_dialog_content = "Saya hanya berpikir, alangkah baiknya jika Eclipsites dapat memahami lagu saya.",
  ui_story_5036_50360502_14_dialog_content = "Jika mereka dapat mendengar kasih dan kedamaian dalam diri mereka, mungkin itu akan mempengaruhi mereka",
  ui_story_5036_50360502_15_dialog_content = "untuk menghentikan perilaku biadab dan membunuh mereka.",
  ui_story_5036_50360502_16_dialog_content = "Heh... Apakah itu terkesan sombong atau apa?",
  ui_story_5036_50360502_17_dialog_content = "Pengaruh, biadab, ... membunuh?",
  ui_story_5036_50360502_18_dialog_content = "Apa yang Goldie katakan? Sulit untuk mengatakannya dari jarak sejauh ini.",
  ui_story_5036_50360502_19_dialog_content = "Kurasa aku harus sedikit lebih dekat...",
  ui_story_5036_50360502_20_dialog_content = "<color=#e8d9bb>Boing!</color>",
  ui_story_5036_50360502_21_dialog_content = "Oh ayolah! Bagaimana saya bisa seberuntung ini?",
  ui_story_5036_50360502_22_dialog_content = "Tentu saja saya harus menabrak peti kayu saat ini juga!",
  ui_story_5036_50360502_23_dialog_content = "Apakah mereka mendengar saya?",
  ui_story_5036_50360502_24_dialog_content = "Fiuh, kurasa mereka tidak melakukannya.",
  ui_story_5036_50360502_25_dialog_content = "Siapa di sana?",
  ui_story_5036_50360502_26_dialog_content = "Hah?",
  ui_story_5036_50360502_27_dialog_content = "Ups, aku tertangkap!",
  ui_story_5036_50360502_28_dialog_content = "Tidak masalah. Saya hanya akan menjelaskan bahwa saya hanya lewat. Nona Goldie pasti akan...",
  ui_story_5036_50360502_29_dialog_content = "percayalah padaku, kan?",
  ui_story_5036_50360502_30_dialog_content = "<color=#e8d9bb>*Menabrak*</color>",
  ui_story_5036_50360502_31_dialog_content = "Berhenti sekarang juga!",
  ui_story_5036_50360502_32_dialog_content = "Apa? Apa...?",
  ui_story_5036_50360502_33_dialog_content = "Goldie sepertinya berteriak ke arah lain?",
  ui_story_5036_50360502_34_dialog_content = "Apakah ada orang lain selain aku yang bersembunyi di sini?",
  ui_story_5036_50360502_35_dialog_content = "Anda bahkan lebih tanggap daripada pramuka kami, Nona Goldie!",
  ui_story_5036_50360502_36_dialog_content = "Saya tidak berpikir seseorang akan bersembunyi di bawah papan lantai.",
  ui_story_5036_50360502_37_dialog_content = "Sayang pelakunya kabur sebelum aku bisa mengangkatnya.",
  ui_story_5036_50360502_38_dialog_content = "Lihat, ransum setengah dimakan.",
  ui_story_5036_50360502_39_dialog_content = "Ini kemasan Illumina.",
  ui_story_5036_50360502_40_dialog_content = "Ransum iluminasi?",
  ui_story_5036_50360502_41_dialog_content = "Namun tidak ada tentara Illumina yang ditugaskan bekerja di dekat panggung.",
  ui_story_5036_50360502_42_dialog_content = "Ya. Orang-orang di sekitar saya semua mengalami hal yang sama terjadi pada mereka.",
  ui_story_5036_50360502_43_dialog_content = "Jatah kami terus menghilang secara misterius.",
  ui_story_5036_50360502_44_dialog_content = "Apa mungkin...",
  ui_story_5036_50360502_45_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_5036_50360502_46_dialog_content = "Apakah itu tikus?",
  ui_story_5036_50360502_47_dialog_content = "Tidak! Bukan tikus.",
  ui_story_5036_50360502_48_dialog_content = "Anda melihat benda itu melarikan diri, Marshmallow?",
  ui_story_5036_50360502_49_dialog_content = "Kejarlah!",
  ui_story_5036_50360502_50_dialog_content = "Guk, guk!",
  ui_story_5036_50360502_51_dialog_content = "Hai?",
  ui_story_5036_50360502_52_dialog_content = "Hai hai!",
  ui_story_5036_50360502_53_dialog_content = "Jangan ditangkap, Marshmallow. Ikuti saja dengan cermat untuk saat ini.",
  ui_story_5036_50360502_54_dialog_content = "Mungkin itu akan membawa kita ke <color=#FFB400>ikan yang lebih besar</color>.",
  ui_story_5036_50360502_55_dialog_content = "Hai—!",
  ui_story_5036_50360502_56_dialog_content = "Hah? Mendesah...",
  ui_story_5036_50360502_57_dialog_content = "Anda benar-benar mengabaikan saya beberapa menit yang lalu, Bica ...",
  ui_story_5036_50360502_58_dialog_content = "Sekarang kamu ingin berpelukan?",
  ui_story_5036_50360502_59_dialog_content = "Guk!",
  ui_story_5036_50360502_60_dialog_content = "Ahem. Ngomong-ngomong, bukankah sebaiknya kau tetap mengikat anjing gemukmu itu?",
  ui_story_5036_50360502_61_dialog_content = "Bica saya sangat sensitif dan mudah gugup, yang kemudian membuat perutnya sakit—",
  ui_story_5036_50360502_62_dialog_content = "Anda Pencuri Hantu?",
  ui_story_5036_50360502_63_dialog_content = "Hantu? Tidak mungkin.",
  ui_story_5036_50360502_64_dialog_content = "Tidak percaya padaku? Saya akan menggigit diri sendiri untuk membuktikannya. Aduh!",
  ui_story_5036_50360502_65_dialog_content = "Astaga, itu benar-benar menyakitkan!",
  ui_story_5036_50360502_66_dialog_content = "Lihat, aku bisa hidup. Saya merasakan sakit. Hantu tidak.",
  ui_story_5036_50360502_67_dialog_content = "(Ini tugas berbicara dengan orang ini.)",
  ui_story_5036_50360502_68_dialog_content = "(Tapi kenapa dia terdengar familiar?)",
  ui_story_5036_50360502_69_dialog_content = "Saya tidak peduli apakah Anda hantu atau bukan, tetapi saya tidak akan mentolerir siapa pun yang mencoba merusak konser saya!",
  ui_story_5036_50360502_70_dialog_content = "Anda sebaiknya mulai menjelaskan diri Anda sendiri!",
  ui_story_5036_50360502_71_dialog_content = "<color=#e8d9bb>Ding!</color>",
  ui_story_5036_50360502_72_dialog_content = "Benda di tanganku ini bukan hanya hiasan!",
  ui_story_5036_50360502_73_dialog_content = "Oke oke...",
  ui_story_5036_50360502_74_dialog_content = "Santai saja! Aku hampir tersandung karena ancamanmu.",
  ui_story_5036_50360502_75_dialog_content = "Pakaian Anda terlihat kental. Apa yang kamu sembunyikan di bawah sana?",
  ui_story_5036_50360502_76_dialog_content = "Hanya bayi yang berharga yang baru saja saya jinakkan. Ia sedang beristirahat sekarang.",
  ui_story_5036_50360502_77_dialog_content = "Mengapa saya tidak percaya sedikit pun?",
  ui_story_5036_50360502_78_dialog_content = "Mendesah. Saya hanya bisa mengatakan Anda kurang pengertian saat itu.",
  ui_story_5036_50360502_79_dialog_content = "Baca lebih banyak buku, telusuri lebih banyak surat kabar, lakukan lebih banyak pekerjaan amal... Itu semua saran yang bisa saya berikan kepada Anda.",
  ui_story_5036_50360502_80_dialog_content = "Jika tidak ada yang lain, saya akan pergi sekarang.",
  ui_story_5036_50360502_81_dialog_content = "Lepas bajumu!",
  ui_story_5036_50360502_82_dialog_content = "Hah?! Mungkin gelap, dan Anda tidak dapat melihat apa-apa ...",
  ui_story_5036_50360502_83_dialog_content = "tapi aku masih memiliki kerendahan hati untuk dilindungi!",
  ui_story_5036_50360502_84_dialog_content = "Tangkap dia, Marshmallow!",
  ui_story_5036_50360502_85_dialog_content = "Guk!",
  ui_story_5036_50360502_86_dialog_content = "Awas...!",
  ui_story_5036_50360502_87_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5036_50360502_88_dialog_content = "Aku tetap jatuh...",
  ui_story_5036_50360502_89_dialog_content = "Hei, bukankah dia salah satu penampil di audisi?",
  ui_story_5036_50360502_90_dialog_content = "Jadi itu kepura-puraan yang kau gunakan untuk menyelinap di kapal.",
  ui_story_5036_50360502_91_dialog_content = "Aduh, aduh, aduh...",
  ui_story_5036_50360502_92_dialog_content = "Dia?!",
  ui_story_5036_50360502_93_dialog_content = "Kacau!",
  ui_story_5036_50360502_94_dialog_content = "Apa...? Apakah burung hantu baru saja lepas dari pelukannya?",
  ui_story_5036_50360502_95_dialog_content = "Itu bukan barang curian? Apakah saya terlalu paranoid?",
  ui_story_5036_50360502_96_dialog_content = "Sudah kubilang aku tidak bersalah.",
  ui_story_5036_50360502_97_dialog_content = "<color=#e8d9bb>*Splash* Dentang, dentang...</color>",
  ui_story_5036_50360502_98_dialog_content = "Banyak perhiasan yang jatuh dari dalam bulu burung hantu.",
  ui_story_5036_50360502_99_dialog_content = "Lihat, sudah kubilang aku bukan pencuri.",
  ui_story_5036_50360502_100_dialog_content = "Oh, Lutumi, kamu bisa jadi apa saja! Mengapa Anda menjadi pencuri?",
  ui_story_5036_50360502_101_dialog_content = "Ugh...",
  ui_story_5036_50360502_102_dialog_content = "Bagaimana Anda masih menyangkalnya? Buktinya benar-benar tersebar di sekitar kita!",
  ui_story_5036_50360502_103_dialog_content = "Santai!",
  ui_story_5036_50360502_104_dialog_content = "Aku tidak akan menunjukkan belas kasihan!",
  ui_story_5036_50360502_105_dialog_content = "Ugh...",
  ui_story_5036_50360502_106_dialog_content = "Nona Goldie?!",
  ui_story_5036_50360502_107_dialog_content = "Jangan khawatir, dia hanya pingsan sementara.",
  ui_story_5036_50360502_108_dialog_content = "Dia punya lidah perak, dan tak satu pun dari kita punya waktu atau tenaga untuk menghadapinya sekarang.",
  ui_story_5036_50360502_109_dialog_content = "Harap bawa dia ke tahanan dan interogasi dia setelah Anda selesai dengan tugas yang ada.",
  ui_story_5036_50360502_110_dialog_content = "<color=#e8d9bb>Klik!</color>",
  ui_story_5036_50360502_111_dialog_content = "Jadi...",
  ui_story_5036_50360502_112_dialog_content = "Rumor tentang pukulan Goldie yang kejam itu benar?",
  ui_story_5036_50360502_113_dialog_content = "Dengan gambar ini, saya bisa...",
  ui_story_5036_50360601_1_dialog_content = "Hah?",
  ui_story_5036_50360601_2_dialog_content = "Saya mendapatkannya! Bagian dalam sendok yang akan menjamin dilihat!",
  ui_story_5036_50360601_3_dialog_content = "Anda lebih baik tidak membuang-buang waktu saya.",
  ui_story_5036_50360601_4_dialog_content = "Saya berjanji Anda akan senang dengan apa yang saya punya!",
  ui_story_5036_50360601_5_dialog_content = "Ingat ketika Anda menerima tip tentang Goldie yang memiliki pukulan jahat?",
  ui_story_5036_50360601_6_dialog_content = "(Di mana aku?)",
  ui_story_5036_50360601_7_dialog_content = "(Kapan saya kembali ke Eraveil? Terakhir yang saya ingat, saya adalah...)",
  ui_story_5036_50360601_8_dialog_content = "(Di mana saya lagi?)",
  ui_story_5036_50360601_9_dialog_content = "♪ La... La la la... ♪",
  ui_story_5036_50360601_10_dialog_content = "(Saya tahu lagu itu!)",
  ui_story_5036_50360601_11_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360601_12_dialog_content = "(Siapa yang bersenandung?)",
  ui_story_5036_50360601_13_dialog_content = "<color=#e8d9bb>Wuuss!</color>",
  ui_story_5036_50360601_14_dialog_content = "(Apa yang baru saja lewat, Colossus?)",
  ui_story_5036_50360601_15_dialog_content = "(Saya harus mencari tahu.)",
  ui_story_5036_50360601_16_dialog_content = "♪ La la la la... ♪",
  ui_story_5036_50360601_17_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360601_18_dialog_content = "♪ La... La la... ♪",
  ui_story_5036_50360601_19_dialog_content = "(Gadis di sana, dialah yang telah bernyanyi.)",
  ui_story_5036_50360601_20_dialog_content = "Di situ kau rupanya.",
  ui_story_5036_50360601_21_dialog_content = "(Apakah dia berbicara dengan saya?)",
  ui_story_5036_50360601_22_dialog_content = "Kree, Kree!",
  ui_story_5036_50360601_23_dialog_content = "(Oh, dia sedang berbicara dengan makhluk yang terlihat seperti Colossus.)",
  ui_story_5036_50360601_24_dialog_content = "Di sini untuk mendengarkan saya bernyanyi? Anda benar-benar penggemar setia!",
  ui_story_5036_50360601_25_dialog_content = "Tapi saya pikir sudah waktunya untuk memasukkan kata-kata ke dalam musik.",
  ui_story_5036_50360601_26_dialog_content = "(Cara dia berpakaian dan bertindak... Dia benar-benar seorang Caelestite.)",
  ui_story_5036_50360601_27_dialog_content = "(Saya tahu saya akan menemukan Caelestite lain!)",
  ui_story_5036_50360601_28_dialog_content = "Hmm, aku sedikit haus.",
  ui_story_5036_50360601_29_dialog_content = "Mari kita memetik beberapa buah liar!",
  ui_story_5036_50360601_30_dialog_content = "Kree, Kree!",
  ui_story_5036_50360601_31_dialog_content = "Hei, gadis kecil!",
  ui_story_5036_50360601_32_dialog_content = "Tunggu!",
  ui_story_5036_50360601_33_dialog_content = "Hah?",
  ui_story_5036_50360601_34_dialog_content = "<color=#e8d9bb>Tok, tok!</color>",
  ui_story_5036_50360601_35_dialog_content = "Gadis kecil!",
  ui_story_5036_50360601_36_dialog_content = "Hah?",
  ui_story_5036_50360601_37_dialog_content = "Ah, ternyata hanya mimpi...",
  ui_story_5036_50360601_38_dialog_content = "<color=#e8d9bb>Empat hari menuju konser</color>",
  ui_story_5036_50360601_39_dialog_content = "<color=#e8d9bb>Pon, pon, pon!</color>",
  ui_story_5036_50360601_40_dialog_content = "Apakah kamu baik-baik saja di sana, PlayerName?",
  ui_story_5036_50360601_41_dialog_content = "Aku datang!",
  ui_story_5036_50360601_42_dialog_content = "Anda tertidur lelap!",
  ui_story_5036_50360601_43_dialog_content = "Apakah Anda tidak mendengar kami menggedor pintu?",
  ui_story_5036_50360601_44_dialog_content = "Kami mulai mengira Eclipsites menyelinap ke kamarmu...",
  ui_story_5036_50360601_45_dialog_content = "Vice dan aku sudah sedekat ini untuk mendobrak pintu.",
  ui_story_5036_50360601_46_dialog_content = "Maaf, saya baru saja mengalami mimpi ini. Rasanya seperti aku masih di dalamnya.",
  ui_story_5036_50360601_47_dialog_content = "Ah, mimpi lagi.",
  ui_story_5036_50360601_48_dialog_content = "Lain?",
  ui_story_5036_50360601_49_dialog_content = "Ya. Apakah kamu lupa, Carleen?",
  ui_story_5036_50360601_50_dialog_content = "PlayerName sering mendapat mimpi aneh.",
  ui_story_5036_50360601_51_dialog_content = "Saya tiba-tiba teringat bahwa saya juga bermimpi aneh pagi ini.",
  ui_story_5036_50360601_52_dialog_content = "Saya pikir saya memimpikan Eraveil.",
  ui_story_5036_50360601_53_dialog_content = "Kecuali orang yang tinggal di sana tidak PlayerName, tapi seorang gadis kecil yang belum pernah saya lihat sebelumnya.",
  ui_story_5036_50360601_54_dialog_content = "Saya juga! Saya memiliki mimpi yang sama!",
  ui_story_5036_50360601_55_dialog_content = "Wow, kami benar-benar memiliki chemistry yang hebat akhir-akhir ini.",
  ui_story_5036_50360601_56_dialog_content = "Pasti semua latihan itu!",
  ui_story_5036_50360601_57_dialog_content = "Tapi aku memimpikan hal yang sama.",
  ui_story_5036_50360601_58_dialog_content = "Apa?",
  ui_story_5036_50360601_59_dialog_content = "Saya melihat seorang gadis kecil bernyanyi di Eraveil.",
  ui_story_5036_50360601_60_dialog_content = "Lagunya adalah lagu yang melekat di kepalaku!",
  ui_story_5036_50360601_61_dialog_content = "Gadis dalam mimpiku tidak menyanyi. Dia hanya sedang membereskan rumahnya.",
  ui_story_5036_50360601_62_dialog_content = "Gadis yang saya impikan sedang membaca di sebuah ruangan.",
  ui_story_5036_50360601_63_dialog_content = "Jadi impian kami semua sedikit berbeda.",
  ui_story_5036_50360601_64_dialog_content = "Saya mendengar ketika beberapa orang mengalami hal yang sama, ada kemungkinan mereka akhirnya mengalami mimpi yang sama.",
  ui_story_5036_50360601_65_dialog_content = "Karena pengalaman bersama mereka, alam bawah sadar mereka tertarik pada pemikiran yang sama, sehingga menghasilkan mimpi yang serupa.",
  ui_story_5036_50360601_66_dialog_content = "Seseorang bermimpi di malam hari apa yang direnungkannya di siang hari, seperti kata pepatah.",
  ui_story_5036_50360601_67_dialog_content = "Tetapi kepribadian kami yang berbeda tercermin dalam detail dalam mimpi yang identik.",
  ui_story_5036_50360601_68_dialog_content = "Apakah hanya itu saja? Saya menjadi bersemangat atas apa pun.",
  ui_story_5036_50360601_69_dialog_content = "Ngomong-ngomong, PlayerName, apakah Anda yakin ingin tetap mengobrol dengan kami?",
  ui_story_5036_50360601_70_dialog_content = "Anda harus hadir di putaran kedua audisi hari ini, bukan?",
  ui_story_5036_50360601_71_dialog_content = "Ups!! Saya benar-benar lupa!",
  ui_story_5036_50360601_72_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360601_73_dialog_content = "♪ La... La la... ♪",
  ui_story_5036_50360601_74_dialog_content = "Itulah keseluruhan melodi di kepalaku. Rasanya menyenangkan untuk mengeluarkan semuanya!",
  ui_story_5036_50360601_75_dialog_content = "*Huahh*",
  ui_story_5036_50360601_76_dialog_content = "A-Apa aku benar-benar tidak selaras atau semacamnya?",
  ui_story_5036_50360601_77_dialog_content = "Tidak, saya tidak tidur nyenyak tadi malam, jadi maafkan saya, PlayerName.",
  ui_story_5036_50360601_78_dialog_content = "Apakah karena Anda memiliki terlalu banyak mimpi?",
  ui_story_5036_50360601_79_dialog_content = "Anda punya cukup imajinasi, PlayerName.",
  ui_story_5036_50360601_80_dialog_content = "Saya memeriksa panggung tadi malam.",
  ui_story_5036_50360601_81_dialog_content = "Dan pergi ke area lockdown untuk mengurus Eclipsites sampai larut malam.",
  ui_story_5036_50360601_82_dialog_content = "Bukankah Tentara Bayaran Api Putih yang bertanggung jawab atas itu?",
  ui_story_5036_50360601_83_dialog_content = "Yeah, tapi aku tidak tahan terkurung di kamarku.",
  ui_story_5036_50360601_84_dialog_content = "Saya pikir daripada mengkhawatirkannya, saya mungkin juga membantu.",
  ui_story_5036_50360601_85_dialog_content = "Pantas saja kau adalah idola paling populer di Umbraton. Anda bekerja terlalu keras.",
  ui_story_5036_50360601_86_dialog_content = "Anda terlibat dalam segala hal!",
  ui_story_5036_50360601_87_dialog_content = "Hal kecil apa pun dapat membuat atau merusak konser.",
  ui_story_5036_50360601_88_dialog_content = "Pertunjukan itu sangat penting bagi saya. Aku tidak bisa membiarkan apapun menggagalkannya.",
  ui_story_5036_50360601_89_dialog_content = "Anda tampaknya adalah tipe yang memperlakukan setiap penampilan seolah-olah itu akan menjadi penampilan terakhir Anda.",
  ui_story_5036_50360601_90_dialog_content = "B-Benarkah? Ahaha...",
  ui_story_5036_50360601_91_dialog_content = "Tapi kami ngelantur. Bagaimana saya harus menggambarkan melodi yang baru saja Anda bagikan dengan saya?",
  ui_story_5036_50360601_92_dialog_content = "Lembut, menenangkan, terapeutik, Caelestite unik, dan mudah dinyanyikan!",
  ui_story_5036_50360601_93_dialog_content = "Ini persis jenis musik yang saya cari dalam semua aspek!",
  ui_story_5036_50360601_94_dialog_content = "Apakah Anda yakin tidak keberatan saya melakukannya di atas panggung?",
  ui_story_5036_50360601_95_dialog_content = "Saya tidak pernah berpikir saya akan menjadi seorang komposer, jadi hentikan diri Anda!",
  ui_story_5036_50360601_96_dialog_content = "Memiliki idola terkenal membawakan lagu saya akan menjadi suatu kehormatan.",
  ui_story_5036_50360601_97_dialog_content = "Beri tahu saya jika Anda punya ide untuk liriknya!",
  ui_story_5036_50360601_98_dialog_content = "Sekarang, ada hal lain yang ingin saya bicarakan dengan Anda.",
  ui_story_5036_50360601_99_dialog_content = "Apakah Anda ingat peserta terakhir dalam audisi kemarin?",
  ui_story_5036_50360601_100_dialog_content = "Maksudmu Vik?",
  ui_story_5036_50360601_101_dialog_content = "Apa dia temanmu?",
  ui_story_5036_50360601_102_dialog_content = "Saya dekat dengan muridnya, jadi saya kira Anda bisa mengatakan itu.",
  ui_story_5036_50360601_103_dialog_content = "Tapi saya tidak tahu dia mendaftar, dan saya juga tidak memilih dia.",
  ui_story_5036_50360601_104_dialog_content = "Anda tidak perlu khawatir tentang favoritisme dari saya!",
  ui_story_5036_50360601_105_dialog_content = "Apakah dia memiliki kecenderungan kleptomaniak?",
  ui_story_5036_50360601_106_dialog_content = "Apa? Mengapa Anda bertanya?",
  ui_story_5036_50360601_107_dialog_content = "Nah, tadi malam...",
  ui_story_5036_50360601_108_dialog_content = "Tolong!",
  ui_story_5036_50360601_109_dialog_content = "Grahhhhhhhh!",
  ui_story_5036_50360601_110_dialog_content = "Berhentilah berlari!",
  ui_story_5036_50360601_111_dialog_content = "Eclipsites mengejar Vic, tentara bayaran mengejar Eclipsites? Apa yang terjadi di sini?!",
  ui_story_5036_50360602_1_dialog_content = "Para juri lainnya duduk di kursi mereka, Nona Goldie dan PlayerName.",
  ui_story_5036_50360602_2_dialog_content = "Kalau kamu tak keberatan...",
  ui_story_5036_50360602_3_dialog_content = "Tolong!",
  ui_story_5036_50360602_4_dialog_content = "Anda harus bergabung dengan kami untuk putaran kedua audisi.",
  ui_story_5036_50360602_5_dialog_content = "Graah!!!!",
  ui_story_5036_50360602_6_dialog_content = "Rasakan ini!",
  ui_story_5036_50360602_7_dialog_content = "Semua orang tampaknya sedikit sibuk saat ini ...",
  ui_story_5036_50360602_8_dialog_content = "Tolong!",
  ui_story_5036_50360602_9_dialog_content = "Anda bisa berhenti berteriak sekarang. Eclipsites turun.",
  ui_story_5036_50360602_10_dialog_content = "* terengah-engah berat *",
  ui_story_5036_50360602_11_dialog_content = "Saya berteriak agar Anda tidak mengunci saya dengan mereka lagi!",
  ui_story_5036_50360602_12_dialog_content = "Beruntung bagi saya, cakar Little Furball cukup panjang untuk membuka kuncinya.",
  ui_story_5036_50360602_13_dialog_content = "Kalau tidak, saya bahkan tidak akan mendapat kesempatan untuk meminta bantuan!",
  ui_story_5036_50360602_14_dialog_content = "Maaf, kami sama sekali tidak berniat membahayakan Anda.",
  ui_story_5036_50360602_15_dialog_content = "Tapi saat kami mengurungmu di ruangan itu, tidak ada Eclipsites di sana.",
  ui_story_5036_50360602_16_dialog_content = "...",
  ui_story_5036_50360602_17_dialog_content = "Mereka merangkak keluar melalui ventilasi udara, Nona Goldie.",
  ui_story_5036_50360602_18_dialog_content = "Ventilasi di ruangan itu sepertinya terhubung ke area kuncian.",
  ui_story_5036_50360602_19_dialog_content = "Tapi bukankah ventilasi udara diamankan dengan penutup?",
  ui_story_5036_50360602_20_dialog_content = "Oh, begitu.",
  ui_story_5036_50360602_21_dialog_content = "Anda mencoba melarikan diri melalui ventilasi, yang menarik Eclipsites ke sana!",
  ui_story_5036_50360602_22_dialog_content = "Uh... hee hee.",
  ui_story_5036_50360602_23_dialog_content = "Itu sangat panas di dalam ruangan. Aku benar-benar membutuhkan udara.",
  ui_story_5036_50360602_24_dialog_content = "Apa yang sedang terjadi? Mengapa Anda mengunci Vic?",
  ui_story_5036_50360602_25_dialog_content = "Maaf, PlayerName.",
  ui_story_5036_50360602_26_dialog_content = "Tapi temanmu Vic adalah pencuri hantu yang telah mencuri selama beberapa hari ini.",
  ui_story_5036_50360602_27_dialog_content = "Vic adalah pencurinya?",
  ui_story_5036_50360602_28_option_content = "Yah, itu mungkin.",
  ui_story_5036_50360602_29_dialog_content = "Dia seorang ahli ekstrozoologi yang dipublikasikan, tapi itu bertahun-tahun yang lalu.",
  ui_story_5036_50360602_30_dialog_content = "Aku bisa melihat dia terpaksa mencuri tanpa buku baru di bawah ikat pinggangnya atau penghasilan yang dapat diandalkan.",
  ui_story_5036_50360602_31_dialog_content = "Tetapi betapapun miskinnya Anda, Anda tetap harus menghasilkan uang dengan kedua tangan Anda sendiri.",
  ui_story_5036_50360602_32_dialog_content = "Anda tidak boleh memasukkan tangan Anda ke saku orang lain dan mengambil barang-barang mereka!",
  ui_story_5036_50360602_33_option_content = "Tak mungkin!",
  ui_story_5036_50360602_34_dialog_content = "Dia seorang ahli ekstrozoologi yang diterbitkan dengan banyak siswa.",
  ui_story_5036_50360602_35_dialog_content = "Tidak peduli seberapa miskinnya dia, dia tidak akan melakukan pencurian kecil-kecilan!",
  ui_story_5036_50360602_36_dialog_content = "Aku tahu sulit bagimu untuk menerimanya.",
  ui_story_5036_50360602_37_dialog_content = "Saya sendiri tidak percaya. Saya melihat banyak potensi dalam dirinya.",
  ui_story_5036_50360602_38_dialog_content = "Tapi kami menemukan makanan dan perhiasan curian di sakunya kemarin. Buktinya ada di sana.",
  ui_story_5036_50360602_39_dialog_content = "Dengarkan aku menjelaskan...",
  ui_story_5036_50360602_40_dialog_content = "Aku sudah cukup mendengar alasanmu yang berbelit-belit kemarin.",
  ui_story_5036_50360602_41_dialog_content = "Apakah Anda masih berusaha menyangkalnya dengan jumlah bukti yang tersedia?",
  ui_story_5036_50360602_42_dialog_content = "Oke, oke, saya akui semua pencurian baru-baru ini.",
  ui_story_5036_50360602_43_dialog_content = "Jadi kamu benar-benar pencuri hantu itu?!",
  ui_story_5036_50360602_44_dialog_content = "Meskipun saya bertanggung jawab, ada penafian!",
  ui_story_5036_50360602_45_dialog_content = "Saya, Vic, adalah ahli ekstrozoologi terkenal, tetapi saya tidak pernah menjadi pencuri.",
  ui_story_5036_50360602_46_dialog_content = "Pencuri yang dibicarakan semua orang sebenarnya adalah binatang ajaib yang kubawa.",
  ui_story_5036_50360602_47_dialog_content = "Hai...",
  ui_story_5036_50360602_48_dialog_content = "Ugh...",
  ui_story_5036_50360602_49_dialog_content = "Cit cit cuit!",
  ui_story_5036_50360602_50_dialog_content = "Anak kecil berbulu di bahu Anda tampaknya gelisah.",
  ui_story_5036_50360602_51_dialog_content = "Little Furball berkata: \"Itu mereka berdua, bukan aku!\"",
  ui_story_5036_50360602_52_dialog_content = "Cuit!",
  ui_story_5036_50360602_53_dialog_content = "Biasanya, saya mengganti makanan mereka setiap hari.",
  ui_story_5036_50360602_54_dialog_content = "Tapi saya terlalu sibuk berkemas untuk diri saya sendiri dan hanya membawa satu jenis makanan.",
  ui_story_5036_50360602_55_dialog_content = "Keduanya pergi sendiri, mungkin karena mereka bosan makan hal yang sama.",
  ui_story_5036_50360602_56_dialog_content = "Ketika saya mendengar tentang pencurian Colossus, saya pikir itu mungkin mereka.",
  ui_story_5036_50360602_57_dialog_content = "Butuh waktu lama bagiku untuk akhirnya menangkap mereka berdua tadi malam.",
  ui_story_5036_50360602_58_dialog_content = "Tepat sebelum kami menangkapmu?",
  ui_story_5036_50360602_59_dialog_content = "Ya. Kebetulan sekali, ya?",
  ui_story_5036_50360602_60_dialog_content = "Saya mengerti bahwa hewan ingin makan, tetapi mengapa mencuri perhiasan?",
  ui_story_5036_50360602_61_dialog_content = "Apakah itu Burung Hantu Lutumi?",
  ui_story_5036_50360602_62_dialog_content = "Betul sekali. Burung Hantu Lutumi dapat mengeluarkan gas bius. Saya membawanya dengan saya untuk tujuan pertahanan diri.",
  ui_story_5036_50360602_63_dialog_content = "Tapi dia suka mengumpulkan benda-benda mengkilap, jadi jika Anda kehilangan jejaknya...",
  ui_story_5036_50360602_64_dialog_content = "Itu akhirnya menjadi jenis pencuri yang digosipkan semua orang.",
  ui_story_5036_50360602_65_dialog_content = "Namun, mereka hanya bertindak berdasarkan insting. Mereka tidak menyimpan kebencian terhadap kita.",
  ui_story_5036_50360602_66_dialog_content = "Saya yang harus disalahkan karena tidak membuat mereka sejalan.",
  ui_story_5036_50360602_67_dialog_content = "Saya berjanji untuk mengembalikan semua perhiasan dan koin kembali ke pemiliknya!",
  ui_story_5036_50360602_68_dialog_content = "Jika perlu, saya bahkan akan membayar masalah yang saya sebabkan kepada semua orang.",
  ui_story_5036_50360602_69_dialog_content = "Tolong jangan menghukum makhluk itu! Mereka tidak bersungguh-sungguh.",
  ui_story_5036_50360602_70_dialog_content = "Hai, hai, hai.",
  ui_story_5036_50360602_71_dialog_content = "...",
  ui_story_5036_50360602_72_dialog_content = "Oke, tetapi Anda harus melakukan apa yang Anda janjikan.",
  ui_story_5036_50360602_73_dialog_content = "Kembalikan semuanya dengan permintaan maaf dan kompensasi.",
  ui_story_5036_50360602_74_dialog_content = "Jadi, bagaimana kalau tidak mengunci kita di ruangan kecil yang gelap lagi?",
  ui_story_5036_50360602_75_dialog_content = "Di sana benar-benar pengap...",
  ui_story_5036_50360602_76_dialog_content = "Saya bisa melakukan itu.",
  ui_story_5036_50360602_77_dialog_content = "Tetapi Anda harus berjanji kepada saya bahwa Anda akan meninggalkan Eulogoz setelah Anda mengurus semuanya.",
  ui_story_5036_50360602_78_dialog_content = "Apa? Tidak, saya tidak bisa pergi. Aku masih belum mencapai impianku menjadi seorang idola!",
  ui_story_5036_50360602_79_dialog_content = "Bukankah Anda mendorong saya untuk terus mengikuti audisi, Miss Goldie?",
  ui_story_5036_50360602_80_dialog_content = "Anda memiliki bakat serta lidah fasih ...",
  ui_story_5036_50360602_81_dialog_content = "Tapi entah bagaimana aku merasa bahwa kamu tidak datang ke sini untuk audisi idola.",
  ui_story_5036_50360602_82_dialog_content = "!!!",
  ui_story_5036_50360602_83_dialog_content = "... Baiklah, saya kira saya akan berterus terang.",
  ui_story_5036_50360602_84_dialog_content = "Saya sebenarnya di sini mencari binatang yang luar biasa bernama Ouroboros.",
  ui_story_5036_50360602_85_dialog_content = "Saat makhluk itu tumbuh hingga tahap tertentu, ia berubah menjadi telur.",
  ui_story_5036_50360602_86_dialog_content = "Kemudian pecah setelah inkubasi, dan siklus berulang, memungkinkannya mencapai keabadian.",
  ui_story_5036_50360602_87_dialog_content = "Ada makhluk abadi di dunia?!",
  ui_story_5036_50360602_88_dialog_content = "Saya sudah tahu sejak saya masih sangat muda bahwa ayah dan ibu saya bukanlah orang tua kandung saya.",
  ui_story_5036_50360602_89_dialog_content = "Saya baru-baru ini menemukan bahwa garis keturunan saya tampaknya terhubung ke Ouroboros. Oleh karena itu, saya harus menemukannya!",
  ui_story_5036_50360602_89X1_dialog_content = "Jika saya menemukan Ouroboros, saya dapat mengetahui lebih banyak tentang asal-usul saya, dan bahkan mungkin saya dapat menemukan orang tua kandung saya.",
  ui_story_5036_50360602_90_dialog_content = "Catatan tentang spesies langka. Satu-satunya hal yang pasti tentang mereka adalah mereka suka berkeliaran di sekitar Colossi.",
  ui_story_5036_50360602_91_dialog_content = "Anda dalam keadaan mabuk lagi, tuan! Hentikan itu!",
  ui_story_5036_50360602_92_dialog_content = "Saya sudah menjelajahi informasi tentang semua Colossi di Astra, termasuk Soroz dari PlayerName.",
  ui_story_5036_50360602_93_dialog_content = "Tidak ada tanda-tanda Ouroboros yang pernah ditemukan di dekat salah satu dari mereka.",
  ui_story_5036_50360602_94_dialog_content = "Apakah Ouroboros benar-benar ada?",
  ui_story_5036_50360602_96_dialog_content = "Kau tidak main-main denganku lagi, kan?!",
  ui_story_5036_50360602_97_dialog_content = "Hmph! Jangan membuatku mencari Ouroboros bodoh untukmu lagi!",
  ui_story_5036_50360602_98_dialog_content = "Saya menyisir semua Colossi di Astra tetapi gagal menemukan jejak Ouroboros.",
  ui_story_5036_50360602_99_dialog_content = "Satu-satunya tempat yang belum kucari adalah Colossus terbang tempat kita berada.",
  ui_story_5036_50360602_100_dialog_content = "Jadi, apakah Anda menemukan jejak Ouroboros di Eulogoz?",
  ui_story_5036_50360602_101_dialog_content = "Tidak, tapi aku punya firasat, firasat yang sangat kuat.",
  ui_story_5036_50360602_102_dialog_content = "Pasti ada Ouroboros di Eulogoz!",
  ui_story_5036_50360602_103_dialog_content = "Tolong izinkan saya untuk tinggal dan mencarinya!",
  ui_story_5036_50360602_104_dialog_content = "Tolong beri seseorang yang belum pernah mengalami hangatnya kehangatan rumah yang penuh kasih, kesempatan untuk menemukan keluarganya!",
  ui_story_5036_50360602_105_dialog_content = "... Kau sudah selesai?",
  ui_story_5036_50360602_106_dialog_content = "Ya, saya sudah selesai.",
  ui_story_5036_50360602_107_dialog_content = "Kisah Anda itu lebih tidak percaya daripada yang bisa ditawarkan oleh film beranggaran rendah mana pun dari Umbraton.",
  ui_story_5036_50360602_108_dialog_content = "Saya harus berterima kasih karena telah memperluas wawasan saya.",
  ui_story_5036_50360602_109_dialog_content = "Ehehe, tidak masalah. Terima kasih atas pengertian.",
  ui_story_5036_50360602_110_dialog_content = "Seharusnya aku menjelaskannya pada semua orang sejak awal.",
  ui_story_5036_50360602_111_dialog_content = "Baiklah, waktu cerita selesai.",
  ui_story_5036_50360602_112_dialog_content = "Sekarang bisakah Anda turun dari Eulogoz?",
  ui_story_5036_50360602_113_dialog_content = "Apa?",
  ui_story_5036_50360602_114_dialog_content = "Silahkan lewat sini. Aku akan mengantarmu.",
  ui_story_5036_50360602_115_dialog_content = "Tunggu sebentar! Saya belum selesai!",
  ui_story_5036_50360602_116_dialog_content = "Hanya bercanda! Aku hanya bercanda, hahaha.",
  ui_story_5036_50360602_116X1_dialog_content = "Beradaptasi dan berimprovisasi untuk situasi apa pun, menghidupkan suasana, dan menarik emosi penggemar—itu semua adalah bagian dari tanggung jawab seorang idola.",
  ui_story_5036_50360602_116X2_dialog_content = "Saya ingin menunjukkan kepada Anda apa yang saya mampu sehingga Anda tahu betapa tulusnya saya ingin berpartisipasi dalam audisi!",
  ui_story_5036_50360602_117_dialog_content = "Maksudmu seperti, komedi improvisasi?",
  ui_story_5036_50360602_118_dialog_content = "Bukankah cerita spontan saya membuat Anda tertawa?",
  ui_story_5036_50360602_119_dialog_content = "Hmm…",
  ui_story_5036_50360602_120_dialog_content = "(Memang, Vic memikat semua perhatianku sejak awal.)",
  ui_story_5036_50360602_121_dialog_content = "(Lady Sheol memang mengatakan aku kehilangan sesuatu... Mungkinkah selera humor yang dimiliki Vic?)",
  ui_story_5036_50360602_124_dialog_content = "Saya benar-benar ingin menjadi idola... Tolong biarkan saya tetap tinggal dan bersaing.",
  ui_story_5036_50360602_125_dialog_content = "Anda mungkin tidak percaya saya, tapi jangan Anda percaya PlayerName?",
  ui_story_5036_50360602_126_dialog_content = "Dia VIP kami, tentu saja saya percaya padanya dengan sepenuh hati.",
  ui_story_5036_50360602_127_dialog_content = "Itu dia.",
  ui_story_5036_50360602_128_dialog_content = "Fia membantumu berkali-kali sebelumnya, kan, PlayerName?",
  ui_story_5036_50360602_129_dialog_content = "Er... ya, bisa dibilang begitu.",
  ui_story_5036_50360602_130_dialog_content = "Dan dengan asosiasi, bukankah itu berarti saya secara teknis adalah dermawan Anda?",
  ui_story_5036_50360602_131_dialog_content = "B-dermawan?",
  ui_story_5036_50360602_132_dialog_content = "Jadi, sebagai hakim, Anda akan menjamin saya, bukan?",
  ui_story_5036_50360602_133_dialog_content = "...",
  ui_story_5036_50360602_134_dialog_content = "PlayerName menjamin saya, Nona Goldie.",
  ui_story_5036_50360602_135_dialog_content = "Tolong jangan keluarkan aku atas namanya...",
  ui_story_5036_50360602_136_dialog_content = "Apakah Anda menjamin dia, PlayerName?",
  ui_story_5036_50360602_137_dialog_content = "Aduh… yah…",
  ui_story_5036_50360602_138_dialog_content = "Mendekat, PlayerName. Mendengarkan...",
  ui_story_5036_50360602_139_dialog_content = "Jangan beri tahu saya bahwa Anda tidak memperhatikan kehadiran Lumina yang kuat di area kuncian di Eulogoz!",
  ui_story_5036_50360602_140_dialog_content = "Apa?!",
  ui_story_5036_50360602_141_dialog_content = "Jadi Goldie hanya berusaha menangkap pencuri tadi malam...",
  ui_story_5036_50360602_142_dialog_content = "Itu berarti foto saya menyesatkan ...",
  ui_story_5036_50360602_143_dialog_content = "<color=#e8d9bb>Ngungg!</color>",
  ui_story_5036_50360602_144_dialog_content = "Kapan Anda mengirimi saya foto yang Anda sebutkan, Brandy?",
  ui_story_5036_50360602_145_dialog_content = "Saya perlu menggali situasi lebih lanjut!",
  ui_story_5036_50360602_146_dialog_content = "Apa lagi penggalian yang harus Anda lakukan?",
  ui_story_5036_50360602_147_dialog_content = "Kebenaran tidak masalah, hanya berita menawan yang merupakan kabar baik!",
  ui_story_5036_50360602_148_dialog_content = "Namun…",
  ui_story_5036_50360602_149_dialog_content = "Jangan repot-repot kembali jika Anda tidak mengirim fotonya!",
  ui_story_5036_50360602_150_dialog_content = "Editor! Editor!",
  ui_story_5036_50360701_1_dialog_content = "Komentar Anda semakin profesional, PlayerName!",
  ui_story_5036_50360701_2_dialog_content = "Anda mungkin bisa menjadi produser idola yang sebenarnya suatu hari nanti!",
  ui_story_5036_50360701_3_dialog_content = "Namun…",
  ui_story_5036_50360701_4_dialog_content = "Apakah Anda masih khawatir tentang Vic?",
  ui_story_5036_50360701_5_dialog_content = "Ya, maaf!",
  ui_story_5036_50360701_6_dialog_content = "Meskipun Anda menjamin dia, saya masih cemas.",
  ui_story_5036_50360701_7_dialog_content = "Saya menempatkannya di ruang latihan terdekat, tetapi saya tidak tahu apakah dia berlatih dengan serius.",
  ui_story_5036_50360701_8_dialog_content = "Aku ingin tahu apakah dia mengganggu orang lain?",
  ui_story_5036_50360701_9_dialog_content = "Kau tahu, aku harus memeriksanya.",
  ui_story_5036_50360701_10_dialog_content = "Biar kubantu.",
  ui_story_5036_50360701_11_dialog_content = "Dia menepati janjiku, jadi aku harus mengawasinya.",
  ui_story_5036_50360701_12_dialog_content = "Dan Anda hampir tidak pernah beristirahat sejak kemarin. Anda harus istirahat.",
  ui_story_5036_50360701_13_dialog_content = "BENAR. Saya juga punya lagu untuk ditulis ... Tidak bisa menyia-nyiakan melodi yang Anda bagikan dengan saya!",
  ui_story_5036_50360701_14_dialog_content = "Aku akan menyerahkan Vic padamu!",
  ui_story_5036_50360701_15_dialog_content = "* Menguap * Apa yang kamu katakan?",
  ui_story_5036_50360701_16_dialog_content = "Bagaimana kabarmu hari ini?",
  ui_story_5036_50360701_17_dialog_content = "Lumayan.",
  ui_story_5036_50360701_18_dialog_content = "Saya tidur nyenyak tadi malam!",
  ui_story_5036_50360701_19_dialog_content = "Aku bertanya tentang latihanmu.",
  ui_story_5036_50360701_20_dialog_content = "Jangan bilang kamu tidur sepanjang hari dan tidak pernah memikirkannya?",
  ui_story_5036_50360701_21_dialog_content = "Bukankah saya sudah membuat diri saya jelas? Baiklah, sekali lagi.",
  ui_story_5036_50360701_22_dialog_content = "Mendaftar kompetisi adalah alasan, cerita tentang Ouroboros tidak palsu.",
  ui_story_5036_50360701_23_dialog_content = "Saya ingin menggunakan kesempatan ini untuk masuk ke dalam Eulogoz dan menemukan makhluk itu.",
  ui_story_5036_50360701_24_dialog_content = "Saya tahu itu, tapi saya tidak merasakan Lumina yang kuat datang dari area terkunci.",
  ui_story_5036_50360701_25_dialog_content = "Hanya ada sekelompok Eclipsites yang tidur di sana.",
  ui_story_5036_50360701_26_dialog_content = "Ouroboros yang menginkubasi tidak melepaskan Lumina yang signifikan.",
  ui_story_5036_50360701_27_dialog_content = "Berarti makhluk itu masih di dalam telur!",
  ui_story_5036_50360701_28_dialog_content = "Bagaimana Anda begitu yakin bahwa ada salah satu dari hal-hal itu di Eugoloz?",
  ui_story_5036_50360701_29_dialog_content = "Sebut saja intuisi. Intuisi ahli ekstrozoologi.",
  ui_story_5036_50360701_30_dialog_content = "Jadi pada dasarnya Anda tidak ada bukti apapun.",
  ui_story_5036_50360701_31_dialog_content = "Saya agak bisa mengerti mengapa Fia selalu dalam mood di sekitar Anda sekarang.",
  ui_story_5036_50360701_32_dialog_content = "Anda masih tidak bisa meyakinkan mereka untuk mengizinkan saya masuk ke area kuncian?",
  ui_story_5036_50360701_33_dialog_content = "B-Bagaimana Anda mengharapkan saya untuk memulai pembicaraan?",
  ui_story_5036_50360701_34_dialog_content = "Goldie memerintahkan tentara bayaran untuk menjaga area tersebut, jadi dia jelas tidak ingin ada orang yang masuk dan menimbulkan masalah.",
  ui_story_5036_50360701_35_dialog_content = "Bahkan jika ada Ouroboros di Eulogoz, Anda setidaknya bisa menunggu hingga konser selesai sebelum mencarinya.",
  ui_story_5036_50360701_36_dialog_content = "Maksudmu aku bisa tetap di Eulogoz sampai acaranya selesai?",
  ui_story_5036_50360701_37_dialog_content = "Itu tergantung pada apakah Anda berhasil melewati audisi.",
  ui_story_5036_50360701_38_dialog_content = "Kontestan yang gagal mengumpulkan cukup suara harus segera pergi. Sudah jelas tertuang dalam peraturan.",
  ui_story_5036_50360701_39_dialog_content = "Oh itu? Itu sepotong kue.",
  ui_story_5036_50360701_40_dialog_content = "Oh? Apakah Anda memiliki pertunjukan dalam pikiran?",
  ui_story_5036_50360701_41_dialog_content = "Apa pendapat Anda tentang membuat Little Furball melakukan backflip?",
  ui_story_5036_50360701_42_dialog_content = "Pertunjukan binatang? Anda akan lebih baik mengikuti audisi sirkus.",
  ui_story_5036_50360701_43_dialog_content = "Bukankah ini kompetisi menyanyi idola?",
  ui_story_5036_50360701_44_dialog_content = "Apakah Anda tersandung ke tempat yang salah?",
  ui_story_5036_50360701_45_dialog_content = "Ooh, apakah ada pembuatan drama di sini?",
  ui_story_5036_50360701_46_dialog_content = "Di mana ada drama, di situ ada berita. Sebaiknya saya mencatat dengan baik!",
  ui_story_5036_50360701_47_dialog_content = "Hei, berhenti memandangi orang lain! Ya kamu!",
  ui_story_5036_50360701_48_dialog_content = "Apa kau mengenalku?",
  ui_story_5036_50360701_49_dialog_content = "Aku tahu kamu.",
  ui_story_5036_50360701_50_dialog_content = "Wow, saya tidak menyangka akan bertemu dengan seseorang yang membaca karya saya di sini!",
  ui_story_5036_50360701_51_dialog_content = "Anda adalah pencuri hantu yang baru saja ditangkap.",
  ui_story_5036_50360701_52_dialog_content = "Bukankah pencuri seharusnya ditangkap? Apa yang masih dia lakukan di audisi?",
  ui_story_5036_50360701_53_dialog_content = "Belum lagi dia mengambil slot!",
  ui_story_5036_50360701_54_dialog_content = "Dengar, pencuri. Saya tidak tahu telapak tangan siapa yang Anda olesi ...",
  ui_story_5036_50360701_55_dialog_content = "Tapi tidak satu pun dari kami yang mengizinkan Anda menodai panggung atau impian kami!",
  ui_story_5036_50360701_56_dialog_content = "Jika Anda tidak berencana untuk benar-benar mengikuti audisi, maka pergilah!",
  ui_story_5036_50360701_57_dialog_content = "Tenang saja, semuanya...",
  ui_story_5036_50360701_58_dialog_content = "Itu semua salah paham. Saya benar-benar ingin bersaing.",
  ui_story_5036_50360701_59_dialog_content = "Tidak hanya itu, saya telah memutuskan untuk mencapai tahap akhir.",
  ui_story_5036_50360701_60_dialog_content = "Dengan aksi sirkusmu?",
  ui_story_5036_50360701_61_dialog_content = "Aku hanya bercanda!",
  ui_story_5036_50360701_62_dialog_content = "Mengapa saya harus mendaftar jika saya tidak menyiapkan pertunjukan?",
  ui_story_5036_50360701_63_dialog_content = "Kemudian tunjukkan kami apa yang Anda punya.",
  ui_story_5036_50360701_64_dialog_content = "Ya!",
  ui_story_5036_50360701_65_dialog_content = "Mari kita lihat pertunjukan seperti apa yang Anda tampilkan!",
  ui_story_5036_50360701_66_dialog_content = "Tentang itu...",
  ui_story_5036_50360701_67_dialog_content = "Nah, tunggu apa lagi?",
  ui_story_5036_50360701_68_dialog_content = "Ayo! Tunjukkan pada kami!",
  ui_story_5036_50360701_69_dialog_content = "Oke, tenang! Aku akan melakukannya!",
  ui_story_5036_50360701_70_dialog_content = "Ahem, hadirin sekalian: tarian Drakolion.",
  ui_story_5036_50360701_71_dialog_content = "Tarian ini merupakan tiruan dari drakolion yang sedang terbang mencari jodoh. Perhatikan baik-baik!",
  ui_story_5036_50360701_72_dialog_content = "Hei!",
  ui_story_5036_50360701_73_dialog_content = "Ha.",
  ui_story_5036_50360701_74_dialog_content = "Apa... itu seharusnya tarian?",
  ui_story_5036_50360701_75_dialog_content = "Ini lebih terlihat seperti seseorang yang belajar berjalan kembali setelah kakinya patah.",
  ui_story_5036_50360701_76_dialog_content = "Lihat ini, backflip di udara!",
  ui_story_5036_50360701_77_dialog_content = "Hiya!",
  ui_story_5036_50360701_78_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5036_50360701_79_dialog_content = "Ya ampun... Aduh, aduh, aduh, aduh, aduh!",
  ui_story_5036_50360701_80_dialog_content = "Hahaha!",
  ui_story_5036_50360701_81_dialog_content = "Apakah Anda malah menyakiti punggung Anda?",
  ui_story_5036_50360701_82_dialog_content = "Butuh bakat khusus untuk menari seperti itu!",
  ui_story_5036_50360701_83_dialog_content = "Ekstrozoolog Menjadi Idola Diintimidasi di Eulogoz...",
  ui_story_5036_50360701_84_dialog_content = "Akankah editor menyukai cerita seperti ini?",
  ui_story_5036_50360701_85_dialog_content = "Apakah kamu baik-baik saja, Vic?",
  ui_story_5036_50360701_86_dialog_content = "saya hanya melihat PlayerName peduli pada orang tua!",
  ui_story_5036_50360701_87_dialog_content = "pantatku terjebak pada sesuatu. Bisakah kamu menarikku?",
  ui_story_5036_50360701_88_dialog_content = "Tentu saja…",
  ui_story_5036_50360701_89_dialog_content = "Hei, apa itu... ventilasi udara di belakangmu?!",
  ui_story_5036_50360701_90_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5036_50360701_91_dialog_content = "Apa katamu?",
  ui_story_5036_50360701_92_dialog_content = "Wow, saya membuka ventilasi lagi, hahaha!",
  ui_story_5036_50360701_93_dialog_content = "Graagh!",
  ui_story_5036_50360701_94_dialog_content = "Mengapa ada Eclipsites di ventilasi ini juga?",
  ui_story_5036_50360701_95_dialog_content = "Lari-!",
  ui_story_5036_50360702_1_dialog_content = "Graagh!",
  ui_story_5036_50360702_2_dialog_content = "Mekar!",
  ui_story_5036_50360702_3_dialog_content = "Cara Goldie berurusan dengan Eclipsites itu... Aku harus bergegas dan mencari cara untuk menyelidiki petunjuk tentang dia.",
  ui_story_5036_50360702_4_dialog_content = "Oh tidak! Aku lupa untuk mengambil gambar...",
  ui_story_5036_50360702_5_dialog_content = "Apa ada yang terluka?",
  ui_story_5036_50360702_6_dialog_content = "Semuanya baik-baik saja, hanya sedikit ketakutan.",
  ui_story_5036_50360702_7_dialog_content = "Terima kasih telah menyelamatkan kami, Nona Goldie.",
  ui_story_5036_50360702_8_dialog_content = "Kamu secantik kamu di poster... Tidak, kamu jauh lebih cantik!",
  ui_story_5036_50360702_9_dialog_content = "Nona Goldie?!",
  ui_story_5036_50360702_10_dialog_content = "Saya telah menjadi Goldilock sejak Anda debut!",
  ui_story_5036_50360702_11_dialog_content = "Maukah Anda tanda tangan di sini, Nona Goldie?",
  ui_story_5036_50360702_12_dialog_content = "Goldie! Goldie! Goldie!",
  ui_story_5036_50360702_13_dialog_content = "Maaf soal ini. Saya akan mengirim seseorang untuk menutup ventilasi dan menyediakan makanan untuk semua orang.",
  ui_story_5036_50360702_14_dialog_content = "Itu semua kesalahan pencuri itu. Semua ini tidak akan terjadi jika pantatnya tidak merusak layar.",
  ui_story_5036_50360702_15_dialog_content = "Dan dia benar-benar penari yang buruk!",
  ui_story_5036_50360702_16_dialog_content = "Usir dia! Usir dia! Usir dia!",
  ui_story_5036_50360702_17_dialog_content = "Namun…",
  ui_story_5036_50360702_18_dialog_content = "Aku benar-benar ingin lolos audisi.",
  ui_story_5036_50360702_19_dialog_content = "Oh ya?",
  ui_story_5036_50360702_20_dialog_content = "Apakah Anda memiliki ketekunan untuk membuatnya sampai akhir?",
  ui_story_5036_50360702_21_dialog_content = "Untuk Ouroboro...",
  ui_story_5036_50360702_22_dialog_content = "Saya harus!",
  ui_story_5036_50360702_23_dialog_content = "Aku harus berhasil sampai akhir!",
  ui_story_5036_50360702_24_dialog_content = "(Optimisme dan tekad buta seperti itu membuat saya bernostalgia.)",
  ui_story_5036_50360702_25_dialog_content = "(Sebelum saya menjalani pelatihan apa pun, saya juga bersumpah bahwa suatu hari saya akan berdiri di panggung yang lebih besar.)",
  ui_story_5036_50360702_26_dialog_content = "(Apakah saya melihat sesuatu?)",
  ui_story_5036_50360702_27_dialog_content = "(Mengapa saya melihat diri saya yang lebih muda di Vic?)",
  ui_story_5036_50360702_28_dialog_content = "(Apakah karena kita berdua percaya pada kekuatan keyakinan?)",
  ui_story_5036_50360702_29_dialog_content = "Aku harus bertahan sampai akhir!",
  ui_story_5036_50360702_30_dialog_content = "...",
  ui_story_5036_50360702_31_dialog_content = "Baiklah, aku akan mempercayaimu untuk terakhir kalinya.",
  ui_story_5036_50360702_32_dialog_content = "Usir dia! Usir dia! Usir dia!",
  ui_story_5036_50360702_33_dialog_content = "Dengar...",
  ui_story_5036_50360702_34_dialog_content = "Karena beberapa kesalahpahaman, kami salah mengira Vic sebagai pencuri hantu.",
  ui_story_5036_50360702_35_dialog_content = "Tapi semuanya beres. Vic sudah mengembalikan semuanya ke pemiliknya masing-masing dan menebus kesalahannya.",
  ui_story_5036_50360702_36_dialog_content = "Jadi, kami setuju untuk membiarkan dia melanjutkan audisi.",
  ui_story_5036_50360702_37_dialog_content = "Namun tindakannya tetap mengganggu proses.",
  ui_story_5036_50360702_38_dialog_content = "Oleh karena itu, kami hanya memberinya satu kesempatan terakhir.",
  ui_story_5036_50360702_39_dialog_content = "Jika dia masih tidak bisa datang, kami akan membuatnya pergi.",
  ui_story_5036_50360702_40_dialog_content = "Hanya ada satu atau dua hari tersisa. Dia tidak akan meningkat terlepas dari seberapa banyak dia berlatih.",
  ui_story_5036_50360702_41_dialog_content = "Tapi, sejak Nona Goldie berbicara...",
  ui_story_5036_50360702_42_dialog_content = "Saya mendukung keputusannya!",
  ui_story_5036_50360702_43_dialog_content = "Jika dia lulus dengan tarian seperti itu...",
  ui_story_5036_50360702_44_dialog_content = "Saya tidak bisa tidak meragukan Nona Goldie dan integritas acara tersebut.",
  ui_story_5036_50360702_45_dialog_content = "Tolong percayalah padaku ketika aku mengatakan aku akan adil!",
  ui_story_5036_50360702_46_dialog_content = "Goldie! Goldie! Goldie!",
  ui_story_5036_50360702_47_dialog_content = "Ahem, terima kasih, Nona Goldie.",
  ui_story_5036_50360702_48_dialog_content = "Apa yang masih kamu lakukan disini?",
  ui_story_5036_50360702_49_dialog_content = "Hah?",
  ui_story_5036_50360702_50_dialog_content = "Temukan ruangan dan mulailah berlatih.",
  ui_story_5036_50360702_51_dialog_content = "Tapi sekarang sudah sangat larut...",
  ui_story_5036_50360702_52_dialog_content = "Sudah kubilang kamu memiliki suara yang sangat bagus dan visual yang luar biasa.",
  ui_story_5036_50360702_53_dialog_content = "Anda sudah jauh di depan kurva daripada kebanyakan orang.",
  ui_story_5036_50360702_54_dialog_content = "Tetapi jika Anda benar-benar ingin mencapai akhir ...",
  ui_story_5036_50360702_55_dialog_content = "Anda harus melakukan apa yang saya katakan.",
  ui_story_5036_50360801_1_dialog_content = "<color=#e8d9bb>Tiga hari menuju konser</color>",
  ui_story_5036_50360801_2_dialog_content = "♪ Ah... Oh...",
  ui_story_5036_50360801_3_dialog_content = "Berhenti!",
  ui_story_5036_50360801_4_dialog_content = "Apakah itu lagu yang Anda rencanakan untuk dinyanyikan?",
  ui_story_5036_50360801_5_dialog_content = "Sudah kubilang aku sudah menyiapkan sesuatu, tapi tidak ada yang percaya padaku!",
  ui_story_5036_50360801_6_dialog_content = "Apakah lagu ini akan berhasil?",
  ui_story_5036_50360801_7_dialog_content = "Saya pergi ke hutan terpencil di Northland dan mengamati auroragal langka bernyanyi untuk inspirasi melodi.",
  ui_story_5036_50360801_8_dialog_content = "Ditambah dengan lirik liar dan naturistik yang ditulis oleh ahli ekstrozoologi seperti saya...",
  ui_story_5036_50360801_9_dialog_content = "Tidak mungkin itu tidak akan berjalan dengan baik!",
  ui_story_5036_50360801_10_dialog_content = "Ehem...",
  ui_story_5036_50360801_11_dialog_content = "Lagu bukan masalah. Nyanyian Anda masih memiliki banyak ruang untuk perbaikan.",
  ui_story_5036_50360801_12_dialog_content = "Saya pikir Anda mengatakannya terlalu bagus.",
  ui_story_5036_50360801_13_dialog_content = "Memang, SANGAT bagus.",
  ui_story_5036_50360801_14_dialog_content = "PlayerName adalah satu hal, tetapi mengapa Anda juga mengejek saya, Nona Reporter?",
  ui_story_5036_50360801_15_dialog_content = "Aku hanya berbicara kebenaran.",
  ui_story_5036_50360801_16_dialog_content = "Brandy adalah reporter yang baik hati, objektif, dan profesional.",
  ui_story_5036_50360801_17_dialog_content = "Jika nyanyian Anda tidak membuatnya terkesan, Anda harus mencari tahu apa masalahnya.",
  ui_story_5036_50360801_18_dialog_content = "Mungkinkah telinganya mengalami luka di masa lalu? Apakah itu sebabnya Anda tidak bisa melihat betapa indahnya suara saya, Nona Reporter?",
  ui_story_5036_50360801_19_dialog_content = "Tidak, bukan itu tujuan saya dengan ini!",
  ui_story_5036_50360801_20_dialog_content = "Um, jadi, bagaimanapun juga...",
  ui_story_5036_50360801_21_dialog_content = "Untuk menyanyikan lagu dengan benar, pertama-tama Anda harus belajar bernapas dengan benar.",
  ui_story_5036_50360801_22_dialog_content = "Saya perlu belajar bagaimana untuk bernapas?",
  ui_story_5036_50360801_23_dialog_content = "Jika Anda ingin dipilih, ikuti instruksi saya.",
  ui_story_5036_50360801_24_dialog_content = "Dimengerti, Tuan Goldie!",
  ui_story_5036_50360801_25_dialog_content = "Tarik napas dan isi perut Anda dengan udara seperti balon. Kontraksikan perut Anda saat menghembuskan napas.",
  ui_story_5036_50360801_26_dialog_content = "Ini adalah teknik pernapasan perut.",
  ui_story_5036_50360801_27_dialog_content = "Berlatihlah selama sekitar sepuluh menit.",
  ui_story_5036_50360801_28_dialog_content = "Kedengarannya seperti ketika Little Furball meringkuk dan pergi tidur.",
  ui_story_5036_50360801_29_dialog_content = "Menghirup napas...",
  ui_story_5036_50360801_30_dialog_content = "Tidak buruk. Tarik keluar lebih lama.",
  ui_story_5036_50360801_31_dialog_content = "Inhaaaaale... Hehehehe...",
  ui_story_5036_50360801_32_dialog_content = "Sangat bagus. Teruskan.",
  ui_story_5036_50360801_33_dialog_content = "Menghirup napas...",
  ui_story_5036_50360801_34_dialog_content = "Menghirup napas...",
  ui_story_5036_50360801_35_dialog_content = "Apakah Vic tertidur?",
  ui_story_5036_50360801_36_dialog_content = "Zzz...",
  ui_story_5036_50360801_37_dialog_content = "Vic!",
  ui_story_5036_50360801_38_dialog_content = "Jangan marah, Fia! Apa...?",
  ui_story_5036_50360801_39_dialog_content = "Oh, itu Goldie. Tunggu bercanda, itu Tuan Goldie.",
  ui_story_5036_50360801_40_dialog_content = "Anda seharusnya berlatih bernapas, bukan tertidur.",
  ui_story_5036_50360801_41_dialog_content = "<color=#e8d9bb>Suatu saat nanti</color>",
  ui_story_5036_50360801_42_dialog_content = "Setelah Anda mempelajari cara bernapas, Anda dapat melatih teknik vokal Anda.",
  ui_story_5036_50360801_43_dialog_content = "Suaramu bagus, Vic, tapi ingat ini!",
  ui_story_5036_50360801_44_dialog_content = "Bernyanyi tanpa teknik vokal yang tepat akan merusak pita suara Anda secara permanen.",
  ui_story_5036_50360801_45_dialog_content = "Tapi bagaimana cara mengembangkan teknik vokal yang benar, Master Goldie?",
  ui_story_5036_50360801_46_dialog_content = "Pertanyaan bagus.",
  ui_story_5036_50360801_47_dialog_content = "Saya akan mengajari Anda metode super spesial saya... Getaran bibir!",
  ui_story_5036_50360801_48_dialog_content = "Perhatikan baik-baik! Tekan kedua bibirmu, lalu...",
  ui_story_5036_50360801_49_dialog_content = "Brrrrrrrrr...",
  ui_story_5036_50360801_50_dialog_content = "Brrrrrrrrr...",
  ui_story_5036_50360801_51_dialog_content = "Wow, itu sangat bagus. Anda pembelajar yang cepat!",
  ui_story_5036_50360801_52_dialog_content = "Ini tidak sulit untuk saya lakukan sama sekali!",
  ui_story_5036_50360801_53_dialog_content = "Kadang-kadang, saya mengeluarkan suara ini di lapangan untuk mengeluarkan badak lumpur saat panas.",
  ui_story_5036_50360801_54_dialog_content = "Brrrrrrrrr...",
  ui_story_5036_50360801_55_dialog_content = "Pada hari yang baik, saya dapat menarik lebih dari selusin sekaligus!",
  ui_story_5036_50360801_56_dialog_content = "Aku… Aku mengerti…",
  ui_story_5036_50360801_57_dialog_content = "Untungnya, kita berada di langit sekarang.",
  ui_story_5036_50360801_58_dialog_content = "Bagaimanapun, berlatih ini tidak hanya akan menambah kedalaman suara Anda, tetapi juga akan mengatasi masalah pernapasan.",
  ui_story_5036_50360801_59_dialog_content = "Anda memiliki waktu kurang dari dua hari hingga putaran audisi terakhir.",
  ui_story_5036_50360801_60_dialog_content = "Jika Anda serius ingin berlatih, sehari sudah lebih dari cukup bagi Anda untuk melatih memori otot dan meningkatkan kemampuan bernyanyi Anda.",
  ui_story_5036_50360801_61_dialog_content = "Meniru rintihan badak lumpur dengan bibir saya akan meningkatkan nyanyian saya?",
  ui_story_5036_50360801_62_dialog_content = "Saya harus memperluas itu dan meniru binatang menakjubkan lainnya juga!",
  ui_story_5036_50360801_63_dialog_content = "Hai, hai hai!",
  ui_story_5036_50360801_64_dialog_content = "Hai?",
  ui_story_5036_50360801_65_dialog_content = "Hoot, hoot.",
  ui_story_5036_50360801_66_dialog_content = "Menggeram?",
  ui_story_5036_50360801_67_dialog_content = "Kicauan! Kicau, kicau!",
  ui_story_5036_50360801_68_dialog_content = "Kicauan?",
  ui_story_5036_50360801_69_dialog_content = "A-Baiklah, baiklah.",
  ui_story_5036_50360801_70_dialog_content = "Hanya badak lumpur yang akan melakukannya.",
  ui_story_5036_50360801_71_dialog_content = "Betulkah? Saya kira saya pergi terlalu jauh.",
  ui_story_5036_50360801_72_dialog_content = "Yang juga benar-benar perlu Anda kerjakan adalah tarian Anda.",
  ui_story_5036_50360801_73_dialog_content = "Bernyanyi hanyalah salah satu bagian. Menari akan menyempurnakan penampilan Anda.",
  ui_story_5036_50360801_74_dialog_content = "Kami masih perlu membuat koreografi rutin untuk lagu Anda.",
  ui_story_5036_50360801_75_dialog_content = "Sebelum kita melakukan itu, saya perlu melihat seberapa terkoordinasi Anda.",
  ui_story_5036_50360801_76_dialog_content = "Saya akan melakukan beberapa langkah tarian dasar. Cobalah yang terbaik untuk mengikuti.",
  ui_story_5036_50360801_77_dialog_content = "Dapatkah Anda menangani musik, PlayerName?",
  ui_story_5036_50360801_78_dialog_content = "Ya, saya akan memainkan pengiring!",
  ui_story_5036_50360801_79_dialog_content = "Oke, Vic, ikuti iramanya!",
  ui_story_5036_50360801_80_dialog_content = "A-satu, a-dua, gerakkan kakimu!",
  ui_story_5036_50360801_81_dialog_content = "Sekali ke kiri, sekali ke kanan!",
  ui_story_5036_50360801_82_dialog_content = "Uh, kiri... kanan... Entah kenapa tiba-tiba aku tidak bisa membedakan kiri dari kanan?!",
  ui_story_5036_50360801_83_dialog_content = "Sekarang, angkat tanganmu! Buat lingkaran di udara!",
  ui_story_5036_50360801_84_dialog_content = "Keluarkan tangan kiri, tarik kembali!",
  ui_story_5036_50360801_85_dialog_content = "Tangan kanan keluar, tarik kembali!",
  ui_story_5036_50360801_86_dialog_content = "Kaki kiri... Eh, kamu sudah di tangan kanan?!",
  ui_story_5036_50360801_87_dialog_content = "Jangan berhenti menggerakkan kaki Anda!",
  ui_story_5036_50360801_88_dialog_content = "Aku tidak melihat sesuatu, kan?",
  ui_story_5036_50360801_89_dialog_content = "Nona Goldie...",
  ui_story_5036_50360801_90_dialog_content = "Idola terpopuler Umbraton, Nona Goldie, benar-benar menari di depanku sekarang?!",
  ui_story_5036_50360801_91_dialog_content = "Bahkan Goldilock yang paling fanatik pun tidak bisa menikmati keuntungan seperti itu!",
  ui_story_5036_50360801_X91_dialog_content = "Tetap tenang, harus tetap tenang... Aku bahkan belum menemukan untuk apa aku datang kesini...",
  ui_story_5036_50360801_92_dialog_content = "Dia terlihat lebih anggun di samping Vic!",
  ui_story_5036_50360801_93_dialog_content = "Saya harus mendapatkan ini di film!",
  ui_story_5036_50360801_94_dialog_content = "Ulurkan tangan seolah-olah Anda sedang meraih impian Anda… lalu tarik ke dada Anda!",
  ui_story_5036_50360801_95_dialog_content = "A-satu, a-dua, gerakkan kakimu!",
  ui_story_5036_50360801_96_dialog_content = "Lambaikan tangan kiri, lambaikan tangan kanan!",
  ui_story_5036_50360801_97_dialog_content = "*Terengah-engah* Apakah sudah selesai?",
  ui_story_5036_50360801_98_dialog_content = "Terakhir, kami mengangkat kedua tangan!",
  ui_story_5036_50360801_99_dialog_content = "Berputar sekali!",
  ui_story_5036_50360801_100_dialog_content = "Berputar... Berputar!",
  ui_story_5036_50360801_101_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5036_50360801_102_dialog_content = "Aduh, aduh... Itu sakit.",
  ui_story_5036_50360801_103_dialog_content = "Sudah berapa kali kamu jatuh hari ini?",
  ui_story_5036_50360801_104_dialog_content = "Tidak apa-apa, aku sudah terbiasa!",
  ui_story_5036_50360801_105_dialog_content = "Sulit dipercaya bahwa Anda bahkan lebih canggung daripada balita yang belajar berjalan.",
  ui_story_5036_50360801_106_dialog_content = "Dan kau terengah-engah hanya setelah melakukan beberapa manuver sederhana... Bukankah kau berolahraga secara teratur?",
  ui_story_5036_50360801_107_dialog_content = "Apakah tidur dihitung sebagai olahraga?",
  ui_story_5036_50360801_108_dialog_content = "Ini akan menjadi masalah. Koordinasi membutuhkan waktu untuk berkembang.",
  ui_story_5036_50360801_109_dialog_content = "<color=#e8d9bb>Beberapa waktu yang lebih lama kemudian...</color>",
  ui_story_5036_50360801_110_dialog_content = "Dapatkah Anda mengingat langkah-langkahnya?",
  ui_story_5036_50360801_111_dialog_content = "Ya, itu hanya berjalan-jalan sambil melambaikan tangan!",
  ui_story_5036_50360801_112_dialog_content = "Meskipun ini adalah langkah paling dasar dan sederhana...",
  ui_story_5036_50360801_113_dialog_content = "Aku masih membutuhkanmu untuk memasukkan perasaanmu ke dalamnya.",
  ui_story_5036_50360801_114_dialog_content = "Menari dengan perasaan? Saya tidak begitu mengerti itu.",
  ui_story_5036_50360801_115_dialog_content = "Vic, menurutmu apa aset terbesar seorang idola?",
  ui_story_5036_50360801_116_dialog_content = "Kemampuan menyanyi dan menari?",
  ui_story_5036_50360801_117_dialog_content = "Benar dan salah.",
  ui_story_5036_50360801_118_dialog_content = "Mampu menyanyi dan menari sangat dibutuhkan, tidak diragukan lagi.",
  ui_story_5036_50360801_119_dialog_content = "Tapi itu hanya sarana untuk menyampaikan emosi Anda kepada audiens Anda.",
  ui_story_5036_50360801_120_dialog_content = "Hal terpenting bagi seorang idola adalah tekad dan semangat mereka yang pantang menyerah.",
  ui_story_5036_50360801_121_dialog_content = "Anda menyampaikan ini kepada penonton melalui lagu dan tarian.",
  ui_story_5036_50360801_122_dialog_content = "Ah...",
  ui_story_5036_50360801_123_dialog_content = "<size=35>Mungkin dia sudah memilikinya...</size>",
  ui_story_5036_50360801_124_dialog_content = "Apakah Anda mengatakan sesuatu, Guru?",
  ui_story_5036_50360801_125_dialog_content = "*Ahem* Anda harus terlebih dahulu mengesankan diri sendiri sebelum Anda dapat menggerakkan orang lain.",
  ui_story_5036_50360801_126_dialog_content = "Saya sudah mengatakan semua yang bisa saya katakan. Sisanya terserah padamu.",
  ui_story_5036_50360801_127_dialog_content = "Saya tidak akan menunjukkan pilih kasih selama audisi.",
  ui_story_5036_50360801_128_dialog_content = "Anda hanya memiliki satu setengah hari tersisa.",
  ui_story_5036_50360801_129_dialog_content = "Satu setengah hari lagi, dan saya dapat melanjutkan pencarian Ouroboros!",
  ui_story_5036_50360801_130_dialog_content = "*Batuk* Goldie!",
  ui_story_5036_50360801_131_dialog_content = "Terima kasih banyak telah datang pada akhirnya.",
  ui_story_5036_50360801_132_dialog_content = "Tidak masalah. Sudah tugas saya untuk memberikan nasihat kepada para kontestan.",
  ui_story_5036_50360801_133_dialog_content = "Sejujurnya, saya pikir Anda tidak akan membantunya setelah semua masalah yang dia timbulkan.",
  ui_story_5036_50360801_134_dialog_content = "Dia pasti pembuat onar.",
  ui_story_5036_50360801_135_dialog_content = "Tapi, potensinya juga tak terbantahkan.",
  ui_story_5036_50360801_136_dialog_content = "Jika dia benar-benar bisa memulai jalan untuk menjadi idola, itu juga akan menjadi semacam motivasi untukku.",
  ui_story_5036_50360801_137_dialog_content = "Hei, apakah kalian berdua mengatakan hal-hal baik tentangku?",
  ui_story_5036_50360801_138_dialog_content = "Dapatkah saya mendengarkan?",
  ui_story_5036_50360801_139_dialog_content = "Oh, aku hampir melupakan hal yang paling penting.",
  ui_story_5036_50360801_140_dialog_content = "Bagi para idola, kebugaran fisik adalah dasar dari semua yang kalian lakukan.",
  ui_story_5036_50360801_141_dialog_content = "Saya kebetulan punya rahasia untuk itu. Ingin tahu apa itu?",
  ui_story_5036_50360801_142_dialog_content = "Hei, dari mana kamu mendapatkan sangkar yang penuh dengan Eclipsites?",
  ui_story_5036_50360801_143_dialog_content = "Saya menangkap mereka, tentu saja!",
  ui_story_5036_50360801_144_dialog_content = "Astaga!",
  ui_story_5036_50360801_145_dialog_content = "Rahasiamu tidak akan kebetulan melawan Eclipsites, kan?",
  ui_story_5036_50360801_146_dialog_content = "Sisihkan teman-teman Anda yang luar biasa.",
  ui_story_5036_50360801_147_dialog_content = "Anda sendirian kali ini.",
  ui_story_5036_50360801_148_dialog_content = "Apa?",
  ui_story_5036_50360801_149_dialog_content = "Graagh!",
  ui_story_5036_50360801_150_dialog_content = "Menjauhlah dariku!",
  ui_story_5036_50360801_151_dialog_content = "Saya tahu Anda bisa melawan Eclipsites sendiri!",
  ui_story_5036_50360801_152_dialog_content = "Tapi itu terlalu melelahkan!",
  ui_story_5036_50360801_153_dialog_content = "Jangan berhenti sekarang!",
  ui_story_5036_50360801_154_dialog_content = "Teruslah bernyanyi dan menari sambil bertarung!",
  ui_story_5036_50360801_155_dialog_content = "Apa?!",
  ui_story_5036_50360801_156_dialog_content = "Kamu adalah iblis sejati!",
  ui_story_5036_50360801_157_dialog_content = "Grahhhhhhhh!",
  ui_story_5036_50360802_1_dialog_content = "<color=#e8d9bb>Dua hari menuju konser</color>",
  ui_story_5036_50360802_2_dialog_content = "Angkat tangan, semuanya! Mari...",
  ui_story_5036_50360802_3_dialog_content = "Melakukannya lagi!",
  ui_story_5036_50360802_4_dialog_content = "A-Benarkah itu pencuri yang kita lihat beberapa hari yang lalu?",
  ui_story_5036_50360802_5_dialog_content = "Mungkin dia, tapi mungkin bukan?",
  ui_story_5036_50360802_6_dialog_content = "♪ Ah, musim semi telah tiba, dan semuanya menjadi hidup kembali ! ♪",
  ui_story_5036_50360802_7_dialog_content = "♪ Hewan bangkit dari liang dan sarang mereka ♪",
  ui_story_5036_50360802_8_dialog_content = "♪ Di hutan dan padang rumput ♪",
  ui_story_5036_50360802_9_dialog_content = "♪ Manisnya hidup berlimpah ♪",
  ui_story_5036_50360802_10_dialog_content = "Aku tidak tahu apa yang dia nyanyikan...",
  ui_story_5036_50360802_11_dialog_content = "tapi melodinya entah bagaimana sangat menarik?",
  ui_story_5036_50360802_12_dialog_content = "♪ Lihat, apa itu? ♪",
  ui_story_5036_50360802_13_dialog_content = "♪ Bica kabur yang suka mengatakan \"Hai!\" ♪",
  ui_story_5036_50360802_14_dialog_content = "Hai hai hai!",
  ui_story_5036_50360802_15_dialog_content = "Hai hai hai!",
  ui_story_5036_50360802_16_dialog_content = "♪ Lihat, apa itu? ♪",
  ui_story_5036_50360802_17_dialog_content = "♪ Burung Hantu Lutumi ada di tikungan. Awasi kantong Anda! ♪",
  ui_story_5036_50360802_18_dialog_content = "Kacau!",
  ui_story_5036_50360802_19_dialog_content = "Kaok kaok!!",
  ui_story_5036_50360802_20_dialog_content = "Goldie, apakah Anda menemukan seseorang untuk menyamar sebagai Vic?",
  ui_story_5036_50360802_21_dialog_content = "Apa maksudmu?",
  ui_story_5036_50360802_22_dialog_content = "Maksudku, dia meningkat pesat hanya dalam satu setengah hari!",
  ui_story_5036_50360802_23_dialog_content = "Saya bahkan tidak mengenali orang ini di depan mata saya.",
  ui_story_5036_50360802_24_dialog_content = "Dia seperti orang yang sama sekali berbeda!",
  ui_story_5036_50360802_25_dialog_content = "Sudah kubilang Vic punya potensi idola yang hebat.",
  ui_story_5036_50360802_26_dialog_content = "Dia adalah berlian yang kasar yang membutuhkan sedikit polesan untuk bersinar.",
  ui_story_5036_50360802_27_dialog_content = "Sukacita pertumbuhan!",
  ui_story_5036_50360802_28_dialog_content = "Siapa di sini yang memahami kegembiraan pertumbuhan?",
  ui_story_5036_50360802_29_dialog_content = "Nyaris sempurna dalam menyanyi, menari, berpenampilan, bertubuh, EQ, dan IQ.",
  ui_story_5036_50360802_30_dialog_content = "Akhirnya, seorang kontestan yang berpengetahuan luas!",
  ui_story_5036_50360802_31_dialog_content = "Aku tidak percaya aku terpesona oleh penampilan itu...",
  ui_story_5036_50360802_32_dialog_content = "Maafkan aku, Dewa Cahaya!",
  ui_story_5036_50360802_33_dialog_content = "Ya, peningkatan yang bagus.",
  ui_story_5036_50360802_34_dialog_content = "♪ Brrrrrrrrr... ♪",
  ui_story_5036_50360802_35_dialog_content = "♪ Ada yang melihat telur Ouroboros yang sulit ditangkap♪",
  ui_story_5036_50360802_36_dialog_content = "♪ Brrrrrrrrr... ♪",
  ui_story_5036_50360802_37_dialog_content = "♪ Aku tidak akan berhenti sampai aku menemukanmu ♪",
  ui_story_5036_50360802_38_dialog_content = "Dan itulah akhirnya. Terima kasih semuanya!",
  ui_story_5036_50360802_39_dialog_content = "Vic! Vic! Vic! Vic!",
  ui_story_5036_50360802_40_dialog_content = "Seperti yang bisa kita lihat, seluruh venue diambil oleh pertunjukan itu!",
  ui_story_5036_50360802_41_dialog_content = "Terima kasih, Vic, untuk pertunjukan yang luar biasa!",
  ui_story_5036_50360802_42_dialog_content = "Mari kita lihat apa kata juri kita.",
  ui_story_5036_50360802_43_dialog_content = "Nona Goldie, semuanya milikmu!",
  ui_story_5036_50360802_44_dialog_content = "Saya tidak punya apa-apa untuk dikatakan.",
  ui_story_5036_50360802_45_dialog_content = "Apa? Tapi saya begadang untuk berlatih selama dua malam berturut-turut! Aku masih tidak bisa?",
  ui_story_5036_50360802_46_dialog_content = "Saya akan tetap di tempat tidur jika saya tahu itu.",
  ui_story_5036_50360802_47_dialog_content = "Yang saya maksud adalah kinerja Anda terlalu bagus bagi saya untuk menemukan kekurangan.",
  ui_story_5036_50360802_48_dialog_content = "Saya yakin suara kita akan berbicara sendiri.",
  ui_story_5036_50360802_49_dialog_content = "Baik! Hasilnya ada di.",
  ui_story_5036_50360802_50_dialog_content = "Mari kita lihat apakah Vic bisa tampil di panggung konser!",
  ui_story_5036_50360802_51_dialog_content = "Dia menerima...",
  ui_story_5036_50360802_52_dialog_content = "saya terima...?",
  ui_story_5036_50360802_53_dialog_content = "<size=45>Suara bulat!</size>",
  ui_story_5036_50360802_54_dialog_content = "Dengan serius? Bahkan pemula berhasil. Tekanan untuk seseorang tertentu.",
  ui_story_5036_50360802_55_dialog_content = "Haruskah saya menyanyikan lagu yang positif untuk memompa semangatnya?",
  ui_story_5036_50360802_56_dialog_content = "Bawa musik pop sakarin Anda yang monoton ke tempat lain.",
  ui_story_5036_50360802_57_dialog_content = "Oh, tapi aku akan sangat sedih dan kesepian jika kamu tidak berhasil.",
  ui_story_5036_50360802_58_dialog_content = "Anda hanya berhasil sebelum saya karena Anda tampil sebelum saya.",
  ui_story_5036_50360802_59_dialog_content = "Tunggu dan lihat saja. Para juri akan menyesal memilihmu sebagai badut setelah mereka melihat penampilanku!",
  ui_story_5036_50360802_60_dialog_content = "Bagaimana perasaanmu, Vik?",
  ui_story_5036_50360802_61_dialog_content = "Akhirnya, saatnya tidur…",
  ui_story_5036_50360802_62_dialog_content = "Saat aku bangun, aku...",
  ui_story_5036_50360802_63_dialog_content = "bisa pergi mencari... Ourobo...",
  ui_story_5036_50360802_64_dialog_content = "Vic?",
  ui_story_5036_50360802_65_dialog_content = "Apakah kamu baik-baik saja, Vik?",
  ui_story_5036_50360802_66_dialog_content = "Zzz...",
  ui_story_5036_50360802_67_dialog_content = "eh, Vik...",
  ui_story_5036_50360802_68_dialog_content = "Tolong jangan tertidur selama audisi!",
  ui_story_5036_50360802_69_dialog_content = "Sepertinya Vic benar-benar tertidur lelap.",
  ui_story_5036_50360802_70_dialog_content = "Aku tidak percaya dia tidur sepanjang hari, melalui semua kebisingan itu!",
  ui_story_5036_50360802_71_dialog_content = "Ya, dia bahkan tidak bangun ketika tentara menyeretnya kembali ke kamarnya.",
  ui_story_5036_50360802_72_dialog_content = "Kami semua menyaksikan peningkatannya.",
  ui_story_5036_50360802_73_dialog_content = "Dia pasti kelelahan karena berlatih begitu keras selama dua hari terakhir.",
  ui_story_5036_50360802_74_dialog_content = "Saya pikir kalian berdua berlatih keras juga.",
  ui_story_5036_50360802_75_dialog_content = "Atau Anda juga tidak akan mendapatkan suara bulat.",
  ui_story_5036_50360802_76_dialog_content = "Oh, kami benar-benar mengharapkan itu!",
  ui_story_5036_50360802_77_dialog_content = "Tapi ya, aku lelah.",
  ui_story_5036_50360802_78_dialog_content = "Kita harus menyerahkan lebih awal hari ini.",
  ui_story_5036_50360802_79_dialog_content = "Akan ada latihan sehari penuh besok.",
  ui_story_5036_50360802_80_dialog_content = "Aku harap aku tidak bermimpi lagi malam ini.",
  ui_story_5036_50360802_81_dialog_content = "Ya. Selamat malam.",
  ui_story_5036_50360802_82_dialog_content = "Keburukan? Carleen?",
  ui_story_5036_50360802_83_dialog_content = "Mereka pergi begitu cepat...",
  ui_story_5036_50360802_84_dialog_content = "Jadi...",
  ui_story_5036_50360802_85_dialog_content = "Aku harus menyerahkan juga.",
  ui_story_5036_50360901_1_dialog_content = "Dimana saya...?",
  ui_story_5036_50360901_2_dialog_content = "Pada Colossus, saya pikir... Apakah itu Caelestite yang ada dalam mimpi saya sebelumnya?",
  ui_story_5036_50360901_3_dialog_content = "Apa aku bermimpi lagi?",
  ui_story_5036_50360901_4_dialog_content = "Anda Eulogoz, kan?",
  ui_story_5036_50360901_5_dialog_content = "Ya. Anda Navigator baru saya, saya kira?",
  ui_story_5036_50360901_6_dialog_content = "Betul sekali! Nama saya Chaminade. Senang bertemu denganmu.",
  ui_story_5036_50360901_7_dialog_content = "(Lokasinya berubah... Sepertinya ini jembatannya?)",
  ui_story_5036_50360901_8_dialog_content = "Mengapa Anda memiliki begitu banyak layar dan sistem suara yang aneh, Eulogoz?",
  ui_story_5036_50360901_9_dialog_content = "Saya bertanya kepada teman-teman saya, dan mereka belum pernah melihat yang seperti ini di Colossi lain sebelumnya.",
  ui_story_5036_50360901_10_dialog_content = "Bahkan saya tidak tahu jawaban untuk pertanyaan itu.",
  ui_story_5036_50360901_11_dialog_content = "Kenangan lama lepas dariku seperti bernyanyi tertiup angin.",
  ui_story_5036_50360901_12_dialog_content = "Sayang sekali...",
  ui_story_5036_50360901_13_dialog_content = "Tapi semua orang mencintaimu!",
  ui_story_5036_50360901_14_dialog_content = "Hanya Anda yang dapat membuat musik bergema di seluruh Eraveil.",
  ui_story_5036_50360901_15_dialog_content = "Terima kasih. Saya sangat senang mendengarnya.",
  ui_story_5036_50360901_16_dialog_content = "Ayo jalan-jalan, Eulogoz!",
  ui_story_5036_50360901_17_dialog_content = "Hmm? Mengapa begitu tiba-tiba?",
  ui_story_5036_50360901_18_dialog_content = "Guru saya mengatakan bahwa banyak orang di Astra masih menderita akibat perang dan gerhana.",
  ui_story_5036_50360901_19_dialog_content = "Hidup mereka tanpa harapan dan sulit, jadi saya ingin bernyanyi untuk mereka!",
  ui_story_5036_50360901_20_dialog_content = "Aku tahu nyanyianku tidak bisa mengalahkan Eclipsites atau memberi mereka sesuatu yang berguna...",
  ui_story_5036_50360901_21_dialog_content = "tapi paling tidak, saya bisa memberi mereka sesuatu untuk didengarkan selain tembakan.",
  ui_story_5036_50360901_22_dialog_content = "Tempat-tempat seperti itu terlalu berbahaya untukmu.",
  ui_story_5036_50360901_23_dialog_content = "Aku tahu, tapi jika nyanyianku bisa memberi mereka sedikit kenyamanan dan harapan, bahaya apa pun sepadan.",
  ui_story_5036_50360901_24_dialog_content = "Aku mengerti.",
  ui_story_5036_50360901_25_dialog_content = "Mari kita pergi sekarang.",
  ui_story_5036_50360901_26_dialog_content = "Mimpi lain? Tapi rasanya berbeda... lebih seperti kenangan.",
  ui_story_5036_50360901_27_dialog_content = "Jadi nama gadis Caelestite itu adalah Chaminade.",
  ui_story_5036_50360901_28_dialog_content = "Kecuali mimpi itu adalah aku yang merasakan jejak kehadirannya di Colossus ini.",
  ui_story_5036_50360901_29_dialog_content = "Caelestite bernyanyi mengendarai Colossus, tur melalui Astra... Dia terdengar sangat mirip Goldie.",
  ui_story_5036_50360901_30_dialog_content = "* Menguap * Saya yakin banyak bermimpi hanya untuk satu jam tidur.",
  ui_story_5036_50360901_31_dialog_content = "Aku tidak akan bisa tidur kembali untuk sementara waktu... mungkin aku harus makan.",
  ui_story_5036_50360901_32_dialog_content = "<color=#e8d9bb>Tok, tok!</color>",
  ui_story_5036_50360901_33_dialog_content = "(Siapa yang mengetuk selarut ini?)",
  ui_story_5036_50360901_34_dialog_content = "Aku datang!",
  ui_story_5036_50360901_35_dialog_content = "Maaf, PlayerName, apakah aku membangunkanmu?",
  ui_story_5036_50360901_36_dialog_content = "Tidak, aku bangun... Apa yang kau lakukan disini, Goldie?",
  ui_story_5036_50360901_37_dialog_content = "Saya membutuhkan bantuan Anda. Seluruh masa depan konser bergantung padanya!",
  ui_story_5036_50360901_38_dialog_content = "Serius itu? Apakah Eulogoz mogok?",
  ui_story_5036_50360901_39_dialog_content = "Tidak, tidak seburuk itu... Apakah kamu mengalami mimpi aneh akhir-akhir ini?",
  ui_story_5036_50360901_40_dialog_content = "Mimpi tentang lembah yang luas, dan suara nyanyian seorang gadis.",
  ui_story_5036_50360901_41_dialog_content = "Ya, saya punya. Untuk alasan apa pun, saya mengalami mimpi itu setiap malam.",
  ui_story_5036_50360901_42_dialog_content = "Lembah itu adalah Eraveil, dan gadis itu adalah seorang Caelestite.",
  ui_story_5036_50360901_43_dialog_content = "Jadi dia Caelestite?!",
  ui_story_5036_50360901_44_dialog_content = "Bukankah cara dia berpakaian memberikannya?",
  ui_story_5036_50360901_45_dialog_content = "Mimpinya aneh, tapi aku tidak terlalu memperhatikannya karena ini bukan mimpi buruk.",
  ui_story_5036_50360901_46_dialog_content = "Tunggu, bukankah kita membicarakan ini sebelumnya dan menganggapnya sebagai kebetulan?",
  ui_story_5036_50360901_47_dialog_content = "Itu juga yang kupikirkan, tapi sekarang, semua orang di Colossus memiliki mimpi yang sama!",
  ui_story_5036_50360901_48_dialog_content = "Setiap orang?!",
  ui_story_5036_50360901_49_dialog_content = "Ya. Ini kebetulan ketika dua atau tiga orang, tetapi tidak ketika semua orang!",
  ui_story_5036_50360901_50_dialog_content = "Itu membuat semua orang cemas.",
  ui_story_5036_50360901_51_dialog_content = "Para kontestan datang kepada saya mengeluh bahwa mimpi itu mengganggu tidur mereka.",
  ui_story_5036_50360901_52_dialog_content = "Mereka tidak dapat bekerja dengan baik tanpa istirahat yang cukup.",
  ui_story_5036_50360901_53_dialog_content = "Jadi, Anda ingin mengetahui akar masalahnya untuk memastikan istirahat yang layak bagi semua orang?",
  ui_story_5036_50360901_54_dialog_content = "Ya. Saya mencoba mencarinya sendiri, tetapi tidak berhasil, karena saya tidak memiliki kemampuan psikis Anda.",
  ui_story_5036_50360901_55_dialog_content = "Bisakah kamu membantuku, PlayerName?",
  ui_story_5036_50360901_56_dialog_content = "Demi konser, pastinya!",
  ui_story_5036_50360901_57_dialog_content = "Terima kasih!",
  ui_story_5036_50360901_58_dialog_content = "Tetapi mengingat ukuran Eulogoz yang tipis, saya tidak dapat menutupi seluruh struktur bahkan dengan telepati saya.",
  ui_story_5036_50360901_59_dialog_content = "Di mana kita harus mulai?",
  ui_story_5036_50360901_60_dialog_content = "Entahwah...",
  ui_story_5036_50360901_61_dialog_content = "Saya sarankan mulai dari bagian belakang!",
  ui_story_5036_50360901_62_dialog_content = "Vic! Darimana asalmu?",
  ui_story_5036_50360901_63_dialog_content = "Konsernya dua hari lagi! Bukankah seharusnya kau berlatih?",
  ui_story_5036_50360901_64_dialog_content = "Ayolah, bukankah kamu hanya stres karena mimpi aneh itu?",
  ui_story_5036_50360901_65_dialog_content = "Anda perlu mendapatkan tidur yang berkualitas terlebih dahulu agar memiliki energi untuk berlatih.",
  ui_story_5036_50360901_66_dialog_content = "Itu benar, tapi mendengarnya dari mulutmu itu mencurigakan.",
  ui_story_5036_50360901_67_dialog_content = "Ha ha ha! Kau hanya menjadi paranoid.",
  ui_story_5036_50360901_68_dialog_content = "Mencurigakan melihatmu begitu proaktif.",
  ui_story_5036_50360901_69_dialog_content = "Aku ingat sekarang! Anda ingin mencari Ouroboros di sana. Anda pasti memiliki motif tersembunyi!",
  ui_story_5036_50360901_70_dialog_content = "Bagaimana Anda bisa mengatakan itu? Semakin banyak, semakin meriah. Anda tidak akan rugi membiarkan saya ikut.",
  ui_story_5036_50360901_71_dialog_content = "Oke, tapi aku akan melihatmu dalam latihan besok, jadi jangan mencoba mengendur.",
  ui_story_5036_50360901_72_dialog_content = "Ahli ekstrozoologi tidak berbohong.",
  ui_story_5036_50360901_73_dialog_content = "Tapi untuk saat ini, mari berkonsentrasi untuk menghadapi mimpi aneh itu.",
  ui_story_5036_50360901_74_dialog_content = "(Mencurigakan bahwa Vic sangat tertarik dengan ini.)",
  ui_story_5036_50360901_75_dialog_content = "(Apa yang dia rencanakan?)",
  ui_story_5036_50360901_76_dialog_content = "Bagian belakang... Bukankah itu tempat Eclipsites berada?",
  ui_story_5036_50360901_77_dialog_content = "Adakah bukti yang menunjukkan bahwa kita harus mulai dengan tempat berbahaya seperti itu?",
  ui_story_5036_50360901_78_dialog_content = "Tidak sama sekali!",
  ui_story_5036_50360901_79_option_content = "Mari kita abaikan dia",
  ui_story_5036_50360901_80_dialog_content = "Oh ayolah, PlayerName, kami pernah bekerja sama sebelumnya. Jangan terlalu kejam!",
  ui_story_5036_50360901_81_option_content = "...",
  ui_story_5036_50360901_82_dialog_content = "...",
  ui_story_5036_50360901_83_dialog_content = "Orang-orang muda begitu mudah bingung karena masih banyak yang belum mereka lihat.",
  ui_story_5036_50360901_84_dialog_content = "Saya tidak punya bukti nyata, tetapi saran saya bukannya tidak berdasar.",
  ui_story_5036_50360901_85_dialog_content = "Bagian atas semuanya bersih dari Eclipsites, jadi semua orang bisa bergerak dengan bebas.",
  ui_story_5036_50360901_86_dialog_content = "Secara alami, itu berarti area tersebut tidak perlu diselidiki.",
  ui_story_5036_50360901_87_dialog_content = "BENAR. Seseorang akan menyadari ada sesuatu yang salah sekarang.",
  ui_story_5036_50360901_88_dialog_content = "Sehingga hanya menyisakan bagian belakang saja.",
  ui_story_5036_50360901_89_dialog_content = "Tapi ada banyak Eclipsites di sana. Ini terlalu berisiko dengan hanya kami bertiga.",
  ui_story_5036_50360901_90_dialog_content = "Saya memikirkan itu juga. Kami hanya membutuhkan Lutumi Owl untuk membantu.",
  ui_story_5036_50360901_91_dialog_content = "Biarkan itu menidurkan Eclipsites sebelum kita menyelinap masuk. Itu seharusnya meminimalkan kebutuhan untuk bertarung.",
  ui_story_5036_50360901_92_dialog_content = "Itukah caramu mencuri semua barang itu sebelumnya?",
  ui_story_5036_50360901_93_dialog_content = "Tentu saja tidak!",
  ui_story_5036_50360901_94_dialog_content = "Ngomong-ngomong, burung hantulah yang menyebabkan semua kesalahpahaman itu.",
  ui_story_5036_50360901_95_dialog_content = "Sekarang, kita akan membiarkannya menebus masalahnya. Bagaimana dengan itu?",
  ui_story_5036_50360901_96_dialog_content = "Mari kita bahas masalah ini setelah konser.",
  ui_story_5036_50360901_97_dialog_content = "Vic memang ada benarnya. Mari kita mulai dengan bagian belakang Colossus.",
  ui_story_5036_50360901_98_dialog_content = "Oke, ayo pergi.",
  ui_story_5036_50360901_99_dialog_content = "Aku akan mendekati Goldie tentang gosip jahatnya...",
  ui_story_5036_50360901_100_dialog_content = "tapi sekarang mereka bertiga sedang melakukan sesuatu yang rahasia!",
  ui_story_5036_50360901_101_dialog_content = "Untungnya, saya terlalu jauh untuk PlayerName merasakan saya dengan keahliannya!",
  ui_story_5036_50360901_102_dialog_content = "Mereka terlalu jauh bagi saya untuk mendengarnya dengan jelas ...",
  ui_story_5036_50360901_103_dialog_content = "Bukankah itu... di mana bagian belakangnya?",
  ui_story_5036_50360901_104_dialog_content = "Mereka bertindak terlalu mencurigakan bagi saya untuk tidak mengikuti!",
  ui_story_5036_50360901_105_dialog_content = "Di sini sangat gelap... Sepertinya Eclipsites akan muncul kapan saja.",
  ui_story_5036_50360901_106_dialog_content = "Santai dan serahkan semuanya pada Lutumi Owl. Lihat.",
  ui_story_5036_50360901_107_dialog_content = "Kacau!",
  ui_story_5036_50360901_108_dialog_content = "(Eclipsian) L-Lady Forsakin?!",
  ui_story_5036_50360901_109_dialog_content = "Kaok kaok!!",
  ui_story_5036_50360901_110_dialog_content = "(Eclipsian) Terima kasih atas pujiannya. Saya akan bekerja lebih keras!",
  ui_story_5036_50360901_111_dialog_content = "(Eclipsian) Saya tidak percaya saya dipuji... Sangat aneh... sangat mengantuk...",
  ui_story_5036_50360901_112_dialog_content = "(Eclipsian) Menguap...",
  ui_story_5036_50360901_113_dialog_content = "Melihat? Mudah sekali.",
  ui_story_5036_50360901_114_dialog_content = "Apakah Anda yakin ini tidak dihitung sebagai mengeksploitasi hewan untuk kekuatannya?",
  ui_story_5036_50360901_115_dialog_content = "Lutumi Owl adalah temanku. Ini membantu saya dengan sukarela. Saya yakin itu.",
  ui_story_5036_50360901_116_dialog_content = "Disini sangat gelap...",
  ui_story_5036_50360901_117_dialog_content = "*Merintih* Tidak! Aku harus terus berjalan!",
  ui_story_5036_50360901_118_dialog_content = "Apakah kamu baik-baik saja, Goldie?",
  ui_story_5036_50360901_119_dialog_content = "Hah? Saya baik-baik saja!",
  ui_story_5036_50360901_120_dialog_content = "Mengapa seorang idola tidak baik-baik saja? Aku hanya sedikit lelah dan butuh istirahat.",
  ui_story_5036_50360901_121_dialog_content = "Biarkan aku memelukmu, Marshmallow.",
  ui_story_5036_50360901_122_dialog_content = "Pakan...",
  ui_story_5036_50360901_123_dialog_content = "Sangat lembut dan kabur... Oke, saya siap sekarang!",
  ui_story_5036_50360901_124_dialog_content = "Ayo lanjutkan!",
  ui_story_5036_50360901_125_dialog_content = "(Goldie bertingkah aneh. Apakah dia takut pada kegelapan?)",
  ui_story_5036_50360901_126_dialog_content = "Kita sudah berjalan begitu lama... Seharusnya kita sudah dekat dengan ekor Colossus sekarang.",
  ui_story_5036_50360901_X126_dialog_content = "Dapatkah Anda merasakan sesuatu di dekatnya, PlayerName?",
  ui_story_5036_50360901_127_dialog_content = "Biarku lihat.",
  ui_story_5036_50360901_128_option_content = "Force Boost!",
  ui_story_5036_50360901_129_dialog_content = "(Tidak ada apa-apa selain Eclipsites yang tertidur di sekitar.)",
  ui_story_5036_50360901_130_dialog_content = "(Kecuali ada sesuatu yang terasa aneh... apakah saya paranoid?)",
  ui_story_5036_50360901_131_dialog_content = "(Tunggu, ini terasa...)",
  ui_story_5036_50360901_132_dialog_content = "(Rasanya sangat mirip dengan ketika saya merasakan emosi Caelestites yang tersisa ketika saya kembali ke Eraveil untuk pertama kalinya!)",
  ui_story_5036_50360901_133_dialog_content = "(Biarkan saya mencoba untuk menggali lebih dalam.)",
  ui_story_5036_50360901_134_dialog_content = "Wah! A-Apa ini, Eulogoz?",
  ui_story_5036_50360901_135_dialog_content = "Jangan panik, Chaminade, ini bukan Eclipsite.",
  ui_story_5036_50360901_136_dialog_content = "Menurut data saya, itu adalah binatang yang disebut Ouroboros. Sangat bersahabat dengan Aurorian dan Caelestites.",
  ui_story_5036_50360901_137_dialog_content = "Syukurlah itu bukan Eclipsite.",
  ui_story_5036_50360901_138_dialog_content = "Kree, Kree!",
  ui_story_5036_50360901_139_dialog_content = "Hee, berhenti menjilati wajahku!",
  ui_story_5036_50360901_140_dialog_content = "Kau merasakan sesuatu, PlayerName?",
  ui_story_5036_50360901_141_dialog_content = "Lagipula namanya adalah Chaminade...",
  ui_story_5036_50360901_142_dialog_content = "Chaminade? Apakah Anda berbicara tentang gadis Caelestite itu?",
  ui_story_5036_50360901_143_dialog_content = "Ya. Aku merasakan jejaknya yang tertinggal, dan...",
  ui_story_5036_50360901_144_dialog_content = "Ouroboros juga!",
  ui_story_5036_50360901_145_dialog_content = "Apa?!",
  ui_story_5036_50360901_146_dialog_content = "Anda merasakan Ouroboros? Cepat, ceritakan lebih banyak!",
  ui_story_5036_50360901_147_dialog_content = "Berhenti mengguncangku dan lepaskan sebelum aku muntah!",
  ui_story_5036_50360901_148_dialog_content = "Bicara dulu, baru saya lepaskan.",
  ui_story_5036_50360901_149_dialog_content = "Apa yang saya rasakan bukanlah Ouroboros dari masa sekarang tetapi dari masa lalu!",
  ui_story_5036_50360901_150_dialog_content = "Masa lalu?",
  ui_story_5036_50360901_151_dialog_content = "Mantan pemilik Colossus ini dan gadis Caelestite yang diimpikan semua orang, namanya Chaminade.",
  ui_story_5036_50360901_152_dialog_content = "Sekali waktu, dia bertemu dengan Ouroboros dan membiarkannya tetap di kapal.",
  ui_story_5036_50360901_153_dialog_content = "Tapi saya menduga itu terjadi setidaknya seratus tahun yang lalu.",
  ui_story_5036_50360901_154_dialog_content = "Ouroboros yang Anda cari mungkin sudah lama hilang.",
  ui_story_5036_50360901_155_dialog_content = "Oh...",
  ui_story_5036_50360901_156_dialog_content = "Katakan, bagaimana kalau melepaskanku?",
  ui_story_5036_50360901_157_dialog_content = "Ya, Anda tidak mendapatkan lokasinya, tetapi itu masih merupakan informasi yang berharga.",
  ui_story_5036_50360901_158_dialog_content = "Bantu aku Caelestite muda, tetap gunakan indramu itu!",
  ui_story_5036_50360901_159_dialog_content = "Pertimbangkan ini membayar saya kembali untuk semua bahaya yang diderita siswa tersayang Fia demi Anda!",
  ui_story_5036_50360901_160_dialog_content = "Membayar ANDA kembali?!",
  ui_story_5036_50360901_161_dialog_content = "Berhenti! Bukankah kita seharusnya memecahkan masalah mimpi sekarang?",
  ui_story_5036_50360901_162_dialog_content = "Kapan tujuan kami menjadi tentang menemukan Ouroboros?",
  ui_story_5036_50360901_163_dialog_content = "Oh ya, saya hampir teralihkan!",
  ui_story_5036_50360901_164_dialog_content = "Anak-anak muda, Anda melihat ini dengan cara yang salah.",
  ui_story_5036_50360901_165_dialog_content = "Bukankah kau bilang Caelestite dengan Ouroboros adalah gadis dalam mimpi kita?",
  ui_story_5036_50360901_166_dialog_content = "Ya... Dan kita harus memusatkan penyelidikan kita pada dia, apapun itu.",
  ui_story_5036_50360901_167_dialog_content = "Yah, saya hanya meminta Anda mengawasi petunjuk tentang Ouroboros untuk sementara.",
  ui_story_5036_50360901_168_dialog_content = "Mengapa saya merasa seperti memberi Anda tenaga kerja gratis?",
  ui_story_5036_50360901_169_dialog_content = "Ini bukan tenaga kerja gratis. Menghormati orang yang lebih tua adalah kebajikan yang baik.",
  ui_story_5036_50360901_170_dialog_content = "Anda benar-benar memikirkan apa pun, bukan ...",
  ui_story_5036_50360901_171_dialog_content = "Wah terima kasih.",
  ui_story_5036_50360901_172_dialog_content = "Kita butuh PlayerName untuk menyelidiki mimpi itu.",
  ui_story_5036_50360901_173_dialog_content = "Maukah Anda merasakan lagi di tempat lain untuk melihat apakah Anda dapat menemukan jejak yang tersisa?",
  ui_story_5036_50360901_174_dialog_content = "Mungkin kita bisa memilah-milahnya dan mengungkap sumber mimpi itu.",
  ui_story_5036_50360901_175_dialog_content = "Tentu, saya akan mencobanya!",
  ui_story_5036_50360901_176_dialog_content = "Saya belum pernah ke sini sebelumnya.",
  ui_story_5036_50360901_177_dialog_content = "Kami lebih dekat ke bagian belakang daripada sebelumnya, jadi kami bisa menemukan sesuatu yang baru.",
  ui_story_5036_50360901_178_dialog_content = "Goldie, Vic, apakah kalian merasakan sesuatu yang aneh tentang tempat ini?",
  ui_story_5036_50360901_179_dialog_content = "Agak dingin. Mungkin karena Darkflow?",
  ui_story_5036_50360901_180_dialog_content = "Tidak, saya tidak merasakan terlalu banyak Darkflow. Aku hanya merasa cemas untuk beberapa alasan.",
  ui_story_5036_50360901_181_dialog_content = "Kau tidak takut gelap, kan?",
  ui_story_5036_50360901_182_dialog_content = "Tentu saja tidak!",
  ui_story_5036_50360901_183_dialog_content = "Tidak ada yang perlu dipermalukan.",
  ui_story_5036_50360901_184_dialog_content = "Shira takut gelap ketika dia masih muda. Angin akan membuatnya takut hingga menangis di malam hari!",
  ui_story_5036_50360901_185_dialog_content = "Selain memangsa burung, drakolion juga bisa... Achoo!",
  ui_story_5036_50360901_186_dialog_content = "... Bisa juga bersin?",
  ui_story_5036_50360901_187_dialog_content = "Tidak, tidak... Achoo!",
  ui_story_5036_50360901_188_dialog_content = "Aku hanya perlu bersin tiba-tiba.",
  ui_story_5036_50360901_189_dialog_content = "Apakah Anda masuk angin?",
  ui_story_5036_50360901_190_dialog_content = "Tidak. Saya menduga Vic adalah sampah berbicara saya di suatu tempat.",
  ui_story_5036_50360901_191_dialog_content = "Aku akan memarahinya tentang hal itu ketika dia kembali.",
  ui_story_5036_50360901_192_dialog_content = "Apakah kamu berbohong lagi?",
  ui_story_5036_50360901_193_dialog_content = "Tidak mungkin. Tanya Shira kalau tidak percaya.",
  ui_story_5036_50360901_194_dialog_content = "Sudahlah, aku punya hal-hal yang lebih baik untuk dilakukan.",
  ui_story_5036_50360901_X194_dialog_content = "Tampaknya ada beberapa emosi yang masih melekat di sini. Saya akan mencoba merasakannya.",
  ui_story_5036_50360901_195_option_content = "Mindlink!",
  ui_story_5036_50360901_196_dialog_content = "♪ Tetesan embun, menangkap fajar keemasan ♪",
  ui_story_5036_50360901_197_dialog_content = "♪ Bersinar dengan malu-malu ♪",
  ui_story_5036_50360901_198_dialog_content = "(Ini lagu untuk memulai Colossus!)",
  ui_story_5036_50360901_199_dialog_content = "Kree, kree... kree!",
  ui_story_5036_50360901_200_dialog_content = "Ouroboros? Apakah kamu tidak tidur? Apa yang kamu lakukan di sini?",
  ui_story_5036_50360901_201_dialog_content = "Kree—♪ Kree—♪",
  ui_story_5036_50360901_202_dialog_content = "Apakah kamu bernyanyi ?! Lagu yang baru saja aku nyanyikan?!",
  ui_story_5036_50360901_203_dialog_content = "Apakah Anda mengerti musik saya ?!",
  ui_story_5036_50360901_204_dialog_content = "Kree— ♪ Kree, kree, kree ♪",
  ui_story_5036_50360901_205_dialog_content = "Apakah itu sebuah penegasan?!",
  ui_story_5036_50360901_206_dialog_content = "Alangkah menakjubkannya, makhluk itu bisa berkomunikasi menggunakan melodi yang digunakan Caelestites untuk mengendalikan Colossi.",
  ui_story_5036_50360901_207_dialog_content = "Aku merasakan sesuatu yang lain...",
  ui_story_5036_50360901_208_dialog_content = "Kenangan ini hanya datang kepada saya dalam potongan-potongan kecil.",
  ui_story_5036_50360901_209_dialog_content = "Apa itu? Katakan padaku!",
  ui_story_5036_50360901_210_dialog_content = "Apakah mereka menyebutkan sesuatu tentang mimpi aneh itu?",
  ui_story_5036_50360901_211_dialog_content = "Tidak.",
  ui_story_5036_50360901_212_dialog_content = "Saya merasakan kejutan menyenangkan Chaminade saat dia menemukan rahasia Ouroboros secara kebetulan.",
  ui_story_5036_50360901_213_dialog_content = "Makhluk ini tampaknya mampu menyampaikan emosi dan berkomunikasi dengan manusia menggunakan melodi untuk mengendalikan Colossi.",
  ui_story_5036_50360901_214_dialog_content = "Itu benar-benar informasi baru yang berkaitan dengan Ouroboros!",
  ui_story_5036_50360901_215_dialog_content = "Bagus sekali! Aku tidak punya apa-apa untuk membalasmu.",
  ui_story_5036_50360901_216_dialog_content = "...",
  ui_story_5036_50360901_217_dialog_content = "Anda tahu, buku-buku kuno menyebutkan hubungan misterius antara spesies ini dan Colossi.",
  ui_story_5036_50360901_218_dialog_content = "Kami tidak dapat mengabaikan kemungkinan bahwa mungkin mereka juga memiliki kemampuan psikis tertentu.",
  ui_story_5036_50360901_219_dialog_content = "Misalnya... membuat orang bermimpi.",
  ui_story_5036_50360901_220_dialog_content = "Kau pikir begitu?!",
  ui_story_5036_50360901_221_dialog_content = "Aku benar-benar akan menghukummu kali ini jika kau berbohong!",
  ui_story_5036_50360901_222_dialog_content = "Saya tidak akan berani!",
  ui_story_5036_50360901_223_dialog_content = "Itu hanya teori. Saya tidak dapat menjamin bahwa saya benar.",
  ui_story_5036_50360901_224_dialog_content = "Betapa meragukan...",
  ui_story_5036_50360901_225_dialog_content = "Bagaimana menurutmu, PlayerName?",
  ui_story_5036_50360901_226_option_content = "Percaya Vik",
  ui_story_5036_50360901_227_dialog_content = "Sementara Vic biasanya banyak berbohong dan tidak terlalu bisa diandalkan...",
  ui_story_5036_50360901_228_dialog_content = "dia benar-benar otoritas mutlak pada semua hal yang berhubungan dengan binatang yang menakjubkan.",
  ui_story_5036_50360901_229_dialog_content = "Seharusnya tidak menjadi masalah untuk memercayainya di bidang itu.",
  ui_story_5036_50360901_230_dialog_content = "Memang, Anda harus selalu mendengarkan orang tua Anda.",
  ui_story_5036_50360901_231_dialog_content = "Baiklah, saya percaya penilaian PlayerName.",
  ui_story_5036_50360901_232_option_content = "Jangan percaya Vik",
  ui_story_5036_50360901_233_dialog_content = "Saran saya jangan dengarkan dia, karena dia hampir tidak pernah mengatakan yang sebenarnya.",
  ui_story_5036_50360901_234_dialog_content = "Oh, hati tuaku yang malang... *Hiks*",
  ui_story_5036_50360901_235_dialog_content = "Sama seperti itu, Anda lihat? Dia menangis bahwa dia sudah tua satu detik, lalu memberitahumu dia selamanya 18 tahun berikutnya.",
  ui_story_5036_50360901_236_dialog_content = "Anda whippersnappers tidak mengerti. Ini disebut berjiwa muda.",
  ui_story_5036_50360901_237_dialog_content = "Pasti tidak bisa dipercaya.",
  ui_story_5036_50360901_238_dialog_content = "Mendesah!",
  ui_story_5036_50360901_239_dialog_content = "Namun, kami tidak punya pilihan selain mengikuti satu-satunya petunjuk yang kami miliki.",
  ui_story_5036_50360901_240_dialog_content = "Jadi kita hanya bisa terus? Huh, tapi tetap saja, kurasa kita tidak bisa menyerah begitu saja.",
  ui_story_5036_50360901_241_dialog_content = "Mari kita lihat apa lagi yang bisa kita temukan.",
  ui_story_5036_50360901_242_dialog_content = "Mereka terus berhenti, apa yang mereka lakukan?",
  ui_story_5036_50360901_243_dialog_content = "Sekarang saya menyadarinya, ini adalah area kuncian, bukan? Begitu gelap dan menakutkan...",
  ui_story_5036_50360901_244_dialog_content = "<color=#e8d9bb>Wuush…</color>",
  ui_story_5036_50360901_245_dialog_content = "Eh?! A-Apakah itu angin? Aku mungkin harus kembali dan bertanya pada Goldie di lain hari...",
  ui_story_5036_50360901_246_dialog_content = "Tidak, Brandy, Anda seorang reporter pencari kebenaran. Anda tidak bisa berhenti sekarang!",
  ui_story_5036_50360901_247_dialog_content = "Saya harus mengikuti mereka!",
  ui_story_5036_50360901_248_dialog_content = "Sudah berapa lama kita berjalan? Dua puluh menit?",
  ui_story_5036_50360901_249_dialog_content = "Koridor di sini adalah labirin. Kami hanya akan berputar-putar.",
  ui_story_5036_50360901_250_dialog_content = "Bukankah seharusnya kamu memimpin, PlayerName, karena kamu sudah lama tinggal di Colossus?",
  ui_story_5036_50360901_251_dialog_content = "Saya hanya tahu Soroz, bukan yang ini di sini.",
  ui_story_5036_50360901_252_dialog_content = "BENAR. Bagaimana kalau mencoba kemampuan psikis Anda?",
  ui_story_5036_50360901_253_dialog_content = "Jika jejak Caelestite itu masih ada, itu bisa memandu kita.",
  ui_story_5036_50360901_254_dialog_content = "Itu ide. Biarkan aku mencoba.",
  ui_story_5036_50360901_255_option_content = "Mindlink!",
  ui_story_5036_50360901_256_dialog_content = "Oh tidak, Eulogoz!",
  ui_story_5036_50360901_257_dialog_content = "Lihat apa yang terjadi pada Ouroboros!",
  ui_story_5036_50360901_258_dialog_content = "* Hiks * Apa yang terjadi padanya? Apakah hilang selamanya?",
  ui_story_5036_50360901_259_dialog_content = "Tanpanya, kami tidak akan bisa menghindari semua serangan Eclipsite itu...",
  ui_story_5036_50360901_260_dialog_content = "Jangan panik, Chaminade.",
  ui_story_5036_50360901_261_dialog_content = "Ouroboros adalah makhluk berumur panjang. Mereka berubah menjadi telur saat sudah tua, mengerami kembali, dan kemudian terlahir kembali.",
  ui_story_5036_50360901_262_dialog_content = "Ia memercayai Anda untuk melindunginya saat berada pada saat terlemahnya. Itu sebabnya ia memilih menjadi telur di sini.",
  ui_story_5036_50360901_263_dialog_content = "Tunggu sebentar, dan itu akan dapat berjalan bersama Anda lagi.",
  ui_story_5036_50360901_264_dialog_content = "Sungguh?",
  ui_story_5036_50360901_265_dialog_content = "Ini bagus! Jadi Ouroboros tidak mati, dan kami masih bisa bersama.",
  ui_story_5036_50360901_266_dialog_content = "Aku akan melindunginya. Bagaimana dengan ini? Ayo taruh telur di ruangan paling aman!",
  ui_story_5036_50360901_267_dialog_content = "Tidak ada Eclipsites yang bisa mendekat!",
  ui_story_5036_50360901_268_dialog_content = "Saya melihatnya! Sangat jelas kali ini!",
  ui_story_5036_50360901_269_dialog_content = "Chaminade berkata dia meletakkan telur itu di ruangan paling berbenteng di Colossus.",
  ui_story_5036_50360901_X269_dialog_content = "Dia berlari ke arah itu.",
  ui_story_5036_50360901_270_dialog_content = "Ayo pergi! Kita mungkin menemukan sesuatu yang baru.",
  ui_story_5036_50360901_271_dialog_content = "Padahal sudah bertahun-tahun. Petunjuk apa pun pasti sudah dingin sekarang.",
  ui_story_5036_50360901_272_dialog_content = "Sudahlah, ayo pergi saja.",
  ui_story_5036_50361001_1_dialog_content = "Kami telah berjalan untuk sementara waktu. Kenapa kita belum sampai ke ruangan itu?",
  ui_story_5036_50361001_2_dialog_content = "Eulogoz sangat besar, tapi kita seharusnya masih ada di sana sekarang.",
  ui_story_5036_50361001_3_dialog_content = "Kecuali kita benar-benar berputar-putar selama ini?",
  ui_story_5036_50361001_4_dialog_content = "Tidak tahu, tapi ini menjadi semakin tak tertahankan.",
  ui_story_5036_50361001_5_dialog_content = "Tempat ini menyeramkan dan membuatku merinding.",
  ui_story_5036_50361001_6_dialog_content = "Saya sering tersesat dan berputar-putar di alam liar.",
  ui_story_5036_50361001_7_dialog_content = "Hal yang harus dilakukan adalah meninggalkan jejak!",
  ui_story_5036_50361001_8_dialog_content = "Ide bagus. Ada yang punya sesuatu untuk ditulis?",
  ui_story_5036_50361001_9_dialog_content = "Tidak!",
  ui_story_5036_50361001_10_dialog_content = "Aku juga tidak, tapi aku membawa ini.",
  ui_story_5036_50361001_11_dialog_content = "Poster konser? Anda membawa ini dengan Anda?",
  ui_story_5036_50361001_12_dialog_content = "Banyak penggemar datang dan meminta tanda tangan, tetapi mereka tidak selalu memiliki sesuatu untuk saya tandatangani.",
  ui_story_5036_50361001_13_dialog_content = "Saya membawa poster untuk ditandatangani agar mereka tidak kecewa.",
  ui_story_5036_50361001_14_dialog_content = "Sangat memikirkanmu!",
  ui_story_5036_50361001_15_dialog_content = "Menjadi perhatian penggemar adalah salah satu pekerjaan paling mendasar dari seorang idola!",
  ui_story_5036_50361001_16_dialog_content = "Poster, ya? Pasti pelacak yang sangat mencolok.",
  ui_story_5036_50361001_17_dialog_content = "Bagaimanapun, saya akan menempatkan satu di sini. Ayo lanjutkan!",
  ui_story_5036_50361001_18_dialog_content = "<color=#e8d9bb>Suatu saat nanti</color>",
  ui_story_5036_50361001_19_dialog_content = "Sudah lama, tapi sepertinya tidak ada yang berubah di sekitar kita.",
  ui_story_5036_50361001_20_dialog_content = "Hei, bukankah itu poster yang dipasang Goldie?",
  ui_story_5036_50361001_21_dialog_content = "Dia! Kami benar-benar hanya berputar-putar!",
  ui_story_5036_50361001_22_dialog_content = "Tunggu, ada yang salah dengan poster ini...",
  ui_story_5036_50361001_23_dialog_content = "Kenapa rambut Goldie gelap di poster ini? Dan ekspresinya tidak terlihat alami...",
  ui_story_5036_50361001_24_dialog_content = "B-Bagaimana ini bisa terjadi? Apakah seseorang menarik lelucon?",
  ui_story_5036_50361001_25_dialog_content = "Ini adalah area yang belum dipetakan di bagian belakang. Seharusnya tidak ada orang lain di sini selain kami bertiga.",
  ui_story_5036_50361001_26_dialog_content = "Jangan bilang…",
  ui_story_5036_50361001_27_option_content = "Kita sedang diikuti?!",
  ui_story_5036_50361001_28_dialog_content = "Penggemar yang terlalu bersemangat, mungkin? Atau bajingan yang ingin menyabotase konser?",
  ui_story_5036_50361001_29_dialog_content = "Terlepas dari itu, ini agak menakutkan ...",
  ui_story_5036_50361001_30_dialog_content = "Kita harus keluar dari sini.",
  ui_story_5036_50361001_31_option_content = "Eclipsite?!",
  ui_story_5036_50361001_32_dialog_content = "Tapi bukankah Burung Hantu Lutumi membuat mereka tertidur?",
  ui_story_5036_50361001_33_dialog_content = "Mereka harus tetap keluar.",
  ui_story_5036_50361001_34_dialog_content = "Tempat ini terasa tidak benar. Ayo cepat dan pergi dari sini.",
  ui_story_5036_50361001_35_dialog_content = "Tapi ke arah mana?",
  ui_story_5036_50361001_36_dialog_content = "Pilih saja arah dan terus berjalan lurus!",
  ui_story_5036_50361001_37_dialog_content = "Mari kita pergi dengan cara ini!",
  ui_story_5036_50361001_38_dialog_content = "Hei, pelan-pelan untuk orang tua ini!",
  ui_story_5036_50361001_39_dialog_content = "Pelan - pelan!",
  ui_story_5036_50361001_40_dialog_content = "S-Ada yang aneh dengan poster ini.",
  ui_story_5036_50361001_41_dialog_content = "Hei, tunggu aku!",
  ui_story_5036_50361001_42_dialog_content = "*Terengah-engah* Hmm, ini berbeda dari koridor tempat kita berada.",
  ui_story_5036_50361001_43_dialog_content = "Mungkinkah ini ruangan yang dibicarakan Chaminade?",
  ui_story_5036_50361001_44_dialog_content = "Kelihatannya sangat kokoh, meskipun dindingnya masih compang-camping karena diabaikan selama bertahun-tahun.",
  ui_story_5036_50361001_45_dialog_content = "Di sini juga terasa lebih menyeramkan. Aku benar-benar tidak ingin berlama-lama...",
  ui_story_5036_50361001_46_dialog_content = "Aku terus merasa seperti Eclipsites akan muncul kapan saja.",
  ui_story_5036_50361001_47_dialog_content = "*Suara gemerisik*",
  ui_story_5036_50361001_48_dialog_content = "Siapa di sana?!",
  ui_story_5036_50361001_49_dialog_content = "Tunjukan dirimu!",
  ui_story_5036_50361001_50_dialog_content = "Ini aku! Jangan pukul aku!",
  ui_story_5036_50361001_51_dialog_content = "Saya tidak berbicara tentang Anda!",
  ui_story_5036_50361001_52_dialog_content = "Hah?",
  ui_story_5036_50361001_53_dialog_content = "Brandy? Apa yang kamu lakukan di sini? Tunggu, awas!",
  ui_story_5036_50361001_54_dialog_content = "Graaaaaah!",
  ui_story_5036_50361001_55_dialog_content = "Bebek!",
  ui_story_5036_50361001_56_dialog_content = "Goldie?!",
  ui_story_5036_50361001_57_dialog_content = "(Goldie baru saja menyelamatkan hidupku!)",
  ui_story_5036_50361001_58_dialog_content = "Aku tidak akan membiarkanmu menyakiti siapa pun di hadapanku!",
  ui_story_5036_50361001_59_dialog_content = "Bersiaplah untuk apa yang akan datang untukmu!",
  ui_story_5036_50361001_60_dialog_content = "Guk!",
  ui_story_5036_50361002_1_dialog_content = "Wah, itu sudah dekat!",
  ui_story_5036_50361002_2_dialog_content = "Tidak apa-apa sekarang. Aku membunuh Eclipsite terakhir.",
  ui_story_5036_50361002_3_dialog_content = "Apakah kamu baik-baik saja? Anda tidak terluka, bukan?",
  ui_story_5036_50361002_4_dialog_content = "Aku baik-baik saja selain kakiku terasa seperti jeli...",
  ui_story_5036_50361002_5_dialog_content = "Tidak heran saya merasa seseorang sedang menonton selama ini... Anda telah mengikuti kami.",
  ui_story_5036_50361002_6_dialog_content = "Sedang apa kau di sini?",
  ui_story_5036_50361002_7_dialog_content = "Apakah kamu tidak tahu menguntit itu ilegal, Brandy? Anda dihukum untuk itu!",
  ui_story_5036_50361002_8_dialog_content = "Aku... aku tidak menguntit!",
  ui_story_5036_50361002_9_dialog_content = "Aku di sini untuk mengungkap kebenaran!",
  ui_story_5036_50361002_10_dialog_content = "Kebenaran? Anda melihat ke dalam mimpi aneh juga?",
  ui_story_5036_50361002_11_dialog_content = "Tidak bukan itu. Itu sesuatu yang lain. Saya ingin menyelidiki secara rahasia, tetapi sekarang setelah Anda tahu, saya hanya akan bertanya langsung kepada Anda.",
  ui_story_5036_50361002_12_dialog_content = "Goldie, apakah Anda ingat pemilik Star Theater?",
  ui_story_5036_50361002_13_dialog_content = "Biarkan saya berpikir ... Itu membunyikan lonceng.",
  ui_story_5036_50361002_14_dialog_content = "Apakah Goldie memukulinya juga?",
  ui_story_5036_50361002_15_dialog_content = "Berhenti menyela, Vic.",
  ui_story_5036_50361002_16_dialog_content = "Kami memang bekerja sama sebentar, tetapi semuanya berakhir dengan nada masam.",
  ui_story_5036_50361002_17_dialog_content = "Jadi Anda pergi dengan hubungan buruk? Mengapa Anda tidak mencari tempat lain daripada bersusah payah menaiki Wandering Colossus hanya untuk mengadakan konser?",
  ui_story_5036_50361002_18_dialog_content = "Sejak itu, semua pemilik teater lainnya menolak tawaran saya untuk menyewa tempat mereka.",
  ui_story_5036_50361002_19_dialog_content = "Apa kamu tahu kenapa?",
  ui_story_5036_50361002_20_dialog_content = "Ceritanya panjang.",
  ui_story_5036_50361002_21_dialog_content = "Pemilik teater itu pernah mengirim tip ke editor The Daily Scoop, mengklaim bahwa Anda menyerangnya.",
  ui_story_5036_50361002_X21_dialog_content = "Apa artinya? Apakah Anda rentan terhadap ledakan kekerasan?",
  ui_story_5036_50361002_22_dialog_content = "Dia bahkan menunjukkan kepada editor luka di wajahnya. Wajah dan hidungnya bengkak dan memar... Itu terlihat sangat menyakitkan.",
  ui_story_5036_50361002_23_dialog_content = "Aku tidak menyakitinya sedikit pun! Sebaliknya, dialah yang menyakiti anak-anak kecil yang tidak bersalah!",
  ui_story_5036_50361002_24_dialog_content = "Saya masih tidak ingin percaya bahwa Anda melakukannya, tapi... Saya seorang reporter, jadi saya harus mengandalkan bukti.",
  ui_story_5036_50361002_25_dialog_content = "Apakah Anda memiliki sesuatu untuk membuktikan bahwa Anda tidak bersalah atau membuktikan kesalahan apa pun di pihaknya?",
  ui_story_5036_50361002_26_dialog_content = "Saya mengatakan yang sebenarnya! Di sini, cerita lengkapnya harus menjelaskan semuanya.",
  ui_story_5036_50361002_27_dialog_content = "Semuanya dimulai sekitar sepuluh hari yang lalu. Saat itu, saya sedang mencari tempat untuk mengadakan konser berikutnya.",
  ui_story_5036_50361002_28_dialog_content = "Setelah banyak memikirkannya, saya memutuskan bahwa Star Theater adalah pilihan terbaik, jadi saya mendekati pemiliknya tentang hal itu.",
  ui_story_5036_50361002_29_dialog_content = "Saya menjadwalkan latihan sebelum pertunjukan saya agar terbiasa dengan tempat tersebut.",
  ui_story_5036_50361002_30_dialog_content = "♪ La—la la la ♪",
  ui_story_5036_50361002_31_dialog_content = "<color=#e8d9bb>Tamparan-!</color>",
  ui_story_5036_50361002_32_dialog_content = "Hei!",
  ui_story_5036_50361002_33_dialog_content = "Tolong!",
  ui_story_5036_50361002_34_dialog_content = "Hah? Apa itu tadi?",
  ui_story_5036_50361002_35_dialog_content = "Apa kalian terlihat seperti bajingan di sini, ya? Enyahlah! Kalahkan, kalian semua!",
  ui_story_5036_50361002_36_dialog_content = "Tikus kotor sialan, jauhi teaterku!",
  ui_story_5036_50361002_37_dialog_content = "Ah!",
  ui_story_5036_50361002_38_dialog_content = "Jangan pukul saudaraku!",
  ui_story_5036_50361002_39_dialog_content = "Apa yang terjadi di sini?",
  ui_story_5036_50361002_40_dialog_content = "Nah, jika bukan Goldie sendiri! Tidak ada yang bisa dilihat di sini, tidak ada alasan untuk khawatir.",
  ui_story_5036_50361002_41_dialog_content = "Itu hanya beberapa bocah nakal yang tidak punya uang yang mencoba menonton pertunjukan gratis. Aku akan membuangnya sebentar lagi.",
  ui_story_5036_50361002_42_dialog_content = "Ini bukan konser resmi, ini hanya latihan. Apa salahnya kita datang ke sini untuk mendengarkan Goldie bernyanyi?",
  ui_story_5036_50361002_43_dialog_content = "Mendengarkan tidak gratis, punk. Bayar, atau tersesat.",
  ui_story_5036_50361002_44_dialog_content = "Tetapi jika Anda masih merasa angkuh, izinkan saya menempatkan Anda kembali di tempat Anda!",
  ui_story_5036_50361002_45_dialog_content = "Agh!",
  ui_story_5036_50361002_X45_dialog_content = "Tolong!",
  ui_story_5036_50361002_46_dialog_content = "Berhenti!",
  ui_story_5036_50361002_47_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5036_50361002_48_dialog_content = "Aduh! *Batuk*",
  ui_story_5036_50361002_49_dialog_content = "Beraninya kau menyentuhku? Apa kau tidak tahu siapa aku? Saya pemilik Teater Bintang!",
  ui_story_5036_50361002_50_dialog_content = "Saya tidak peduli jika Anda adalah pemiliknya! Saya tidak akan membiarkan Anda menyakiti beberapa anak yang tidak bersalah!",
  ui_story_5036_50361002_51_dialog_content = "Apakah Anda bahkan menyadari apa yang Anda lakukan?",
  ui_story_5036_50361002_52_dialog_content = "*Batuk-batuk*",
  ui_story_5036_50361002_53_dialog_content = "Sayangnya, saya tidak akan mengizinkan Anda tampil di teater saya lagi, Nona Goldie.",
  ui_story_5036_50361002_54_dialog_content = "... Sayang sekali.",
  ui_story_5036_50361002_55_dialog_content = "Jadi Anda melompat keluar untuk membela anak-anak itu dan secara tidak sengaja menjatuhkannya ke tanah?",
  ui_story_5036_50361002_56_dialog_content = "Itu sama sekali berbeda dari apa yang dikatakan semua orang!",
  ui_story_5036_50361002_57_dialog_content = "Itu semua hanyalah rumor tak berdasar!",
  ui_story_5036_50361002_58_dialog_content = "Dan hal lainnya! Ketika dia jatuh ke tanah, dia mendarat di pantatnya, bukan wajahnya!",
  ui_story_5036_50361002_59_dialog_content = "Jika Anda tidak percaya kepada saya, tanyakan pada kedua anak itu tentang hal itu! Mereka akan menceritakan semua yang terjadi hari itu.",
  ui_story_5036_50361002_60_dialog_content = "(Goldie selalu menjadi orang yang baik dan adil. Saya tidak berpikir dia akan bertindak kasar tanpa alasan yang baik.)",
  ui_story_5036_50361002_61_dialog_content = "Mengapa Anda tidak memberi tahu semua orang tentang semua ini sejak awal?",
  ui_story_5036_50361002_62_dialog_content = "Saya seorang idola, saya tidak mampu mengungkapkan kerentanan saya.",
  ui_story_5036_50361002_63_dialog_content = "Untuk merusak reputasi saya, sejumlah pemilik teater telah berkolusi satu sama lain agar saya tidak menyewa tempat untuk konser saya.",
  ui_story_5036_50361002_64_dialog_content = "Mereka tahu saya menjanjikan konser kepada penggemar saya di sini di Umbraton, dan mencoba membuat saya menarik kembali kata-kata saya.",
  ui_story_5036_50361002_65_dialog_content = "Penggemarku akan sangat kecewa jika aku tidak bisa menepati janjiku kepada mereka...",
  ui_story_5036_50361002_X65_dialog_content = "Saya mungkin juga mengucapkan selamat tinggal pada karir idola saya jika saya melakukan itu!",
  ui_story_5036_50361002_X66_dialog_content = "Itu sebabnya, apapun yang terjadi, aku harus mengadakan konser itu sesuai jadwal.",
  ui_story_5036_50361002_X67_dialog_content = "Saya harus membuktikan kepada penggemar saya bahwa saya tidak akan pernah mengkhianati semua cinta dan dukungan yang telah mereka berikan kepada saya!",
  ui_story_5036_50361002_66_dialog_content = "Bagaimana mungkin orang-orang itu melakukan itu padamu?!",
  ui_story_5036_50361002_67_dialog_content = "Satu-satunya hal yang dapat saya lakukan sekarang adalah mengadakan konser satu-satunya agar semua orang dapat merasakan diri saya yang sebenarnya.",
  ui_story_5036_50361002_68_dialog_content = "Saat saya semakin populer, semakin banyak orang yang mau mendengarkan saya dan mempercayai saya!",
  ui_story_5036_50361002_69_dialog_content = "Jadi ketika insiden itu turun, saya memilih untuk bersembunyi dan menyimpan semuanya untuk diri saya sendiri. Saya tidak ingin ada yang melihat saya dalam posisi rentan.",
  ui_story_5036_50361002_70_dialog_content = "(Jadi itulah yang dipikirkan Goldie selama ini...)",
  ui_story_5036_50361002_71_dialog_content = "(Sorotan matanya memberi tahu saya bahwa dia tidak berbohong. Ditambah dia bahkan menyelamatkan saya dari Eclipsites.)",
  ui_story_5036_50361002_72_dialog_content = "Fiuh... Aku hampir percaya rumor itu dan menganggapmu sebagai orang jahat...",
  ui_story_5036_50361002_73_dialog_content = "Saya akan mengklarifikasi masalah ini dengan kedua anak itu nanti.",
  ui_story_5036_50361002_X73_dialog_content = "Jika Anda mengatakan yang sebenarnya, saya akan segera menulis artikel tentang itu. Kami akan membersihkan nama baik Anda dan menyingkirkan semua rumor!",
  ui_story_5036_50361002_74_dialog_content = "Saya tidak bisa meminta apa-apa lagi!",
  ui_story_5036_50361002_75_dialog_content = "Mari kita simpan hal-hal sentimental setelah kita selesai di sini. Masih ada urusan lain yang harus kami tangani.",
  ui_story_5036_50361002_76_dialog_content = "Betul sekali! Ke mana kita akan pergi selanjutnya, PlayerName?",
  ui_story_5036_50361002_77_dialog_content = "Aku bisa merasakan bahwa kita semakin dekat dengan tempat Chaminade menyembunyikan telurnya.",
  ui_story_5036_50361002_78_dialog_content = "Biarkan aku mencoba sekali lagi.",
  ui_story_5036_50361002_79_option_content = "Tautkan pikiran!",
  ui_story_5036_50361002_80_dialog_content = "Graah—!",
  ui_story_5036_50361002_81_dialog_content = "<color=#e8d9bb>Brak—!</color>",
  ui_story_5036_50361002_82_dialog_content = "Ah-!",
  ui_story_5036_50361002_83_dialog_content = "Mereka mencoba masuk... Apa yang harus saya lakukan?",
  ui_story_5036_50361002_84_dialog_content = "Bahkan ruangan terkuat di Colossus tidak dapat menahan semua Eclipsites ini?",
  ui_story_5036_50361002_85_dialog_content = "Eulogoz? Eulogoz!",
  ui_story_5036_50361002_86_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5036_50361002_87_dialog_content = "Tidak... Mungkinkah Eulogoz sudah menjadi...?",
  ui_story_5036_50361002_88_dialog_content = "Tidak! Saya tidak bisa menyerah! Aku masih harus melindungi Ouroboros!",
  ui_story_5036_50361002_89_dialog_content = "Aku harus menyembunyikannya di tempat yang aman dulu!",
  ui_story_5036_50361002_90_dialog_content = "Seharusnya tidak ada yang bisa menemukannya di dalam kompartemen dinding rahasia ini.",
  ui_story_5036_50361002_91_dialog_content = "Tetap di sini dan jangan bergerak sedikit pun, oke?",
  ui_story_5036_50361002_92_dialog_content = "Aku akan melindungimu apapun yang terjadi!",
  ui_story_5036_50361002_93_dialog_content = "<color=#e8d9bb>Dharr!!!</color>",
  ui_story_5036_50361002_94_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5036_50361002_95_dialog_content = "Graaah...",
  ui_story_5036_50361002_96_dialog_content = "Eclipsite...",
  ui_story_5036_50361002_97_dialog_content = "Datanglah padaku... Datanglah padaku, kalian semua!",
  ui_story_5036_50361002_98_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5036_50361002_99_dialog_content = "Sakit...",
  ui_story_5036_50361002_100_dialog_content = "Tubuhku... Terasa sangat dingin...",
  ui_story_5036_50361002_101_dialog_content = "Eulogoz... Ouroboros... Kalian berdua masih disana?",
  ui_story_5036_50361002_102_dialog_content = "Aku... Aku hanya ingin pulang...",
  ui_story_5036_50361002_103_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5036_50361002_104_dialog_content = "Kree—!",
  ui_story_5036_50361101_1_dialog_content = "...",
  ui_story_5036_50361101_2_dialog_content = "PlayerName?",
  ui_story_5036_50361101_3_dialog_content = "...",
  ui_story_5036_50361101_4_dialog_content = "PlayerName! Apakah kamu baik-baik saja? Apa yang Anda lihat?",
  ui_story_5036_50361101_5_dialog_content = "Aku... Aku melihat ingatan terakhir Chaminade.",
  ui_story_5036_50361101_6_dialog_content = "Setelah Ouroboros berubah menjadi telur, dia dan Eulogoz diserang oleh Eclipsites.",
  ui_story_5036_50361101_7_dialog_content = "Untuk melindungi telur Ouroboros, dia menyembunyikannya di kompartemen rahasia di dinding.",
  ui_story_5036_50361101_8_dialog_content = "Setelah itu, Chaminade menarik Eclipsites menjauh dari ruangan sendirian... Dan kemudian...",
  ui_story_5036_50361101_9_dialog_content = "... Cukup. Kami mengerti.",
  ui_story_5036_50361101_10_dialog_content = "Gadis malang itu berjuang mati-matian untuk melindungi telur Ouroboros.",
  ui_story_5036_50361101_11_dialog_content = "Dia melakukannya dengan baik, bahkan jika itu terlihat sedikit berlebihan.",
  ui_story_5036_50361101_12_dialog_content = "Sekarang bukan waktunya bicara seperti itu, Vic.",
  ui_story_5036_50361101_13_dialog_content = "Maksud kamu apa? Lihat ke dalam celah di dinding ini, jika Anda tidak percaya padaku.",
  ui_story_5036_50361101_14_dialog_content = "Apakah ada sesuatu di sana?",
  ui_story_5036_50361101_15_dialog_content = "Ahhh!",
  ui_story_5036_50361101_16_dialog_content = "Apa yang kamu lihat?",
  ui_story_5036_50361101_17_dialog_content = "Apa ini? Itu tidak terlihat seperti pola di dinding.",
  ui_story_5036_50361101_18_dialog_content = "Itu tidak terbuat dari logam atau Colossus Patches. Ini lebih mirip ... kulit telur.",
  ui_story_5036_50361101_19_dialog_content = "Mungkinkah itu milik Ouroboros?",
  ui_story_5036_50361101_20_dialog_content = "Jadi itu masih di sini. Tapi bagaimana bisa begitu besar? Itu bahkan membuka dinding!",
  ui_story_5036_50361101_21_dialog_content = "Bukankah seharusnya hanya sedikit lebih besar dari semangka? Bahkan gadis kecil itu bisa membawanya.",
  ui_story_5036_50361101_22_dialog_content = "\"Telur Ouroboros\"?! Saya pikir Vic hanya bercanda tentang itu! Bagaimana ini sebenarnya terjadi?",
  ui_story_5036_50361101_23_dialog_content = "Apa sebenarnya yang terjadi di sini, Vic?",
  ui_story_5036_50361101_24_dialog_content = "Entahlah…",
  ui_story_5036_50361101_25_dialog_content = "Apa? Bukankah Anda seharusnya ahli ekstrozoologi terkemuka di dunia?",
  ui_story_5036_50361101_26_dialog_content = "Justru karena saya seorang ahli ekstrozoologi, saya menolak untuk membuat asumsi yang terburu-buru.",
  ui_story_5036_50361101_27_dialog_content = "Satu-satunya hal yang dapat saya pastikan untuk saat ini adalah bahwa telur ini telah melewati masa inkubasinya tetapi masih belum menetas.",
  ui_story_5036_50361101_28_dialog_content = "Tidak hanya itu, Ouroboros di dalam telur masih sangat hidup. Itu terus tumbuh, dan telur tumbuh bersamanya.",
  ui_story_5036_50361101_29_dialog_content = "Adapun yang lainnya, saya sama sekali tidak tahu!",
  ui_story_5036_50361101_30_dialog_content = "Ouroboros adalah spesies yang sangat langka, jadi informasi tentangnya sangat langka.",
  ui_story_5036_50361101_31_dialog_content = "Ini benar-benar misteri, sederhananya.",
  ui_story_5036_50361101_32_dialog_content = "Selama ini, saya pikir Vic hanya mengada-ada. Aku tidak tahu dia sedang serius.",
  ui_story_5036_50361101_33_dialog_content = "Apakah menurut Anda telur ini adalah sumber mimpi aneh semua orang?",
  ui_story_5036_50361101_34_dialog_content = "Itu mungkin!",
  ui_story_5036_50361101_35_dialog_content = "Apa? Kalian serius?",
  ui_story_5036_50361101_36_dialog_content = "Saya tidak punya bukti, jadi itu hanya tebakan.",
  ui_story_5036_50361101_37_dialog_content = "Saya selalu ingin tahu bagaimana Ouroboros bertahan dalam masa inkubasinya sebagai telur.",
  ui_story_5036_50361101_38_dialog_content = "Bagaimana telur seharusnya melawan pemangsa atau melarikan diri dari mereka?",
  ui_story_5036_50361101_39_dialog_content = "Tapi sekarang, saya punya hipotesis baru! Saya percaya bahwa Ouroboros mungkin memiliki kemampuan psikis yang unik saat berada dalam keadaan telurnya.",
  ui_story_5036_50361101_40_dialog_content = "Salah satu yang dapat menyebabkan makhluk lain mengalami mimpi atau halusinasi yang aneh! Dengan membuat mereka merasakan bahaya, Ouroboros dapat menjaga jarak yang aman.",
  ui_story_5036_50361101_41_dialog_content = "Ini melindungi dirinya sendiri dengan cara ini untuk menangkal bahaya.",
  ui_story_5036_50361101_42_dialog_content = "Jadi maksudmu mimpi aneh yang kita alami, dan rasa tidak nyaman yang aneh itu...",
  ui_story_5036_50361101_43_dialog_content = "Atau bahkan poster aneh sebelumnya. Semua itu adalah perbuatan Ouroboros?!",
  ui_story_5036_50361101_44_dialog_content = "Memang. Atau lebih tepatnya, itulah penjelasan paling masuk akal yang bisa saya pikirkan!",
  ui_story_5036_50361101_45_dialog_content = "Jadi langkah kita selanjutnya sudah jelas, bukan? Kita perlu menemukan cara untuk memindahkan telur ini ke suatu tempat yang jauh!",
  ui_story_5036_50361101_46_option_content = "Telur ini?",
  ui_story_5036_50361101_47_option_content = "Pindahkan?",
  ui_story_5036_50361101_48_dialog_content = "Ya!",
  ui_story_5036_50361101_49_dialog_content = "Jika kita tidak mengeluarkan telur ini dari sini, kekuatan Ouroboros hanya akan mempengaruhi semua orang.",
  ui_story_5036_50361101_50_dialog_content = "Dan pada tingkat ini, itu pasti akan mempengaruhi konserku!",
  ui_story_5036_50361101_51_dialog_content = "Saya tidak setuju.",
  ui_story_5036_50361101_52_dialog_content = "Apa?!",
  ui_story_5036_50361101_53_dialog_content = "Telurnya kolosal, dan menempel di dinding.",
  ui_story_5036_50361101_54_dialog_content = "Bahkan jika Anda berhasil melepaskannya, bagaimana Anda berniat memindahkannya ke tempat lain dengan aman?",
  ui_story_5036_50361101_55_dialog_content = "Saya akan menyewa Tentara Bayaran Api Putih untuk menggalinya dan membawanya pergi dengan pesawat!",
  ui_story_5036_50361101_56_dialog_content = "Tembok ini sebenarnya tidak terbuat dari tongkat dan batu, tahu? Pada saat Anda selesai menggali, konser sudah lama berakhir.",
  ui_story_5036_50361101_57_dialog_content = "Aku…",
  ui_story_5036_50361101_58_dialog_content = "Belum lagi, ini mungkin satu-satunya telur Ouroboros yang tersisa di seluruh dunia, mengingat betapa langkanya eksotik.",
  ui_story_5036_50361101_59_dialog_content = "Jika sesuatu terjadi padanya selama pelepasan, nyawa Ouroboros bisa terancam.",
  ui_story_5036_50361101_60_dialog_content = "Jika itu terjadi, apakah Anda siap memikul kesalahan karena menyebabkan kepunahan seluruh spesies binatang buas yang menakjubkan?",
  ui_story_5036_50361101_61_dialog_content = "Aku…",
  ui_story_5036_50361101_62_dialog_content = "Mengapa tidak mengikuti saran saya dan membatalkan konser ini?",
  ui_story_5036_50361101_63_dialog_content = "Anda dapat mengadakan konser di tempat lain kapan saja. Hanya sekali ini saja, jadi mari kita tunggu Ouroboros menetas, dan—",
  ui_story_5036_50361101_64_dialog_content = "Tidak mungkin!",
  ui_story_5036_50361101_65_dialog_content = "Konser ini adalah <color=#FFB400>sangat penting</color> untuk saya! Aku tidak bisa menyerah begitu saja!",
  ui_story_5036_50361101_66_dialog_content = "Saya dapat berkompromi dalam situasi lain, tetapi tidak untuk situasi ini!",
  ui_story_5036_50361101_67_dialog_content = "Memang benar, konser ini adalah janji Goldie kepada para penggemarnya...",
  ui_story_5036_50361101_68_dialog_content = "(\"Terutama penting\"? Goldie terlihat sangat tertekan sekarang. Apa yang terjadi?)",
  ui_story_5036_50361101_69_dialog_content = "Ah, sepertinya kita memiliki sedikit dilema di tangan kita.",
  ui_story_5036_50361101_70_dialog_content = "...",
  ui_story_5036_50361101_71_dialog_content = "(Tidak satu pun dari mereka yang mau mundur. Saya harus melakukan sesuatu tentang ini.)",
  ui_story_5036_50361101_72_dialog_content = "Apakah benar-benar tidak ada cara lain?",
  ui_story_5036_50361101_73_dialog_content = "Mungkin kita bisa menghilangkan pengaruh psikis telur tanpa memindahkannya?",
  ui_story_5036_50361101_74_dialog_content = "Betul sekali! Anda ahli ekstrozoologi, Vic. Tidak bisakah kamu memikirkan cara yang lebih baik?",
  ui_story_5036_50361101_75_dialog_content = "Mendesah. Seperti biasa, kalian pasti suka membuat orang tua menderita. Mereka semakin buruk dari generasi ke generasi...",
  ui_story_5036_50361101_76_dialog_content = "Ah well, tebak itu tidak bisa membantu. Murid saya selalu memohon saya untuk menyelamatkan puntung maaf mereka. Ini tidak berbeda, saya kira.",
  ui_story_5036_50361101_77_dialog_content = "Pilihan kata yang menarik, Vic. Aku ingin tahu apa pendapat Shira dan Fia tentang mereka.",
  ui_story_5036_50361101_78_dialog_content = "Maaf apa? Apakah saya mengatakan sesuatu? Sepertinya saya tidak ingat!",
  ui_story_5036_50361101_79_dialog_content = "Oh, berhenti berakting, Vic. Mari kita lanjutkan ini.",
  ui_story_5036_50361101_80_dialog_content = "Ahem. Ada metode lain, tapi agak merepotkan, dan saya tidak bisa menjamin itu akan berhasil.",
  ui_story_5036_50361101_81_dialog_content = "Cukup beri tahu kami! Saya akan melakukan apa saja, asalkan memberi saya kesempatan untuk mengadakan konser ini!",
  ui_story_5036_50361101_82_dialog_content = "Ceritakan tentang penglihatan yang Anda lihat beberapa menit yang lalu, PlayerName. Apakah Chaminade tampaknya terpengaruh secara negatif oleh telur Ouroboros?",
  ui_story_5036_50361101_83_dialog_content = "Hah? Sekarang aku memikirkannya... Tidak, dia sama sekali tidak terlihat terganggu oleh itu.",
  ui_story_5036_50361101_84_dialog_content = "Saya mengerti. Di situlah letak jawabannya, teman-teman!",
  ui_story_5036_50361101_85_dialog_content = "Kemampuan psikis Ouroboros tampaknya merupakan mekanisme pertahanan diri yang hanya digunakan saat merasakan bahaya di dekatnya.",
  ui_story_5036_50361101_86_dialog_content = "Jika kita dapat menghilangkan sumber bahaya itu dari Colossus, ia akan merasa cukup aman untuk menghilangkan pengaruh psikisnya!",
  ui_story_5036_50361101_87_dialog_content = "Jadi maksudmu kita hanya perlu membersihkan Eclipsites di Colossus?",
  ui_story_5036_50361101_88_dialog_content = "Itu salah satu cara untuk menggambarkannya, ya.",
  ui_story_5036_50361101_89_dialog_content = "Apakah itu semuanya? Itu bukan masalah bagi kami!",
  ui_story_5036_50361101_90_dialog_content = "T-Sekarang tunggu sebentar!",
  ui_story_5036_50361101_91_dialog_content = "Colossus ini, yah, kolosal! Bagaimana kita bisa menghabisi setiap Eclipsite hanya dengan kita berempat?! Tidak mungkin!",
  ui_story_5036_50361101_92_dialog_content = "Benar juga…",
  ui_story_5036_50361101_93_dialog_content = "Plus ada kemungkinan ini tidak akan berhasil, kan?",
  ui_story_5036_50361101_94_dialog_content = "Benar. Tapi kita tidak akan mengetahuinya kecuali kita mencobanya!",
  ui_story_5036_50361101_95_dialog_content = "Bagaimana jika kita mencoba melenyapkan Eclipsites di sekitarnya, lalu menutup semua retakan di dinding? Dengan begitu, mereka tidak akan bisa mendekati telur!",
  ui_story_5036_50361101_96_dialog_content = "Hmm, itu mungkin menghasilkan hasil yang serupa, ya.",
  ui_story_5036_50361101_97_dialog_content = "Mari kita mencobanya!",
  ui_story_5036_50361101_98_dialog_content = "Baiklah, ayo kita keluar!",
  ui_story_5036_50361101_99_dialog_content = "Untuk konser!",
  ui_story_5036_50361102_1_dialog_content = "Ayo bantu aku di sini, PlayerName.",
  ui_story_5036_50361102_2_dialog_content = "Ayo dorong batu ini ke sana dan blokir retakan di dinding itu.",
  ui_story_5036_50361102_3_dialog_content = "Baik!",
  ui_story_5036_50361102_4_dialog_content = "Hrrrnnnng—!",
  ui_story_5036_50361102_5_dialog_content = "Fiuh! Itu seharusnya menjadi celah terakhir, bukan?",
  ui_story_5036_50361102_6_dialog_content = "Sepertinya begitu! Kerja bagus, semuanya.",
  ui_story_5036_50361102_7_dialog_content = "Usaha sukses lainnya di bawah kepemimpinan saya yang sempurna!",
  ui_story_5036_50361102_8_dialog_content = "Jika Anda bisa menyebut duduk-duduk dan menyemangati kami sebagai \"kepemimpinan\", maka tentu...",
  ui_story_5036_50361102_9_dialog_content = "Apakah Anda benar-benar berharap bahwa seorang kakek tua seperti saya mengikuti sekelompok ayam musim semi seperti Anda?",
  ui_story_5036_50361102_10_dialog_content = "Suasana suram tampaknya melemah ...",
  ui_story_5036_50361102_11_dialog_content = "Kamu benar. Meskipun aku masih bisa merasakannya secara samar, rasanya jauh lebih baik sekarang daripada sebelumnya.",
  ui_story_5036_50361102_12_dialog_content = "Maka sepertinya hipotesis saya benar!",
  ui_story_5036_50361102_13_dialog_content = "Jadi apa yang kita lakukan sekarang? Haruskah kita terus membersihkan Eclipsites?",
  ui_story_5036_50361102_14_dialog_content = "Saya pikir kami telah melakukan lebih dari cukup pada saat ini. Satu-satunya hal yang tersisa untuk dilakukan sekarang ...",
  ui_story_5036_50361102_15_dialog_content = "adalah merangkak kembali ke tempat tidur untuk melihat apakah kita memiliki mimpi yang lebih aneh lagi!",
  ui_story_5036_50361102_16_dialog_content = "Anda hanya ingin pergi tidur, bukan?!",
  ui_story_5036_50361102_17_dialog_content = "Maaf, karena hanya ada sedikit info tentang Ouroboros, coba-coba adalah satu-satunya pilihan kami.",
  ui_story_5036_50361102_18_dialog_content = "Dia ada benarnya.",
  ui_story_5036_50361102_19_dialog_content = "Sudah sangat larut, dan semua orang terlihat kelelahan.",
  ui_story_5036_50361102_20_dialog_content = "Mari kita kembali dan beristirahat, dan lihat apakah usaha kita membuahkan hasil.",
  ui_story_5036_50361102_21_dialog_content = "Dan jika belum, saya akan memikirkan hal lain.",
  ui_story_5036_50361102_22_dialog_content = "Saya pikir semua kerja keras Anda pasti akan terbayar, Goldie!",
  ui_story_5036_50361102_23_dialog_content = "Heehee! Terima kasih sudah mengatakannya!",
  ui_story_5036_50361102_24_dialog_content = "Baiklah kalau begitu, mari kita kembali untuk tidur yang sangat dibutuhkan. Kita akan bertemu lagi di pagi hari!",
  ui_story_5036_50361102_25_dialog_content = "<color=#e8d9bb>Keesokan paginya, sehari sebelum konser</color>",
  ui_story_5036_50361102_26_dialog_content = "Yaaaawn... sudah lama aku tidak tidur nyenyak seperti itu!",
  ui_story_5036_50361102_27_dialog_content = "Aku sangat terpukul setelah tadi malam, aku pingsan begitu sampai di kamarku. Aku terlalu lelah bahkan untuk bermimpi!",
  ui_story_5036_50361102_28_dialog_content = "Pagi, sainganku yang kalah!",
  ui_story_5036_50361102_29_dialog_content = "Jika Anda baru saja bangun, itu artinya saya memenangkan permainan membangunkan hari ini! Luar biasa!",
  ui_story_5036_50361102_30_dialog_content = "Hei, Gronru. Apakah Anda tidur nyenyak tadi malam?",
  ui_story_5036_50361102_31_dialog_content = "Aku benar-benar tidur S-tier tadi malam!",
  ui_story_5036_50361102_32_dialog_content = "Tidak ada apa-apanya dibandingkan dengan beberapa malam terakhir, dimana aku terus bermimpi tentang gadis Caelestite itu.",
  ui_story_5036_50361102_33_dialog_content = "Betulkah? Itu berita bagus!",
  ui_story_5036_50361102_34_dialog_content = "Kau pikir begitu? Saya tidak. Memiliki mimpi aneh seperti itu seperti membuka pencapaian tersembunyi dalam sebuah game!",
  ui_story_5036_50361102_35_dialog_content = "Uh, ya, tentu... Ngomong-ngomong, aku senang kamu bisa istirahat dengan baik.",
  ui_story_5036_50361102_36_dialog_content = "Terima kasih! Saya pergi untuk menonton latihan, sampai nanti!",
  ui_story_5036_50361102_37_dialog_content = "Baiklah, sampai jumpa!",
  ui_story_5036_50361102_38_dialog_content = "Ini bagus! Sepertinya semua kerja keras kita tadi malam tidak sia-sia!",
  ui_story_5036_50361102_39_dialog_content = "Aku harus segera memberi tahu Goldie, jadi dia akhirnya bisa sedikit santai.",
  ui_story_5036_50361102_40_dialog_content = "Saat ini, dia seharusnya... di ruang latihan, kurasa?",
  ui_story_5036_50361102_41_dialog_content = "Oh, hai PlayerName!",
  ui_story_5036_50361102_42_dialog_content = "Anda sudah bangun? Kami keluar sangat larut tadi malam, saya pikir Anda mungkin ingin tidur lebih lama hari ini.",
  ui_story_5036_50361102_43_dialog_content = "Sama sekali tidak! Saya merasa benar-benar segar sekarang!",
  ui_story_5036_50361102_44_dialog_content = "Juga, sepertinya kerja keras kita terbayar. Saya baru saja berbicara dengan Gronru, dan dia bilang dia tidak bermimpi aneh tadi malam!",
  ui_story_5036_50361102_45_dialog_content = "Bagus! Saya juga bertanya kepada beberapa kontestan, dan mereka semua mengatakan bahwa mereka tidur nyenyak tadi malam juga!",
  ui_story_5036_50361102_46_dialog_content = "Ini sempurna!",
  ui_story_5036_50361102_47_dialog_content = "Ini benar-benar ... sempurna.",
  ui_story_5036_50361102_48_option_content = "Goldie? Apakah kamu baik-baik saja?",
  ui_story_5036_50361102_49_dialog_content = "Kenapa kamu terlihat sangat lelah?",
  ui_story_5036_50361102_50_dialog_content = "Hah? Apakah saya?",
  ui_story_5036_50361102_51_dialog_content = "Saya tidak merasa lelah sama sekali! Lagipula, para idola penuh dengan banyak energi!",
  ui_story_5036_50361102_52_option_content = "Kenapa kamu terlihat sangat lelah?",
  ui_story_5036_50361102_53_dialog_content = "Hah? Apakah saya?",
  ui_story_5036_50361102_54_dialog_content = "Saya pikir Anda mungkin melihat sesuatu. Saya merasa baik-baik saja sekarang!",
  ui_story_5036_50361102_55_dialog_content = "(Aku bersumpah aku tidak melihat apa-apa. Ekspresi tadi... Mungkinkah?)",
  ui_story_5036_50361102_56_dialog_content = "Anda memaksa diri Anda untuk menjaga semangat Anda, bukan?",
  ui_story_5036_50361102_57_dialog_content = "…!",
  ui_story_5036_50361102_58_dialog_content = "Tidak sulit untuk mengatakannya. Lagi pula, Anda keluar sama larutnya dengan kami tadi malam.",
  ui_story_5036_50361102_59_dialog_content = "Terlebih lagi, Anda harus mengatur pelatihan dan audisi hari ini, bukan? Sepertinya Anda tidak beristirahat sama sekali tadi malam.",
  ui_story_5036_50361102_60_dialog_content = "Tidak apa-apa, aku janji! Aku seorang idola, ingat? Dan berhala—",
  ui_story_5036_50361102_61_option_content = "—Apakah orang juga, kan?",
  ui_story_5036_50361102_62_dialog_content = "Anda masih manusia. Kamu juga butuh istirahat.",
  ui_story_5036_50361102_63_dialog_content = "Saya mungkin tidak tahu cerita lengkap di balik konser ini atau mengapa ini sangat penting bagi Anda...",
  ui_story_5036_50361102_64_dialog_content = "Tapi aku tahu kau harus mengesampingkan pekerjaanmu sebentar dan beristirahat sekarang, Goldie.",
  ui_story_5036_50361102_65_dialog_content = "Huh.",
  ui_story_5036_50361102_66_dialog_content = "Saya kira tidak ada salahnya untuk mengatakan yang sebenarnya, PlayerName. Lagi pula, Anda telah melakukan banyak hal untuk membantu saya.",
  ui_story_5036_50361102_67_dialog_content = "Hah? Apakah Anda baru saja mengatakan \"kebenaran\"?",
  ui_story_5036_50361102_X67_dialog_content = "Saya tidak hanya memenuhi janji saya kepada penggemar saya dengan konser ini... Saya juga memenuhi janji saya kepada Lady Sheol.",
  ui_story_5036_50361102_68_dialog_content = "Sejujurnya, saya membuat perjanjian dengan Sheol.",
  ui_story_5036_50361102_69_dialog_content = "Pakta? Dengan Sheol?!",
  ui_story_5036_50361102_70_dialog_content = "Dia mengenali potensi industri idola, serta kemampuan saya sendiri. Jadi dia memutuskan untuk berinvestasi dalam karir saya.",
  ui_story_5036_50361102_71_dialog_content = "Dia adalah sumber dukungan keuangan terbesar saya, tetapi pada saat yang sama, saya harus melakukan segala daya saya untuk memenuhi permintaannya.",
  ui_story_5036_50361102_72_dialog_content = "Salah satunya adalah mengadakan konser di sini di Umbraton dalam jangka waktu tertentu, dan konser itu—",
  ui_story_5036_50361102_73_dialog_content = "Itu harus mencerahkan semua orang di Umbraton dan Lumopolis tentang konsep idola, dan menyebarkan nama saya ke seluruh wilayah.",
  ui_story_5036_50361102_74_dialog_content = "Tidakkah menurutmu Sheol memanfaatkanmu? Apakah tujuan itu bahkan mungkin ?!",
  ui_story_5036_50361102_75_dialog_content = "Saya akui bahwa tidak akan mudah bagi seseorang dengan tingkat popularitas seperti saya. Tapi tidak ada yang tidak mungkin selama saya merencanakan semuanya dengan sempurna.",
  ui_story_5036_50361102_76_dialog_content = "Tapi kemudian Anda tahu, semua itu terjadi, jadi saya tidak bisa menyewa tempat.",
  ui_story_5036_50361102_77_dialog_content = "Tapi saat semua harapan tampaknya hilang, Colossus Pengembara tiba-tiba muncul di langit! Kedatangannya sangat kebetulan!",
  ui_story_5036_50361102_78_dialog_content = "Menurut perjanjianku dengan Sheol, besok adalah hari terakhir aku bisa menggelar konserku. Ini adalah kesempatan terakhirku, jadi aku harus memberikan segalanya.",
  ui_story_5036_50361102_79_dialog_content = "Jika saya gagal, saya harus membayar Sheol untuk semua pengeluarannya. Saya akan berada di bawah tumpukan hutang.",
  ui_story_5036_50361102_80_dialog_content = "Karier saya sebagai idola juga akan berakhir.",
  ui_story_5036_50361102_81_dialog_content = "Aku tidak menyangka kau bekerja di bawah tekanan sebesar ini, Goldie. Bukankah itu terlalu berlebihan?",
  ui_story_5036_50361102_82_dialog_content = "Saya kira tidak demikian. Lagipula itu adalah tugasku.",
  ui_story_5036_50361102_83_dialog_content = "Sebagai seorang idola, seluruh alasan keberadaan saya adalah untuk membawa harapan dan kebahagiaan kepada penggemar setia saya melalui lagu dan tarian.",
  ui_story_5036_50361102_84_dialog_content = "Tanpa cinta dan dukungan mereka, saya tidak akan pernah bisa menyebut diri saya seorang idola.",
  ui_story_5036_50361102_85_dialog_content = "Setelah semua cinta yang mereka tunjukkan padaku, aku akan menjadi orang seperti apa jika aku tidak membalasnya dengan bekerja sekeras yang aku bisa?",
  ui_story_5036_50361102_86_dialog_content = "Saya akan mempertaruhkan semuanya jika itu berarti konser saya akan membantu suara saya menjangkau lebih banyak orang!",
  ui_story_5036_50361102_87_dialog_content = "Aku tahu kamu bisa melakukannya, Goldie!",
  ui_story_5036_50361102_88_dialog_content = "Tapi Anda tidak sendirian. Kamu juga punya aku!",
  ui_story_5036_50361102_89_dialog_content = "Jika ada yang bisa saya bantu, Anda hanya perlu bertanya.",
  ui_story_5036_50361102_90_dialog_content = "Terima kasih, PlayerName!",
  ui_story_5036_50361102_91_dialog_content = "Mari lakukan yang terbaik untuk melindungi Eulogoz dan jadikan konser ini yang terbesar yang pernah ada di dunia!",
  ui_story_5036_50361201_1_dialog_content = "<color=#e8d9bb>Keesokan harinya, lima belas menit sebelum dimulainya konser</color>",
  ui_story_5036_50361201_2_dialog_content = "Konser akan segera dimulai! Semua orang siap?",
  ui_story_5036_50361201_3_dialog_content = "Siap!",
  ui_story_5036_50361201_4_dialog_content = "Apakah pertunjukan akhirnya dimulai? Inilah saat yang kita semua tunggu-tunggu!",
  ui_story_5036_50361201_5_dialog_content = "(Sejujurnya, membuatku membuang waktuku yang berharga untuk bergaul dengan rakyat jelata ini.)",
  ui_story_5036_50361201_6_dialog_content = "Ekspresi, mengungkapkan.",
  ui_story_5036_50361201_7_dialog_content = "Kehadiran pikiran kasar dan merendahkan terlihat jelas di wajah Anda.",
  ui_story_5036_50361201_8_dialog_content = "Oh, diamlah.",
  ui_story_5036_50361201_9_dialog_content = "Luar biasa! Permainan akan segera dimulai!",
  ui_story_5036_50361201_10_dialog_content = "Siap membantuku menyemangati mereka, Sio?",
  ui_story_5036_50361201_11_dialog_content = "R-Siap...",
  ui_story_5036_50361201_12_dialog_content = "Mengapa kita belum memulai? Saya sangat ingin menjatuhkan kaus kaki dari kerumunan ini dengan musik rock saya!",
  ui_story_5036_50361201_13_dialog_content = "Jadilah nyata, tolol! Ini adalah konser idola, bukan konser rock! Yang paling penting di sini adalah idola!",
  ui_story_5036_50361201_14_dialog_content = "Itulah mengapa saya, Barbara the Diesel Sweety, dibuat untuk ini!",
  ui_story_5036_50361201_15_dialog_content = "Siapa yang mau mendengarkan musik anak-anak seperti milik Anda? Kerumunan tidak ingin mendengar sampah itu!",
  ui_story_5036_50361201_16_dialog_content = "...?! Apa yang terjadi?",
  ui_story_5036_50361201_17_dialog_content = "Keduanya sama hidup seperti sebelumnya. Saya harap mereka tidak menimbulkan masalah bagi kami.",
  ui_story_5036_50361201_18_dialog_content = "Sepakat. Lagipula, mereka harus melakukan aksi pembuka bersama!",
  ui_story_5036_50361201_19_dialog_content = "Ya, saya tahu apa yang Anda... Tunggu, APA?! Tindakan pembukaan? Bersama?!",
  ui_story_5036_50361201_20_dialog_content = "Apakah Anda yakin tidak apa-apa ?!",
  ui_story_5036_50361201_21_dialog_content = "Aku tidak akan berbohong, aku sedikit khawatir tentang hal itu juga. Tetapi jika saya membiarkan mereka tampil secara terpisah, mereka hanya akan memperebutkan siapa yang akan pergi lebih dulu.",
  ui_story_5036_50361201_22_dialog_content = "Dengan mengajak mereka naik panggung secara bersamaan, setidaknya konser bisa berjalan lancar.",
  ui_story_5036_50361201_23_dialog_content = "Selain itu, mereka berdua bersumpah akan menampilkan aksi pembuka yang mematikan untuk konser tersebut!",
  ui_story_5036_50361201_24_dialog_content = "Oh, itu akan menjadi \"pembunuh,\" baiklah... Hanya tidak yakin apa yang akan menjadi keahliannya...",
  ui_story_5036_50361201_25_dialog_content = "Miliki sedikit kepercayaan pada mereka! Saya tahu mereka bertengkar sepanjang waktu, tetapi tidak dapat disangkal keterampilan atau dedikasi mereka terhadap penampilan mereka.",
  ui_story_5036_50361201_26_dialog_content = "Baik, saya hanya berharap mereka bisa berbagi panggung cukup lama untuk menyelesaikan aksi mereka.",
  ui_story_5036_50361201_27_dialog_content = "Lagi pula, Eulogoz juga memiliki segalanya di konser ini.",
  ui_story_5036_50361201_28_dialog_content = "Anda sangat peduli dengan Eulogoz, bukan?",
  ui_story_5036_50361201_29_dialog_content = "Itu karena itu satu-satunya Colossus yang beroperasi penuh di dunia, selain Soroz dan Lepidoz.",
  ui_story_5036_50361201_30_dialog_content = "The Caelestites berbagi ikatan erat dengan setiap Colossus. Mereka adalah bukti bahwa bangsaku pernah ada.",
  ui_story_5036_50361201_31_dialog_content = "Saya ingin melakukan yang terbaik untuk melestarikannya sebanyak mungkin. Aku tahu Caelestites lain akan menyukainya...",
  ui_story_5036_50361201_32_dialog_content = "Belum lagi jika Eulogoz kita perbaiki, Soroz akhirnya punya pendamping lagi. Itu tidak akan terasa begitu sepi.",
  ui_story_5036_50361201_33_dialog_content = "Jangan khawatir, PlayerName. Saya akan melakukan yang terbaik demi Anda, juga demi mereka!",
  ui_story_5036_50361201_34_dialog_content = "Kami juga akan membantu!",
  ui_story_5036_50361201_35_dialog_content = "Jika ada yang benar-benar salah, saya akan berada di sana untuk menjaga ketertiban.",
  ui_story_5036_50361201_36_dialog_content = "Seperti biasa, Carleen mengendalikan segalanya!",
  ui_story_5036_50361201_37_dialog_content = "Wow, kalian berdua terlihat sangat siap untuk konser ini.",
  ui_story_5036_50361201_38_dialog_content = "Tentu saja! Kami bahkan menyiapkan senjata rahasia hanya untuk acara ini!",
  ui_story_5036_50361201_39_dialog_content = "Lagu apa yang akan kalian bawakan bersama?",
  ui_story_5036_50361201_40_dialog_content = "Kami awalnya akan menyanyikan lagu dari masa sekolah kami, tetapi ketika kami berlatih, ada sesuatu yang hilang.",
  ui_story_5036_50361201_41_dialog_content = "Itu tidak sepenuhnya menangkap segala sesuatu tentang perjalanan, kesulitan, atau momen kegembiraan kami.",
  ui_story_5036_50361201_42_dialog_content = "Betul sekali! Dan ketika saya bertanya kepadanya tentang hal itu, saya menyadari bahwa kami berdua merasakan hal yang sama!",
  ui_story_5036_50361201_43_dialog_content = "Itu sebabnya kami memutuskan untuk menulis lagu yang sama sekali baru untuk pertunjukan itu!",
  ui_story_5036_50361201_44_dialog_content = "Wow, saya tidak sabar untuk mendengarnya!",
  ui_story_5036_50361201_45_dialog_content = "Regina, Barbara, Carleen, Vice, Vi...",
  ui_story_5036_50361201_46_dialog_content = "Tunggu, dimana Vic?",
  ui_story_5036_50361201_47_dialog_content = "Vic? Sekarang setelah Anda menyebutkannya, saya perhatikan kamarnya kosong ketika saya melewatinya dalam perjalanan ke sini.",
  ui_story_5036_50361201_48_dialog_content = "Saya pikir dia datang lebih awal?",
  ui_story_5036_50361201_49_dialog_content = "Anda juga belum melihatnya?",
  ui_story_5036_50361201_50_dialog_content = "Astaga, konsernya akan segera dimulai! Ke mana dia bisa lari?",
  ui_story_5036_50361201_51_dialog_content = "Mungkin dia kembali untuk memeriksa telur Ouroboros?",
  ui_story_5036_50361201_52_dialog_content = "Kadang-kadang, dia lebih peduli tentang binatang ajaib daripada orang lain, dan ada juga kecenderungannya untuk tertidur secara acak.",
  ui_story_5036_50361201_53_dialog_content = "Ada kemungkinan besar dia ketiduran di sana.",
  ui_story_5036_50361201_54_dialog_content = "Tapi jangan khawatir, aku akan membawanya kembali.",
  ui_story_5036_50361201_55_dialog_content = "Sendiri? Apa kamu yakin?",
  ui_story_5036_50361201_56_dialog_content = "Saya akan baik-baik saja. Serahkan saja padaku!",
  ui_story_5036_50361201_57_dialog_content = "Mereka mengisi kita. Itu di area kuncian, bukan?",
  ui_story_5036_50361201_58_dialog_content = "Tempat itu terlalu berbahaya! Aku pergi denganmu!",
  ui_story_5036_50361201_59_dialog_content = "Hitung saya juga.",
  ui_story_5036_50361201_60_dialog_content = "Cukup jauh dari panggung. Pergi ke sana dan kembali pasti akan memakan waktu cukup lama.",
  ui_story_5036_50361201_61_dialog_content = "Jika kalian berdua masih berencana untuk tampil, lebih baik kalian tetap di sini dan bersiap-siap.",
  ui_story_5036_50361201_62_dialog_content = "Tapi bagaimana Anda bisa menangani Eclipsites itu sendiri?",
  ui_story_5036_50361201_63_dialog_content = "Anda tidak perlu khawatir tentang itu, Carleen. Goldie, Vic, dan aku sudah menyingkirkan setiap Eclipsite di sana-sini.",
  ui_story_5036_50361201_64_dialog_content = "Aku akan baik-baik saja jika aku pergi sendiri.",
  ui_story_5036_50361201_65_dialog_content = "Jika Anda mengatakan demikian, cepat saja Dan hati-hati!",
  ui_story_5036_50361201_66_dialog_content = "Aku akan, jangan khawatir.",
  ui_story_5036_50361201_67_dialog_content = "Baiklah, teman-teman! Saatnya memulai konser kita!",
  ui_story_5036_50361201_68_dialog_content = "Jika Vic tidak kembali tepat waktu, kalian berdua harus naik panggung sedikit lebih awal dari yang dijadwalkan, mengerti?",
  ui_story_5036_50361201_69_dialog_content = "Ya! Mengerti!",
  ui_story_5036_50361201_70_dialog_content = "Aku mengerti.",
  ui_story_5036_50361201_71_dialog_content = "Masih belum dimulai?",
  ui_story_5036_50361201_72_dialog_content = "Saya pikir mereka akan melakukannya! Lihat ke sana!",
  ui_story_5036_50361201_73_dialog_content = "Saatnya akhirnya tiba, semuanya! Maaf telah membuat kalian semua menunggu!",
  ui_story_5036_50361201_74_dialog_content = "Konser Langit \"The Moment the Stars Shine Brightest\", akhirnya akan segera dimulai!",
  ui_story_5036_50361201_75_dialog_content = "Woooooo!!!",
  ui_story_5036_50361201_76_dialog_content = "<color=#e8d9bb>Sementara itu</color>",
  ui_story_5036_50361201_77_dialog_content = "Hmm? Apa itu?",
  ui_story_5036_50361201_78_dialog_content = "Sesuatu yang bersinar melewati awan... Apa itu Colossus?!",
  ui_story_5036_50361201_79_dialog_content = "Tampaknya ada musik yang berasal darinya. Suara itu mengatakan sesuatu tentang Konser Langit, kan?",
  ui_story_5036_50361201_80_dialog_content = "Izinkan saya untuk mengklarifikasi, Nona. Seperti yang mungkin atau mungkin tidak Anda ketahui, itu adalah Raksasa Pengembara yang baru saja tiba dari Malam Abadi.",
  ui_story_5036_50361201_81_dialog_content = "Tampaknya seorang idola bernama Goldie mengadakan konser di atasnya.",
  ui_story_5036_50361201_82_dialog_content = "Setiap surat kabar di Umbraton ramai dengan berita tentang konser ini.",
  ui_story_5036_50361201_83_dialog_content = "Apakah begitu? Betapa sangat lucu.",
  ui_story_5036_50361201_84_dialog_content = "Ayo, mari kita temukan sudut pandang yang bagus dan lihat apa keributannya!",
  ui_story_5036_50361201_85_dialog_content = "Seperti yang Anda inginkan, Nyonya.",
  ui_story_5036_50361201_86_dialog_content = "Lihat ke atas sana, Kak! Itu adalah Colossus!",
  ui_story_5036_50361201_87_dialog_content = "Wow! Colossus sungguhan!",
  ui_story_5036_50361201_88_dialog_content = "Tunggu, di atas Colossus, apakah itu sebuah layar? Sepertinya sedang memainkan sesuatu...",
  ui_story_5036_50361201_89_dialog_content = "Hai! Bukankah itu gadis yang melindungi kita dari pemilik teater hari itu?!",
  ui_story_5036_50361201_90_dialog_content = "Itu dia! Jadi dia menemukan tempat untuk mengadakan konsernya! Dan pada Colossus, tidak kurang!",
  ui_story_5036_50361201_91_dialog_content = "Meskipun kami tidak memiliki tiket, kami dapat melihat dan mendengar semuanya sejelas siang hari. Dia luar biasa, ya kak?",
  ui_story_5036_50361201_92_dialog_content = "Itu terbang ke sana! Yuk, kita kejar!",
  ui_story_5036_50361201_93_dialog_content = "Kami akan mengikuti sungai dan menghiburnya sepanjang jalan!",
  ui_story_5036_50361201_94_dialog_content = "Saya sudah bisa merasakan antusiasme semua orang!",
  ui_story_5036_50361201_95_dialog_content = "Untuk aksi pembuka kami, kami memiliki dua idola panas dari tempat yang bahkan lebih panas — Gurun Rediesel, membawakan Anda pertunjukan yang penuh gairah dan berapi-api!",
  ui_story_5036_50361201_96_dialog_content = "Mari kita menyerah untuk Regina dan Barbara!",
  ui_story_5036_50361201_97_dialog_content = "♪ Bakar, bakar semuanya ke tanah—♪",
  ui_story_5036_50361201_98_dialog_content = "♪ Kupersembahkan semua cintaku—♪",
  ui_story_5036_50361201_99_dialog_content = "<size=40>♪ Meledak! Ledakan! Hancurkan menjadi berkeping-keping! ♪</size>",
  ui_story_5036_50361201_100_dialog_content = "<size=45>♪ Dengarkan detak jantungku, yang rindu bertemu denganmu lagi ♪</size>",
  ui_story_5036_50361201_101_dialog_content = "(Sialan, kenapa suaranya begitu keras ?!)",
  ui_story_5036_50361201_102_dialog_content = "(Aku tidak akan membiarkan dia mengalahkanku!!!)",
  ui_story_5036_50361201_103_dialog_content = "<size=40>♪ Ini, adalah—♪ saya</size>",
  ui_story_5036_50361201_104_dialog_content = "<size=45>♪ Satu-satunya harapanku, menjadi milikmu—♪</size>",
  ui_story_5036_50361201_105_dialog_content = "<size=50>♪ Rock 'n' Roll!!! ♪</size>",
  ui_story_5036_50361201_106_dialog_content = "<size=50>♪ Idola!!! ♪</size>",
  ui_story_5036_50361201_107_dialog_content = "Suara apa ini?! Ini sangat keras, dan saya tidak bisa mendengar apa pun yang mereka katakan!",
  ui_story_5036_50361201_108_dialog_content = "Ugh, rasanya telingaku mau meledak. Matikan mikrofon mereka!",
  ui_story_5036_50361201_109_dialog_content = "Apakah kamu bercanda?! Mereka berjanji untuk tidak bertarung di atas panggung!",
  ui_story_5036_50361201_110_dialog_content = "Ini tidak akan berhasil... Jika terus seperti ini, kinerjanya akan menjadi bencana. Aku harus membuat mereka kembali ke jalurnya!",
  ui_story_5036_50361201_111_dialog_content = "♪ Rasakan hatiku, bagaimana ia berdetak dan terbakar, seperti matahari gurun—♪",
  ui_story_5036_50361201_112_dialog_content = "(Tunggu, apa yang dilakukan pembawa acara di atas panggung? Dan mengapa dia bernyanyi?!)",
  ui_story_5036_50361201_113_dialog_content = "(Ini bukan bagian dari latihan!)",
  ui_story_5036_50361201_114_dialog_content = "(Saya harap mereka mengerti pesannya. Ayo, nona keberuntungan, jangan mengecewakan saya sekarang!)",
  ui_story_5036_50361201_115_dialog_content = "♪ Yang saya inginkan, adalah agar Anda mendengar saya dan merasakan apa yang saya rasakan! Dan itu—♪",
  ui_story_5036_50361201_116_dialog_content = "♪ Itu—♪",
  ui_story_5036_50361201_117_dialog_content = "♪ Itu—♪",
  ui_story_5036_50361201_118_dialog_content = "<size=45>♪ Cinta—!!!♪</size>",
  ui_story_5036_50361201_119_dialog_content = "♪ Cinta yang tidak pernah habis terbakar! ♪",
  ui_story_5036_50361201_120_dialog_content = "♪ Cinta yang selalu ada di sini! ♪",
  ui_story_5036_50361201_121_dialog_content = "<size=50>♪ Cinta seperti pasir tak berujung Rediesel—♪</size>",
  ui_story_5036_50361201_122_dialog_content = "(Berhasil! Keduanya akhirnya kembali sinkron!)",
  ui_story_5036_50361201_123_dialog_content = "(Sekarang untuk keluar.)",
  ui_story_5036_50361201_124_dialog_content = "♪ Dengan batu karangku yang tidak bisa dihentikan— ♪",
  ui_story_5036_50361201_125_dialog_content = "♪ Aku akan mengulurkan tangan dan menyentuh hatimu— ♪",
  ui_story_5036_50361201_126_dialog_content = "<size=50>♪ Biarkan lagu kita berkumandang ke langit di atas—♪</size>",
  ui_story_5036_50361201_127_dialog_content = "Hah? Hei, mereka mulai terdengar cukup bagus!",
  ui_story_5036_50361201_128_dialog_content = "Pose Goldie luar biasa! Saya lebih baik mengambil gambar sebanyak yang saya bisa!",
  ui_story_5036_50361201_129_dialog_content = "Terlepas dari betapa berbedanya melodi mereka, keduanya bernyanyi dalam harmoni yang sempurna. Lihat saja kerumunan yang berkumpul!",
  ui_story_5036_50361201_130_dialog_content = "Mencengangkan! Saya tidak percaya Lumopolis pernah menyelenggarakan konser seperti ini!",
  ui_story_5036_50361201_131_dialog_content = "Tampaknya Colossus sedang terbang sekarang, Nona.",
  ui_story_5036_50361201_132_dialog_content = "Cepat! Ke pesawat pribadiku!",
  ui_story_5036_50361201_133_dialog_content = "?!?",
  ui_story_5036_50361201_134_dialog_content = "Bagaimana mungkin saya melewatkan konser yang luar biasa ini? Buru-buru!",
  ui_story_5036_50361201_135_dialog_content = "Mengadakan konser di Colossus untuk dilihat dunia. Saya tidak berpikir ada yang pernah melakukannya sebelumnya!",
  ui_story_5036_50361201_136_dialog_content = "Semakin banyak orang yang berkumpul.",
  ui_story_5036_50361201_137_dialog_content = "Bahkan para pedagang mulai menyewakan kapalnya agar orang-orang bisa melihat konser dari Gold River.",
  ui_story_5036_50361201_138_dialog_content = "Heheheh. Sepertinya aku benar berinvestasi dalam mimpi gadis ini.",
  ui_story_5036_50361201_139_dialog_content = "Apakah Vic dan PlayerName kembali?",
  ui_story_5036_50361201_140_dialog_content = "Belum.",
  ui_story_5036_50361201_141_dialog_content = "Aku mulai mengkhawatirkan mereka berdua...",
  ui_story_5036_50361201_142_dialog_content = "Sepertinya kami tidak punya pilihan selain membiarkan kalian berdua naik ke panggung terlebih dahulu.",
  ui_story_5036_50361201_143_dialog_content = "Baiklah!",
  ui_story_5036_50361201_144_dialog_content = "Mari beri tepuk tangan meriah untuk Regina dan Barbara atas penampilan mereka yang luar biasa!",
  ui_story_5036_50361201_145_dialog_content = "Acara mulai memanas. Jantungku praktis berdetak keluar dari dadaku!",
  ui_story_5036_50361201_146_dialog_content = "Selanjutnya, kami memiliki dua bintang paling cemerlang di seluruh Astra yang siap melakukan debut akbar mereka!",
  ui_story_5036_50361201_147_dialog_content = "Duo yang tidak mungkin: satu adalah ksatria Lumopolis, dan yang lainnya adalah petugas Federasi Illumina!",
  ui_story_5036_50361201_148_dialog_content = "Namun terlepas dari faksi mereka yang berbeda, mereka telah menjadi teman terdekat dan telah melakukan petualangan yang tak terhitung jumlahnya bersama Caelestite yang legendaris!",
  ui_story_5036_50361201_149_dialog_content = "Hari ini, mereka ingin membagikan lagu mereka kepada kalian semua, sebuah lagu yang menangkap keindahan dan kegembiraan dari semua perjalanan mereka bersama!",
  ui_story_5036_50361201_150_dialog_content = "Angkat tangan Anda untuk Carleen dan Vice—!",
  ui_story_5036_50361201_151_dialog_content = "Wow, lihat saja semua orang itu. Jika hanya PlayerName disini...",
  ui_story_5036_50361201_152_dialog_content = "Jangan gugup. Kita akan baik-baik saja.",
  ui_story_5036_50361201_153_dialog_content = "Kamu benar! Ayo pergi, Carleen!",
  ui_story_5036_50361201_154_dialog_content = "♪ Perjalanan yang tak terbayangkan ♪",
  ui_story_5036_50361201_155_dialog_content = "♪ Jalan yang tidak ditemukan di peta mana pun ♪",
  ui_story_5036_50361201_156_dialog_content = "♪ Katakan padaku, apa yang ada di depan? ♪",
  ui_story_5036_50361201_157_dialog_content = "♪ Rasa takjub ♪",
  ui_story_5036_50361201_158_dialog_content = "♪ Kami telah berjalan berdampingan, sejak hari kami bertemu ♪",
  ui_story_5036_50361201_159_dialog_content = "♪ Berapapun jaraknya, kita akan selalu bertemu lagi! ♪",
  ui_story_5036_50361201_160_dialog_content = "♪ Sahabatku tersayang ♪",
  ui_story_5036_50361201_161_dialog_content = "♪ Dari orang asing menjadi teman! ♪",
  ui_story_5036_50361201_162_dialog_content = "♪ Teman seumur hidup, cahaya tanpa akhir! ♪",
  ui_story_5036_50361201_163_dialog_content = "♪ Kami berlayar melintasi langit saat dua komet terjalin ♪",
  ui_story_5036_50361201_164_dialog_content = "Syukurlah Gronru memiliki pandangan jauh ke depan untuk memasang pemancar sinyal sebelum konser dimulai. Sekarang kita semua bisa menikmati musik, bahkan dari sini.",
  ui_story_5036_50361201_165_dialog_content = "Harus saya katakan, bentuk hiburan baru ini cukup layak dipertimbangkan.",
  ui_story_5036_50361201_166_dialog_content = "Mungkin kita bahkan bisa menjalankan uji coba serupa di Undercities suatu hari nanti. Apa yang Anda katakan, Marsekal Agung?",
  ui_story_5036_50361201_167_dialog_content = "Sangat baik. Saya akan mengizinkannya.",
  ui_story_5036_50361201_168_dialog_content = "B-Benarkah? Besar!",
  ui_story_5036_50361201_169_dialog_content = "Kenapa kamu terlihat sangat terkejut?",
  ui_story_5036_50361201_170_dialog_content = "Saya hanya khawatir Anda tidak akan menyetujui hiburan semacam ini, itu saja.",
  ui_story_5036_50361201_171_dialog_content = "Ha ha ha! Tentu saja, aku punya pertimbangan tentang hal semacam ini... tapi dengarkan baik-baik musiknya.",
  ui_story_5036_50361201_172_dialog_content = "Saya mungkin tidak memiliki banyak bakat dalam hal menyanyi, tetapi bahkan saya dapat mengatakan bahwa saat ini, pada saat ini, Vice dipenuhi dengan kebahagiaan.",
  ui_story_5036_50361201_173_dialog_content = "Itu hanya jenis perasaan yang kita butuhkan, bukan?",
  ui_story_5036_50361201_174_dialog_content = "Aku hampir tidak bisa mendengar nyanyian Lady Carleen dan Vice, bahkan dari sini...",
  ui_story_5036_50361201_175_dialog_content = "Mereka terdengar luar biasa! Itu Lady Carleen untukmu!",
  ui_story_5036_50361201_176_dialog_content = "Raphael, tetap di sini dan jaga tempat ini dengan kewaspadaan ekstra.",
  ui_story_5036_50361201_177_dialog_content = "Juga, minta seseorang menyiapkan pesawat untukku, dan merahasiakannya.",
  ui_story_5036_50361201_178_dialog_content = "Hah? Apakah Anda akan keluar sekarang, Tuanku?",
  ui_story_5036_50361201_179_dialog_content = "Masih belum jelas apakah Colossus menimbulkan ancaman atau tidak. Sebagai Tuan Kota, adalah tugas saya untuk menyelidiki masalah ini dan memastikan keamanan kota kami secara pribadi.",
  ui_story_5036_50361201_180_dialog_content = "U-Mengerti!",
  ui_story_5036_50361201_181_dialog_content = "Huh...",
  ui_story_5036_50361201_182_dialog_content = "Kapan Lord Schwartz akan mengakui bahwa dia peduli pada Lady Carleen?",
  ui_story_5036_50361201_183_dialog_content = "<color=#e8d9bb>Sementara itu, di dalam Wandering Colossus</color>",
  ui_story_5036_50361201_184_dialog_content = "Nyanyian itu terdengar seperti Vice dan Carleen!",
  ui_story_5036_50361201_185_dialog_content = "Apakah sudah waktunya untuk penampilan mereka? Sial, aku harus mengambil langkah!",
  ui_story_5036_50361201_186_dialog_content = "Padahal seharusnya aku sudah ada di sana...",
  ui_story_5036_50361201_187_dialog_content = "Tidak seperti penampilan dari dua petualang terhebat di dunia!",
  ui_story_5036_50361201_188_dialog_content = "Itu hanya menunjukkan bahwa idola bisa datang dari semua lapisan masyarakat!",
  ui_story_5036_50361201_189_dialog_content = "Untuk beberapa penggemar, idola terbaik adalah yang mengeluarkan kekuatan sejati orang lain!",
  ui_story_5036_50361201_190_dialog_content = "Selanjutnya yang naik panggung adalah paduan suara karismatik dari Illumina!",
  ui_story_5036_50361201_191_dialog_content = "Mereka di sini untuk menyanyikan lagu militer yang menginspirasi—!",
  ui_story_5036_50361201_192_dialog_content = "Woooooo!!!",
  ui_story_5036_50361201_193_dialog_content = "Fiuh! Sekali lagi terima kasih atas bantuannya, nona!",
  ui_story_5036_50361201_194_dialog_content = "Jangan sebutkan itu! Saya senang semuanya berjalan dengan baik!",
  ui_story_5036_50361201_195_dialog_content = "Saya mulai khawatir tentang PlayerName dan Vic sekalipun. Mereka sudah pergi untuk sementara waktu.",
  ui_story_5036_50361201_196_dialog_content = "Memang. Colossus mungkin besar, tetapi tidak perlu waktu sebanyak ini untuk menemukan seseorang.",
  ui_story_5036_50361201_197_dialog_content = "Hmm…",
  ui_story_5036_50361201_198_dialog_content = "Ayo, Carleen. Kita harus pergi mencari mereka.",
  ui_story_5036_50361201_199_dialog_content = "Saya setuju. Sekarang setelah kinerja kami selesai, prioritas utama kami adalah memastikan keduanya aman.",
  ui_story_5036_50361201_200_dialog_content = "Tentu, tapi hati-hati di luar sana, dan ingatlah untuk kembali agar Anda bisa membungkuk!",
  ui_story_5036_50361201_201_dialog_content = "Siap!",
  ui_story_5036_50361201_202_dialog_content = "Ayo.",
  ui_story_5036_50361201_203_dialog_content = "<color=#e8d9bb>Suatu saat nanti</color>",
  ui_story_5036_50361201_204_dialog_content = "Paduan Suara Illumina menyelesaikan lagu mereka, dan Paduan Suara Lumopolis hampir selesai dengan lagu mereka juga...",
  ui_story_5036_50361201_205_dialog_content = "Di mana di bumi berada PlayerName dan yang lainnya? Mungkinkah sesuatu terjadi pada mereka?",
  ui_story_5036_50361201_206_dialog_content = "Mereka mulai membuatku khawatir, tapi aku tidak bisa pergi begitu saja. Penampilan terakhir saya akan segera hadir!",
  ui_story_5036_50361201_207_dialog_content = "Saya harus memastikan semua orang mendengar lagu saya.",
  ui_story_5036_50361201_208_dialog_content = "Jika tidak, semua kerja keras kita akan sia-sia.",
  ui_story_5036_50361201_209_dialog_content = "Aku akan pergi mencari mereka segera setelah aku selesai.",
  ui_story_5036_50361201_210_dialog_content = "Kita semakin dekat ke grand final, semuanya! Apakah kita masih bersenang-senang?!",
  ui_story_5036_50361201_211_dialog_content = "Ya-!",
  ui_story_5036_50361201_212_dialog_content = "Fantastis! Terima kasih telah menjaga energi sepanjang konser, semuanya!",
  ui_story_5036_50361201_213_dialog_content = "Nah, untuk pertunjukan terakhir, izinkan saya untuk mengirim Anda semua dengan lagu saya sendiri!",
  ui_story_5036_50361201_214_dialog_content = "Wooo!!! Akhirnya giliran Goldie untuk bernyanyi!!!",
  ui_story_5036_50361201_215_dialog_content = "Lagu berikut ini adalah lagu yang sangat spesial. Itu digunakan oleh Caelestites untuk berkomunikasi dengan Colossi.",
  ui_story_5036_50361201_216_dialog_content = "Dengan menggunakan melodinya yang unik, Caelestites akan mengemudikan Colossi mereka yang agung ke seluruh dunia!",
  ui_story_5036_50361201_217_dialog_content = "Hari ini, untuk menghormati kembalinya Colossus yang telah lama ditunggu-tunggu ini, melodi ini akan berbunyi sekali lagi!",
  ui_story_5036_50361201_218_dialog_content = "Wooo—!!!",
  ui_story_5036_50361201_219_dialog_content = "(Ini dia. Inilah saat yang kita semua tunggu-tunggu.)",
  ui_story_5036_50361201_220_dialog_content = "Ke mana pun Goldie pergi, Goldilocks mengikuti!",
  ui_story_5036_50361201_221_dialog_content = "(Biarkan lagu ini menjadi caraku untuk membalas para penggemarku dan PlayerName untuk semua dukungan tanpa akhir mereka!)",
  ui_story_5036_50361201_222_dialog_content = "♪ Cahaya bintang, bersinar terang di langit ♪",
  ui_story_5036_50361201_223_dialog_content = "♪ Seekor burung kecil melebarkan sayapnya untuk terbang ♪",
  ui_story_5036_50361201_224_dialog_content = "♪ Perjalanan panjang dan berbahaya terbentang di depan matanya ♪",
  ui_story_5036_50361201_225_dialog_content = "♪ Jadi terangi jalannya sepanjang malam! ♪",
  ui_story_5036_50361201_226_dialog_content = "Goldie! Goldie!",
  ui_story_5036_50361201_227_dialog_content = "Ah... aku bisa mendengar nyanyian Nona Goldie...",
  ui_story_5036_50361201_228_dialog_content = "Tidak peduli betapa sulitnya hal-hal yang telah terjadi. Ini membuat semuanya berharga!",
  ui_story_5036_50361201_229_dialog_content = "♪ Kesempatan untuk melihatmu, kesempatan untuk cinta tumbuh! ♪",
  ui_story_5036_50361201_230_dialog_content = "♪ Penuhi hatiku dengan keberanian, dan beritahu aku kemana harus pergi! ♪",
  ui_story_5036_50361201_231_dialog_content = "(Urgh... Ke-Kenapa aku merasa sangat mengantuk...?)",
  ui_story_5036_50361201_232_dialog_content = "(Tunggu, apa yang kupikirkan?! Aku sedang di tengah lagu sekarang!!)",
  ui_story_5036_50361201_233_dialog_content = "♪ Ayo pergi, ayo pergi, bawa aku pergi! ♪",
  ui_story_5036_50361201_234_dialog_content = "♪ Ke tempat dimana aku bisa melihatmu setiap hari! ♪",
  ui_story_5036_50361201_235_dialog_content = "(Apa yang terjadi...? Kepalaku pusing...)",
  ui_story_5036_50361201_236_dialog_content = "Kree—!",
  ui_story_5036_50361201_237_dialog_content = "(Suara itu... Darimana asal suara itu?)",
  ui_story_5036_50361201_238_dialog_content = "(Aku sangat lelah... Tapi aku belum bisa tidur! Konsernya... Masih belum selesai...)",
  ui_story_5036_50361301_1_dialog_content = "<color=#e8d9bb>Sementara itu, di area lockdown</color>",
  ui_story_5036_50361301_2_dialog_content = "Apa yang sedang terjadi? Rasanya seperti berputar-putar lagi.",
  ui_story_5036_50361301_3_dialog_content = "Saya masih ingat jalan menuju telur, jadi mengapa saya belum sampai?",
  ui_story_5036_50361301_4_dialog_content = "Bisakah Ouroboros mengaktifkan kekuatan psikisnya lagi?",
  ui_story_5036_50361301_5_dialog_content = "Apakah kita sudah sampai? Konser mungkin hampir berakhir sekarang ...",
  ui_story_5036_50361301_6_dialog_content = "Ah! Itu ada! Setelah sekian lama, akhirnya aku berhasil!",
  ui_story_5036_50361301_7_dialog_content = "Hmm? Apa yang kamu lakukan di sini, PlayerName?",
  ui_story_5036_50361301_8_dialog_content = "Jangan bilang konsernya sangat membosankan sehingga kamu datang ke sini untuk tidur siang juga?",
  ui_story_5036_50361301_9_dialog_content = "Brengsek macam apa yang kamu ambil dariku ?!",
  ui_story_5036_50361301_10_dialog_content = "Lebih penting lagi, apa yang ANDA lakukan di sini ?! Semua orang masih menunggu penampilanmu!",
  ui_story_5036_50361301_11_dialog_content = "Penampilan saya? Oh, maksudmu seluruh hal bernyanyi, kan?",
  ui_story_5036_50361301_12_dialog_content = "Maaf, tapi saya tidak bisa melakukannya.",
  ui_story_5036_50361301_13_dialog_content = "Apa maksudmu?! Anda memiliki bakat, dan Goldie menghabiskan seluruh waktu dan tenaganya untuk melatih Anda! Bagaimana Anda bisa memilih untuk memberi jaminan pada saat seperti ini ?!",
  ui_story_5036_50361301_14_dialog_content = "Ha ha ha ha! Anda benar sekali, saya punya hadiah. Tapi aku benar-benar tidak bisa melakukannya.",
  ui_story_5036_50361301_15_dialog_content = "Pernahkah Anda melihat cara mereka berlatih?",
  ui_story_5036_50361301_16_dialog_content = "Untuk tampil di atas panggung, mereka membutuhkan latihan selama berminggu-minggu, serta pasokan energi dan antusiasme yang tak ada habisnya. Dan saya sangat kurang di kedua departemen, Nak.",
  ui_story_5036_50361301_17_dialog_content = "Selain itu, saya tidak tertarik dengan konser atau idola. Tulang tua saya tidak cocok untuk hal-hal seperti itu.",
  ui_story_5036_50361301_18_dialog_content = "Dan bahkan jika saya naik ke atas panggung itu, saya hanya akan menahan Anda anak muda.",
  ui_story_5036_50361301_19_dialog_content = "Jadi, alih-alih mempersulit semua orang, saya memutuskan untuk menggunakan beberapa keterampilan saya dengan baik! Seperti menjaga telur ini dan memastikan tidak merusak konsernya!",
  ui_story_5036_50361301_20_dialog_content = "Untuk seseorang yang mengatakan bahwa mereka tidak peduli dengan konser, Anda benar-benar menunjukkan banyak perhatian.",
  ui_story_5036_50361301_21_dialog_content = "Ha ha! Aku hanya tidak ingin berada dalam posisi berhutang budi pada banyak anak.",
  ui_story_5036_50361301_22_dialog_content = "Saya pikir itu agak terlambat untuk itu ...",
  ui_story_5036_50361301_23_dialog_content = "Ahem, jika Anda berbicara tentang murid saya, itu semua adalah bagian dari pelatihan mereka.",
  ui_story_5036_50361301_24_dialog_content = "Tapi cukup tentang itu, Anda juga merasakannya dalam perjalanan ke sini, bukan? Telur Ouroboros mengaktifkan kekuatannya lagi.",
  ui_story_5036_50361301_25_dialog_content = "Ya. Rasanya seperti saya berjalan-jalan berjam-jam sebelum saya tiba di sini.",
  ui_story_5036_50361301_26_dialog_content = "Ini hanya berarti Ouroboros mendeteksi bahaya lagi, dan mencoba mempertahankan diri.",
  ui_story_5036_50361301_27_dialog_content = "Tapi bagaimana dengan Eclipsites yang kita ambil, atau retakan yang kita amankan?",
  ui_story_5036_50361301_28_dialog_content = "Mungkinkah karena Aurorian lainnya terlalu jauh?",
  ui_story_5036_50361301_29_dialog_content = "Dengan konser berjalan lancar, setiap Aurorian berkumpul di depan Colossus, tempat terjauh dari posisi kami saat ini.",
  ui_story_5036_50361301_30_dialog_content = "Jika sesuatu terjadi di sini, kita akan menjadi satu-satunya yang tersisa untuk mempertahankannya. Yang lain tidak mungkin sampai di sini tepat waktu.",
  ui_story_5036_50361301_31_dialog_content = "Jadi menurutmu Ouroboros takut karena ini?",
  ui_story_5036_50361301_32_dialog_content = "Itu mungkin!",
  ui_story_5036_50361301_33_dialog_content = "Betapa pengecutnya Ouroboros ini ternyata. Setelah bertahun-tahun di atas Colossus yang dipenuhi Eclipsite, masih menakutkan!",
  ui_story_5036_50361301_34_dialog_content = "Menurutku itu tidak terlalu menakutkan bagi mereka, melainkan takut sendirian lagi, Vic.",
  ui_story_5036_50361301_35_dialog_content = "Saya menghabiskan tujuh belas tahun pertama hidup saya di atas kapal Colossus. Meskipun saya sendirian, saya tidak pernah merasa kesepian karena saya memiliki Soroz untuk menemani saya.",
  ui_story_5036_50361301_36_dialog_content = "Tapi sekarang aku sudah punya banyak teman. Saya tahu bahwa saya tidak akan pernah bisa berpisah dengan mereka.",
  ui_story_5036_50361301_37_dialog_content = "Anda membuat poin yang bagus.",
  ui_story_5036_50361301_38_dialog_content = "Ngomong-ngomong, apa maksudmu barusan dengan telur \"merusak konser\"?",
  ui_story_5036_50361301_39_dialog_content = "Ini sudah berjalan dengan baik. Apa yang mungkin dilakukan telur Ouroboros terhadapnya sekarang?",
  ui_story_5036_50361301_40_dialog_content = "Pengamat yang tajam seperti biasa.",
  ui_story_5036_50361301_41_dialog_content = "Seperti yang saya katakan sebelumnya, beberapa faktor yang tidak diketahui telah mencegah telur ini menetas, itulah sebabnya ia tumbuh dengan proporsi yang luar biasa.",
  ui_story_5036_50361301_42_dialog_content = "Tapi untuk alasan yang sama, saya juga tidak tahu kapan akan menetas.",
  ui_story_5036_50361301_43_dialog_content = "Mengingat ukuran telur saat ini, jika Ouroboros menetas sekarang... Saya khawatir itu akan berdampak besar pada seluruh Colossus.",
  ui_story_5036_50361301_44_dialog_content = "Hah...?!",
  ui_story_5036_50361301_45_dialog_content = "Bukankah itu berarti telur ini sama berbahayanya dengan bom waktu, bukan?!",
  ui_story_5036_50361301_46_dialog_content = "Dengan tepat!",
  ui_story_5036_50361301_47_dialog_content = "Itulah sebabnya saya memutuskan untuk mengawasinya, Anda tahu? Bukan hanya demi konser, tapi demi hidup kita juga.",
  ui_story_5036_50361301_48_dialog_content = "Dan fakta bahwa Anda dapat sampai pada kesimpulan seperti itu berarti Anda memiliki bakat untuk berkarir di bidang ekstrozoologi, PlayerName!",
  ui_story_5036_50361301_49_dialog_content = "Apa yang kamu katakan? Mau bekerja di bawah saya sebagai magang terbaru saya?",
  ui_story_5036_50361301_50_option_content = "Tentu!",
  ui_story_5036_50361301_51_dialog_content = "Harus kuakui, binatang buas yang menakjubkan itu cukup menarik. Belum lagi, banyak dari mereka juga terancam punah.",
  ui_story_5036_50361301_52_dialog_content = "Melindungi mereka akan menjadi pilihan karir yang sangat berarti.",
  ui_story_5036_50361301_53_dialog_content = "Sudut pandang yang sangat valid, PlayerName. Atau haruskah saya katakan, murid kecil saya?",
  ui_story_5036_50361301_54_dialog_content = "Tapi saya beri tahu Anda sekarang, saya tidak akan membiarkan Anda memerintah saya atau mengirim saya tugas secara gratis.",
  ui_story_5036_50361301_55_dialog_content = "* Hiks * Apakah itu cara untuk melihat tuanmu?",
  ui_story_5036_50361301_56_option_content = "Saya pikir saya akan lulus.",
  ui_story_5036_50361301_57_dialog_content = "Meneliti binatang yang menakjubkan memang hebat, tapi setelah bertemu Fia dan Shira, aku tahu semua tentang kehidupan sebagai salah satu muridmu...",
  ui_story_5036_50361301_58_dialog_content = "Dikirim untuk penyelidikan tanpa uang, merawat binatang buas yang menakjubkan, merawat tuannya ...",
  ui_story_5036_50361301_59_dialog_content = "Kehidupan macam apa itu?!",
  ui_story_5036_50361301_60_dialog_content = "Segala sesuatu yang kita lakukan untuk binatang yang luar biasa adalah karena cinta dan rasa hormat kepada mereka, itulah sebabnya kita tidak meminta imbalan apa pun!",
  ui_story_5036_50361301_61_dialog_content = "Tetapi jika Anda merasa sangat menentangnya, saya tidak akan mencoba mengubah pikiran Anda.",
  ui_story_5036_50361301_62_dialog_content = "Saya telah membuang begitu banyak waktu di sini. Aku bertanya-tanya bagaimana konsernya.",
  ui_story_5036_50361301_63_dialog_content = "Saya akan kembali dan memberi tahu mereka bahwa semuanya baik-baik saja, jadi mereka tidak terus mengkhawatirkan kami.",
  ui_story_5036_50361301_64_dialog_content = "Tentu! Kalau begitu, aku akan tinggal di sini dan—",
  ui_story_5036_50361301_65_dialog_content = "Kree—!",
  ui_story_5036_50361301_66_dialog_content = "Suara apa itu?",
  ui_story_5036_50361301_67_dialog_content = "Suara? Suara apa? Anda yakin tidak mendengar sesuatu?",
  ui_story_5036_50361301_68_dialog_content = "Hei, Carleen? Apakah Anda baru saja mendengar suara aneh?",
  ui_story_5036_50361301_69_dialog_content = "Itu terdengar seperti tangisan binatang.",
  ui_story_5036_50361301_70_dialog_content = "Ngh...",
  ui_story_5036_50361301_71_dialog_content = "Carleen! Apakah kamu baik-baik saja?! Apa...",
  ui_story_5036_50361301_72_dialog_content = "Apa yang terjadi...? Sangat mengantuk...",
  ui_story_5036_50361301_73_dialog_content = "Kedengarannya seperti... Ouroboros...",
  ui_story_5036_50361301_74_dialog_content = "(Hah? Kenapa aku... sangat... mengantuk...?)",
  ui_story_5036_50361301_75_dialog_content = "PlayerName? Apa masalahnya? Hentikan itu!",
  ui_story_5036_50361301_76_dialog_content = "Sepertinya saya tidak punya pilihan selain menggunakan pilihan terakhir saya. Bika! Masuk ke dalam saku PlayerName dan makan semua Nightium-nya!",
  ui_story_5036_50361301_77_dialog_content = "Hai!",
  ui_story_5036_50361301_78_dialog_content = "A-Apa?! Tidak, tolong! Apapun selain itu!",
  ui_story_5036_50361301_79_dialog_content = "Tahukah Anda berapa lama saya bekerja untuk menyelamatkan semua ini ?!",
  ui_story_5036_50361301_80_dialog_content = "Ya ampun, kamu sudah bangun.",
  ui_story_5036_50361301_81_dialog_content = "Apakah Anda begadang tadi malam atau sesuatu? Anda akan pingsan.",
  ui_story_5036_50361301_82_dialog_content = "Hah? Tidak sama sekali, saya benar-benar pergi tidur cukup awal tadi malam.",
  ui_story_5036_50361301_83_dialog_content = "Aneh... Aku berani bersumpah baru saja mendengar Ouroboros, lalu tiba-tiba aku merasa sangat mengantuk...",
  ui_story_5036_50361301_84_dialog_content = "Anda mendengar Ouroboros? Mengapa saya tidak mendengarnya?",
  ui_story_5036_50361301_85_dialog_content = "Aku serius! Jika Anda tidak mempercayai saya, teruslah mendengarkan; itu mungkin menangis lagi!",
  ui_story_5036_50361301_86_dialog_content = "Jika Anda mengatakan demikian, saya akan tetap mendengarkan.",
  ui_story_5036_50361301_87_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5036_50361301_88_dialog_content = "Saya tidak mendengar apa-apa, apalagi Ouroboros! Anda pasti salah dengar.",
  ui_story_5036_50361301_89_dialog_content = "Namun…",
  ui_story_5036_50361301_90_dialog_content = "<color=#e8d9bb>Berdebar-</color>",
  ui_story_5036_50361301_91_dialog_content = "Aku mendengar sesuatu lagi! Hanya saja kali ini, tidak terdengar seperti teriakan Ouroboros.",
  ui_story_5036_50361301_92_dialog_content = "Suara itu, mungkinkah?!",
  ui_story_5036_50361301_93_dialog_content = "Jadi, Anda juga mendengarnya, bukan?",
  ui_story_5036_50361301_94_dialog_content = "<color=#e8d9bb>Buk—Buk—</color>",
  ui_story_5036_50361301_95_dialog_content = "Oh, aku mendengarnya, baiklah. Saya mendengarnya keras dan jelas.",
  ui_story_5036_50361301_96_dialog_content = "Ini... detak jantung.",
  ui_story_5036_50361301_97_dialog_content = "Itu berasal dari dalam telur.",
  ui_story_5036_50361301_98_dialog_content = "Hah? K-Maksudmu akhirnya menetas?!",
  ui_story_5036_50361301_99_dialog_content = "Orang ini punya waktu terburuk, tidakkah Anda setuju?",
  ui_story_5036_50361301_100_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5036_50361301_101_dialog_content = "Apa sekarang?!",
  ui_story_5036_50361301_102_dialog_content = "Awas, PlayerName!",
  ui_story_5036_50361301_103_dialog_content = "Ada yang mencoba menerobos tembok yang kita tutup tadi malam!",
  ui_story_5036_50361301_104_dialog_content = "<color=#e8d9bb>Duaar—!!</color>",
  ui_story_5036_50361301_105_dialog_content = "Graaaaaah—!",
  ui_story_5036_50361301_106_dialog_content = "Itu Eclipsites, Vic!",
  ui_story_5036_50361301_107_dialog_content = "Selamatkan kami, Bola Bulu Kecil!",
  ui_story_5036_50361302_1_dialog_content = "Mengapa ada begitu banyak Eclipsites di sini?!",
  ui_story_5036_50361302_2_dialog_content = "Saya pikir kami menyingkirkan mereka semua tadi malam!",
  ui_story_5036_50361302_3_dialog_content = "Tampaknya Eclipsites ini datang dari tempat yang lebih jauh.",
  ui_story_5036_50361302_4_dialog_content = "Dilihat dari betapa gelisahnya mereka, kurasa itu ada hubungannya dengan Ouroboros menetas.",
  ui_story_5036_50361302_5_dialog_content = "Apa pun itu, kita harus segera memberi tahu Goldie dan yang lainnya!",
  ui_story_5036_50361302_6_dialog_content = "Jika Ouroboros benar-benar tentang palka, tetap di atas Colossus akan terlalu berbahaya bagi kita!",
  ui_story_5036_50361302_7_dialog_content = "Kita harus bergegas kembali dan mengevakuasi semua orang!",
  ui_story_5036_50361302_8_dialog_content = "Benar, tinggal di sini sama sekali tidak mungkin.",
  ui_story_5036_50361302_9_dialog_content = "Lagi pula, ruangan ini bisa menabrak kepala kita begitu Ouroboros menetas.",
  ui_story_5036_50361302_10_dialog_content = "Sepertinya sudah waktunya untuk berlari!",
  ui_story_5036_50361302_11_dialog_content = "Cara ini. Jangan dipisahkan!",
  ui_story_5036_50361302_12_dialog_content = "Tunggu, saya pikir ada dua orang di lantai sana.",
  ui_story_5036_50361302_13_dialog_content = "Ini Wakil dan Carleen!",
  ui_story_5036_50361302_14_dialog_content = "Keburukan! Carleen! Bangun!",
  ui_story_5036_50361302_15_dialog_content = "Apa yang sedang terjadi? Aku tidak bisa membangunkan mereka!",
  ui_story_5036_50361302_16_dialog_content = "Mungkinkah ini karya Ouroboros juga?",
  ui_story_5036_50361302_17_dialog_content = "Terlalu berbahaya meninggalkan mereka di sini. Kami hanya harus membawa mereka.",
  ui_story_5036_50361302_18_dialog_content = "Baiklah, serahkan padaku. Aku akan mendapatkan mereka.",
  ui_story_5036_50361302_19_dialog_content = "Hrrrrrrng—oof!",
  ui_story_5036_50361302_20_dialog_content = "Anda mungkin mempertimbangkan mengangkat beban jika kita berhasil keluar dari sini, PlayerName.",
  ui_story_5036_50361302_21_dialog_content = "Sekarang jelas bukan waktunya, Vic! Bantu aku mengambilnya!",
  ui_story_5036_50361302_22_dialog_content = "Saya rasa saya juga tidak akan banyak membantu dalam hal itu. Namun-",
  ui_story_5036_50361302_23_dialog_content = "Ayo keluar, Little Furball!",
  ui_story_5036_50361302_24_dialog_content = "Cuit!",
  ui_story_5036_50361302_25_dialog_content = "Itu bisa menjadi lebih besar ?!",
  ui_story_5036_50361302_26_dialog_content = "Jelas sekali! Tapi itu tidak mengubah bulunya yang lembut dan lembut.",
  ui_story_5036_50361302_27_dialog_content = "Saya tidak bisa meminta tempat tidur yang lebih baik untuk tidur siang saya! Di sini, Anda ingin merasakannya? Sentuhan pertama gratis!",
  ui_story_5036_50361302_28_dialog_content = "M-Mungkin lain kali, Vic...",
  ui_story_5036_50361302_29_dialog_content = "Nah, Bola Bulu Kecil, atau haruskah saya mengatakan Bola Bulu Besar? Aku ingin kau membawa kedua gadis itu ke sana.",
  ui_story_5036_50361302_30_dialog_content = "Chirrrr—!",
  ui_story_5036_50361302_31_dialog_content = "Ayo terus bergerak! Kami masih harus memperingatkan yang lain!",
  ui_story_5036_50361302_32_dialog_content = "Oh, tidak...",
  ui_story_5036_50361302_33_dialog_content = "Sepertinya mereka semua sudah tidur.",
  ui_story_5036_50361302_34_dialog_content = "Gadis itu bahkan pingsan di atas panggung sendirian.",
  ui_story_5036_50361302_35_dialog_content = "...",
  ui_story_5036_50361302_36_dialog_content = "Goldi! Hentikan itu, Goldie!",
  ui_story_5036_50361302_37_dialog_content = "Mengapa saya tidak bisa membangunkan salah satu dari mereka...?",
  ui_story_5036_50361302_38_dialog_content = "Ada yang aneh dengan kondisinya. Ini tampaknya merupakan karya Luminatics.",
  ui_story_5036_50361302_39_dialog_content = "Anda pikir Ouroboros melakukan ini juga?",
  ui_story_5036_50361302_40_dialog_content = "Tapi jika demikian, mengapa kita masih terjaga saat semua orang dalam keadaan koma seperti ini?",
  ui_story_5036_50361302_41_dialog_content = "Karena ada yang spesial dari kita berdua.",
  ui_story_5036_50361302_42_dialog_content = "Anda seorang Caelestite, Anda memiliki kemampuan psikis yang unik.",
  ui_story_5036_50361302_43_dialog_content = "Bagi saya, garis keturunan saya memiliki asal yang sama dengan Ouroboros. Ini bisa menjadi sumber kekebalan saya.",
  ui_story_5036_50361302_44_dialog_content = "Apakah ada cara untuk membangunkan mereka?",
  ui_story_5036_50361302_45_dialog_content = "Saya tidak bisa mengatakan dengan pasti, tidak.",
  ui_story_5036_50361302_46_dialog_content = "Tapi bagaimana bisa? Anda baru saja mengatakannya sendiri: Anda berbagi asal usul dengan Ouroboros! Anda harus memiliki sesuatu.",
  ui_story_5036_50361302_47_dialog_content = "Maaf, tapi selain berumur panjang, Ouroboros dan saya tidak memiliki banyak kesamaan.",
  ui_story_5036_50361302_48_dialog_content = "Anda mungkin memiliki kesempatan yang lebih baik.",
  ui_story_5036_50361302_49_dialog_content = "Kemampuan psikis Anda mungkin memungkinkan Anda untuk merasakan sesuatu yang saya tidak tahu.",
  ui_story_5036_50361302_50_dialog_content = "Oke, saya kira kita tidak punya ide lain.",
  ui_story_5036_50361401_1_dialog_content = "Apa aku... tertidur?",
  ui_story_5036_50361401_2_dialog_content = "Tunggu, ini Eraveil! Apa aku bermimpi lagi?",
  ui_story_5036_50361401_3_dialog_content = "Ada yang berbeda kali ini. Adegan terlihat jauh lebih jelas dari sebelumnya.",
  ui_story_5036_50361401_4_dialog_content = "Aku bahkan bisa melihat menara putih jauh di sana.",
  ui_story_5036_50361401_5_dialog_content = "Tunggu, apa yang terbang di atasnya? Apakah itu...",
  ui_story_5036_50361401_6_dialog_content = "Seekor naga?",
  ui_story_5036_50361401_7_dialog_content = "Oh, aku pasti sedang bermimpi!",
  ui_story_5036_50361401_8_dialog_content = "Tapi bagaimana caranya? Bagaimana ini bisa terjadi? Ayolah, Goldie. Anda harus bangun! Konser belum berakhir!",
  ui_story_5036_50361401_9_dialog_content = "Mereka mengatakan bahwa mencubit paha Anda dalam mimpi akan membangunkan Anda.",
  ui_story_5036_50361401_10_dialog_content = "Ini dia!",
  ui_story_5036_50361401_11_dialog_content = "Yeeeeeowch!",
  ui_story_5036_50361401_12_dialog_content = "Kenapa aku tidak bangun?! Mungkin aku perlu mencubit diriku lebih keras lagi!",
  ui_story_5036_50361401_13_dialog_content = "♪ La—La la ♪",
  ui_story_5036_50361401_14_dialog_content = "Suara itu... Aku pernah mendengarnya sebelumnya! Kedengarannya seperti gadis Caelestite itu, Chaminade!",
  ui_story_5036_50361401_15_dialog_content = "♪ Sayap... basah kuyup ♪",
  ui_story_5036_50361401_16_dialog_content = "Saya pikir saya bisa melihat lirik lagunya kali ini.",
  ui_story_5036_50361401_17_dialog_content = "Saya tidak bisa mendengar apa pun kecuali melodi terakhir kali.",
  ui_story_5036_50361401_18_dialog_content = "♪... rumah ♪",
  ui_story_5036_50361401_19_dialog_content = "Kedengarannya seperti itu berasal dari sana.",
  ui_story_5036_50361401_20_dialog_content = "♪ Yang tersisa hanyalah saat-saat itu dalam ingatanku ♪",
  ui_story_5036_50361401_21_dialog_content = "♪ Menara putih berdiri tegak dan bangga ♪",
  ui_story_5036_50361401_22_dialog_content = "♪ Tapi cahaya penuntunnya berada di luar pandanganku ♪",
  ui_story_5036_50361401_23_dialog_content = "(Melodinya terdengar sangat indah, tapi raut wajahnya penuh dengan kesedihan...)",
  ui_story_5036_50361401_24_dialog_content = "♪ Mengembara, mengembara, melihat daratan dan laut ♪",
  ui_story_5036_50361401_25_dialog_content = "♪ Tapi jangan pernah lupakan rumah dalam mimpimu ♪",
  ui_story_5036_50361401_26_dialog_content = "Hm? Saya tidak menyadari akan ada pengunjung lain.",
  ui_story_5036_50361401_27_dialog_content = "(Hah?! A-Apa dia berbicara denganku?!)",
  ui_story_5036_50361401_28_dialog_content = "(Ini tidak pernah terjadi dalam mimpiku sebelumnya. Kecuali... ini bukan mimpi?)",
  ui_story_5036_50361401_29_dialog_content = "H-Halo disana! Anda pasti Chaminade. Nama saya Goldie. Aku seorang idola!",
  ui_story_5036_50361401_30_dialog_content = "Hmm? Kau tahu namaku?",
  ui_story_5036_50361401_31_dialog_content = "Tentu saja! Temanku PlayerName adalah Caelestite juga! Dia menggunakan kekuatan psikisnya untuk melihat ingatanmu dari masa lalu.",
  ui_story_5036_50361401_32_dialog_content = "Apakah begitu? Hehehehe, itu sedikit memalukan.",
  ui_story_5036_50361401_33_dialog_content = "Ngomong-ngomong, apa sebenarnya \"idola\" itu?",
  ui_story_5036_50361401_34_dialog_content = "Idola adalah seseorang yang menggunakan kekuatan musik untuk membawa kebahagiaan dan harapan kepada orang lain. Saya seorang idola profesional!",
  ui_story_5036_50361401_35_dialog_content = "Itu luar biasa! Aku juga ingin menjadi idola!",
  ui_story_5036_50361401_36_dialog_content = "Saya akan dengan senang hati berbagi beberapa petunjuk dengan Anda jika Anda mau. Oh, tapi sekarang bukan waktu yang tepat. Aku harus kembali ke konserku dan menyelesaikan penampilanku!",
  ui_story_5036_50361401_37_dialog_content = "Apakah Anda tahu bagaimana saya bisa keluar dari sini, Chaminade?",
  ui_story_5036_50361401_38_dialog_content = "Maafkan aku... Tapi aku tidak tahu bagaimana cara meninggalkan tempat ini.",
  ui_story_5036_50361401_39_dialog_content = "Lagipula, aku juga tidak punya jalan keluar dari sini.",
  ui_story_5036_50361401_40_dialog_content = "Tidak ada jalan keluar?",
  ui_story_5036_50361401_41_dialog_content = "(Itu masuk akal karena dia yang sebenarnya sudah...)",
  ui_story_5036_50361401_42_dialog_content = "(Tunggu, jika Chaminade yang asli sudah mati... Lalu siapa, atau apa, yang ada di depanku?)",
  ui_story_5036_50361401_43_dialog_content = "Mm, tidak apa-apa!",
  ui_story_5036_50361401_44_dialog_content = "Selama kita mencari, kita akan menemukannya!",
  ui_story_5036_50361401_45_dialog_content = "<color=#e8d9bb>Kecelakaan—</color>",
  ui_story_5036_50361401_46_dialog_content = "Hah? Suara apa itu?",
  ui_story_5036_50361401_47_dialog_content = "Itu mereka!",
  ui_story_5036_50361401_48_dialog_content = "Mereka datang! Kita harus keluar dari sini!",
  ui_story_5036_50361401_49_dialog_content = "\"Mereka\"? Siapa yang Anda bicarakan?",
  ui_story_5036_50361401_50_dialog_content = "Eclipsites!",
  ui_story_5036_50361401_51_dialog_content = "Graaaaaah—!",
  ui_story_5036_50361401_52_dialog_content = "Oh, dia tidak bercanda! Mengapa ada begitu banyak dari mereka?!",
  ui_story_5036_50361401_53_dialog_content = "Grahhhhhhhh—!",
  ui_story_5036_50361401_54_dialog_content = "Dari mana mereka semua berasal?!",
  ui_story_5036_50361401_55_dialog_content = "Mereka kembali lagi, Goldie! Cepat, sembunyi!",
  ui_story_5036_50361401_56_dialog_content = "Tidak ada tempat untuk bersembunyi, tidak dengan jumlah mereka yang sebanyak ini. Satu-satunya pilihan kita adalah bertarung!",
  ui_story_5036_50361401_57_dialog_content = "Aku tidak akan membiarkanmu Eclipsites mengamuk lagi!",
  ui_story_5036_50361402_1_dialog_content = "Aduh—!",
  ui_story_5036_50361402_2_dialog_content = "Menisik! Tidak ada habisnya bagi mereka! Kita tidak bisa mengalahkan mereka semua!",
  ui_story_5036_50361402_3_dialog_content = "Grahh!",
  ui_story_5036_50361402_4_dialog_content = "Ahhh!",
  ui_story_5036_50361402_5_dialog_content = "Lupakan aku dan lari saja! Mereka akan segera menghilang, jadi menjauhlah untuk saat ini!",
  ui_story_5036_50361402_6_dialog_content = "Hah? Apa maksudmu?",
  ui_story_5036_50361402_7_dialog_content = "Kree—",
  ui_story_5036_50361402_8_dialog_content = "Kree—!",
  ui_story_5036_50361402_9_dialog_content = "Apa naga itu... bersinar!?",
  ui_story_5036_50361402_10_dialog_content = "Ini sangat cerah! Aku tidak bisa melihat apapun—!",
  ui_story_5036_50361402_11_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5036_50361402_12_dialog_content = "Harus terus bergerak, Eclipsites tepat di belakang... Hah? Ke-Kemana perginya Eclipsites?",
  ui_story_5036_50361402_13_dialog_content = "Mereka pergi sekarang. Semuanya baik baik saja.",
  ui_story_5036_50361402_13X1_dialog_content = "Ouroboros membuat mereka semua menghilang!",
  ui_story_5036_50361402_13X2_dialog_content = "Oh ya, aku belum mengenalkannya padamu, kan? Di sana, si kecil terbang di langit di atas!",
  ui_story_5036_50361402_14_dialog_content = "Hilang? Maksudmu cahaya Ouroboros menyingkirkan mereka?",
  ui_story_5036_50361402_15_dialog_content = "Tidak, itu tidak cukup kuat untuk melakukan itu. Yang dilakukannya hanyalah memulai mimpi ini dari awal lagi.",
  ui_story_5036_50361402_16_dialog_content = "Jadi ini benar-benar mimpi!",
  ui_story_5036_50361402_17_dialog_content = "Ya itu. Mimpi yang dibuat untukku oleh Ouroboros.",
  ui_story_5036_50361402_18_dialog_content = "Karena temanmu adalah Caelestite, maka kamu pasti sudah melihat apa yang terjadi padaku...",
  ui_story_5036_50361402_19_dialog_content = "Ya...",
  ui_story_5036_50361402_20_dialog_content = "Setelah merasakan bahwa saya mati melindunginya, Ouroboros diliputi kesedihan.",
  ui_story_5036_50361402_21_dialog_content = "Itu merasakan keinginan terakhir hatiku untuk kembali ke rumahku, jadi itu menciptakan Eraveil dalam alam mimpinya, dan aku.",
  ui_story_5036_50361402_22_dialog_content = "Tetapi karena keinginannya sendiri untuk tidak melepaskan mimpi ini, Ouroboros memaksakan diri untuk tidur tanpa henti.",
  ui_story_5036_50361402_23_dialog_content = "Maka Eclipsites tadi adalah—",
  ui_story_5036_50361402_24_dialog_content = "Mereka adalah ketakutan saya.",
  ui_story_5036_50361402_25_dialog_content = "Itu adalah manifestasi dari ketakutan yang saya rasakan di saat-saat terakhir saya. Itu sebabnya mereka terus menerus muncul dan menyerang saya.",
  ui_story_5036_50361402_26_dialog_content = "Tapi tak apa, karena Ouroboros melindungiku. Tepat ketika mereka hendak menangkapku, itu mengatur ulang mimpinya dan membuat mereka menghilang!",
  ui_story_5036_50361402_27_dialog_content = "Tunggu, mungkin Anda bisa meminta Ouroboros untuk membantu Anda pergi?",
  ui_story_5036_50361402_28_dialog_content = "Ide bagus! Aku akan pergi menanyakannya sekarang!",
  ui_story_5036_50361402_29_dialog_content = "Oke! Tetapi sebelum Anda melakukannya, bisakah Anda tinggal dan berbicara dengan saya sedikit lebih lama?",
  ui_story_5036_50361402_30_dialog_content = "Saya ingin sekali, Chaminade, sungguh. Tapi penggemarku masih menungguku di luar sana.",
  ui_story_5036_50361402_31_dialog_content = "Tidak akan lama, aku janji! Saya hanya punya satu pertanyaan kecil, apakah tidak apa-apa?",
  ui_story_5036_50361402_32_dialog_content = "Tentu saja! Apa itu?",
  ui_story_5036_50361402_33_dialog_content = "Seperti apa rupa Eraveil saat ini?",
  ui_story_5036_50361402_34_dialog_content = "Tolong beritahu aku! Saya sangat penasaran.",
  ui_story_5036_50361402_35_dialog_content = "Um... Eraveil?",
  ui_story_5036_50361402_36_dialog_content = "Maaf, tapi saya belum pernah ke sana sebelumnya...",
  ui_story_5036_50361402_37_dialog_content = "Oh...",
  ui_story_5036_50361402_38_dialog_content = "Tapi jangan merasa sedih! Meskipun saya sendiri belum pernah ke sana, saya memiliki teman Caelestite tepercaya yang tinggal di sana!",
  ui_story_5036_50361402_39_dialog_content = "Maksud Anda Caelestite yang Anda sebutkan sebelumnya?",
  ui_story_5036_50361402_40_dialog_content = "Betul sekali! Namanya adalah PlayerName, dan dia salah satu orang paling luar biasa yang pernah saya temui!",
  ui_story_5036_50361402_41_dialog_content = "Sebelum saya bertemu dengannya, yang saya tahu hanyalah bahwa dia adalah pilot Caelestite dari Colossus yang melakukan perjalanan ke seluruh dunia.",
  ui_story_5036_50361402_42_dialog_content = "Sepanjang perjalanannya, dia mendapatkan banyak teman dan melakukan banyak petualangan. Dia juga mengalahkan lebih banyak Eclipsite daripada yang bisa kuhitung!",
  ui_story_5036_50361402_43_dialog_content = "Dulu aku sangat iri dengan hidupnya. Bagi saya, dia seperti menjalani kehidupan dengan kebebasan tertinggi.",
  ui_story_5036_50361402_44_dialog_content = "Tapi setelah saya mengenal dia yang sebenarnya, saya belajar betapa sulitnya hidupnya.",
  ui_story_5036_50361402_45_dialog_content = "Dia menghabiskan tahun-tahun awal hidupnya hidup di bawah tanah sendirian. Baru setelah dia mendapatkan teman pertamanya, dia akhirnya melihat cahaya hari.",
  ui_story_5036_50361402_46_dialog_content = "Dia yang terakhir dari Caelestites, dan dia bahkan membangun kembali Eraveil dari reruntuhannya.",
  ui_story_5036_50361402_47_dialog_content = "Apa?",
  ui_story_5036_50361402_48_dialog_content = "Maksud kamu apa? Apakah Eraveil... dihancurkan? Hanya ada... satu Caelestite tersisa?",
  ui_story_5036_50361402_49_dialog_content = "Ah! T-Tidak, aku tidak bermaksud seperti itu! Apa yang ingin saya katakan—",
  ui_story_5036_50361402_50_dialog_content = "Saya... rumah saya hancur...",
  ui_story_5036_50361402_51_dialog_content = "Eraveil... apakah Eraveil benar-benar hilang?",
  ui_story_5036_50361402_52_dialog_content = "Tapi bagaimana caranya? Bagaimana ini bisa terjadi?!",
  ui_story_5036_50361402_53_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5036_50361402_54_dialog_content = "<color=#e8d9bb>Retakan-!</color>",
  ui_story_5036_50361402_55_dialog_content = "Pemandangan mimpi mulai runtuh! Apakah karena emosi Chaminade?",
  ui_story_5036_50361402_56_dialog_content = "Chaminade! T-Tolong tenang!",
  ui_story_5036_50361402_57_dialog_content = "Rumahku... Aku hanya ingin pulang... Ahhhhh!",
  ui_story_5036_50361402_58_dialog_content = "Dia tidak tenang sama sekali...",
  ui_story_5036_50361402_59_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5036_50361402_60_dialog_content = "Kree! Kree—!",
  ui_story_5036_50361402_61_dialog_content = "Semakin banyak mimpi yang mulai berantakan. Tapi kenapa tidak di reset?",
  ui_story_5036_50361402_62_dialog_content = "Apa yang harus saya lakukan? Mungkin saya harus mulai menghitung dan melewatkan semua tujuh. Akankah sesuatu yang baik terjadi?",
  ui_story_5036_50361402_63_dialog_content = "Tidak... Sekarang bukan waktunya untuk hanya berdiam diri! Setidaknya saya harus menjauh dari bagian-bagian mimpi yang berantakan!",
  ui_story_5036_50361402_64_dialog_content = "Menara di sana itu sepertinya masih dalam kondisi bagus. Itu juga tempat terdekat dengan Ouroboros.",
  ui_story_5036_50361402_65_dialog_content = "Ayo pergi, Chaminade—Ahh!",
  ui_story_5036_50361402_66_dialog_content = "*Hiks*",
  ui_story_5036_50361402_67_dialog_content = "Aduh! Dia tidak membiarkanku mendekatinya!",
  ui_story_5036_50361402_68_dialog_content = "Chaminade! Chaminade! Kamu harus tenang!!!",
  ui_story_5036_50361402_69_dialog_content = "Dia tidak mendengarkanku...",
  ui_story_5036_50361402_70_dialog_content = "Jika ini terus berlanjut, seluruh mimpi akan runtuh di sekitar kita!",
  ui_story_5036_50361402_71_dialog_content = "Saya harus menemukan cara untuk memperbaiki mimpi ini!",
  ui_story_5036_50361402_72_dialog_content = "Saya hanya berharap Ouroboros tahu apa yang harus dilakukan!",
  ui_story_5036_50361402_73_dialog_content = "Menara ini sepertinya tidak ada habisnya! Bagaimana saya masih belum di atas?",
  ui_story_5036_50361402_74_dialog_content = "Tempat macam apa ini? Begitu gelap dan kosong.",
  ui_story_5036_50361402_75_dialog_content = "Tidak! Aku tidak bisa membiarkan ketakutanku akan kegelapan menghentikanku sekarang!",
  ui_story_5036_50361402_76_dialog_content = "Grah...",
  ui_story_5036_50361402_77_dialog_content = "Sepertinya tempat ini pun tidak aman dari Eclipsites.",
  ui_story_5036_50361402_78_dialog_content = "Saya kira itu masuk akal. Sebagai pusat mimpi, itu adalah tempat yang paling stabil.",
  ui_story_5036_50361402_79_dialog_content = "Bahkan Eclipsites tahu untuk lari dari bahaya, sepertinya.",
  ui_story_5036_50361402_80_dialog_content = "Saya tidak punya waktu untuk disia-siakan pada mereka. Aku harus mencapai puncak!",
  ui_story_5036_50361402_81_dialog_content = "Cahaya di depan itu pasti jalan keluar.",
  ui_story_5036_50361402_82_dialog_content = "Akhirnya!",
  ui_story_5036_50361402_83_dialog_content = "Kree, Kree!",
  ui_story_5036_50361402_84_dialog_content = "Itu adalah Ouroboros! Hai!",
  ui_story_5036_50361402_85_dialog_content = "Bisakah Anda memperbaiki mimpinya dan membuat Chaminade tenang?",
  ui_story_5036_50361402_86_dialog_content = "Kree...",
  ui_story_5036_50361402_87_dialog_content = "(Tampaknya khawatir. Apakah dia mencoba memberitahuku bahwa dia juga tidak bisa membantu?)",
  ui_story_5036_50361402_88_dialog_content = "(Apa yang harus saya lakukan sekarang?!)",
  ui_story_5036_50361402_89_dialog_content = "<color=#e8d9bb>Duarr!!!</color>",
  ui_story_5036_50361402_90_dialog_content = "Bahkan langit pun mulai runtuh!!",
  ui_story_5036_50361402_91_dialog_content = "Kree! Kree—!",
  ui_story_5036_50361402_92_dialog_content = "Ouroboros terlihat sangat kesakitan...",
  ui_story_5036_50361402_93_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5036_50361402_94_dialog_content = "Ahhh! T-Menara mulai runtuh!",
  ui_story_5036_50361402_95_dialog_content = "Ahhhhhhhh—!!!",
  ui_story_5036_50361402_96_dialog_content = "Goldie! Pegang tanganku!",
  ui_story_5036_50361402_97_dialog_content = "PlayerName!?",
  ui_story_5036_50361402_98_dialog_content = "Sedang apa kau di sini?!",
  ui_story_5036_50361402_99_dialog_content = "Kami melihat ada yang tidak beres dengan telur Ouroboros, jadi kami kembali ke panggung untuk menyelidiki.",
  ui_story_5036_50361402_100_dialog_content = "Tapi saat kami kembali ke konser, semua orang pingsan! Tidak hanya itu, ada jejak Luminatics Ouroboros di sekitar tubuh bawah sadar Anda.",
  ui_story_5036_50361402_101_dialog_content = "Jadi Ouroboros akhirnya menetas? Tapi kenapa sekarang, sepanjang masa?!",
  ui_story_5036_50361402_102_dialog_content = "Mungkin menetas setelah mendengar lagu Anda.",
  ui_story_5036_50361402_103_dialog_content = "Dengan menulis lagu Anda dengan melodi yang digunakan untuk mengaktifkan Colossi, Anda mungkin secara tidak sengaja memberi Ouroboros panggilan bangun yang diperlukan untuk menetas!",
  ui_story_5036_50361402_104_dialog_content = "Apa?!",
  ui_story_5036_50361402_105_dialog_content = "Jika kita terus berlama-lama, tanganku tidak akan bisa terus berpegangan...",
  ui_story_5036_50361402_106_dialog_content = "Tunggu! Jangan lepaskan!!!",
  ui_story_5036_50361402_107_dialog_content = "Ha ha ha! Aku hanya bercanda! Apakah Anda benar-benar berpikir saya tidak dapat diandalkan?",
  ui_story_5036_50361402_108_dialog_content = "Baiklah, ayo tarik dia keluar dari sini sekarang!",
  ui_story_5036_50361402_109_dialog_content = "Bertahanlah, Goldie!",
  ui_story_5036_50361402_110_dialog_content = "Ahhh!",
  ui_story_5036_50361402_111_dialog_content = "Aku bangun!",
  ui_story_5036_50361402_112_dialog_content = "Kau baik-baik saja?",
  ui_story_5036_50361402_113_dialog_content = "Ya, kepalaku hanya terasa sedikit pusing...",
  ui_story_5036_50361402_114_dialog_content = "Akhirnya... Setelah sekian lama, akhirnya aku... Hah? A-Apa aku bermimpi?!",
  ui_story_5036_50361402_115_dialog_content = "Ugh... Apa yang terjadi?",
  ui_story_5036_50361402_116_dialog_content = "Kepalaku... Apakah kita tertidur?",
  ui_story_5036_50361402_117_dialog_content = "Menguap. Selamat pagi...? Atau haruskah saya mengucapkan selamat malam?",
  ui_story_5036_50361402_118_dialog_content = "Apakah saya benar-benar tertidur di samping semua rakyat jelata ini ?! Ugh, aku harus membakar pakaian ini ketika aku sampai di rumah...",
  ui_story_5036_50361402_119_dialog_content = "Sepertinya semua orang mulai sadar!",
  ui_story_5036_50361402_120_dialog_content = "Apakah karena mimpi itu kembali normal?",
  ui_story_5036_50361402_121_dialog_content = "Tidak. Itu karena...",
  ui_story_5036_50361402_122_dialog_content = "Ouroboros akan menetas.",
  ui_story_5036_50361501_1_dialog_content = "<color=#e8d9bb>Umbraton, di tepi Sungai Emas</color>",
  ui_story_5036_50361501_2_dialog_content = "Hei, apa yang terjadi di atas sana? Pelaku seperti apa yang tertidur di tengah aksinya?!",
  ui_story_5036_50361501_3_dialog_content = "Aku ingin tahu apakah dia baik-baik saja.",
  ui_story_5036_50361501_4_dialog_content = "Jangan khawatir! Aku yakin dia baik-baik saja. Lagipula dia kuat!",
  ui_story_5036_50361501_5_dialog_content = "Apa yang dilakukan dua orang acak itu di atas panggung?",
  ui_story_5036_50361501_6_dialog_content = "Penipuan yang luar biasa. Saya tidak membuang-buang waktu lagi di sini.",
  ui_story_5036_50361501_7_dialog_content = "Sebentar, Pak.",
  ui_story_5036_50361501_8_dialog_content = "Masih terlalu pagi untuk berangkat. Lagi pula, semua yang Anda lihat adalah bagian dari pertunjukan.",
  ui_story_5036_50361501_9_dialog_content = "Apa?",
  ui_story_5036_50361501_10_dialog_content = "Kami berusaha keras untuk merencanakan semua efek khusus. Menyanyi dan menari saja sudah sangat membosankan, bukan begitu?",
  ui_story_5036_50361501_11_dialog_content = "Kami menyiapkan sejumlah kejutan untuk melengkapi pertunjukan dan membuatnya semenarik mungkin, semuanya untuk kesenangan menonton Anda.",
  ui_story_5036_50361501_12_dialog_content = "Saya harap Anda semua tinggal lebih lama dan menikmati pertunjukan. Saya jamin tidak akan mengecewakan.",
  ui_story_5036_50361501_13_dialog_content = "Baik, kami akan melakukan apa yang Anda katakan untuk saat ini.",
  ui_story_5036_50361501_14_dialog_content = "Terima kasih atas pengertian dan dukungan Anda! Kami juga menyiapkan makanan ringan dan minuman untuk semua orang.",
  ui_story_5036_50361501_15_dialog_content = "Tolong bantu dirimu sendiri.",
  ui_story_5036_50361501_16_dialog_content = "(Saya sudah mengendalikan kerumunan untuk saat ini, tetapi ini tidak akan bertahan lebih lama lagi.)",
  ui_story_5036_50361501_17_dialog_content = "(Apa yang sebenarnya terjadi di atas sana, Goldie?)",
  ui_story_5036_50361501_18_dialog_content = "(PlayerName dan teman-temannya juga ada di sana... Aku hanya berharap mereka tidak dalam bahaya...)",
  ui_story_5036_50361501_19_dialog_content = "<color=#e8d9bb>Sementara itu, di Eulogoz</color>",
  ui_story_5036_50361501_20_dialog_content = "Apa? Ouroboros menetas?!",
  ui_story_5036_50361501_21_dialog_content = "Aku tahu ini tiba-tiba, tapi kami tidak punya waktu untuk menjelaskannya.",
  ui_story_5036_50361501_22_dialog_content = "Jika Ouroboros menetas, itu akan membuat seluruh Colossus kehilangan keseimbangan dan menempatkan kita semua dalam bahaya.",
  ui_story_5036_50361501_23_dialog_content = "Prioritas utama kami saat ini adalah mengevakuasi semua orang di pesawat!",
  ui_story_5036_50361501_24_dialog_content = "Dan lebih baik kita melakukannya dengan cepat, atau... Uh-oh. Sepertinya kita sudah terlambat.",
  ui_story_5036_50361501_25_dialog_content = "Grahhhh—!!!",
  ui_story_5036_50361501_26_dialog_content = "Eclipsites mengalir keluar dari dalam Colossus!",
  ui_story_5036_50361501_27_dialog_content = "Bangun, semuanya! Asumsikan posisi defensif!",
  ui_story_5036_50361501_28_dialog_content = "Ya, Nona!",
  ui_story_5036_50361501_29_dialog_content = "Graaaaaah!",
  ui_story_5036_50361501_30_dialog_content = "Anda tidak akan melewati saya!",
  ui_story_5036_50361501_31_dialog_content = "Berengsek! Apakah tidak ada habisnya makhluk-makhluk kotor ini?!",
  ui_story_5036_50361501_32_dialog_content = "Cukup mengeluh. Fokus pada pertahanan.",
  ui_story_5036_50361501_33_dialog_content = "Ya ya saya tahu!",
  ui_story_5036_50361501_34_dialog_content = "<color=#e8d9bb>Gemuruh…</color>",
  ui_story_5036_50361501_35_dialog_content = "Seluruh Colossus bergetar! Apakah bos terakhir akan muncul?!",
  ui_story_5036_50361501_36_dialog_content = "Bertahanlah, semuanya! Sepertinya ada sesuatu yang keluar dari Colossus!",
  ui_story_5036_50361501_37_dialog_content = "Kree—!",
  ui_story_5036_50361501_38_dialog_content = "Seekor naga?! Ini masif!!",
  ui_story_5036_50361501_39_dialog_content = "Jadi itu benar-benar menetas!",
  ui_story_5036_50361501_40_dialog_content = "Astaga!!!",
  ui_story_5036_50361501_41_dialog_content = "Eclipsites mulai menyerang Ouroboros!",
  ui_story_5036_50361501_42_dialog_content = "Kree—Kree—!",
  ui_story_5036_50361501_43_dialog_content = "Lihat, kak! Di sana, di puncak Colossus!",
  ui_story_5036_50361501_44_dialog_content = "Apa itu... naga?!",
  ui_story_5036_50361501_45_dialog_content = "Hai! Colossus bergetar sangat keras. Itu akan jatuh dari langit!",
  ui_story_5036_50361501_46_dialog_content = "<color=#e8d9bb>DUARR!!!</color>",
  ui_story_5036_50361501_47_dialog_content = "Ini buruk! Ouroboros baru saja menetas. Itu belum bisa terbang!",
  ui_story_5036_50361501_48_dialog_content = "Serangan Eclipsites hanya akan membuatnya berjuang lebih keras!",
  ui_story_5036_50361501_49_dialog_content = "Apakah ada cara untuk menenangkannya terlebih dahulu?",
  ui_story_5036_50361501_50_dialog_content = "Bagaimana kalau kau memakai kemampuan psikismu?",
  ui_story_5036_50361501_51_dialog_content = "Akan kucoba.",
  ui_story_5036_50361501_52_option_content = "\"Berhenti, Ouroboros!\"",
  ui_story_5036_50361501_53_dialog_content = "Kree—!",
  ui_story_5036_50361501_54_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5036_50361501_55_dialog_content = "Ah!",
  ui_story_5036_50361501_56_dialog_content = "Itu tidak akan mendengarkan saya sama sekali!",
  ui_story_5036_50361501_57_dialog_content = "The Eclipsites telah... mengelilingi panggung.",
  ui_story_5036_50361501_58_dialog_content = "Konser ... itu benar-benar hancur ...",
  ui_story_5036_50361501_59_dialog_content = "Goldie, dapatkan pegangan! Kita masih dalam bahaya!",
  ui_story_5036_50361501_60_dialog_content = "Aku tahu, tapi…",
  ui_story_5036_50361501_61_dialog_content = "Tidak ada waktu untuk disia-siakan. Posisi, semuanya! Kita harus membuat jarak antara Eclipsites dan naga!",
  ui_story_5036_50361501_62_dialog_content = "Ya!",
  ui_story_5036_50361501_63_dialog_content = "Illumina juga tidak akan mundur! Pertarungan bos baru saja dimulai!",
  ui_story_5036_50361501_64_dialog_content = "Ya!!!",
  ui_story_5036_50361501_65_dialog_content = "Keburukan, PlayerName! Kalian berdua melindungi dan mengawal warga sipil menjauh dari area pertempuran!",
  ui_story_5036_50361501_66_dialog_content = "Hubungi kapal udara Soroz dan Lumopolis dan buat rencana evakuasi!",
  ui_story_5036_50361501_67_dialog_content = "Baiklah, serahkan padaku!",
  ui_story_5036_50361501_68_dialog_content = "Baiklah!",
  ui_story_5036_50361501_69_dialog_content = "Knights of Lumopolis sangat bisa diandalkan di saat bahaya seperti ini!",
  ui_story_5036_50361501_70_dialog_content = "Apakah Anda tidak memiliki sesuatu untuk dilakukan? Temukan cara untuk menenangkan naga itu.",
  ui_story_5036_50361501_71_dialog_content = "Maafkan aku, aku bukan petarung...",
  ui_story_5036_50361501_72_dialog_content = "Kamu... Sudahlah. Evakuasi dengan yang lain, kalau begitu.",
  ui_story_5036_50361501_73_dialog_content = "Tidak masalah. Aku hanya akan melihat diriku keluar sekarang.",
  ui_story_5036_50361501_74_dialog_content = "Semuanya, ke sini!",
  ui_story_5036_50361501_75_dialog_content = "Bagaimana Soroz, PlayerName?",
  ui_story_5036_50361501_76_dialog_content = "Ouroboros tidak tenang. Soroz tidak bisa terhubung dengannya!",
  ui_story_5036_50361501_77_dialog_content = "Andai saja ada cara untuk menenangkannya meski hanya sesaat...",
  ui_story_5036_50361501_78_dialog_content = "Tapi sepertinya itu tidak akan berhasil, setidaknya tidak untuk waktu yang lama.",
  ui_story_5036_50361501_79_dialog_content = "Di mana kapal udara Lumopolis?",
  ui_story_5036_50361501_80_dialog_content = "Jelas saya sudah menghubungi mereka.",
  ui_story_5036_50361501_81_dialog_content = "Konser tersebut telah menarik beberapa bangsawan dengan kapal udara mereka. Beberapa dari mereka sudah membantu evakuasi.",
  ui_story_5036_50361501_82_dialog_content = "Penguasa Kota mengirim semua kapal udara yang tersedia di Lumopolis ke sini, tapi masih butuh waktu.",
  ui_story_5036_50361501_83_dialog_content = "Belum lagi Lumopolis hanya memiliki kapal udara kecil lebih sering daripada tidak. Butuh beberapa perjalanan untuk mengangkut semua orang itu keluar dari sini.",
  ui_story_5036_50361501_84_dialog_content = "Kita harus membeli mereka lebih banyak waktu.",
  ui_story_5036_50361501_85_dialog_content = "Urgh—!",
  ui_story_5036_50361501_X85_dialog_content = "Tahan!",
  ui_story_5036_50361501_87_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_5036_50361501_88_dialog_content = "Lady Carleen, ada terlalu banyak Eclipsites! Kami tidak bisa menahan garis kami!",
  ui_story_5036_50361501_89_dialog_content = "Ahh, semuanya dari Lumopolis, lebih baik kita pergi dari sana!",
  ui_story_5036_50361501_90_dialog_content = "Naga itu berjuang terlalu keras, dan Colossus terlalu tua—",
  ui_story_5036_50361501_91_dialog_content = "Banyak dari bagian-bagiannya yang tidak tahan dipukuli, itu mulai berantakan!",
  ui_story_5036_50361501_92_dialog_content = "Di mana kapal udara?",
  ui_story_5036_50361501_93_dialog_content = "Laporan! Soroz tidak dapat terhubung, tetapi kapal udara dari Lumopolis sedang dalam perjalanan!",
  ui_story_5036_50361501_94_dialog_content = "Kami kehabisan pilihan! Hubungi semua tim untuk mundur. Berhenti membela Ouroboros untuk saat ini dan bergerak ke arah orang-orang!",
  ui_story_5036_50361501_95_dialog_content = "Ya!",
  ui_story_5036_50361501_96_dialog_content = "Carleen!",
  ui_story_5036_50361501_97_dialog_content = "Saya baik-baik saja, apakah semua orang di sini?",
  ui_story_5036_50361501_98_dialog_content = "Mereka semua ada di sini, Lady Carleen!",
  ui_story_5036_50361501_99_dialog_content = "Gelombang pertama kapal udara telah tiba. Evakuasi sedang berlangsung, tapi...",
  ui_story_5036_50361501_100_dialog_content = "Butuh waktu.",
  ui_story_5036_50361501_101_dialog_content = "Kapal udara terlalu kecil. Terlalu banyak orang.",
  ui_story_5036_50361501_102_dialog_content = "Saya akan melakukan yang terbaik untuk membelikan Anda waktu.",
  ui_story_5036_50361501_103_dialog_content = "Buru-buru! Colossus dapat terbalik kapan saja!",
  ui_story_5036_50361501_104_dialog_content = "Hiks... aku...",
  ui_story_5036_50361501_105_dialog_content = "Apakah kamu baik-baik saja, Goldie?",
  ui_story_5036_50361501_106_dialog_content = "Aku baik-baik saja... konsernya hancur, tapi aku baik-baik saja...",
  ui_story_5036_50361501_107_dialog_content = "Tetap saja, aku harus melindungi penggemarku. Mereka tidak bisa terluka karena aku!",
  ui_story_5036_50361501_108_dialog_content = "Bahkan jika... ini adalah konser terakhirku!",
  ui_story_5036_50361501_109_dialog_content = "Yup, mari kita fokus pada masalah yang ada dulu.",
  ui_story_5036_50361501_110_dialog_content = "Omong-omong Vic, bisakah Ouroboros benar-benar tidak—Vic?",
  ui_story_5036_50361501_111_dialog_content = "Ke mana dia lari sekarang?",
  ui_story_5036_50361501_112_dialog_content = "Bukankah dia mengungsi bersamamu?",
  ui_story_5036_50361501_113_dialog_content = "Saya pikir dia ada di belakang saya, jadi saya tidak terlalu memperhatikan!",
  ui_story_5036_50361501_114_dialog_content = "Oh, aku benar-benar bukan petarung sama sekali.",
  ui_story_5036_50361501_115_dialog_content = "Saya pikir saya mendengarnya?",
  ui_story_5036_50361501_116_dialog_content = "Itu dia!",
  ui_story_5036_50361501_117_dialog_content = "Nah, karena saya menyebut diri saya seorang ahli ekstrozoologi, lebih baik saya mulai bertindak seperti itu.",
  ui_story_5036_50361501_118_dialog_content = "Kenapa dia di sana sendirian?",
  ui_story_5036_50361501_119_dialog_content = "Kembali kesini! Itu berbahaya!",
  ui_story_5036_50361501_120_dialog_content = "Terima kasih atas pengingatnya, tetapi saya tidak bisa. Belum.",
  ui_story_5036_50361501_121_dialog_content = "Hei kau! Anda menjijikkan, hal-hal hantu! Disini!",
  ui_story_5036_50361501_122_dialog_content = "Peeeko! Mendesis-!",
  ui_story_5036_50361501_123_dialog_content = "Grrrr...",
  ui_story_5036_50361501_124_dialog_content = "Ya! Itu dia...",
  ui_story_5036_50361501_125_dialog_content = "Mengapa mengejar Ouroboros ketika ada Aurorian yang tak berdaya di sini?",
  ui_story_5036_50361501_126_dialog_content = "(Sedikit lebih dekat... Harus membawa mereka menjauh dari Ouroboros.)",
  ui_story_5036_50361501_127_dialog_content = "(Burung Hantu Lutumi seharusnya cukup untuk menarik perhatian mereka dan mengulur waktu.)",
  ui_story_5036_50361501_128_option_content = "Vic, kembali ke sini!",
  ui_story_5036_50361501_129_dialog_content = "Ha ha ha! Jangan khawatir tentang itu, aku baik-baik saja!",
  ui_story_5036_50361501_130_dialog_content = "Hanya ahli ekstrozoologi terbaik yang dapat mempercayakan hidupnya kepada binatang buasnya yang menakjubkan!",
  ui_story_5036_50361501_131_dialog_content = "Gahhhhhhh—!",
  ui_story_5036_50361501_132_dialog_content = "(Bagus! Mereka mengambil umpannya!)",
  ui_story_5036_50361501_133_dialog_content = "(Sekarang, yang saya butuhkan hanyalah memanggil Burung Hantu Lutumi!)",
  ui_story_5036_50361501_134_dialog_content = "Burung Hantu Lutumi!",
  ui_story_5036_50361501_135_dialog_content = "Hoot—hoot hoot!",
  ui_story_5036_50361501_136_dialog_content = "Kenapa kau kabur, Lutumi Owl!? Kembali kesini-!",
  ui_story_5036_50361501_137_dialog_content = "<color=#e8d9bb>Gruk!</color>",
  ui_story_5036_50361501_138_dialog_content = "Kree!",
  ui_story_5036_50361501_139_dialog_content = "Apa?!",
  ui_story_5036_50361501_140_dialog_content = "<color=#e8d9bb>Whoosh—Bang!</color>",
  ui_story_5036_50361501_141_dialog_content = "Vic?",
  ui_story_5036_50361501_142_dialog_content = "Aduh, aduh, aduh!",
  ui_story_5036_50361501_143_dialog_content = "(Ekor Ouroboros membuatnya terbang! Tunggu sebentar! Itu...!)",
  ui_story_5036_50361501_144_dialog_content = "Vic! Lari!",
  ui_story_5036_50361501_145_dialog_content = "Tsk! Naga itu benar-benar tidak tahu bagaimana bersikap lembut.",
  ui_story_5036_50361501_146_dialog_content = "PlayerName, apa katamu? Aku tidak mendengarmu!",
  ui_story_5036_50361501_147_dialog_content = "Aahhhh!",
  ui_story_5036_50361501_148_dialog_content = "Astaga... aku dikepung!",
  ui_story_5036_50361501_149_dialog_content = "Hei, Eclipsites, aku sudah tua, dan itu membuatku tidak enak!",
  ui_story_5036_50361501_150_dialog_content = "Lihatlah Caelestite di sana! Dia muda dan lembut! Dan jauh lebih segar dari saya!",
  ui_story_5036_50361501_151_dialog_content = "Graaaaaah!!!",
  ui_story_5036_50361501_152_dialog_content = "Selamatkan aku, Bola Bulu Kecil!",
  ui_story_5036_50361501_153_dialog_content = "PlayerName!",
  ui_story_5036_50361502_1_dialog_content = "Sangat menyenangkan! Aku masih hidup!",
  ui_story_5036_50361502_2_dialog_content = "Meski seluruh rencanaku untuk menarik perhatian Eclipsites gagal.",
  ui_story_5036_50361502_3_dialog_content = "Bagaimana mood Anda untuk tertawa !?",
  ui_story_5036_50361502_4_dialog_content = "Jika Anda punya rencana, Anda perlu memberi tahu kami tentang itu!",
  ui_story_5036_50361502_5_dialog_content = "Maaf maaf! Saya sangat khawatir tentang keamanan Ouroboros sehingga saya benar-benar lupa.",
  ui_story_5036_50361502_6_dialog_content = "Tapi, sebagai catatan saja, rencanaku akan berhasil jika tidak membuatku terbang.",
  ui_story_5036_50361502_7_dialog_content = "Ini bukan waktunya untuk mendiskusikan keinginan!",
  ui_story_5036_50361502_8_dialog_content = "Apakah ada cara lain untuk menenangkannya?",
  ui_story_5036_50361502_9_dialog_content = "Sayangnya, saya tidak bisa memikirkan apa pun selain mengalahkan semua Eclipsites.",
  ui_story_5036_50361502_10_dialog_content = "Tidak bisakah kita menunggu Ouroboros mengumpulkan kekuatan yang cukup untuk terbang dengan sendirinya?",
  ui_story_5036_50361502_11_dialog_content = "Itu sedikit terlalu optimis. The Eclipsites tidak mundur sama sekali.",
  ui_story_5036_50361502_12_dialog_content = "Jika ini terus berlanjut, bahkan jika Ouroboros bisa terbang lagi, itu akan terlalu menyakitkan.",
  ui_story_5036_50361502_13_dialog_content = "Bagaimana…",
  ui_story_5036_50361502_14_dialog_content = "Lady Carleen, kami telah menerima perintah dari Penguasa Kota.",
  ui_story_5036_50361502_15_dialog_content = "Majulah.",
  ui_story_5036_50361502_16_dialog_content = "Evakuasi hampir selesai. Baik administrasi Illumina dan Lumopolis telah menyelesaikan evaluasi risiko terhadap Colossus.",
  ui_story_5036_50361502_17_dialog_content = "Mereka telah memutuskan untuk meninggalkan para prajurit untuk menahan Eclipsites, mengendalikan naga, dan menjaga keseimbangan Colossus.",
  ui_story_5036_50361502_18_dialog_content = "Setelah Colossus keluar dari Umbraton, mereka akan menembak jatuh.",
  ui_story_5036_50361502_19_dialog_content = "Anda ingin menembak Colossus bersama dengan Ouroboros !? Tidak mungkin!",
  ui_story_5036_50361502_20_dialog_content = "Ini mungkin yang terakhir dari jenisnya! Mereka akan benar-benar punah jika Anda melakukan itu!",
  ui_story_5036_50361502_21_dialog_content = "Dan saya tidak akan kehilangan Eulogoz!",
  ui_story_5036_50361502_22_dialog_content = "Apakah Anda punya ide yang lebih baik? Jika tidak, maka diamlah.",
  ui_story_5036_50361502_23_dialog_content = "Colossus berada tepat di atas area Umbraton yang paling padat penduduknya. Kami tidak akan mempertaruhkan nyawa jutaan Aurorian!",
  ui_story_5036_50361502_24_dialog_content = "Bagaimana jika saya menolak meninggalkan Colossus?",
  ui_story_5036_50361502_25_dialog_content = "Vic, apa yang kamu katakan—?",
  ui_story_5036_50361502_26_dialog_content = "Saya seorang ahli ekstrozoologi. Tidak mungkin aku akan membiarkan bahaya menimpa Ouroboros itu.",
  ui_story_5036_50361502_27_dialog_content = "Jika kau ingin menjatuhkan Colossus, kau harus menjatuhkanku bersamanya.",
  ui_story_5036_50361502_28_dialog_content = "Vic, itu berbahaya!",
  ui_story_5036_50361502_29_dialog_content = "Berhenti main-main!",
  ui_story_5036_50361502_30_dialog_content = "(Apa yang harus saya lakukan? Bagaimana saya bisa menyelamatkan Ouroboros dan Colossus?)",
  ui_story_5036_50361502_31_dialog_content = "(Pasti ada jalan...)",
  ui_story_5036_50361502_32_dialog_content = "Mereka pasti bisa mendengar suaraku di tanah melalui peralatan!",
  ui_story_5036_50361502_33_dialog_content = "Alangkah menakjubkannya, makhluk itu bisa berkomunikasi menggunakan melodi yang digunakan Caelestites untuk mengendalikan Colossi.",
  ui_story_5036_50361502_34_dialog_content = "Dengan menulis lagu Anda dengan melodi yang digunakan untuk mengaktifkan Colossi, Anda mungkin secara tidak sengaja memberi Ouroboros panggilan bangun yang diperlukan untuk menetas!",
  ui_story_5036_50361502_35_dialog_content = "Ada cara lain yang ingin saya coba!",
  ui_story_5036_50361502_36_dialog_content = "Hah?",
  ui_story_5036_50361502_37_dialog_content = "Ada apa?",
  ui_story_5036_50361502_38_dialog_content = "Chaminade menemukan bahwa Ouroboros dapat memahami melodi yang digunakan Caelestites untuk mengontrol Colossi.",
  ui_story_5036_50361502_39_dialog_content = "Jika kita bisa memainkan melodi yang mematikan Colossus dan menghentikan Eclipsites pada saat bersamaan, mungkin kita bisa menenangkannya.",
  ui_story_5036_50361502_40_dialog_content = "Itu patut dicoba.",
  ui_story_5036_50361502_41_dialog_content = "Apakah sebuah lagu akan berhasil jika bahkan kemampuan psikis PlayerName tidak dapat mencapai naga?",
  ui_story_5036_50361502_42_dialog_content = "Yah... Selama itu cukup keras, kita harus bisa menarik perhatiannya.",
  ui_story_5036_50361502_43_dialog_content = "Kita bisa menggunakan sistem speaker panggung!",
  ui_story_5036_50361502_44_dialog_content = "Ya. Aku butuh bantuan Goldie. Kita seharusnya bisa melakukannya dengan Luminatics dan perlengkapannya!",
  ui_story_5036_50361502_45_dialog_content = "Aku?",
  ui_story_5036_50361502_46_dialog_content = "...",
  ui_story_5036_50361502_47_dialog_content = "Aku paham.",
  ui_story_5036_50361502_48_dialog_content = "Konser saya tidak dapat berakhir sebelum saya menyelesaikan lagu saya.",
  ui_story_5036_50361502_49_dialog_content = "Bahkan jika aku tidak bisa lagi tampil sebagai idola di masa depan, selama kamu dan penggemarku ada di luar sana...",
  ui_story_5036_50361502_50_dialog_content = "Saya akan bernyanyi untuk Anda semua kapan pun Anda membutuhkan saya.",
  ui_story_5036_50361502_51_dialog_content = "Belum lagi Umbraton berada tepat di bawah kita. Ini rumah saya, dan rumah para penggemar saya.",
  ui_story_5036_50361502_52_dialog_content = "Seberapa yakin Anda bahwa ini akan berhasil, PlayerName?",
  ui_story_5036_50361502_53_option_content = "aku tidak bisa menjanjikan apapun padamu...",
  ui_story_5036_50361502_54_option_content = "Saya ingin mencobanya!",
  ui_story_5036_50361502_55_dialog_content = "Baiklah.",
  ui_story_5036_50361502_56_dialog_content = "Aku akan membantu.",
  ui_story_5036_50361502_57_dialog_content = "Nona Carleen! Apakah kamu serius?",
  ui_story_5036_50361502_58_dialog_content = "Tentu saja. Dan saya juga akan memberikan dukungan jika gagal.",
  ui_story_5036_50361502_59_dialog_content = "Beri tahu semua tim untuk siaga!",
  ui_story_5036_50361502_60_dialog_content = "Dipahami. Ksatria, bentuklah!",
  ui_story_5036_50361502_61_dialog_content = "Carleen, terima kasih banyak!",
  ui_story_5036_50361502_62_dialog_content = "Saya akan membantu juga!",
  ui_story_5036_50361502_63_dialog_content = "Tapi kru yang menangani sistem pengeras suara sudah pergi dengan pesawat.",
  ui_story_5036_50361502_64_dialog_content = "Jangan lupakan kami! Kami punya ini.",
  ui_story_5036_50361502_65_dialog_content = "Peralatan dapat dimodifikasi, tetapi masih sangat mirip. Serahkan pada kami.",
  ui_story_5036_50361502_66_dialog_content = "Gronru, Siobhan!?",
  ui_story_5036_50361502_67_dialog_content = "PlayerName, Anda mencoba menantang beberapa tahapan yang sangat sulit, bukan?",
  ui_story_5036_50361502_68_dialog_content = "Bagaimana saya bisa melewatkan sesuatu yang begitu menyenangkan?",
  ui_story_5036_50361502_69_dialog_content = "A-Dan aku!",
  ui_story_5036_50361502_70_dialog_content = "Saya telah mewawancarai orang-orang beberapa hari terakhir, termasuk orang-orang yang menangani sistem pengeras suara.",
  ui_story_5036_50361502_71_dialog_content = "Saya juga belajar satu atau dua hal dari mereka!",
  ui_story_5036_50361502_72_dialog_content = "Ini sepertinya usaha yang gila, tapi tolong izinkan saya ikut! Saya akan melakukan yang terbaik untuk membantu Goldie dan Anda!",
  ui_story_5036_50361502_73_dialog_content = "Terima kasih…",
  ui_story_5036_50361502_74_dialog_content = "PlayerName, Anda pasti memiliki cara untuk menyatukan semua orang.",
  ui_story_5036_50361502_75_dialog_content = "Kemampuan ini saja membuat Caelestite menjadi binatang yang menakjubkan.",
  ui_story_5036_50361502_76_dialog_content = "Tunggu, aku bukan binatang yang menakjubkan!",
  ui_story_5036_50361502_77_dialog_content = "Hahaha. Tidak ada waktu untuk berdebat.",
  ui_story_5036_50361502_78_dialog_content = "Kami kekurangan waktu. Ayo selamatkan Ouroboros dulu!",
  ui_story_5036_50361502_79_dialog_content = "Benar. Ke panggung!",
  ui_story_5036_50361601_1_dialog_content = "Goldie, apakah kamu menghafal melodi yang saya ajarkan?",
  ui_story_5036_50361601_2_dialog_content = "Tentu saja! Setiap catatan itu!",
  ui_story_5036_50361601_3_dialog_content = "Tapi ada begitu banyak Eclipsites di jalan kita...",
  ui_story_5036_50361601_4_dialog_content = "Jangan khawatir. Kami akan mengurus mereka dan membuka jalan untuk Anda.",
  ui_story_5036_50361601_5_dialog_content = "Ya. Serahkan pertempuran pada kami. Anda hanya fokus pada bernyanyi!",
  ui_story_5036_50361601_6_dialog_content = "Memang. Aku tidak bisa melawan, tapi Little Furball akan membantu.",
  ui_story_5036_50361601_7_dialog_content = "Cuit!",
  ui_story_5036_50361601_8_dialog_content = "Terima kasih karena masih mau membantuku, Goldie.",
  ui_story_5036_50361601_9_dialog_content = "Tidak perlu berterima kasih padaku.",
  ui_story_5036_50361601_10_dialog_content = "Anda telah membantu saya selama beberapa hari terakhir, PlayerName.",
  ui_story_5036_50361601_11_dialog_content = "Jika bukan karena bantuan Anda, konser ini tidak akan pernah ada.",
  ui_story_5036_50361601_12_dialog_content = "Tapi sudah hancur...",
  ui_story_5036_50361601_13_dialog_content = "Meski begitu, saya tahu berapa banyak usaha yang Anda lakukan.",
  ui_story_5036_50361601_14_dialog_content = "Kegagalan konser tidak mengubah fakta itu.",
  ui_story_5036_50361601_15_dialog_content = "Jadi sekarang, saatnya aku membayarmu!",
  ui_story_5036_50361601_16_dialog_content = "Oke!",
  ui_story_5036_50361601_17_dialog_content = "Ayo pergi!",
  ui_story_5036_50361601_18_dialog_content = "Graaaaaah!!!",
  ui_story_5036_50361601_19_dialog_content = "Eclipse masuk! Bersiap untuk bertempur!",
  ui_story_5036_50361602_1_dialog_content = "Kami telah mencapai tahap! Bagaimana perlengkapannya?",
  ui_story_5036_50361602_2_dialog_content = "Peralatannya baik-baik saja!",
  ui_story_5036_50361602_3_dialog_content = "Output volume maksimal—!",
  ui_story_5036_50361602_4_dialog_content = "Grahhhhhhhh—!",
  ui_story_5036_50361602_5_dialog_content = "Hah?!",
  ui_story_5036_50361602_6_dialog_content = "Rapid Torrent!",
  ui_story_5036_50361602_7_dialog_content = "Th-Terima kasih!",
  ui_story_5036_50361602_8_dialog_content = "Sama-sama.",
  ui_story_5036_50361602_9_dialog_content = "Serahkan Eclipsites kepada kami! Anda hanya fokus menangani peralatan!",
  ui_story_5036_50361602_10_dialog_content = "Selama kita masih di sini, kita tidak akan membiarkan Eclipsite lewat!",
  ui_story_5036_50361602_11_dialog_content = "Grah!",
  ui_story_5036_50361602_12_dialog_content = "Jangan pernah berpikir untuk melarikan diri!",
  ui_story_5036_50361602_13_dialog_content = "Inilah kesempatan Anda! Bola Bulu Kecil, serang punggungnya!",
  ui_story_5036_50361602_14_dialog_content = "Cuit!",
  ui_story_5036_50361602_15_dialog_content = "Grahhhh—",
  ui_story_5036_50361602_16_dialog_content = "Wow, barangnya cepat. Bahkan Little Furball kesulitan mengejarnya.",
  ui_story_5036_50361602_17_dialog_content = "Itu terus berlarian. Betapa merepotkan!",
  ui_story_5036_50361602_18_dialog_content = "Tunggu sebentar! Setidaknya, jangan biarkan itu mengganggu nyanyian Goldie!",
  ui_story_5036_50361602_19_dialog_content = "Ya!",
  ui_story_5036_50361602_20_dialog_content = "(Semua orang berkelahi. Saya harus melakukan pekerjaan saya.)",
  ui_story_5036_50361602_21_dialog_content = "Kree—Kree!",
  ui_story_5036_50361602_22_dialog_content = "<color=#e8d9bb>Gemuruh-!</color>",
  ui_story_5036_50361602_23_dialog_content = "Ouroboros, kamu juga berjuang, bukan?",
  ui_story_5036_50361602_24_dialog_content = "Bertahanlah sedikit lebih lama. Percayalah pada kami. Kami akan melindungimu.",
  ui_story_5036_50361602_25_dialog_content = "Uhm... Aku akan mulai bernyanyi!",
  ui_story_5036_50361602_26_dialog_content = "Siap!",
  ui_story_5036_50361602_27_dialog_content = "(Tenang, Goldie.)",
  ui_story_5036_50361602_28_dialog_content = "(Tenangkan saraf Ouroboros dengan lagu ini, dan tenangkan.)",
  ui_story_5036_50361602_29_dialog_content = "(Jadikan lagu ini layak sebagai perpisahan terakhir ke panggung, dan hidup sebagai idola.)",
  ui_story_5036_50361602_30_dialog_content = "Ouroboros, dengarkan laguku!",
  ui_story_5036_50361602_31_dialog_content = "♪ Dunia ini luas, alam semesta lautan ♪",
  ui_story_5036_50361602_32_dialog_content = "♪ Kita terlahir seperti meteorit, ceria dan ceria ♪",
  ui_story_5036_50361602_33_dialog_content = "♪ Kami bermain dengan gembira, tapi terkadang kami lelah ♪",
  ui_story_5036_50361602_34_dialog_content = "♪ Lampu rumah, pandu kami dengan hangat ke sarang kami ♪",
  ui_story_5036_50361602_35_dialog_content = "Semuanya, ikuti instruksi dan evakuasi! Shadowlord akan memastikan keselamatanmu!",
  ui_story_5036_50361602_36_dialog_content = "♪ Lampu rumah, pandu kami dengan hangat ke sarang kami ♪",
  ui_story_5036_50361602_37_dialog_content = "Kakak, apakah kamu mendengarnya?",
  ui_story_5036_50361602_38_dialog_content = "Itu bernyanyi!",
  ui_story_5036_50361602_39_dialog_content = "Nona, semua orang yang dievakuasi telah keluar dari pesawat.",
  ui_story_5036_50361602_40_dialog_content = "Oke. Bersiaplah untuk keluar lagi dan mengevakuasi kelompok warga sipil berikutnya!",
  ui_story_5036_50361602_41_dialog_content = "♪ Lampu rumah, pandu kami dengan hangat ke sarang kami ♪",
  ui_story_5036_50361602_42_dialog_content = "Apakah itu... bernyanyi?",
  ui_story_5036_50361602_43_dialog_content = "Suara yang begitu lembut. Apakah itu berasal dari Colossus?",
  ui_story_5036_50361602_44_dialog_content = "♪ Anak yang kelelahan, tidurlah ♪",
  ui_story_5036_50361602_45_dialog_content = "♪ Semoga ninabobo ini, jagalah mimpimu ♪",
  ui_story_5036_50361602_46_dialog_content = "♪ Ini rumahmu ♪",
  ui_story_5036_50361602_47_dialog_content = "Kree—!",
  ui_story_5036_50361602_48_dialog_content = "(The Ouroboros tampaknya merespons!)",
  ui_story_5036_50361602_49_dialog_content = "Carleen, PlayerName! Sepertinya mulai tenang!",
  ui_story_5036_50361602_50_dialog_content = "Besar! Lagu itu bekerja!",
  ui_story_5036_50361602_51_dialog_content = "Colossus telah berhenti bergoyang. Ini akan berhasil!",
  ui_story_5036_50361602_52_dialog_content = "Maju di Eclipsites!",
  ui_story_5036_50361602_53_dialog_content = "♪ Ini rumahmu ♪",
  ui_story_5036_50361602_54_dialog_content = "Lagu?",
  ui_story_5036_50361602_55_dialog_content = "Melodi itulah yang mematikan Colossus. Ini lembut seperti lagu pengantar tidur.",
  ui_story_5036_50361602_56_dialog_content = "Apakah itu Goldie yang bernyanyi? Tetapi...",
  ui_story_5036_50361602_57_dialog_content = "♪ Sekarang rumah itu tidak ada lagi ♪",
  ui_story_5036_50361602_58_dialog_content = "(Sepertinya saya mendengar nyanyian Chaminade!)",
  ui_story_5036_50361602_59_dialog_content = "(Dia pasti hancur. Aku bahkan tidak mendapat kesempatan untuk menghiburnya...)",
  ui_story_5036_50361602_60_dialog_content = "(Dia mungkin hanya sosok dari mimpi, dan tidak benar-benar ada.)",
  ui_story_5036_50361602_61_dialog_content = "(Tapi kesedihan dan kesepiannya begitu nyata.)",
  ui_story_5036_50361602_62_dialog_content = "(Maka saya akan mendedikasikan lagu ini untuk Anda, Chaminade.)",
  ui_story_5036_50361602_63_dialog_content = "(Dan semoga itu menghilangkan kesedihanmu.)",
  ui_story_5036_50361602_64_dialog_content = "♪ Sekarang rumah itu tidak ada lagi ♪",
  ui_story_5036_50361602_65_dialog_content = "♪ Tetap saja, apakah anak-anak muda memulai perjalanan ♪",
  ui_story_5036_50361602_66_dialog_content = "♪ Melalui air mata yang mengalir sepanjang malam ♪",
  ui_story_5036_50361602_67_dialog_content = "♪ Melalui kesedihan dan kegembiraan, kepergian dan reuni ♪",
  ui_story_5036_50361602_68_dialog_content = "♪ Bisakah mereka masih melihat cahaya fajar harapan? ♪",
  ui_story_5036_50361602_69_dialog_content = "♪ Cahaya yang masih menunggu di depan ♪",
  ui_story_5036_50361602_70_dialog_content = "Rapid Torrent!",
  ui_story_5036_50361602_71_dialog_content = "Ada berapa lagi...?",
  ui_story_5036_50361602_72_dialog_content = "Keren!!!",
  ui_story_5036_50361602_73_dialog_content = "Awas! Itu datang kembali!",
  ui_story_5036_50361602_74_dialog_content = "Aku tidak akan membiarkanmu mendekat!",
  ui_story_5036_50361602_75_dialog_content = "Apakah itu lagumu, Goldie?",
  ui_story_5036_50361602_76_dialog_content = "Sangat hangat, seperti matahari dan angin di Eraveil.",
  ui_story_5036_50361602_77_dialog_content = "Saya melihat sekarang. Bahkan jika Eraveil dihancurkan, itu tidak hilang. Rumah... bisa dibangun kembali.",
  ui_story_5036_50361602_78_dialog_content = "Goldie, aku mendengarmu.",
  ui_story_5036_50361602_79_dialog_content = "Jadi, saya harus—",
  ui_story_5036_50361602_80_dialog_content = "♪ Coba hapus air mata itu ♪",
  ui_story_5036_50361602_81_dialog_content = "♪ Hapus air mata itu, mulai lagi— ♪",
  ui_story_5036_50361602_82_dialog_content = "♪ Sebarkan lagu ini jauh-jauh ♪",
  ui_story_5036_50361602_83_dialog_content = "Terima kasih, Goldie.",
  ui_story_5036_50361602_84_dialog_content = "Idola dari masa depan, saya mempercayakan Ouroboros dan masa depan kepada Anda.",
  ui_story_5036_50361602_85_dialog_content = "Chaminade... tampaknya benar-benar hilang.",
  ui_story_5036_50361602_86_dialog_content = "Kree—",
  ui_story_5036_50361602_87_dialog_content = "Ouroboros telah tenang!",
  ui_story_5036_50361602_88_dialog_content = "Itu berhasil! PlayerName, rencanamu berhasil!",
  ui_story_5036_50361602_89_dialog_content = "Baiklah!",
  ui_story_5036_50361602_90_dialog_content = "Tapi kita tidak bisa bertahan lebih lama lagi di sini!",
  ui_story_5036_50361602_91_dialog_content = "Argh!",
  ui_story_5036_50361602_92_dialog_content = "Keren!!!",
  ui_story_5036_50361602_93_dialog_content = "Rapid Torrent!",
  ui_story_5036_50361602_94_dialog_content = "Grahh! Grah!",
  ui_story_5036_50361602_95_dialog_content = "Bagaimana benda ini masih hidup?!",
  ui_story_5036_50361602_96_dialog_content = "Eclipsite apa pun yang dapat bertahan di Colossus ini seharusnya tidak mudah menyerah.",
  ui_story_5036_50361602_97_dialog_content = "Tunggu saja. Ouroboros seharusnya bisa terbang kapan saja sekarang!",
  ui_story_5036_50361602_98_dialog_content = "Mengaum-!",
  ui_story_5036_50361602_99_dialog_content = "Carleen, awas!",
  ui_story_5036_50361602_100_dialog_content = "Kree!",
  ui_story_5036_50361602_101_dialog_content = "<color=#e8d9bb>Tamparan-!</color>",
  ui_story_5036_50361602_102_dialog_content = "Mengaum-",
  ui_story_5036_50361602_103_dialog_content = "Wah! A-Apa...?",
  ui_story_5036_50361602_104_dialog_content = "Ouroboros mengirim Eclipsite itu terbang dengan ekornya!",
  ui_story_5036_50361602_105_dialog_content = "Kree, Kree!",
  ui_story_5036_50361602_106_dialog_content = "Tidak terlihat takut lagi! Itu bahagia!",
  ui_story_5036_50361602_107_dialog_content = "Itu brilian! Tanpa Eclipsite yang main-main, sisanya harus mudah ditangani.",
  ui_story_5036_50361602_108_dialog_content = "Ice Blossom!",
  ui_story_5036_50361602_109_dialog_content = "Grrrr...",
  ui_story_5036_50361602_110_dialog_content = "Kree—!",
  ui_story_5036_50361602_111_dialog_content = "<color=#e8d9bb>Kecelakaan—</color>",
  ui_story_5036_50361602_112_dialog_content = "Colossus bergoyang lagi!?",
  ui_story_5036_50361602_113_dialog_content = "Namun, Ouroboros menjadi tenang.",
  ui_story_5036_50361602_114_dialog_content = "Tunggu sebentar! Sepertinya akan terbang!",
  ui_story_5036_50361602_115_dialog_content = "Kree—!",
  ui_story_5036_50361602_116_dialog_content = "Kree!",
  ui_story_5036_50361602_117_dialog_content = "Lihat, naga di Colossus baru saja lepas landas!",
  ui_story_5036_50361602_118_dialog_content = "Itu benar! Apakah Goldie masih di Colossus? Apakah dia aman?",
  ui_story_5036_50361602_119_dialog_content = "Dia adalah idola yang luar biasa.",
  ui_story_5036_50361602_120_dialog_content = "Tidak peduli apa yang ada di depan, dia akan berhasil.",
  ui_story_5036_50361602_121_dialog_content = "Jadi... percaya saja padanya.",
  ui_story_5036_50361602_122_dialog_content = "Ya!",
  ui_story_5036_50361602_123_dialog_content = "Aku juga percaya padanya!",
  ui_story_5036_50361602_124_dialog_content = "Baik. Anda harus bergabung dengan yang lain dalam evakuasi.",
  ui_story_5036_50361602_125_dialog_content = "Sekarang naga itu terbang, apakah semuanya sudah berakhir?",
  ui_story_5036_50361602_126_dialog_content = "Saya harus menghubungi mereka dan mengkonfirmasi situasinya.",
  ui_story_5036_50361602_127_dialog_content = "Laporan! Semua personel yang dievakuasi dari Wandering Colossus telah diamankan.",
  ui_story_5036_50361602_128_dialog_content = "Hanya sedikit yang mengalami luka ringan. Tidak ada luka berat atau kematian!",
  ui_story_5036_50361602_129_dialog_content = "Untungnya, Tuan Kota berada di pesawat di dekat Wandering Colossus.",
  ui_story_5036_50361602_130_dialog_content = "Lumopolis hanya mampu merespon begitu cepat dan meminimalisir cedera karena hal tersebut.",
  ui_story_5036_50361602_131_dialog_content = "Bagaimana situasi saat ini dengan Colossus dan naga?",
  ui_story_5036_50361602_132_dialog_content = "Naga itu meninggalkan Colossus, tetapi Carleen dan yang lainnya masih ada di dalamnya.",
  ui_story_5036_50361602_133_dialog_content = "...",
  ui_story_5036_50361602_134_dialog_content = "PlayerName dan Vice ada di sana, jadi Carleen pasti aman!",
  ui_story_5036_50361602_135_dialog_content = "Perintahkan kapal udara untuk melanjutkan evakuasi personel di atas Colossus.",
  ui_story_5036_50361602_136_dialog_content = "Siap, Pak!",
  ui_story_5036_50361602_137_dialog_content = "<color=#e8d9bb>Gruk!</color>",
  ui_story_5036_50361602_138_dialog_content = "Hah?!",
  ui_story_5036_50361602_139_dialog_content = "Apakah Colossus terbalik?!",
  ui_story_5036_50361602_140_dialog_content = "Aah?!",
  ui_story_5036_50361602_141_dialog_content = "Kepergian Ouroboros mengubah keseimbangan Colossus!",
  ui_story_5036_50361602_142_dialog_content = "Ini mendapatkan ketinggian!",
  ui_story_5036_50361602_143_dialog_content = "Rencananya sukses besar!",
  ui_story_5036_50361602_144_dialog_content = "Ayo cepat dan pergi dari sini. Ada terlalu banyak Eclipsites. Mereka melebihi kita!",
  ui_story_5036_50361602_145_dialog_content = "PlayerName!",
  ui_story_5036_50361602_146_dialog_content = "Ouroboros terbang. Kami berhasil!",
  ui_story_5036_50361602_147_dialog_content = "Sungguh kesimpulan yang diberkati bagi kita semua!",
  ui_story_5036_50361602_148_option_content = "Di mana Chaminade?",
  ui_story_5036_50361602_149_dialog_content = "Saya pikir saya mendengar dia bernyanyi dengan Anda.",
  ui_story_5036_50361602_150_dialog_content = "aku rasa dia sudah pergi...",
  ui_story_5036_50361602_151_dialog_content = "Tidak pergi dengan Ouroboros, tapi pergi sepenuhnya.",
  ui_story_5036_50361602_152_dialog_content = "Oh, begitu…",
  ui_story_5036_50361602_153_dialog_content = "Ya. Dia bilang dia akan mempercayakan semuanya padaku.",
  ui_story_5036_50361602_154_dialog_content = "Dia mungkin ingin lagu ini didengar oleh seluruh Astra.",
  ui_story_5036_50361602_155_option_content = "Bagaimana dengan Eulogoz?",
  ui_story_5036_50361602_156_dialog_content = "Tidak apa-apa sekarang, tapi kepergian Ouroboros menyimpang dari jalurnya.",
  ui_story_5036_50361602_157_dialog_content = "Ini mendapatkan ketinggian.",
  ui_story_5036_50361602_158_dialog_content = "PlayerName, tidak ada waktu untuk mengobrol. Mari kita pergi dari sini!",
  ui_story_5036_50361602_159_dialog_content = "Keberangkatan Ouroboros mengubah rute Eulogoz dan beban yang lebih ringan membuatnya berakselerasi.",
  ui_story_5036_50361602_160_dialog_content = "Ya, dengan kecepatan sekarang, kita akan sangat tinggi sehingga kita tidak akan bisa bernapas dalam sepuluh menit atau lebih.",
  ui_story_5036_50361602_161_dialog_content = "Ayo cepat dan keluar dari sini!",
  ui_story_5036_50361602_162_dialog_content = "Tapi Eulogoz—",
  ui_story_5036_50361602_163_dialog_content = "Eulogoz mungkin tidak akan pernah kembali...",
  ui_story_5036_50361602_164_dialog_content = "Bahkan Gronru tidak dapat memperbaiki sistem kontrol Eulogoz dalam waktu sesingkat itu.",
  ui_story_5036_50361602_165_dialog_content = "Lalu bukankah semua usaha kita sia-sia?",
  ui_story_5036_50361602_166_dialog_content = "Sama sekali tidak!",
  ui_story_5036_50361602_167_dialog_content = "Konsernya mungkin tidak berjalan sesuai rencana, tapi kami harus membaginya dengan semua orang untuk sementara.",
  ui_story_5036_50361602_168_dialog_content = "Dan kami belajar tentang Eulogoz dan Chaminade melalui petualangan kami.",
  ui_story_5036_50361602_169_dialog_content = "Selama kita tidak melupakan mereka, mereka akan selalu bersama kita.",
  ui_story_5036_50361602_170_dialog_content = "...",
  ui_story_5036_50361602_171_option_content = "Ayo.",
  ui_story_5036_50361602_172_option_content = "Saya tidak akan pernah melupakan mereka.",
  ui_story_5036_50361602_173_dialog_content = "Iya!",
  ui_story_5036_50361602_174_dialog_content = "PlayerName, kita kehabisan waktu.",
  ui_story_5036_50361602_175_dialog_content = "Mari kita kembali.",
  ui_story_5036_50361602_176_dialog_content = "Benar.",
  ui_story_5036_50361602_177_dialog_content = "Maaf, Eulogoz.",
  ui_story_5036_50361602_178_dialog_content = "Selamat tinggal.",
  ui_story_5036_50361701_1_dialog_content = "Terlibat, Soroz!",
  ui_story_5036_50361701_2_dialog_content = "<color=#e8d9bb>Gruk!</color>",
  ui_story_5036_50361701_3_dialog_content = "Eulogoz terbang semakin tinggi, menuju alam semesta di atas.",
  ui_story_5036_50361701_4_dialog_content = "Ini akan membawakan lagu Chaminade ke bintang-bintang.",
  ui_story_5036_50361701_5_dialog_content = "Tidak peduli apa, kita akhirnya aman.",
  ui_story_5036_50361701_6_dialog_content = "Meski konsernya gagal, dan kami tidak bisa menyelamatkan Eulogoz.",
  ui_story_5036_50361701_7_dialog_content = "Semua orang aman sekarang. Masyarakat Umbraton tidak perlu takut lagi. Itu harus cukup.",
  ui_story_5036_50361701_8_dialog_content = "Yang masih belum saya mengerti adalah mengapa Ouroboros tiba-tiba menetas.",
  ui_story_5036_50361701_9_dialog_content = "Kalau saja itu menetas sedikit kemudian, segalanya akan sangat berbeda sekarang ...",
  ui_story_5036_50361701_10_dialog_content = "Sebenarnya, saya memikirkannya, dan saya pikir itu karena saya.",
  ui_story_5036_50361701_11_dialog_content = "Dalam mimpiku... Tidak, sebenarnya, itu adalah mimpi Ouroboros. Saya bertemu Chaminade.",
  ui_story_5036_50361701_12_dialog_content = "Bertemu? Bukankah maksudmu kau memimpikannya?",
  ui_story_5036_50361701_13_dialog_content = "Tidak. Aku bertemu dengannya.",
  ui_story_5036_50361701_14_dialog_content = "Siapa atau apa sebenarnya Chaminade itu?",
  ui_story_5036_50361701_15_dialog_content = "Mungkinkah ada cara bagi orang mati untuk terus ada?",
  ui_story_5036_50361701_16_dialog_content = "Memikirkannya saja membuatku merinding...",
  ui_story_5036_50361701_17_dialog_content = "Mungkin Chaminade dalam mimpi itu hanyalah isapan jempol dari imajinasi Ouroboros.",
  ui_story_5036_50361701_18_dialog_content = "Maksudmu dia bukan Chaminade yang asli?",
  ui_story_5036_50361701_19_dialog_content = "Ya. Saya ingat Chaminade dalam mimpi saya berkata—",
  ui_story_5036_50361701_20_dialog_content = "Itu merasakan keinginan terakhir hatiku untuk kembali ke rumahku, jadi itu menciptakan Eraveil dalam alam mimpinya, dan aku.",
  ui_story_5036_50361701_21_dialog_content = "Jadi saya kira, Eraveil dan Chaminade yang saya lihat dalam mimpi itu semuanya diciptakan oleh Ouroboros.",
  ui_story_5036_50361701_22_dialog_content = "Kami tidak semua tenggelam dalam mimpi di Colossus hanya karena kemampuan psikis Ouroboros.",
  ui_story_5036_50361701_23_dialog_content = "Kami bermimpi karena itu adalah mimpi.",
  ui_story_5036_50361701_24_dialog_content = "Kami tidak memiliki mimpi yang sama. Kami semua berbagi mimpi naga.",
  ui_story_5036_50361701_25_dialog_content = "Tapi mengapa itu menciptakan mimpi seperti itu?",
  ui_story_5036_50361701_26_dialog_content = "Karena kerinduan dan kebencian, mungkin...",
  ui_story_5036_50361701_27_dialog_content = "Meski telah menjadi telur, ia masih bisa merasakan bahwa Chaminade dalam bahaya.",
  ui_story_5036_50361701_28_dialog_content = "Itu tidak bisa membantunya, tetapi dia tahu keinginannya adalah kembali ke rumah.",
  ui_story_5036_50361701_29_dialog_content = "Jadi, mimpi itu lahir dari betapa merindukannya. Itu menciptakan mimpi di mana temannya akhirnya kembali ke rumah.",
  ui_story_5036_50361701_30_dialog_content = "Ouroboros terus tidur hanya untuk menjaga mimpi itu tetap hidup.",
  ui_story_5036_50361701_31_dialog_content = "Saya mengerti. Tidak heran itu tidak pernah menetas!",
  ui_story_5036_50361701_32_dialog_content = "Lalu kenapa tiba-tiba menetas? Mungkinkah ada hubungannya dengan mimpi itu juga?",
  ui_story_5036_50361701_33_dialog_content = "Karena aku mungkin telah tergelincir...",
  ui_story_5036_50361701_34_dialog_content = "Chaminade sangat terpukul setelah mengetahui bahwa Eraveil dihancurkan.",
  ui_story_5036_50361701_35_dialog_content = "Jadi mimpi itu runtuh, dan tidak pernah bisa kembali seperti semula.",
  ui_story_5036_50361701_36_dialog_content = "Aku bahkan tidak mendapatkan kesempatan untuk meminta maaf padanya.",
  ui_story_5036_50361701_37_dialog_content = "Tapi, pada akhirnya, dia ingin aku membawakan lagu itu untuk semua orang.",
  ui_story_5036_50361701_38_dialog_content = "Aku akan menepati janji itu, bahkan jika aku tidak bisa lagi menjadi idola.",
  ui_story_5036_50361701_39_dialog_content = "<color=#e8d9bb>Bip bip bip—</color>",
  ui_story_5036_50361701_40_dialog_content = "Hai! Permintaan pesan dari Sheol!",
  ui_story_5036_50361701_41_dialog_content = "A-Apa yang kita lakukan? Haruskah kita menjawabnya?",
  ui_story_5036_50361701_42_dialog_content = "Entah kenapa, aku punya firasat buruk tentang ini.",
  ui_story_5036_50361701_43_dialog_content = "Tunggu, mari kita tanyakan jepit rambutku!",
  ui_story_5036_50361701_44_dialog_content = "<color=#e8d9bb>ding—</color>",
  ui_story_5036_50361701_45_dialog_content = "Itu menunjuk ke bawah. Itu pertanda baik!",
  ui_story_5036_50361701_46_dialog_content = "Haruskah kita menjawab?",
  ui_story_5036_50361701_47_dialog_content = "Mari kita jawab, PlayerName.",
  ui_story_5036_50361701_48_dialog_content = "Satu-satunya jalan ke depan adalah menghadapi masalah kita.",
  ui_story_5036_50361701_49_dialog_content = "Baik-baik saja maka. Menempatkannya melalui—",
  ui_story_5036_50361701_50_dialog_content = "PlayerName?",
  ui_story_5036_50361701_51_dialog_content = "Nona Sheol? Aku mendengarkan!",
  ui_story_5036_50361701_52_dialog_content = "Kamu ada di mana sekarang? Apa yang sedang terjadi?",
  ui_story_5036_50361701_53_dialog_content = "Kami berada di Soroz. Kita semua di sini. Semua orang baik-baik saja.",
  ui_story_5036_50361701_54_dialog_content = "Tidak ada yang terluka? Itu bagus ... sekarang ...",
  ui_story_5036_50361701_55_dialog_content = "GOL—MATI!",
  ui_story_5036_50361701_56_dialog_content = "*Hiks*",
  ui_story_5036_50361701_57_dialog_content = "Anda lebih baik menjelaskan diri Anda sendiri. Bagaimana konser yang seharusnya berjalan lancar berubah menjadi malapetaka ini!?",
  ui_story_5036_50361701_58_dialog_content = "aku, eh...",
  ui_story_5036_50361701_59_dialog_content = "Saya minta maaf. aku mengacaukannya...",
  ui_story_5036_50361701_60_dialog_content = "Saya tidak memeriksa tempat tersebut dengan cukup hati-hati sehingga saya gagal menemukan telur Ouroboros di Colossus dan menyadari potensi ancaman yang diwakilinya.",
  ui_story_5036_50361701_61_dialog_content = "Dan saya tidak menyangka Ouroboros entah bagaimana akan bereaksi terhadap nyanyian saya dan menetas...",
  ui_story_5036_50361701_62_dialog_content = "Anda tahu, Anda bisa menyalahkan Ouroboros untuk semuanya.",
  ui_story_5036_50361701_63_dialog_content = "Tidak. Saya akan bertanggung jawab penuh atas hal ini dan memberikan kompensasi penuh untuk semua kerugian sesuai kontrak.",
  ui_story_5036_50361701_64_dialog_content = "Sigh... kau benar-benar mengacaukanku.",
  ui_story_5036_50361701_65_dialog_content = "Saya menginvestasikan banyak uang untuk mempromosikan konser. Dengan hilangnya Colossus, semua uang yang dihabiskan untuk merawat peralatannya dan menyiapkan panggung juga sia-sia.",
  ui_story_5036_50361701_66_dialog_content = "Belum lagi ada biaya lain, seperti biaya mengurus penonton saat peristiwa itu terjadi.",
  ui_story_5036_50361701_67_dialog_content = "Aku turut sedih...",
  ui_story_5036_50361701_68_dialog_content = "Tapi yakinlah, saya akan membayar Anda kembali secara penuh.",
  ui_story_5036_50361701_69_dialog_content = "Bahkan jika aku bukan lagi idola di masa depan, aku akan tetap bekerja keras untuk membayar⁠—",
  ui_story_5036_50361701_70_dialog_content = "Hah? Kapan saya meminta Anda untuk menutupi kerugian?",
  ui_story_5036_50361701_71_dialog_content = "Hah…?",
  ui_story_5036_50361701_72_dialog_content = "Konser itu adalah bencana, ya, tapi Anda tampil dengan sangat baik!",
  ui_story_5036_50361701_73_dialog_content = "Emosi dalam lagu Anda disampaikan tidak hanya kepada Ouroboros tetapi juga kepada penonton!",
  ui_story_5036_50361701_74_dialog_content = "Bahkan mereka yang tidak pernah tertarik dengan idol mengetahui tentangmu karena kejadian ini!",
  ui_story_5036_50361701_75_dialog_content = "Dan banyak yang datang bertanya tentang \"idola\"!",
  ui_story_5036_50361701_76_dialog_content = "Apa?!",
  ui_story_5036_50361701_77_dialog_content = "Anda tidak hanya menyelesaikan kontrak Anda secara penuh tetapi jauh melebihi itu.",
  ui_story_5036_50361701_78_dialog_content = "A-Apakah kamu serius?",
  ui_story_5036_50361701_79_dialog_content = "Apakah saya? Mengapa Anda tidak mencari tahu dari penggemar Anda?",
  ui_story_5036_50361701_80_dialog_content = "Merindukan! Apa itu kamu?",
  ui_story_5036_50361701_81_dialog_content = "Itu kamu! Apakah Anda dan adik Anda aman?",
  ui_story_5036_50361701_82_dialog_content = "Kami baik-baik saja! Kamu luar biasa!",
  ui_story_5036_50361701_83_dialog_content = "Lagunya bagus, dan kamu bahkan menjinakkan naga itu!",
  ui_story_5036_50361701_84_dialog_content = "Semua orang melihat betapa beraninya kamu! Keren abis!",
  ui_story_5036_50361701_85_dialog_content = "Betulkah? Heheh! Saya sangat senang mendengar Anda mengatakan itu!",
  ui_story_5036_50361701_86_dialog_content = "Orang lain juga ingin berbicara dengan Anda!",
  ui_story_5036_50361701_87_dialog_content = "Apakah itu Goldie?",
  ui_story_5036_50361701_88_dialog_content = "Y-Ya, ini Goldie yang berbicara. Dan Anda-?",
  ui_story_5036_50361701_89_dialog_content = "Apakah Anda tertarik untuk menjadi solois pribadi saya?",
  ui_story_5036_50361701_90_dialog_content = "Apa kaubilang!?",
  ui_story_5036_50361701_91_dialog_content = "Penampilan Anda membuat saya percaya bahwa Anda adalah orang yang dapat dipercaya dengan kehormatan dan keberanian.",
  ui_story_5036_50361701_92_dialog_content = "Harap menjadi solois saya! Saya dapat membantu Anda bernyanyi di panggung paling mewah di seluruh Lumopolis.",
  ui_story_5036_50361701_93_dialog_content = "Terima kasih atas tawaranmu yang murah hati, tapi...",
  ui_story_5036_50361701_94_dialog_content = "Bagaimana aku bisa meyakinkanmu? Sebutkan harga Anda!",
  ui_story_5036_50361701_95_dialog_content = "Ini bukan masalah uang. Saya lebih suka tetap menjadi idola daripada menjadi penyanyi pribadi.",
  ui_story_5036_50361701_96_dialog_content = "Seorang idola membawa harapan dan kebahagiaan bagi semua orang, apapun statusnya.",
  ui_story_5036_50361701_97_dialog_content = "Saya telah berjanji kepada seorang teman dan pendahulu yang penting untuk membawakan lagu kami kepada semua orang!",
  ui_story_5036_50361701_98_dialog_content = "Apakah begitu...? Sayang sekali.",
  ui_story_5036_50361701_99_dialog_content = "Baiklah, saya berharap Anda beruntung dengan impian Anda, dan saya pasti akan menghadiri konser Anda berikutnya.",
  ui_story_5036_50361701_100_dialog_content = "Terima kasih banyak!",
  ui_story_5036_50361701_101_dialog_content = "Jadi? Apakah Anda yakin sekarang?",
  ui_story_5036_50361701_102_dialog_content = "Ya! Tanpa keraguan!",
  ui_story_5036_50361701_103_dialog_content = "Kemudian bergembiralah dan bersiaplah untuk tantangan berikutnya.",
  ui_story_5036_50361701_104_dialog_content = "Aku sudah mengisi jadwalmu. Banyak yang harus kau lakukan setelah kembali ke Umbraton.",
  ui_story_5036_50361701_105_dialog_content = "Oke! Aku akan kembali sekarang!",
  ui_story_5036_50361701_106_dialog_content = "Omong-omong, kudengar kau menemukan potensi bakat baru bernama Vic. Apakah dia disini?",
  ui_story_5036_50361701_107_dialog_content = "Siapa, saya?",
  ui_story_5036_50361701_108_dialog_content = "Apakah Anda tertarik untuk mendaftar sebagai salah satu idola saya?",
  ui_story_5036_50361701_109_dialog_content = "Apa? Ha ha ha? Anda pasti bercanda.",
  ui_story_5036_50361701_110_dialog_content = "Saya tidak cocok berada di bawah sorotan. Saya suka menghabiskan waktu dengan binatang.",
  ui_story_5036_50361701_111_dialog_content = "Anda tidak akan mempertimbangkan kembali?",
  ui_story_5036_50361701_112_dialog_content = "Saya dapat membayar Anda dengan mahal dan menyertakan sampanye terbaik dari Umbraton sebagai bonus.",
  ui_story_5036_50361701_113_dialog_content = "Kedengarannya menarik. Aku tidak perlu mengurus Little Furball, dan aku bisa minum setiap hari—",
  ui_story_5036_50361701_114_dialog_content = "Kicauan?! ",
  ui_story_5036_50361701_115_dialog_content = "KICAUAN!!!",
  ui_story_5036_50361701_116_dialog_content = "Hah? Hai! Lepaskan, kamu! Berangkat!",
  ui_story_5036_50361701_117_dialog_content = "Sepertinya seseorang sangat tidak setuju.",
  ui_story_5036_50361701_118_dialog_content = "Baiklah kalau begitu. Kita akan membicarakan ini lain kali.",
  ui_story_5036_50361701_119_dialog_content = "Lalu, sampai jumpa di Umbraton.",
  ui_story_5036_50361701_120_dialog_content = "Besar! Ini benar-benar ... sempurna!",
  ui_story_5036_50361701_121_dialog_content = "Aku bisa terus menjadi idola!",
  ui_story_5036_50361701_122_dialog_content = "Selamat, Goldie!",
  ui_story_5036_50361701_123_dialog_content = "Meskipun bagaimana konser ini gagal, lain kali saya akan berhasil!",
  ui_story_5036_50361701_124_dialog_content = "Silahkan datang, PlayerName. Saya akan menghemat tempat terbaik!",
  ui_story_5036_50361701_125_dialog_content = "Tentu saja. Itu kesepakatan!",
  ui_story_5036_50361701_126_dialog_content = "Tapi itu akan menjadi beberapa waktu sebelum itu terjadi.",
  ui_story_5036_50361701_127_dialog_content = "Setelah saya kembali, saya akan menulis lagu tentang cobaan ini!",
  ui_story_5036_50361701_128_dialog_content = "Sepertinya semuanya baik-baik saja yang berakhir dengan baik.",
  ui_story_5036_50361701_129_dialog_content = "Pasti terlihat seperti itu. Wow, sekarang saya mendapatkan waktu untuk bersantai, tiba-tiba saya sangat lelah.",
  ui_story_5036_50361701_130_dialog_content = "Aku sudah mulai mengantuk... Menguap...",
  ui_story_5036_50361701_131_dialog_content = "Hmph! Jika bukan karena drama ini, saya akan mandi air panas yang menyenangkan sekarang!",
  ui_story_5036_50361701_132_dialog_content = "Tidak mandi, tidak masalah.",
  ui_story_5036_50361701_133_dialog_content = "Tidak ada bedanya.",
  ui_story_5036_50361701_134_dialog_content = "Sangat menyenangkan melihat semua teknologi kuno yang langka di Eulogoz.",
  ui_story_5036_50361701_135_dialog_content = "Layar dan sistem stereo sangat menarik. Saya terinspirasi!",
  ui_story_5036_50361701_136_dialog_content = "Saya bertanya-tanya apakah saya harus melihat ke dalam prinsip kerja mereka dan membuat beberapa untuk singgasana...",
  ui_story_5036_50361701_137_dialog_content = "Jangan bilang…",
  ui_story_5036_50361701_138_dialog_content = "Lalu saya bisa bermain game kapan saja, setiap saat!",
  ui_story_5036_50361701_139_dialog_content = "Seperti yang kupikirkan.",
  ui_story_5036_50361701_140_dialog_content = "Bagaimanapun. Mari kita kembali ke permukaan terlebih dahulu.",
  ui_story_5036_50361701_141_dialog_content = "<color=#e8d9bb>Suatu saat nanti</color>",
  ui_story_5036_50361701_142_dialog_content = "Ini sudah siang hari. Saya tidak menyadari begitu banyak waktu telah berlalu.",
  ui_story_5036_50361701_143_dialog_content = "Akhirnya kembali ke darat! Itu sesuatu yang luar biasa, bukan, Little Furball?",
  ui_story_5036_50361701_144_dialog_content = "Cuit!",
  ui_story_5036_50361701_145_dialog_content = "Kami yang melakukan pertempuran saat Anda hanya menonton!",
  ui_story_5036_50361701_146_dialog_content = "Hei, tidak adil untuk mengatakan itu. Saya melakukan yang terbaik untuk melindungi Ouroboros juga!",
  ui_story_5036_50361701_147_dialog_content = "Sudahlah, saya tidak akan berdebat dengan Anda karena Anda berusaha.",
  ui_story_5036_50361701_148_dialog_content = "Aku akan lepas landas sekarang. Fia dan Shira masih menungguku untuk kembali menemui mereka dan menceritakan tentang Ouroboros.",
  ui_story_5036_50361701_149_dialog_content = "Sampai bertemu.",
  ui_story_5036_50361701_150_dialog_content = "Nanti, Vic!",
  ui_story_5036_50361701_151_dialog_content = "Hati-hati di luar sana! Jangan diculik lagi!",
  ui_story_5036_50361701_152_dialog_content = "Jangan khawatir! Saya orang dewasa yang benar-benar dapat diandalkan!",
  ui_story_5036_50361701_153_dialog_content = "Kami juga akan mengambil pesawat kembali ke Lumopolis.",
  ui_story_5036_50361701_154_dialog_content = "(Sejujurnya, lain kali aku harus meminta seseorang untuk menyiapkan mandi air panas untukku...)",
  ui_story_5036_50361701_155_dialog_content = "Hei, kamu anak nakal Rediesel Wrench. Lain kali saya melihat Anda, saya akan mengirim Anda semua ke penjara.",
  ui_story_5036_50361701_156_dialog_content = "Apa? Betapa sombongnya. Kamu pikir kamu ini siapa?",
  ui_story_5036_50361701_157_dialog_content = "Kemudian, Caelestite.",
  ui_story_5036_50361701_158_dialog_content = "Selamat tinggal!",
  ui_story_5036_50361701_159_dialog_content = "Semua orang pergi? Sio, ayo kita kembali juga.",
  ui_story_5036_50361701_160_dialog_content = "Baik. Waktu liburan telah usai. Saatnya kembali bekerja.",
  ui_story_5036_50361701_161_dialog_content = "Petugas Gronru, apakah Anda tidak terbang kembali bersama kami di Colossus?",
  ui_story_5036_50361701_162_dialog_content = "Tidak apa-apa. Sio dan aku akan mengambil mobilnya, jadi kami tidak mengganggu rencanamu.",
  ui_story_5036_50361701_163_dialog_content = "Plus saya perlu berdiskusi dengan Sio kemungkinan menambahkan layar dan konsol game ke singgasana!",
  ui_story_5036_50361701_164_dialog_content = "A-Apa yang kau katakan!?",
  ui_story_5036_50361701_165_dialog_content = "Ayo pergi, Sio kecilku!",
  ui_story_5036_50361701_166_dialog_content = "B-Tolong aku...!",
  ui_story_5036_50361701_167_dialog_content = "Sepertinya masih ada masalah yang belum terpecahkan untuk orang seperti Siobhan.",
  ui_story_5036_50361701_168_dialog_content = "Sepertinya kita juga harus kembali.",
  ui_story_5036_50361701_169_dialog_content = "Ya, ya!",
  ui_story_5036_50361701_170_dialog_content = "Saya telah memutuskan!",
  ui_story_5036_50361701_171_dialog_content = "Hah? Hal gila apa yang kamu putuskan kali ini?",
  ui_story_5036_50361701_172_dialog_content = "Begitu kita kembali, aku akan meyakinkan bos untuk menaruh panggung di kepala Lepidoz!",
  ui_story_5036_50361701_173_dialog_content = "Itu sebenarnya terdengar seperti ide yang bagus!",
  ui_story_5036_50361701_174_dialog_content = "Hai! Itu ide saya! Saya akan meminta bos untuk membuat panggung idola!",
  ui_story_5036_50361701_175_dialog_content = "Kembali ke sini, kamu! Heavy metal adalah musik sungguhan!",
  ui_story_5036_50361701_176_dialog_content = "Oh, betapa hidup.",
  ui_story_5036_50361701_177_dialog_content = "Mari kita mengucapkan selamat tinggal juga, PlayerName.",
  ui_story_5036_50361701_178_dialog_content = "Terimakasih untuk semuanya!",
  ui_story_5036_50361701_179_dialog_content = "Kamu juga. Anda bekerja keras untuk mewujudkan konser ini, dan kami berjuang keras. Saatnya istirahat yang baik.",
  ui_story_5036_50361701_180_dialog_content = "Saya seorang idola profesional, Anda tahu. Tidur sebentar saja dan aku akan siap berangkat!",
  ui_story_5036_50361701_181_dialog_content = "Tolong nantikan konser saya berikutnya!",
  ui_story_5036_50361701_182_dialog_content = "Saya pasti akan menunggu kabar baik Anda!",
  ui_story_5036_50361701_183_dialog_content = "Sampai jumpa, kalau begitu!",
  ui_story_5036_50361701_184_dialog_content = "Jadi kecenderungan kekerasan Goldie hanyalah desas-desus belaka. Saya harus menjelaskannya di artikel saya.",
  ui_story_5036_50361701_185_dialog_content = "Hei, pemimpin redaksi?",
  ui_story_5036_50361701_186_dialog_content = "<size=45>Brandy! Apa yang membuat Anda begitu lama untuk menghubungi saya?</size>",
  ui_story_5036_50361701_187_dialog_content = "Anda akan dipecat jika Anda tidak memiliki sesuatu yang besar untuk saya!",
  ui_story_5036_50361701_188_dialog_content = "Aku sudah menyelidiki rumor yang mengklaim bahwa Goldie adalah orang yang kejam. Itu semua palsu!",
  ui_story_5036_50361701_189_dialog_content = "...",
  ui_story_5036_50361701_190_dialog_content = "Hanya itu yang kau temukan selama Wandering Colossus terbang di atas Umbraton!?",
  ui_story_5036_50361701_191_dialog_content = "Bahkan jika itu adalah berita palsu, itu tetap akan menarik pembaca, bukan? Tanpa jenis gosip ini, kami harus menutup diri.",
  ui_story_5036_50361701_192_dialog_content = "Aku sangat kecewa padamu, Brandy. Kamu diturunkan pangkat⁠—",
  ui_story_5036_50361701_193_dialog_content = "Tunggu! Itu bukan satu-satunya! Saya memiliki detail eksklusif tentang konser Wandering Colossus!",
  ui_story_5036_50361701_194_dialog_content = "Apa!? Kamu serius! Nah, bawa ke sini, kalau begitu!",
  ui_story_5036_50361701_195_dialog_content = "Dengan satu syarat.",
  ui_story_5036_50361701_196_dialog_content = "Ada apa?",
  ui_story_5036_50361701_197_dialog_content = "Eksklusif dan artikel yang menghilangkan rumor tentang Goldie harus ada di halaman yang sama.",
  ui_story_5036_50361701_198_dialog_content = "Saya ingin semua orang tahu bahwa mereka salah paham tentang Goldie!",
  ui_story_5036_50361701_199_dialog_content = "I-Itu prepost...",
  ui_story_5036_50361701_200_dialog_content = "<size=45>Ugh, baiklah, baiklah!</size>",
  ui_story_5036_50361701_201_dialog_content = "Saya akan melakukan itu. Sekarang bawa laporanmu ke sini.",
  ui_story_5036_50361701_202_dialog_content = "Baiklah!",
  ui_story_5036_50361701_203_dialog_content = "Jadi Anda menculik Drakolion dengan kue binatang dan menyelinap ke Wandering Colossus untuk menyelidikinya... tanpa hasil!?",
  ui_story_5036_50361701_204_dialog_content = "Saya hampir disergap oleh Eclipsites saat mencoba menemukan Drakolion!",
  ui_story_5036_50361701_205_dialog_content = "Bagaimana Anda akan memberikan kompensasi kepada saya untuk ini, ya !? Menguasai?",
  ui_story_5036_50361701_206_dialog_content = "Sehat! Meskipun gagal mengetahui lebih banyak tentang Ouroboros, kami membangunkannya dan mendapat banyak informasi!",
  ui_story_5036_50361701_207_dialog_content = "Kembalinya Ouroboros pasti akan mengguncang Astra!",
  ui_story_5036_50361701_208_dialog_content = "Percayalah, dengan intel yang kumiliki sekarang. Akan mudah melacak Ouroboros di masa mendatang!",
  ui_story_5036_50361701_209_dialog_content = "Kenapa rasanya aku pernah dengar, ya?",
  ui_story_5036_50361701_210_dialog_content = "Itulah yang dia katakan terakhir kali.",
  ui_story_5036_50361701_211_dialog_content = "\"Percayalah, aku pasti akan menghasilkan banyak uang lain kali!\"",
  ui_story_5036_50361701_212_dialog_content = "Bagaimana Anda mengingatnya dengan sangat baik?",
  ui_story_5036_50361701_213_dialog_content = "Karena itu juga yang dia katakan waktu sebelumnya.",
  ui_story_5036_50361701_214_dialog_content = "Namun, hingga saat ini, belum ada perubahan positif dalam status keuangannya. Dia terus saja semakin miskin.",
  ui_story_5036_50361701_215_dialog_content = "BENAR. Dia masih belum membayar pakan binatang yang luar biasa bulan lalu!",
  ui_story_5036_50361701_216_dialog_content = "* Hiks * Apakah aku benar-benar pecundang di matamu?",
  ui_story_5036_50361701_217_dialog_content = "Apa yang kamu harapkan?",
  ui_story_5036_50361701_218_dialog_content = "Aku sangat sedih!",
  ui_story_5036_50361701_219_dialog_content = "Jadi apakah semua orang berpikir aku lebih baik menjadi idola?",
  ui_story_5036_50361701_220_dialog_content = "Mereka memberi Anda tepuk tangan karena mereka mengasihani Anda. Anda seharusnya tidak menganggapnya serius.",
  ui_story_5036_50361701_221_dialog_content = "*Hiks*",
  ui_story_5036_50361701_222_dialog_content = "Tapi, kamu benar sekali. Ouroboros benar-benar ada di Wandering Colossus.",
  ui_story_5036_50361701_223_dialog_content = "Bagaimana Anda mengetahuinya?",
  ui_story_5036_50361701_224_dialog_content = "Mungkin bagi Ouroboros, pergi ke Colossus adalah cara kembali.",
  ui_story_5036_50361701_225_dialog_content = "Maksudmu?",
  ui_story_5036_50361701_226_dialog_content = "Tidak peduli berapa lama Ouroboros dapat hidup atau berapa kali menetas...",
  ui_story_5036_50361701_227_dialog_content = "Itu dimulai sebagai telur dari Ouroboros lain.",
  ui_story_5036_50361701_228_dialog_content = "Seorang anak muda mengandalkan orang tuanya untuk perlindungan dengan naluri.",
  ui_story_5036_50361701_229_dialog_content = "Hal yang sama berlaku bahkan untuk Ouroboros yang kembali ke tahap awal dalam setiap siklus hidup.",
  ui_story_5036_50361701_230_dialog_content = "Namun, Ouroboroses jumlahnya terlalu sedikit. Banyak yang tidak pernah menemukan orang tua mereka.",
  ui_story_5036_50361701_231_dialog_content = "Karena itu, mereka hanya dapat mencari Colossi, yang memiliki ikatan kuat dengan mereka.",
  ui_story_5036_50361701_232_dialog_content = "Memperlakukan Colossi sebagai orang tua mereka... sungguh menyedihkan.",
  ui_story_5036_50361701_233_dialog_content = "Kalau begitu, karena Anda berbagi darah dengan Ouroboros, apakah itu berarti suatu hari Anda akan mencari Colosuss atau semacamnya?",
  ui_story_5036_50361701_234_dialog_content = "Masa laluku adalah sebuah misteri! Jangan membuat dugaan liar!",
  ui_story_5036_50361701_235_dialog_content = "Itu benar. Untuk seseorang yang tidak berguna seperti Anda yang bahkan tidak bisa menggunakan kemampuan psikis, Anda mungkin menggertak saat mengatakan bahwa Anda berbagi garis keturunan dengan Ouroboros.",
  ui_story_5036_50361701_236_dialog_content = "Itu benar, kok!",
  ui_story_5036_50361701_237_dialog_content = "Jika itu benar, mengapa Ouroboros tidak datang mencarimu?",
  ui_story_5036_50361701_238_dialog_content = "Bukankah itu yang harus kita cermati? Mari—",
  ui_story_5036_50361701_239_dialog_content = "Kree—!",
  ui_story_5036_50361701_240_dialog_content = "?!"
}
return config
